// Validate SESSION_SECRET in production
if (process.env.NODE_ENV === 'production' && !process.env.SESSION_SECRET) {
  throw new Error('SESSION_SECRET environment variable is required in production');
}

const sessionSecret = process.env.SESSION_SECRET || 'dev-only-secret-do-not-use-in-production';

function getHeaderValue(value: string | string[] | undefined): string | undefined {
  return Array.isArray(value) ? value[0] : value;
}

// Conditional CSRF middleware - skip for API token auth (Bearer tokens are not vulnerable to CSRF)
import { Request, Response, NextFunction } from 'express';
const CSRF_COOKIE_NAME = 'csrf_token';

function generateCsrfToken(): string {
  return crypto.randomBytes(32).toString('hex');
}

function csrfTokensMatch(expected: string, presented: string): boolean {
  const expectedBuffer = Buffer.from(expected);
  const presentedBuffer = Buffer.from(presented);
  return expectedBuffer.length === presentedBuffer.length
    && crypto.timingSafeEqual(expectedBuffer, presentedBuffer);
}

const conditionalCsrf = (req: Request, res: Response, next: NextFunction) => {
  const authHeader = req.headers?.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    // Skip CSRF for API token requests - Bearer tokens are not auto-attached by browsers
    return next();
  }

  const originDecision = validateCookieAuthOrigin(req);
  if (!originDecision.allowed) {
    res.status(403).json({ error: originDecision.reason });
    return;
  }

  if (!isStateChangingMethod(req.method)) {
    return next();
  }

  const expectedToken = req.signedCookies?.[CSRF_COOKIE_NAME];
  const presentedToken = getHeaderValue(req.headers['x-csrf-token']);
  if (
    typeof expectedToken !== 'string'
    || typeof presentedToken !== 'string'
    || !csrfTokensMatch(expectedToken, presentedToken)
  ) {
    res.status(403).json({ error: 'Invalid or missing CSRF token' });
    return;
  }

  return next();
};

function isStateChangingMethod(method: string): boolean {
  return !['GET', 'HEAD', 'OPTIONS'].includes(method.toUpperCase());
}

function parseOrigin(value: string | undefined): string | null {
  if (!value) return null;
  try {
    return new URL(value).origin;
  } catch {
    return null;
  }
}

function requestOrigin(req: Request): string {
  const protocol = req.protocol;
  const host = req.get('host') ?? '';
  return `${protocol}://${host}`;
}

function configuredAllowedOrigins(): Set<string> {
  const values = [
    process.env.CORS_ORIGIN,
    process.env.FRONTEND_URL,
    process.env.WEB_URL,
  ]
    .flatMap(value => (value ?? '').split(','))
    .map(value => value.trim())
    .filter(Boolean)
    .filter(value => value !== '*')
    .map(value => parseOrigin(value) ?? value);

  return new Set(values);
}

function wildcardOriginAllowed(): boolean {
  if (isProduction()) return false;
  return [process.env.CORS_ORIGIN, process.env.FRONTEND_URL, process.env.WEB_URL]
    .flatMap(value => (value ?? '').split(','))
    .map(value => value.trim())
    .includes('*');
}

function validateCookieAuthOrigin(req: Request): { allowed: true } | { allowed: false; reason: string } {
  if (!isStateChangingMethod(req.method)) return { allowed: true };

  const origin = parseOrigin(getHeaderValue(req.headers.origin));
  const referer = parseOrigin(getHeaderValue(req.headers.referer));
  const presentedOrigin = origin ?? referer;

  if (!presentedOrigin) {
    return isProduction()
      ? { allowed: false, reason: 'Missing Origin or Referer header' }
      : { allowed: true };
  }

  const sameOrigin = requestOrigin(req);
  const allowedOrigins = configuredAllowedOrigins();
  if (presentedOrigin === sameOrigin || allowedOrigins.has(presentedOrigin) || wildcardOriginAllowed()) {
    return { allowed: true };
  }

  return { allowed: false, reason: 'Cross-site request rejected' };
}

function isBodyParserSyntaxError(err: unknown): boolean {
  if (!err || typeof err !== 'object') return false;
  const candidate = err as { type?: string; status?: number; body?: unknown };
  return candidate.status === 400 && candidate.type === 'entity.parse.failed';
}

function shouldBypassRateLimit(req: Request): boolean {
  if (isProduction()) return false;
  if (process.env.API_BENCHMARK_RATE_LIMIT_BYPASS !== '1') return false;

  const token = process.env.API_BENCHMARK_RATE_LIMIT_BYPASS_TOKEN;
  if (!token) return false;

  return getHeaderValue(req.headers['x-benchmark-rate-limit-bypass']) === token;
}

export function openApiShouldRequireAuth(env: NodeJS.ProcessEnv = process.env): boolean {
  if (env.NODE_ENV !== 'production') return false;
  return env.OPENAPI_PUBLIC !== '1';
}

// Rate limiting configurations
// In test/dev environment, use much higher limits to avoid issues
// Production limits: login=5/15min (failed only), api=100/min

// Strict rate limit for login (5 failed attempts / 15 min) - brute force protection
// skipSuccessfulRequests: true means only failed attempts count toward the limit
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: isTestEnv() ? 1000 : 5, // High limit for tests
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many login attempts. Try again in 15 minutes.' },
  skipSuccessfulRequests: true, // Only count failed login attempts
  skip: shouldBypassRateLimit,
});

// General API rate limit (100 req/min in prod, 1000 in dev)
const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: isTestEnv() ? 10000 : isDevEnv() ? 1000 : 100, // High limit for tests/dev
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests. Please slow down.' },
  skip: shouldBypassRateLimit,
});


export function createApp(corsOrigin: string = 'http://localhost:5173'): express.Express {
  const app = express();

  // Trust proxy headers (CloudFront) for secure cookies and correct protocol detection
  if (isProduction()) {
    app.set('trust proxy', 1);

    // CloudFront with viewer_protocol_policy="redirect-to-https" always serves viewers over HTTPS.
    // However, CloudFront -> EB uses HTTP (origin_protocol_policy="http-only"), so CloudFront
    // sets X-Forwarded-Proto to "http". Override it to "https" when request comes via CloudFront.
    app.use((req, _res, next) => {
      // CloudFront adds Via header like "2.0 <id>.cloudfront.net (CloudFront)"
      const viaHeader = getHeaderValue(req.headers.via);
      if (viaHeader?.toLowerCase().includes('cloudfront')) {
        req.headers['x-forwarded-proto'] = 'https';
      }
      next();
    });
  }

  // Middleware - Security headers
  app.use(helmet({
    crossOriginResourcePolicy: { policy: 'cross-origin' },  // Allow images to be loaded cross-origin
    // Content Security Policy - prevents XSS attacks
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", "'unsafe-inline'"], // TipTap editor needs inline styles
        imgSrc: ["'self'", "data:", "blob:", "https:"],
        connectSrc: ["'self'", "wss:", "ws:"], // WebSocket connections
        fontSrc: ["'self'", "data:"],
        objectSrc: ["'none'"],
        frameSrc: ["'none'"],
        baseUri: ["'self'"],
        formAction: ["'self'"],
      }
    },
    // HTTP Strict Transport Security
    hsts: {
      maxAge: 31536000, // 1 year in seconds
      includeSubDomains: true,
      preload: true,
    },
  }));

  // Apply rate limiting to all API routes
  app.use('/api/', apiLimiter);
  app.use(cors({
    origin: corsOrigin,
    credentials: true,
  }));
  app.use(express.json({ limit: '10mb' }));  // Large wiki documents can be several MB
  app.use(express.urlencoded({ extended: true, limit: '10mb' })); // For HTML form submissions
  app.use(cookieParser(sessionSecret));

  // CSRF token endpoint (must be before CSRF protection middleware)
  app.get('/api/csrf-token', (_req, res) => {
    const token = generateCsrfToken();
    res.cookie(CSRF_COOKIE_NAME, token, sessionCookieOptions({ signed: true }, 'lax'));
    res.json({ token });
  });

  // Health check (no CSRF needed)
  app.get('/health', (_req, res) => {
    res.json({ status: 'ok' });
  });

  if (isDevEnv()) {
    app.use('/api/dev', devRoutes);
  }

  setupSwagger(app, openApiShouldRequireAuth() ? authMiddleware : undefined);

  // Setup routes (CSRF protected - first-time setup only)
  app.use('/api/setup', conditionalCsrf, setupRoutes);

  // Public feedback routes - no auth or CSRF required (must be before protected routes)
  app.use('/api/feedback', publicFeedbackRouter);

  // Apply stricter rate limiting to login endpoint (brute force protection)
  app.use('/api/auth/login', loginLimiter);

  // Apply CSRF protection to all state-changing API routes
  app.use('/api/auth', conditionalCsrf, authRoutes);
  app.use('/api/documents', conditionalCsrf, documentsRoutes);
  app.use('/api/documents', conditionalCsrf, backlinksRoutes);
  app.use('/api/documents', conditionalCsrf, associationsRoutes);
  app.use('/api/issues', conditionalCsrf, issuesRoutes);
  app.use('/api/feedback', conditionalCsrf, feedbackRoutes);
  app.use('/api/programs', conditionalCsrf, programsRoutes);
  app.use('/api/projects', conditionalCsrf, projectsRoutes);
  app.use('/api/weeks', conditionalCsrf, weeksRoutes);
  app.use('/api/weeks', conditionalCsrf, iterationsRoutes);
  app.use('/api/standups', conditionalCsrf, standupsRoutes);
  app.use('/api/team', conditionalCsrf, teamRoutes);
  app.use('/api/workspaces', conditionalCsrf, workspacesRoutes);
  app.use('/api/admin', conditionalCsrf, adminRoutes);
  app.use('/api/invites', conditionalCsrf, invitesRoutes);
  app.use('/api/api-tokens', conditionalCsrf, apiTokensRoutes);

  // Claude context routes - read-only GET endpoints for Claude skills
  app.use('/api/claude', claudeRoutes);

  // Search routes are read-only GET endpoints - no CSRF needed
  app.use('/api/search', searchRouter);

  // Activity routes are read-only GET endpoints - no CSRF needed
  app.use('/api/activity', activityRoutes);

  // Dashboard routes are read-only GET endpoints - no CSRF needed
  app.use('/api/dashboard', dashboardRoutes);

  // Bootstrap route is read-only app-shell hydration - no CSRF needed
  app.use('/api/bootstrap', bootstrapRoutes);

  // Accountability routes - inference-based action items (read-only GET)
  app.use('/api/accountability', accountabilityRoutes);

  // AI analysis routes - plan and retro quality feedback (CSRF protected)
  app.use('/api/ai', conditionalCsrf, aiRoutes);

  // FleetGraph routes - visible findings and bounded on-demand graph actions
  app.use('/api/fleetgraph', conditionalCsrf, fleetgraphRoutes);

  // Weekly plans routes - per-person accountability documents (CSRF protected)
  app.use('/api/weekly-plans', conditionalCsrf, weeklyPlansRoutes);

  // Weekly retros routes - per-person accountability documents (CSRF protected)
  app.use('/api/weekly-retros', conditionalCsrf, weeklyRetrosRouter);

  // CAIA auth routes - no CSRF protection (OAuth flow with external callback)
  // This is the single identity provider for PIV authentication
  // Mount at both /caia and /piv paths - /piv/callback is registered with CAIA
  app.use('/api/auth/caia', caiaAuthRoutes);
  app.use('/api/auth/piv', caiaAuthRoutes);

  // Admin credentials management (CSRF protected, super-admin only)
  app.use('/api/admin/credentials', conditionalCsrf, adminCredentialsRoutes);

  // File upload routes (CSRF protected for POST endpoints)
  app.use('/api/files', conditionalCsrf, filesRouter);

  // Comments routes
  app.use('/api/documents', conditionalCsrf, documentCommentsRouter);
  app.use('/api/comments', conditionalCsrf, commentsRouter);

  // Initialize CAIA OAuth client at startup
  initializeCAIA().catch((err) => {
    console.warn('CAIA initialization failed:', err);
  });

  app.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
    if (isBodyParserSyntaxError(err)) {
      res.status(400).json({ error: 'Malformed JSON request body' });
      return;
    }

    next(err);
  });

  return app;
}

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import * as Y from 'yjs'
import { pool } from '../../db/client.js'
import { ContentRow, DocumentContentRow, DocumentStateRow, IdRow, requireFirstRow } from '../../test/pg-result.js';
import { jsonToYjs, yjsToJson, loadContentFromYjsState } from '../../utils/yjsConverter.js'

/**
 * API Content Preservation Tests
 *
 * Tests to verify that content created via API is correctly preserved
 * when loaded via the collaboration server.
 *
 * Root cause: Documents created via API have yjs_state = NULL.
 * When a browser opens the document, the collaboration server converts
 * JSON content to Yjs format. This conversion can silently fail,
 * resulting in empty documents.
 */

describe('API Content Preservation', () => {
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
  const testWorkspaceName = `API Content Test ${testRunId}`

  let testWorkspaceId: string
  let testUserId: string

  beforeAll(async () => {
    // Create test workspace
    const workspaceResult = await pool.query<IdRow>(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [testWorkspaceName]
    )
    testWorkspaceId = requireFirstRow(workspaceResult.rows).id

    // Create test user
    const userResult = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'API Content User') RETURNING id`,
      [`api-content-${testRunId}@test.local`]
    )
    testUserId = requireFirstRow(userResult.rows).id

    // Create workspace membership
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role) VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    )
  })

  afterAll(async () => {
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [testUserId])
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [testWorkspaceId])
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [testWorkspaceId])
    await pool.query('DELETE FROM users WHERE id = $1', [testUserId])
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId])
  })

  describe('Document Creation Scenarios', () => {
    it('should preserve content when document is created via API with TipTap JSON', async () => {
      const testContent = {
        type: 'doc',
        content: [
          {
            type: 'heading',
            attrs: { level: 1 },
            content: [{ type: 'text', text: 'API Created Document' }]
          },
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'This content was created via API.' }]
          }
        ]
      }

      // Create document with content (simulating POST /api/documents with content)
      const docResult = await pool.query<DocumentContentRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'API Content Test', $2, $3)
         RETURNING id, content, yjs_state`,
        [testWorkspaceId, JSON.stringify(testContent), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Verify content was stored correctly
      expect(requireFirstRow(docResult.rows).content).toEqual(testContent)
      expect(requireFirstRow(docResult.rows).yjs_state).toBeNull() // yjs_state is NULL on API creation

      // Simulate what collaboration server does on first connection
      const result = await pool.query<DocumentStateRow>(
        'SELECT yjs_state, content FROM documents WHERE id = $1',
        [docId]
      )

      // yjs_state is NULL, so fallback to content
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')

      if (requireFirstRow(result.rows).yjs_state) {
        Y.applyUpdate(doc, requireFirstRow(result.rows).yjs_state)
      } else if (requireFirstRow(result.rows).content) {
        // This is what getOrCreateDoc does
        let jsonContent = requireFirstRow(result.rows).content
        if (typeof jsonContent === 'string') {
          jsonContent = JSON.parse(jsonContent)
        }

        if (jsonContent && jsonContent.type === 'doc' && Array.isArray(jsonContent.content)) {
          jsonToYjs(doc, fragment, jsonContent)
        }
      }

      // Verify content was converted to Yjs correctly
      expect(fragment.length).toBe(2) // heading + paragraph

      // Convert back to JSON and verify
      const convertedBack = yjsToJson(fragment)
      expect(convertedBack.type).toBe('doc')
      expect(convertedBack.content).toHaveLength(2)
      expect(convertedBack.content[0].type).toBe('heading')
      expect(convertedBack.content[1].type).toBe('paragraph')

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })

    it('should use default content for issues created without explicit content', async () => {
      // Create issue without content column (mimics POST /api/issues)
      const issueResult = await pool.query<DocumentContentRow>(
        `INSERT INTO documents (workspace_id, document_type, title, properties, created_by)
         VALUES ($1, 'issue', 'Test Issue', '{"state": "backlog"}', $2)
         RETURNING id, content, yjs_state`,
        [testWorkspaceId, testUserId]
      )

      const issueId = requireFirstRow(issueResult.rows).id

      // The schema default should be applied
      expect(requireFirstRow(issueResult.rows).content).toEqual({
        type: 'doc',
        content: [{ type: 'paragraph' }]
      })
      expect(requireFirstRow(issueResult.rows).yjs_state).toBeNull()

      // Simulate collaboration server loading
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')

      if (requireFirstRow(issueResult.rows).content) {
        let jsonContent = requireFirstRow(issueResult.rows).content
        if (jsonContent && jsonContent.type === 'doc' && Array.isArray(jsonContent.content)) {
          jsonToYjs(doc, fragment, jsonContent)
        }
      }

      // Should have the default empty paragraph
      expect(fragment.length).toBe(1)

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [issueId])
    })

    it('should handle rich content with formatted text', async () => {
      const richContent = {
        type: 'doc',
        content: [
          {
            type: 'heading',
            attrs: { level: 2 },
            content: [{ type: 'text', text: 'Formatted Content' }]
          },
          {
            type: 'paragraph',
            content: [
              { type: 'text', text: 'This has ' },
              { type: 'text', text: 'bold', marks: [{ type: 'bold' }] },
              { type: 'text', text: ' and ' },
              { type: 'text', text: 'italic', marks: [{ type: 'italic' }] },
              { type: 'text', text: ' text.' }
            ]
          },
          {
            type: 'bulletList',
            content: [
              {
                type: 'listItem',
                content: [
                  {
                    type: 'paragraph',
                    content: [{ type: 'text', text: 'First item' }]
                  }
                ]
              },
              {
                type: 'listItem',
                content: [
                  {
                    type: 'paragraph',
                    content: [{ type: 'text', text: 'Second item' }]
                  }
                ]
              }
            ]
          }
        ]
      }

      // Create document
      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Rich Content Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(richContent), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Load and convert
      const result = await pool.query<ContentRow>(
        'SELECT content FROM documents WHERE id = $1',
        [docId]
      )

      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      jsonToYjs(doc, fragment, requireFirstRow(result.rows).content)

      // Should have heading, paragraph, and bulletList
      expect(fragment.length).toBe(3)

      // Verify bullet list structure
      const bulletList = fragment.get(2)
      expect(bulletList).toBeInstanceOf(Y.XmlElement)
      if (bulletList instanceof Y.XmlElement) {
        expect(bulletList.nodeName).toBe('bulletList')
        expect(bulletList.length).toBe(2) // Two list items
      }

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })

    it('should handle code blocks', async () => {
      const codeContent = {
        type: 'doc',
        content: [
          {
            type: 'codeBlock',
            attrs: { language: 'typescript' },
            content: [{ type: 'text', text: 'const x = 1;\nconsole.log(x);' }]
          }
        ]
      }

      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Code Block Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(codeContent), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      const result = await pool.query<ContentRow>(
        'SELECT content FROM documents WHERE id = $1',
        [docId]
      )

      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      jsonToYjs(doc, fragment, requireFirstRow(result.rows).content)

      expect(fragment.length).toBe(1)

      const codeBlock = fragment.get(0)
      expect(codeBlock).toBeInstanceOf(Y.XmlElement)
      if (codeBlock instanceof Y.XmlElement) {
        expect(codeBlock.nodeName).toBe('codeBlock')
        expect(codeBlock.getAttribute('language')).toBe('typescript')
      }

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })
  })

  describe('Document Type Content Preservation', () => {
    const documentTypes = ['wiki', 'issue', 'project', 'sprint', 'program'] as const

    for (const docType of documentTypes) {
      it(`should preserve content for ${docType} document type`, async () => {
        const testContent = {
          type: 'doc',
          content: [
            {
              type: 'paragraph',
              content: [{ type: 'text', text: `Content for ${docType}` }]
            }
          ]
        }

        const docResult = await pool.query<DocumentContentRow>(
          `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
           VALUES ($1, $2, $3, $4, $5)
           RETURNING id, content, yjs_state`,
          [testWorkspaceId, docType, `${docType} Test`, JSON.stringify(testContent), testUserId]
        )

        const docId = requireFirstRow(docResult.rows).id

        // Simulate collaboration server loading
        const doc = new Y.Doc()
        const fragment = doc.getXmlFragment('default')
        jsonToYjs(doc, fragment, requireFirstRow(docResult.rows).content)

        // Verify content was preserved
        expect(fragment.length).toBe(1)

        // Convert back and check text
        const convertedBack = yjsToJson(fragment)
        expect(convertedBack.content[0].content[0].text).toBe(`Content for ${docType}`)

        // Cleanup
        await pool.query('DELETE FROM documents WHERE id = $1', [docId])
      })
    }
  })

  describe('Content Update Scenarios', () => {
    it('should preserve content after PATCH /content update', async () => {
      // Create document with initial content
      const initialContent = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Initial content' }]
          }
        ]
      }

      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Update Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(initialContent), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Simulate PATCH /content update (what the API does)
      const updatedContent = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Updated content via API' }]
          },
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Second paragraph added' }]
          }
        ]
      }

      await pool.query(
        `UPDATE documents SET content = $1, yjs_state = NULL, updated_at = now()
         WHERE id = $2`,
        [JSON.stringify(updatedContent), docId]
      )

      // Simulate collaboration server reloading after invalidation
      const result = await pool.query<DocumentStateRow>(
        'SELECT content, yjs_state FROM documents WHERE id = $1',
        [docId]
      )

      expect(requireFirstRow(result.rows).yjs_state).toBeNull()

      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      jsonToYjs(doc, fragment, requireFirstRow(result.rows).content)

      // Should have both paragraphs
      expect(fragment.length).toBe(2)

      const convertedBack = yjsToJson(fragment)
      expect(convertedBack.content[0].content[0].text).toBe('Updated content via API')
      expect(convertedBack.content[1].content[0].text).toBe('Second paragraph added')

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })

    it('should handle Yjs state being persisted and reloaded', async () => {
      const content = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Will be persisted as Yjs' }]
          }
        ]
      }

      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Yjs Persist Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(content), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Convert to Yjs and persist (what collaboration server does)
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      jsonToYjs(doc, fragment, content)

      const yjsState = Y.encodeStateAsUpdate(doc)

      await pool.query(
        `UPDATE documents SET yjs_state = $1 WHERE id = $2`,
        [Buffer.from(yjsState), docId]
      )

      // Now reload from yjs_state (preferred path)
