  describe('Content invalidation and reload', () => {
    it('should correctly reload content after yjs_state is cleared', async () => {
      const initialContent = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Initial content' }]
          }
        ]
      }

      // Create document with initial content
      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Invalidation Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(initialContent), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Simulate first browser load - convert JSON to Yjs
      const doc1 = new Y.Doc()
      const fragment1 = doc1.getXmlFragment('default')
      jsonToYjs(doc1, fragment1, initialContent)

      // Persist yjs_state (what collaboration server does)
      const yjsState = Y.encodeStateAsUpdate(doc1)
      await pool.query(
        `UPDATE documents SET yjs_state = $1 WHERE id = $2`,
        [Buffer.from(yjsState), docId]
      )

      // Simulate API content update (clears yjs_state)
      const updatedContent = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Updated via API' }]
          }
        ]
      }

      await pool.query(
        `UPDATE documents SET content = $1, yjs_state = NULL WHERE id = $2`,
        [JSON.stringify(updatedContent), docId]
      )

      // Simulate second browser load after invalidation
      const result = await pool.query<DocumentStateRow>(
        'SELECT yjs_state, content FROM documents WHERE id = $1',
        [docId]
      )

      // yjs_state should be NULL after API update
      expect(requireFirstRow(result.rows).yjs_state).toBeNull()

      // Create new Y.Doc and load from content
      const doc2 = new Y.Doc()
      const fragment2 = doc2.getXmlFragment('default')

      const content = requireFirstRow(result.rows).content
      if (content && content.type === 'doc' && Array.isArray(content.content)) {
        jsonToYjs(doc2, fragment2, content)
      }

      // Verify updated content was loaded
      expect(fragment2.length).toBe(1)

      const convertedBack = yjsToJson(fragment2)
      expect(convertedBack.content[0].content[0].text).toBe('Updated via API')

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })

    it('should handle concurrent content updates gracefully', async () => {
      const content1 = {
        type: 'doc',
        content: [
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Version 1' }]
          }
        ]
      }

      // Create document
      const docResult = await pool.query<IdRow>(
        `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
         VALUES ($1, 'wiki', 'Concurrent Update Test', $2, $3)
         RETURNING id`,
        [testWorkspaceId, JSON.stringify(content1), testUserId]
      )

      const docId = requireFirstRow(docResult.rows).id

      // Simulate multiple API updates in sequence
      for (let i = 2; i <= 5; i++) {
        const contentN = {
          type: 'doc',
          content: [
            {
              type: 'paragraph',
              content: [{ type: 'text', text: `Version ${i}` }]
            }
          ]
        }

        await pool.query(
          `UPDATE documents SET content = $1, yjs_state = NULL WHERE id = $2`,
          [JSON.stringify(contentN), docId]
        )
      }

      // Final load should have version 5
      const result = await pool.query<ContentRow>(
        'SELECT content FROM documents WHERE id = $1',
        [docId]
      )

      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      jsonToYjs(doc, fragment, requireFirstRow(result.rows).content)

      const convertedBack = yjsToJson(fragment)
      expect(convertedBack.content[0].content[0].text).toBe('Version 5')

      // Cleanup
      await pool.query('DELETE FROM documents WHERE id = $1', [docId])
    })
  })
})

import { describe, it, expect, beforeAll, afterAll } from 'vitest'
import * as Y from 'yjs'
import type { WebSocket } from 'ws'
import { pool } from '../../db/client.js'
import crypto from 'crypto'
import { __collaborationSecurityTestHooks, isAllowedWebSocketOrigin } from '../index.js'

/**
 * Collaboration server tests
 *
 * Tests for the WebSocket collaboration module covering:
 * - Rate limiting (connection and message)
 * - Document ID parsing
 * - Yjs to JSON and JSON to Yjs conversion
 * - Visibility change handling
 * - Document conversion handling
 * - Document persistence
 */

// Import the module to test internal functions
// We need to re-export some internals for testing, or test via behavior

describe('Collaboration Server', () => {
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
  const testWorkspaceName = `Collab Test ${testRunId}`

  let testWorkspaceId: string
  let testUserId: string
  let testUser2Id: string
  let testDocId: string

  beforeAll(async () => {
    // Create test workspace
    const workspaceResult = await pool.query(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [testWorkspaceName]
    )
    testWorkspaceId = workspaceResult.rows[0].id

    // Create test users
    const userResult = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Collab User 1') RETURNING id`,
      [`collab-user1-${testRunId}@test.local`]
    )
    testUserId = userResult.rows[0].id

    const user2Result = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Collab User 2') RETURNING id`,
      [`collab-user2-${testRunId}@test.local`]
    )
    testUser2Id = user2Result.rows[0].id

    // Create workspace memberships
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role) VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    )
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role) VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUser2Id]
    )

    // Create test document
    const docResult = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by)
       VALUES ($1, 'wiki', 'Test Collab Doc', 'workspace', $2)
       RETURNING id`,
      [testWorkspaceId, testUserId]
    )
    testDocId = docResult.rows[0].id
  })

  afterAll(async () => {
    await pool.query('DELETE FROM sessions WHERE user_id IN ($1, $2)', [testUserId, testUser2Id])
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [testWorkspaceId])
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [testWorkspaceId])
    await pool.query('DELETE FROM users WHERE id IN ($1, $2)', [testUserId, testUser2Id])
    await pool.query('DELETE FROM users WHERE email LIKE $1', [`collab-%-${testRunId}@test.local`])
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId])
  })

  describe('Document ID Parsing', () => {
    // Test parseDocId behavior by testing document lookup patterns
    it('should extract UUID from doc:uuid format', async () => {
      // The collaboration server uses parseDocId to extract UUID from room names like "wiki:uuid"
      // We test this by verifying documents can be looked up using just the UUID part
      const result = await pool.query(
        'SELECT id FROM documents WHERE id = $1',
        [testDocId]
      )
      expect(result.rows[0].id).toBe(testDocId)
    })

    it('should handle plain UUID format', async () => {
      // parseDocId handles both "type:uuid" and just "uuid"
      // We verify the document can be accessed by UUID directly
      const uuid = testDocId
      const result = await pool.query(
        'SELECT id FROM documents WHERE id = $1',
        [uuid]
      )
      expect(result.rows[0]).toBeDefined()
    })
  })

  describe('WebSocket Origin Validation', () => {
    const originalNodeEnv = process.env.NODE_ENV

    afterAll(() => {
      process.env.NODE_ENV = originalNodeEnv
    })

    it('allows wildcard origin only outside production', () => {
      process.env.NODE_ENV = 'test'
      expect(isAllowedWebSocketOrigin('https://attacker.example', '*')).toBe(true)

      process.env.NODE_ENV = 'production'
      expect(isAllowedWebSocketOrigin('https://attacker.example', '*')).toBe(false)
    })

    it('allows explicit matching origin and rejects wrong origin', () => {
      process.env.NODE_ENV = 'production'
      expect(isAllowedWebSocketOrigin('https://app.example/path', 'https://app.example')).toBe(true)
      expect(isAllowedWebSocketOrigin('https://attacker.example', 'https://app.example')).toBe(false)
    })
  })

  describe('Collaboration Cache Limits', () => {
    afterAll(() => {
      __collaborationSecurityTestHooks.docs.clear()
      __collaborationSecurityTestHooks.awareness.clear()
      __collaborationSecurityTestHooks.conns.clear()
      __collaborationSecurityTestHooks.eventConns.clear()
    })

    it('evicts inactive cached documents before rejecting new rooms', () => {
      __collaborationSecurityTestHooks.docs.clear()
      __collaborationSecurityTestHooks.awareness.clear()
      __collaborationSecurityTestHooks.conns.clear()

      for (let i = 0; i < __collaborationSecurityTestHooks.rateLimit.MAX_CACHED_DOCS; i += 1) {
        __collaborationSecurityTestHooks.docs.set(`wiki:${crypto.randomUUID()}`, new Y.Doc())
      }

      expect(__collaborationSecurityTestHooks.canAcceptCachedDoc(`wiki:${crypto.randomUUID()}`)).toBe(true)
    })

    it('rejects new document rooms when the cache is full of active documents', () => {
      __collaborationSecurityTestHooks.docs.clear()
      __collaborationSecurityTestHooks.awareness.clear()
      __collaborationSecurityTestHooks.conns.clear()

      for (let i = 0; i < __collaborationSecurityTestHooks.rateLimit.MAX_CACHED_DOCS; i += 1) {
        const docName = `wiki:${crypto.randomUUID()}`
        __collaborationSecurityTestHooks.docs.set(docName, new Y.Doc())
        __collaborationSecurityTestHooks.conns.set({} as WebSocket, {
          docName,
          awarenessClientId: i,
          userId: testUserId,
          workspaceId: testWorkspaceId,
          principal: {
            kind: 'session',
            sessionId: `cache-session-${i}`,
            userId: testUserId,
            workspaceId: testWorkspaceId,
            isSuperAdmin: false,
          },
        })
      }

      expect(__collaborationSecurityTestHooks.canAcceptCachedDoc(`wiki:${crypto.randomUUID()}`)).toBe(false)
    })
  })

  describe('Collaboration History Attribution', () => {
    let creatorId: string
    let editorId: string
    let personId: string
    let weeklyPlanId: string

    beforeAll(async () => {
      const creator = await pool.query(
        `INSERT INTO users (email, password_hash, name)
         VALUES ($1, 'test-hash', 'Collab Creator') RETURNING id`,
        [`collab-creator-${testRunId}@test.local`]
      )
      creatorId = creator.rows[0].id

      const editor = await pool.query(
        `INSERT INTO users (email, password_hash, name)
         VALUES ($1, 'test-hash', 'Collab Editor') RETURNING id`,
        [`collab-editor-${testRunId}@test.local`]
      )
      editorId = editor.rows[0].id

      await pool.query(
        `INSERT INTO workspace_memberships (workspace_id, user_id, role)
         VALUES ($1, $2, 'member'), ($1, $3, 'member')`,
        [testWorkspaceId, creatorId, editorId]
      )

      const person = await pool.query(
        `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by, properties)
         VALUES ($1, 'person', 'Collab Editor Person', 'workspace', $2, $3)
         RETURNING id`,
        [testWorkspaceId, editorId, JSON.stringify({ user_id: editorId })]
      )
      personId = person.rows[0].id

      const weeklyPlan = await pool.query(
        `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by, properties, content)
         VALUES ($1, 'weekly_plan', 'Creator Plan', 'workspace', $2, $3, $4)
         RETURNING id`,
        [
          testWorkspaceId,
          creatorId,
          JSON.stringify({ person_id: personId, week_number: 1 }),
          JSON.stringify({ type: 'doc', content: [] }),
        ]
      )
      weeklyPlanId = weeklyPlan.rows[0].id
    })

    it('attributes persisted weekly plan history to the editing principal', async () => {
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')
      doc.transact(() => {
        const paragraph = new Y.XmlElement('paragraph')
        fragment.push([paragraph])
        const text = new Y.XmlText()
        paragraph.push([text])
        text.insert(0, 'Editor-owned collaboration content')
      })

      await __collaborationSecurityTestHooks.persistDocumentStrict(`weekly_plan:${weeklyPlanId}`, doc, {
        kind: 'session',
        sessionId: `test-session-${testRunId}`,
        userId: editorId,
        workspaceId: testWorkspaceId,
        isSuperAdmin: false,
      })

      const history = await pool.query(
        `SELECT changed_by FROM document_history
         WHERE document_id = $1 AND field = 'content'
         ORDER BY created_at DESC
         LIMIT 1`,
        [weeklyPlanId]
      )
      expect(history.rows[0]?.changed_by).toBe(editorId)
      expect(history.rows[0]?.changed_by).not.toBe(creatorId)
    })
  })

  describe('Session Revalidation', () => {
    it('closes an active connection when its session has been revoked', async () => {
      const sessionId = crypto.randomBytes(32).toString('hex')
      await pool.query(
        `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
         VALUES ($1, $2, $3, now() + interval '1 hour')`,
        [sessionId, testUserId, testWorkspaceId]
      )
      await pool.query('DELETE FROM sessions WHERE id = $1', [sessionId])

      const closeCalls: Array<{ code: number; reason: string }> = []
      const ws = {
        close(code: number, reason: string) {
          closeCalls.push({ code, reason })
        },
      } as WebSocket

      await __collaborationSecurityTestHooks.revalidateConnection(ws, {
        kind: 'session',
        sessionId,
        userId: testUserId,
        workspaceId: testWorkspaceId,
        isSuperAdmin: false,
      })

      expect(closeCalls).toEqual([{ code: 4401, reason: 'Session expired' }])
    })
  })

  describe('Yjs Document State', () => {
    it('should create and persist Yjs state to database', async () => {
      // Create a Yjs doc with content
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')

      doc.transact(() => {
        const paragraph = new Y.XmlElement('paragraph')
        fragment.push([paragraph])
        const text = new Y.XmlText()
        paragraph.push([text])
        text.insert(0, 'Test content for persistence')
      })

      // Encode state
      const state = Y.encodeStateAsUpdate(doc)

      // Store in database
      await pool.query(
        `UPDATE documents SET yjs_state = $1, updated_at = now() WHERE id = $2`,
        [Buffer.from(state), testDocId]
      )

      // Retrieve and verify
      const result = await pool.query(
        'SELECT yjs_state FROM documents WHERE id = $1',
        [testDocId]
      )

      expect(result.rows[0].yjs_state).toBeDefined()

      // Verify content can be decoded
      const loadedDoc = new Y.Doc()
      Y.applyUpdate(loadedDoc, new Uint8Array(result.rows[0].yjs_state))

      const loadedFragment = loadedDoc.getXmlFragment('default')
      expect(loadedFragment.length).toBeGreaterThan(0)
    })

    it('should merge concurrent Yjs updates correctly', async () => {
      // Create two docs simulating concurrent edits
      const doc1 = new Y.Doc()
      const doc2 = new Y.Doc()

      // User 1 makes an edit
      const fragment1 = doc1.getXmlFragment('default')
      doc1.transact(() => {
        const p = new Y.XmlElement('paragraph')
        fragment1.push([p])
        const t = new Y.XmlText()
        p.push([t])
        t.insert(0, 'User 1 content')
      })

      // User 2 makes a different edit
      const fragment2 = doc2.getXmlFragment('default')
      doc2.transact(() => {
        const p = new Y.XmlElement('paragraph')
        fragment2.push([p])
        const t = new Y.XmlText()
        p.push([t])
        t.insert(0, 'User 2 content')
      })

      // Exchange updates (simulate sync)
      const update1 = Y.encodeStateAsUpdate(doc1)
      const update2 = Y.encodeStateAsUpdate(doc2)

      Y.applyUpdate(doc1, update2)
      Y.applyUpdate(doc2, update1)

      // Both docs should now have both edits
      expect(doc1.getXmlFragment('default').length).toBe(2)
      expect(doc2.getXmlFragment('default').length).toBe(2)
    })
  })

  describe('Yjs JSON Conversion', () => {
    it('should convert TipTap JSON to Yjs and back', async () => {
      const tipTapContent = {
        type: 'doc',
        content: [
          {
            type: 'heading',
            attrs: { level: 1 },
            content: [{ type: 'text', text: 'Test Heading' }]
          },
          {
            type: 'paragraph',
            content: [{ type: 'text', text: 'Test paragraph content.' }]
          }
        ]
      }

      // Create Yjs doc and convert from JSON
      const doc = new Y.Doc()
      const fragment = doc.getXmlFragment('default')

      // Replicate jsonToYjs logic
      doc.transact(() => {
        for (const node of tipTapContent.content) {
          const element = new Y.XmlElement(node.type)
          fragment.push([element])
          if (node.attrs) {
            for (const [key, value] of Object.entries(node.attrs)) {
              element.setAttribute(key, String(value))
            }
          }
          if (node.content) {
            for (const child of node.content) {
              if (child.type === 'text') {
                const text = new Y.XmlText()
                element.push([text])
                text.insert(0, child.text || '')
              }
            }
          }
        }
      })

      // Verify structure
      expect(fragment.length).toBe(2)

      // First element should be heading
      const heading = fragment.get(0)
      expect(heading).toBeInstanceOf(Y.XmlElement)
      if (heading instanceof Y.XmlElement) {
        expect(heading.nodeName).toBe('heading')
        expect(heading.getAttribute('level')).toBe('1')
      }

      // Second element should be paragraph
      const paragraph = fragment.get(1)
      expect(paragraph).toBeInstanceOf(Y.XmlElement)
      if (paragraph instanceof Y.XmlElement) {
        expect(paragraph.nodeName).toBe('paragraph')
      }
    })

