// Context chat resolves bounded page/notification capsules into deterministic or model-backed answers.
import { pool } from '../../db/client.js';
import { resolveInitialContent } from '../../db/document-content-codec.js';
import { authorize } from '../../security/capabilities.js';
import type { Principal } from '../../security/principal.js';
import { visibleOutputForFinding } from '../evidence.js';
import type { FleetGraphFinding } from '../persistence.js';
import type { FleetGraphInput, FleetGraphVisibleOutput } from '../types.js';
import type { FleetGraphChatHistoryEntry, FleetGraphEvidenceItem, FleetGraphPageContext } from '@ship/shared';
import {
  unsupportedChatAnswer,
  type FleetGraphChatAnswerPayload,
} from './chat.js';

type QueryRunner = Pick<typeof pool, 'query'>;

export type ContextChatContext = Extract<FleetGraphInput['trigger'], { type: 'context_chat' }>['context'];

export type ContextChatDocument = {
  id: string;
  document_type: string;
  title: string;
  properties: Record<string, unknown>;
  content: unknown;
  belongsTo: Array<{ type: string; title: string }>;
};

export type ContextChatSignal = {
  finding: FleetGraphFinding;
  output: FleetGraphVisibleOutput;
  evidence: FleetGraphEvidenceItem[];
};

export type ContextChatBundle = {
  documents: ContextChatDocument[];
  signals: ContextChatSignal[];
  pages: FleetGraphPageContext[];
  visibleOutput?: FleetGraphVisibleOutput;
  evidence: FleetGraphEvidenceItem[];
};

export type ContextChatPersistencePort = {
  getFinding(workspaceId: string, findingId: string): Promise<FleetGraphFinding | null>;
  listFindingsForSource(input: {
    workspaceId: string;
    sourceIssueId?: string;
    sourceSprintId?: string;
  }): Promise<FleetGraphFinding[]>;
};

export type ContextChatResolveOptions = {
  db?: QueryRunner;
  principal?: Principal;
};

export async function resolveContextChatBundle(
  input: FleetGraphInput & { trigger: Extract<FleetGraphInput['trigger'], { type: 'context_chat' }> },
  persistence: ContextChatPersistencePort,
  options: ContextChatResolveOptions
): Promise<ContextChatBundle> {
  const contexts = uniqueChatContexts([input.trigger.context, ...(input.trigger.context.attachedContexts ?? [])]);
  const documents: ContextChatDocument[] = [];
  const signals: ContextChatSignal[] = [];
  const pages: FleetGraphPageContext[] = [];
  const evidence: FleetGraphEvidenceItem[] = [];

  const documentIds = new Set<string>();
  const documentLoads: Array<Promise<ContextChatDocument | null>> = [];
  const findingLookups = contexts.map((context) => resolveFindingForChatContext(input, persistence, context));
  const findings = await Promise.all(findingLookups);
  const visibleLookups = findings.map((finding) => finding
    ? visibleOutputForFinding({
      principal: input.principal,
      workspaceId: input.workspaceId,
      finding,
      db: options.db,
    })
    : Promise.resolve(null));
  const visibles = await Promise.all(visibleLookups);

  const queueDocumentLoad = (documentId: string | null | undefined) => {
    if (!documentId || documentIds.has(documentId)) return;
    documentIds.add(documentId);
    documentLoads.push(loadContextChatDocument({
      db: options.db,
      principal: input.principal,
      workspaceId: input.workspaceId,
      documentId,
    }));
  };

  for (let index = 0; index < contexts.length; index += 1) {
    const context = contexts[index];
    if (!context) continue;

    if (context.pageContext) {
      pages.push(context.pageContext);
      for (const documentId of documentIdsFromPageContext(context.pageContext)) {
        queueDocumentLoad(documentId);
      }
    }

    const finding = findings[index];
    const visible = visibles[index];
    if (finding && visible) {
      if (!visible.output.noSafeOutput) {
        signals.push({ finding, output: visible.output, evidence: visible.evidence });
        evidence.push(...visible.evidence);
      }
      queueDocumentLoad(finding.source_issue_id);
      queueDocumentLoad(finding.source_sprint_id);
      continue;
    }

    queueDocumentLoad(context.documentId ?? documentIdFromSourcePath(context.sourcePath));
  }

  const loadedDocuments = await Promise.all(documentLoads);
  for (const document of loadedDocuments) {
    if (document) documents.push(document);
  }

  return {
    documents: uniqueDocuments(documents),
    signals,
    pages: uniquePages(pages),
    visibleOutput: signals[0]?.output,
    evidence,
  };
}

export function contextTextForModel(bundle: ContextChatBundle): string {
  const documentById = new Map(bundle.documents.map((document) => [document.id, document]));
  const documentText = bundle.documents.map((document) => [
    `Title: ${document.title}`,
    `Type: ${document.document_type}`,
    compactDocumentProperties(document.properties).join(' '),
    document.belongsTo.length > 0 ? `Connected to: ${document.belongsTo.map((item) => `${item.type} ${item.title}`).join(', ')}` : '',
    textFromTipTap(document.content),
  ].filter(Boolean).join('\n')).join('\n\n');
  const signalText = bundle.signals.map((signal) => [
    `Signal: ${signal.output.title}`,
    `Summary: ${signal.output.summary}`,
    `Reason: ${signalReason(signal.output) ?? ''}`,
    `Recommended action: ${recommendedActionFromOutput(signal.output) ?? ''}`,
  ].filter(Boolean).join('\n')).join('\n\n');
  const pageText = bundle.pages.map((page) => [
    `Surface: ${page.surface}`,
    `Route: ${page.route}`,
    `Visible item count hint: ${page.visibleItems.length}`,
    page.selectedItemIds?.length ? `Selected item count hint: ${page.selectedItemIds.length}` : '',
    authorizedDocumentsForPage(page, documentById).length
      ? `Authorized items: ${authorizedDocumentsForPage(page, documentById).map(pageDocumentLabel).join('; ')}`
      : 'Authorized items: none loaded',
  ].filter(Boolean).join('\n')).join('\n\n');

  return [pageText, documentText, signalText].filter(Boolean).join('\n\n---\n\n');
}

export function sourcesFromContextBundle(bundle: ContextChatBundle): Array<{ label: string; kind: string }> {
  return [
    ...bundle.pages.map((page) => ({ label: pageSourceLabel(page.surface), kind: page.surface })),
    ...bundle.documents.map((document) => ({ label: document.title, kind: document.document_type })),
    ...bundle.signals.map((signal) => ({ label: signal.output.title, kind: 'finding' })),
  ].filter((source, index, items) => items.findIndex((item) => item.label === source.label) === index);
}

export function deterministicContextChatAnswer(
  prompt: string,
  bundle: ContextChatBundle,
  history: FleetGraphChatHistoryEntry[] = []
): FleetGraphChatAnswerPayload {
  const primaryDocument = bundle.documents[0];
  const primarySignal = bundle.signals[0];
  const primaryPage = bundle.pages[0];
  const sources = sourcesFromContextBundle(bundle);
  const normalized = prompt.trim().toLowerCase();
  const conversation = conversationFromHistory(history);
  const asksForShipAction = asksForAction(normalized);
  const asksForExternalShipAction = asksForExternalAction(normalized);

  if (/^(hi|hello|hey|yo|sup)[!.?\s]*$/.test(normalized)) {
    return {
      title: 'Chat',
      body: 'Hi. What would you like to look at?',
      sources,
      humanGate: { required: false },
    };
  }

  const generalAnswer = generalConversationAnswer(normalized);
  if (generalAnswer) {
    return {
      title: 'Chat',
      body: generalAnswer,
      sources,
      humanGate: { required: false },
    };
  }

  const hasVisibleShipContext = bundle.documents.length > 0 || bundle.signals.length > 0 || bundle.pages.length > 0;
  const contextIntent = promptTargetsShipContext(normalized, conversation) || (hasVisibleShipContext && asksForShipAction);
  if (!contextIntent) {
    return {
      title: 'Chat',
      body: openConversationAnswer(prompt),
      sources,
      humanGate: { required: false },
    };
  }

  const [firstDocument, ...otherDocuments] = bundle.documents;
  if (asksForComparison(normalized) && firstDocument && otherDocuments.length > 0) {
    return {
      title: 'Context comparison',
      body: compareDocumentsAnswer(firstDocument, otherDocuments, primarySignal),
      sources,
      humanGate: { required: false },
    };
  }

  if (primaryDocument && asksAboutMissingContent(normalized)) {
    return {
      title: primaryDocument.title,
      body: missingContentAnswer(primaryDocument, primarySignal),
      sources,
      humanGate: asksForShipAction ? actionHumanGate(primarySignal) : { required: false },
    };
  }

  if (primarySignal && signalSpecificPrompt(normalized)) {
    return signalAnswer(normalized, primarySignal, sources);
  }

  if (primaryDocument) {
    if (asksForListFormat(normalized)) {
      return {
        title: primaryDocument.title,
        body: bulletAnswerFromDocument(primaryDocument, bundle.documents.slice(1), primarySignal, conversation.previousAssistantAnswer),
        sources,
        humanGate: asksForShipAction && primarySignal ? primarySignal.output.humanGate : { required: false },
      };
    }

    if (asksForComparison(normalized) && bundle.documents.length > 1) {
      return {
        title: 'Compare context',
        body: compareDocumentsAnswer(primaryDocument, bundle.documents.slice(1), primarySignal),
        sources,
        humanGate: { required: false },
      };
    }

    if (asksForWhy(normalized) && primarySignal) {
      return {
        title: primarySignal.output.title,
        body: signalReason(primarySignal.output) ?? primarySignal.output.summary,
        sources,
        humanGate: { required: false },
      };
    }

    const nextStep = primarySignal ? recommendedActionFromOutput(primarySignal.output) : undefined;
    return {
      title: primaryDocument.title,
      body: fallbackAnswer(prompt, primaryDocument, bundle.documents.slice(1), primarySignal, conversation),
      ...(asksForShipAction && nextStep
        ? { nextStep }
        : {}),
      sources,
      humanGate: asksForExternalShipAction
        ? actionHumanGate(primarySignal)
        : asksForShipAction ? primarySignal?.output.humanGate ?? humanGateRequired() : { required: false },
    };
  }

  if (primarySignal) {
    return {
      title: primarySignal.output.title,
      body: signalReason(primarySignal.output) ?? primarySignal.output.summary,
      sources,
      humanGate: asksForExternalShipAction ? actionHumanGate(primarySignal) : { required: false },
    };
  }

  if (primaryPage) {
    return pageAnswer(prompt, primaryPage, bundle.documents, sources);
  }

  return unsupportedChatAnswer('I do not have visible context for that yet.');
}

function pageAnswer(
  prompt: string,
  page: FleetGraphPageContext,
  documents: ContextChatDocument[],
  sources: Array<{ label: string; kind: string }>
): FleetGraphChatAnswerPayload {
  const selected = page.selectedItemIds?.length ? `${page.selectedItemIds.length} selected.` : 'Nothing selected.';
  const documentById = new Map(documents.map((document) => [document.id, document]));
  const visible = authorizedDocumentsForPage(page, documentById).slice(0, 5).map(pageDocumentLabel).join('; ');
  const asksForActionPlan = asksForAction(prompt.toLowerCase());
  return {
    title: pageSourceLabel(page.surface),
    body: [
      `This ${page.surface.replace(/_/g, ' ')} context includes ${page.visibleItems.length} visible item hint${page.visibleItems.length === 1 ? '' : 's'}. ${selected}`,
      visible ? `Authorized items: ${visible}.` : 'I do not have authorized source records loaded for those page items yet.',
      asksForActionPlan ? 'I can reason from this context, but changing Ship records or contacting people still needs human approval.' : null,
    ].filter(Boolean).join('\n\n'),
    sources,
    humanGate: asksForActionPlan ? humanGateRequired() : { required: false },
  };
}

function signalSpecificPrompt(normalizedPrompt: string): boolean {
  return /\b(why|flagged|blocked|blocker|stale|risk|urgent|urgency|reason|attention|signal|next step|next move|what next|what should (i|we) do|unblock|owner|approver|dependency)\b/.test(normalizedPrompt);
}

function signalAnswer(
  normalizedPrompt: string,
  signal: ContextChatSignal,
  sources: Array<{ label: string; kind: string }>
): FleetGraphChatAnswerPayload {
  const reason = signalReason(signal.output) ?? signal.output.summary;
  const nextStep = recommendedActionFromOutput(signal.output);
  const externalAction = asksForExternalAction(normalizedPrompt);
  if (asksForAction(normalizedPrompt)) {
    return {
      title: 'Next move',
      body: externalAction
        ? [nextStep || reason, 'This needs human approval before FleetGraph changes Ship data or contacts anyone.'].join('\n\n')
        : nextStep || reason,
      ...(nextStep ? { nextStep } : {}),
      sources,
      humanGate: asksForAction(normalizedPrompt) ? actionHumanGate(signal) : signal.output.humanGate,
    };
  }

  return {
    title: signal.output.title,
    body: reason,
    sources,
    humanGate: { required: false },
  };
}

function asksForAction(normalizedPrompt: string): boolean {
  return /\b(next step|next move|what next|what should (i|we) do|unblock|owner|approver|action item)\b/.test(normalizedPrompt)
    || asksForExternalAction(normalizedPrompt);
}

function asksForExternalAction(normalizedPrompt: string): boolean {
  return /\b(send|sent|message|email|contact|notify|assign|change|mark|close|resolve)\b/.test(normalizedPrompt);
}

function asksForFormatChange(normalizedPrompt: string): boolean {
  return asksForListFormat(normalizedPrompt) || /\b(make (that|it) simpler|simpler|shorter|plain|tl;dr|tldr)\b/.test(normalizedPrompt);
}

function asksForListFormat(normalizedPrompt: string): boolean {
  return /\b(bullet|bullets|bullet points|format as|make (that|it) (a )?list)\b/.test(normalizedPrompt);
}

function asksForComparison(normalizedPrompt: string): boolean {
  return /\b(compare|contrast|difference|differences|versus|both|other context|other doc|other document|what else is attached)\b| vs\.? /.test(normalizedPrompt);
}

function asksForWhy(normalizedPrompt: string): boolean {
  return /\b(why|reason|because|what caused|how come)\b/.test(normalizedPrompt);
}

function asksAboutMissingContent(normalizedPrompt: string): boolean {
  return /\b(empty|blank|missing|no description|no information|no info|supposed to do|what.*do)\b/.test(normalizedPrompt)
    && /\b(why|description|information|info|issue|ticket|body|content|supposed to do|do)\b/.test(normalizedPrompt);
}

function generalConversationAnswer(normalizedPrompt: string, now = new Date()): string | null {
  if (/\b(what day is today|what date is today|today'?s date|what is today)\b/.test(normalizedPrompt)) {
    return `Today is ${new Intl.DateTimeFormat('en-US', {
      weekday: 'long',
      month: 'long',
      day: 'numeric',
      year: 'numeric',
    }).format(now)}.`;
  }

  if (/\b(linked list)\b/.test(normalizedPrompt) && /\b(python|code|traverse|iterate|loop)\b/.test(normalizedPrompt)) {
    return [
      'Here is the basic Python shape:',
      '',
      '```python',
      'class Node:',
      '    def __init__(self, value, next=None):',
      '        self.value = value',
      '        self.next = next',
      '',
      'current = head',
      'while current is not None:',
      '    print(current.value)',
      '    current = current.next',
      '```',
      '',
      'You keep a pointer to the current node, use it, then advance to `current.next` until there is no next node.',
    ].join('\n');
  }

  return null;
}

function promptTargetsShipContext(normalizedPrompt: string, conversation: ContextChatConversation): boolean {
  if (asksForAction(normalizedPrompt) || asksForComparison(normalizedPrompt) || asksForWhy(normalizedPrompt) || signalSpecificPrompt(normalizedPrompt)) {
    return true;
  }

  if (/\b(this|that|it|these|those|attached|attachment|context|current|selected|visible|page|document|doc|issue|ticket|week|sprint|project|program|notification|finding|risk|blocker|status|priority|owner|assignee|approval|dependency|summary|summarize|explain|describe|detail|details|source|ship|looking at)\b/.test(normalizedPrompt)) {
    return true;
  }

  return Boolean(conversation.previousAssistantAnswer && asksForFormatChange(normalizedPrompt));
}

function openConversationAnswer(prompt: string): string {
  const normalizedPrompt = prompt.trim().toLowerCase();
  const generalAnswer = generalConversationAnswer(normalizedPrompt);
  if (generalAnswer) return generalAnswer;

  if (/\bfavou?rite colou?r\b/.test(normalizedPrompt)) {
    return 'I do not have a real favorite color, but I usually like deep blue for interfaces because it stays calm without disappearing.';
  }

  if (/\b(who are you|what are you)\b/.test(normalizedPrompt)) {
    return 'I am Ship chat. I can talk normally, and I can use the attached Ship context when your question points at it.';
  }

  return 'I can talk about that normally. I will only use the attached Ship context when your question points at it.';
}

export function chatModelAnswerFromContext(body: string, bundle: ContextChatBundle): FleetGraphChatAnswerPayload {
  return {
    title: bundle.documents[0]?.title ?? bundle.signals[0]?.output.title ?? 'Chat',
    body: body || 'I do not have an answer for that yet.',
    sources: sourcesFromContextBundle(bundle),
    humanGate: { required: false },
  };
}

export function documentIdFromSourcePath(sourcePath: string | undefined): string | null {
  const match = sourcePath?.match(/^\/(?:documents|issues|projects|programs|sprints)\/([^/?#]+)/);
  return match?.[1] ?? null;
}

export async function loadContextChatDocument(input: {
  db?: QueryRunner;
  principal?: Principal;
  workspaceId: string;
  documentId: string;
}): Promise<ContextChatDocument | null> {
  if (!input.principal) return null;
  const db = input.db ?? pool;
  const decision = await authorize(db, input.principal, {
    resource: 'document',
    action: 'read',
    documentId: input.documentId,
  });
  if (!decision.allowed) return null;

  const result = await db.query<{
    id: string;
    document_type: string;
    title: string;
    properties: Record<string, unknown> | null;
    content: unknown;
    yjs_state: Buffer | null;
  }>(
    `SELECT id, document_type, title, properties, content, yjs_state
       FROM documents
      WHERE id = $1
        AND workspace_id = $2
        AND archived_at IS NULL
        AND deleted_at IS NULL`,
    [input.documentId, input.workspaceId]
  );
  const row = result.rows[0];
  if (!row) return null;

  const resolvedContent = resolveInitialContent({
    content: row.content,
    yjs_state: row.yjs_state,
  }).docJson ?? row.content;

  const associations = await db.query<{ type: string; title: string }>(
    `SELECT da.relationship_type AS type, d.title
       FROM document_associations da
       JOIN documents d ON d.id = da.related_id
      WHERE da.document_id = $1
        AND d.workspace_id = $2
        AND d.archived_at IS NULL
        AND d.deleted_at IS NULL
      ORDER BY da.relationship_type, d.title
      LIMIT 8`,
    [input.documentId, input.workspaceId]
  );

  return {
    id: row.id,
    document_type: row.document_type,
    title: row.title,
    properties: row.properties ?? {},
    content: resolvedContent,
    belongsTo: associations.rows,
  };
}

async function resolveFindingForChatContext(
  input: FleetGraphInput & { trigger: Extract<FleetGraphInput['trigger'], { type: 'context_chat' }> },
  persistence: ContextChatPersistencePort,
  context: ContextChatContext
): Promise<FleetGraphFinding | null> {
  if (context.findingId) return persistence.getFinding(input.workspaceId, context.findingId);

  const documentId = context.documentId ?? documentIdFromSourcePath(context.sourcePath);
  if (!documentId) return null;
  if (context.kind === 'sprint') {
    const findings = await persistence.listFindingsForSource({ workspaceId: input.workspaceId, sourceSprintId: documentId });
    return findings[0] ?? null;
  }
  if (context.kind === 'issue' || context.kind === 'document') {
    const findings = await persistence.listFindingsForSource({ workspaceId: input.workspaceId, sourceIssueId: documentId });
    return findings[0] ?? null;
  }

  return null;
}

function fallbackAnswer(
  prompt: string,
  document: ContextChatDocument,
  attachedDocuments: ContextChatDocument[],
  signal: ContextChatSignal | undefined,
  conversation: ContextChatConversation
): string {
  if (asksForExternalAction(prompt.toLowerCase())) {
    return actionRequestAnswer(document, signal);
  }

  if (/\b(simpler|simple|shorter|plain|tl;dr|tldr)\b/i.test(prompt)) {
    return simpleDocumentAnswer(document, signal, conversation);
  }

  if (/\b(why|how come|reason)\b/i.test(prompt) && conversation.previousAssistantAnswer) {
    return whyAnswer(document, attachedDocuments, signal);
  }

  if (/\bpython\b/i.test(prompt) && /\blinked list\b/i.test(prompt)) {
    return [
      'Here is the basic Python shape:',
      '',
      '```python',
      'class Node:',
      '    def __init__(self, value, next=None):',
      '        self.value = value',
      '        self.next = next',
      '',
      'current = head',
      'while current is not None:',
      '    print(current.value)',
      '    current = current.next',
      '```',
      '',
      'You keep a pointer to the current node, use it, then advance to `current.next` until there is no next node.',
    ].join('\n');
  }

  return documentAnswer(document, attachedDocuments, signal);
}

function actionRequestAnswer(
  document: ContextChatDocument,
  signal: ContextChatSignal | undefined
): string {
  const nextStep = signal ? recommendedActionFromOutput(signal.output) : null;
  return [
    nextStep ?? `I can explain the next step for ${document.title}.`,
    'This needs human approval before FleetGraph changes Ship data or contacts anyone.',
  ].join('\n\n');
}

function simpleDocumentAnswer(
  document: ContextChatDocument,
  signal: ContextChatSignal | undefined,
  conversation: ContextChatConversation
): string {
  if (conversation.previousAssistantAnswer && /\b(simpler|simple|shorter|plain|tl;dr|tldr)\b/i.test(conversation.previousUserPrompt ?? '')) {
    return shortestDocumentAnswer(document, signal);
  }

  const reason = signal ? signalReason(signal.output) : null;
  const support = reason ? null : strongestDocumentSentence(document);
  const state = stringFromUnknown(document.properties.state) ?? stringFromUnknown(document.properties.status);
  const priority = stringFromUnknown(document.properties.priority);
  const bits = [
    reason || `${document.title} needs attention.`,
    support,
    state ? `Status: ${state}.` : null,
    priority ? `Priority: ${priority}.` : null,
  ].filter(Boolean);
  return bits.join('\n\n');
}

function shortestDocumentAnswer(
  document: ContextChatDocument,
  signal: ContextChatSignal | undefined
): string {
  return [
    document.title,
    conciseFact(signal ? signalReason(signal.output) : strongestDocumentSentence(document)),
  ].filter(Boolean).join(' · ');
}

function documentAnswer(
  document: ContextChatDocument,
  attachedDocuments: ContextChatDocument[],
  signal: ContextChatSignal | undefined
): string {
  const lines: string[] = [];
  const contentText = textFromTipTap(document.content);
  const properties = compactDocumentProperties(document.properties);
  const belongsTo = document.belongsTo.map((item) => `${labelForDocumentType(item.type)}: ${item.title}`);

  const documentTypeLabel = labelForDocumentType(document.document_type);
  lines.push(`${document.title} is ${indefiniteArticle(documentTypeLabel)} ${documentTypeLabel}.`);
  if (properties.length > 0) lines.push(properties.join(' '));
  if (belongsTo.length > 0) lines.push(`It is connected to ${belongsTo.join(', ')}.`);
  if (contentText) lines.push(contentText);
  if (signal) {
    const reason = signalReason(signal.output);
    if (reason) lines.push(`Current signal: ${reason}`);
  }
  if (attachedDocuments.length > 0) {
    lines.push(attachedContextAnswer(attachedDocuments));
  }

  return lines.join('\n\n');
}

function missingContentAnswer(
  document: ContextChatDocument,
  signal: ContextChatSignal | undefined
): string {
  const contentText = textFromTipTap(document.content);
  const reason = signal ? signalReason(signal.output) : null;

  if (contentText) {
    return [
      `The issue is not empty; I can see this body text: ${conciseFact(contentText)}.`,
      reason ? `The FleetGraph signal is separate: ${reason}` : null,
    ].filter(Boolean).join('\n\n');
  }

  return [
    'I do not see a visible issue description or body text on the authorized issue record.',
    reason ? `The alert is coming from FleetGraph evidence instead: ${reason}` : 'I only have the issue fields, not enough body content to explain the intended work.',
    'So the honest answer is: the issue record looks under-described, while the risk signal still has enough evidence to flag it.',
  ].join('\n\n');
}

function actionHumanGate(signal: ContextChatSignal | undefined): Record<string, unknown> {
  if (signal?.output.humanGate?.required === true) return signal.output.humanGate;
  if (signal?.output.humanGate?.approvalRequired === true) return { ...signal.output.humanGate, required: true };
  return { required: true, reason: 'human_must_approve_before_ship_or_external_action' };
}

function bulletAnswerFromDocument(
  document: ContextChatDocument,
  attachedDocuments: ContextChatDocument[],
  signal: ContextChatSignal | undefined,
  previousAnswer?: string
): string {
  const text = previousAnswer?.trim() || documentAnswer(document, attachedDocuments, signal);
  const sentences = text
    .split(/(?<=[.!?])\s+/)
    .map((sentence) => sentence.trim())
    .filter(Boolean)
    .slice(0, 4);
  return sentences.map((sentence) => `- ${sentence.replace(/\s+/g, ' ')}`).join('\n');
}

type ContextChatConversation = {
  previousUserPrompt?: string;
  previousAssistantAnswer?: string;
};

function conversationFromHistory(history: FleetGraphChatHistoryEntry[]): ContextChatConversation {
  return {
    previousUserPrompt: lastHistoryContent(history, 'user') ?? undefined,
    previousAssistantAnswer: lastHistoryContent(history, 'assistant') ?? undefined,
  };
}

function lastHistoryContent(history: FleetGraphChatHistoryEntry[], role: FleetGraphChatHistoryEntry['role']): string | null {
  for (let index = history.length - 1; index >= 0; index--) {
    const entry = history[index];
    if (!entry) continue;
    if (entry.role === role && entry.content.trim()) return entry.content.trim();
  }
  return null;
}

function compactDocumentProperties(properties: Record<string, unknown>): string[] {
  const labels: Array<[string, string]> = [
    ['state', 'State'],
    ['status', 'Status'],
    ['priority', 'Priority'],
    ['source', 'Source'],
    ['plan_approval', 'Plan approval'],
    ['review_approval', 'Review approval'],
  ];
  return labels
    .map(([key, label]) => {
      const value = properties[key];
      return typeof value === 'string' && value.trim() ? `${label}: ${value.trim()}.` : null;
    })
    .filter((line): line is string => Boolean(line));
}

function attachedContextAnswer(attachedDocuments: ContextChatDocument[]): string {
  const facts = attachedDocuments.map((document) => {
    const fact = conciseFact(strongestDocumentSentence(document));
    return fact ? `${document.title}: ${fact}` : document.title;
  });
  return `Also in context: ${facts.join('; ')}.`;
}

function compareDocumentsAnswer(
  primaryDocument: ContextChatDocument,
  attachedDocuments: ContextChatDocument[],
  signal: ContextChatSignal | undefined
): string {
  const primaryFact = conciseFact(signal ? signalReason(signal.output) : strongestDocumentSentence(primaryDocument));
  const attachedFacts = attachedDocuments.map((document) => {
    const fact = conciseFact(strongestDocumentSentence(document)) ?? 'No extra detail visible.';
    return `- ${document.title}: ${fact}`;
  });
  return [
    `- ${primaryDocument.title}: ${primaryFact ?? 'No extra detail visible.'}`,
    ...attachedFacts,
  ].join('\n\n');
}

function whyAnswer(
  document: ContextChatDocument,
  attachedDocuments: ContextChatDocument[],
  signal: ContextChatSignal | undefined
): string {
  const reason = signal ? signalReason(signal.output) : strongestDocumentSentence(document);
  const attached = attachedDocuments.length > 0 ? ` ${attachedContextAnswer(attachedDocuments)}` : '';
  return [
    reason ? `Because ${lowercaseFirst(reason)}` : `${document.title} has limited visible context, so I can only explain from its current fields.`,
    attached.trim(),
  ].filter(Boolean).join('\n\n');
}

function lowercaseFirst(value: string): string {
  return value.replace(/^./, (letter) => letter.toLowerCase());
}

function textFromTipTap(value: unknown): string {
  const text = collectTipTapText(value).replace(/\s+/g, ' ').trim();
  if (!text) return '';
  return text.length > 900 ? `${text.slice(0, 900).trim()}...` : text;
}

function strongestDocumentSentence(document: ContextChatDocument): string | null {
  const text = textFromTipTap(document.content);
  if (!text) return null;
  const sentences = text.split(/(?<=[.!?])\s+/).map((sentence) => sentence.trim()).filter(Boolean);
  return sentences[0] ?? null;
}

function conciseFact(value: string | null): string | null {
  if (!value) return null;
  return value.length > 80 ? `${value.slice(0, 77).trim()}...` : value;
}

function collectTipTapText(value: unknown): string {
  if (!value || typeof value !== 'object') return '';
  const node = value as { text?: unknown; content?: unknown };
  const ownText = typeof node.text === 'string' ? node.text : '';
  const childText = Array.isArray(node.content) ? node.content.map(collectTipTapText).join(' ') : '';
  return [ownText, childText].filter(Boolean).join(' ');
}

function signalReason(output: FleetGraphVisibleOutput): string | null {
  return output.evidence.find((item) => item.kind === 'blocker' && item.excerpt?.trim())?.excerpt?.trim()
    || output.evidence.find((item) => ['stale', 'at_risk'].includes(item.kind) && item.claim?.trim())?.claim?.trim()
    || output.summary
    || null;
}

function recommendedActionFromOutput(output: FleetGraphVisibleOutput): string | undefined {
  return stringFromUnknown(output.recommendedAction?.text)
    || stringFromUnknown(output.recommendedAction?.summary)
    || stringFromUnknown(output.recommendedAction?.label)
    || undefined;
}

function humanGateRequired(): Record<string, unknown> {
  return { required: true, reason: 'human_must_approve_before_ship_or_external_action' };
}

function stringFromUnknown(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function labelForDocumentType(type: string): string {
  if (type === 'sprint') return 'week';
  return type.replace(/_/g, ' ');
}

function indefiniteArticle(label: string): 'a' | 'an' {
  return /^[aeiou]/i.test(label) ? 'an' : 'a';
}

function uniqueChatContexts(contexts: ContextChatContext[]): ContextChatContext[] {
  const seen = new Set<string>();
  return contexts.filter((context) => {
    const key = context.findingId
      ? `finding:${context.findingId}`
      : `document:${context.documentId ?? documentIdFromSourcePath(context.sourcePath) ?? context.pageContext?.route ?? context.kind}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function uniqueDocuments(documents: ContextChatDocument[]): ContextChatDocument[] {
  const seen = new Set<string>();
  return documents.filter((document) => {
    if (seen.has(document.id)) return false;
    seen.add(document.id);
    return true;
  });
}

function uniquePages(pages: FleetGraphPageContext[]): FleetGraphPageContext[] {
  const seen = new Set<string>();
  return pages.filter((page) => {
    const key = `${page.surface}:${page.route}:${page.title}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function documentIdsFromPageContext(page: FleetGraphPageContext): string[] {
  const ids = new Set<string>();
  for (const id of page.selectedItemIds ?? []) ids.add(id);
  for (const item of page.visibleItems.slice(0, 8)) {
    if (item.id) ids.add(item.id);
  }
  return [...ids].slice(0, 12);
}

function authorizedDocumentsForPage(
  page: FleetGraphPageContext,
  documentById: Map<string, ContextChatDocument>
): ContextChatDocument[] {
  const ids = documentIdsFromPageContext(page);
  return ids.map((id) => documentById.get(id)).filter((document): document is ContextChatDocument => Boolean(document));
}

function pageDocumentLabel(document: ContextChatDocument): string {
  return [
    document.title,
    stringFromUnknown(document.properties.state) ? `state ${stringFromUnknown(document.properties.state)}` : null,
    stringFromUnknown(document.properties.priority) ? `priority ${stringFromUnknown(document.properties.priority)}` : null,
  ].filter(Boolean).join(' · ');
}

function pageSourceLabel(surface: FleetGraphPageContext['surface']): string {
  return `Current ${surface.replace(/_/g, ' ')} page`;
}

#!/usr/bin/env node
/**
 * Ship MCP Server - Auto-generated from OpenAPI spec
 *
 * This server dynamically generates MCP tools by fetching the OpenAPI specification
 * from a running Ship instance. As the API changes, tools automatically stay in sync.
 *
 * Configuration is loaded from ~/.claude/.env:
 *   SHIP_API_TOKEN=xxx
 *   SHIP_URL=https://ship.example.com
 */

import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";
import type { Tool } from "@modelcontextprotocol/sdk/types.js";
import { readFileSync, existsSync } from "fs";
import { homedir } from "os";
import { join } from "path";

// ============== Configuration ==============

interface Config {
  token: string;
  url: string;
}

function loadConfig(): Config {
  const envPath = join(homedir(), ".claude", ".env");

  if (!existsSync(envPath)) {
    throw new Error("~/.claude/.env not found. Run /ship:auth first.");
  }

  const content = readFileSync(envPath, "utf-8");
  const lines = content.split("\n");

  let token = "";
  let url = "http://localhost:3001";

  for (const line of lines) {
    if (line.startsWith("SHIP_API_TOKEN=")) {
      token = line.substring("SHIP_API_TOKEN=".length).trim();
    } else if (line.startsWith("SHIP_URL=")) {
      url = line.substring("SHIP_URL=".length).trim();
    }
  }

  if (!token) {
    throw new Error("SHIP_API_TOKEN not found in ~/.claude/.env");
  }

  return { token, url };
}

// ============== OpenAPI Types (inline to avoid dependencies) ==============

interface OpenAPIObject {
  paths?: Record<string, PathItemObject>;
  components?: {
    schemas?: Record<string, SchemaObject>;
  };
}

interface PathItemObject {
  get?: OperationObject;
  post?: OperationObject;
  put?: OperationObject;
  patch?: OperationObject;
  delete?: OperationObject;
}

interface OperationObject {
  operationId?: string;
  summary?: string;
  description?: string;
  parameters?: ParameterObject[];
  requestBody?: {
    content?: {
      "application/json"?: {
        schema?: SchemaObject | ReferenceObject;
      };
    };
  };
}

interface ParameterObject {
  name: string;
  in: "path" | "query" | "header" | "cookie";
  required?: boolean;
  description?: string;
  schema?: SchemaObject | ReferenceObject;
}

interface SchemaObject {
  type?: string;
  description?: string;
  properties?: Record<string, SchemaObject | ReferenceObject>;
  required?: string[];
  items?: SchemaObject | ReferenceObject;
  enum?: unknown[];
}

interface ReferenceObject {
  $ref: string;
}

// ============== Tool Generation ==============

interface ToolOperation {
  method: string;
  path: string;
  operation: OperationObject;
}

// Map of tool name -> operation details
const toolOperations = new Map<string, ToolOperation>();

// Store config globally for use in executeToolCall
let CONFIG: Config;

/**
 * Fetch OpenAPI spec from the Ship instance
 */
async function fetchOpenAPISpec(url: string): Promise<OpenAPIObject> {
  const specUrl = `${url}/api/openapi.json`;
  console.error(`Fetching OpenAPI spec from ${specUrl}...`);

  const response = await fetch(specUrl);
  if (!response.ok) {
    throw new Error(
      `Failed to fetch OpenAPI spec: ${response.status} ${response.statusText}`
    );
  }

  return response.json() as Promise<OpenAPIObject>;
}

/**
 * Convert path to operationId-style string
 * e.g., "/accountability/action-items" -> "accountability_action_items"
 * e.g., "/projects/{id}" -> "projects_by_id"
 * e.g., "/issues/{id}/children" -> "issues_children"
 */
function pathToOperationId(method: string, path: string): string {
  // Replace {param} with descriptive suffix to avoid collisions
  // e.g., /projects/{id} vs /projects need different operationIds
  let cleanPath = path;

  // Check if path ends with a parameter like /{id}
  if (/\/\{[^}]+\}$/.test(path)) {
    cleanPath = path.replace(/\/\{[^}]+\}$/, "_by_id");
  }

  // Replace remaining {param} in middle of path with empty string
  cleanPath = cleanPath
    .replace(/\{[^}]+\}/g, "") // Remove middle {param}
    .replace(/\//g, "_") // / -> _
    .replace(/-/g, "_") // - -> _
    .replace(/_+/g, "_") // Collapse multiple _
    .replace(/^_|_$/g, ""); // Trim leading/trailing _

  return `${method}_${cleanPath}`;
}

/**
 * Convert OpenAPI operationId to MCP tool name
 */
function toToolName(operationId: string): string {
  if (operationId.includes("_")) {
    return `ship_${operationId}`;
  }
  return `ship_${operationId.replace(/([A-Z])/g, "_$1").toLowerCase()}`;
}

/**
 * Check if a schema is a reference object
 */
function isReference(
  schema: SchemaObject | ReferenceObject
): schema is ReferenceObject {
  return "$ref" in schema;
}

/**
 * Resolve a $ref to its schema definition
 */
function resolveRef(
  ref: string,
  spec: OpenAPIObject
): SchemaObject | undefined {
  const parts = ref.split("/");
  if (
    parts[0] !== "#" ||
    parts[1] !== "components" ||
    parts[2] !== "schemas"
  ) {
    return undefined;
  }
  const schemaName = parts[3];
  if (!schemaName || !spec.components?.schemas) {
    return undefined;
  }
  return spec.components.schemas[schemaName];
}

/**
 * Convert OpenAPI schema to JSON Schema for MCP tool input
 */
function openApiToJsonSchema(
  schema: SchemaObject | ReferenceObject | undefined,
  spec: OpenAPIObject
): Record<string, unknown> {
  if (!schema) {
    return { type: "object", properties: {} };
  }

  if (isReference(schema)) {
    const resolved = resolveRef(schema.$ref, spec);
    if (resolved) {
      return openApiToJsonSchema(resolved, spec);
    }
    return { type: "object", properties: {} };
  }

  const result: Record<string, unknown> = {};

  if (schema.type) {
    result.type = schema.type;
  }

  if (schema.description) {
    result.description = schema.description;
  }

  if (schema.enum) {
    result.enum = schema.enum;
  }

  if (schema.properties) {
    result.properties = {};
    for (const [key, prop] of Object.entries(schema.properties)) {
      (result.properties as Record<string, unknown>)[key] = openApiToJsonSchema(
        prop,
        spec
      );
    }
  }

  if (schema.required) {
    result.required = schema.required;
  }

  if (schema.items) {
    result.items = openApiToJsonSchema(
      schema.items,
      spec
    );
  }

  return result;
}

/**
 * Build MCP tool input schema from OpenAPI operation
 */
function buildInputSchema(
  operation: OperationObject,
  spec: OpenAPIObject
): Tool["inputSchema"] {
  const properties: Record<string, object> = {};
  const required: string[] = [];

  // Add path and query parameters
  if (operation.parameters) {
    for (const param of operation.parameters) {
      if (param.name && param.schema) {
        const paramSchema = openApiToJsonSchema(
          param.schema,
          spec
        );
        if (param.description) {
          paramSchema.description = param.description;
        }
        properties[param.name] = paramSchema;
        if (param.required) {
          required.push(param.name);
        }
      }
    }
  }

  // Add request body properties
  if (operation.requestBody?.content?.["application/json"]?.schema) {
    const bodySchema = openApiToJsonSchema(
      operation.requestBody.content["application/json"]
        .schema,
      spec
    );

    if (bodySchema.properties && typeof bodySchema.properties === "object") {
      for (const [key, value] of Object.entries(bodySchema.properties)) {
        properties[key] = value as object;
      }
    }
    if (Array.isArray(bodySchema.required)) {
      required.push(...bodySchema.required);
    }
  }

  return {
    type: "object" as const,
    properties,
    required: required.length > 0 ? required : undefined,
  };
}

/**
 * Generate MCP tools from OpenAPI spec
 */
function generateTools(openApiSpec: OpenAPIObject): Tool[] {
  const tools: Tool[] = [];

  for (const [path, pathItem] of Object.entries(openApiSpec.paths || {})) {
    if (!pathItem) continue;

    const methods = ["get", "post", "put", "patch", "delete"] as const;

    for (const method of methods) {
      const operation = pathItem[method];
      if (!operation) continue;

      const operationId =
        operation.operationId || pathToOperationId(method, path);
      const toolName = toToolName(operationId);
      const description = [
        operation.summary,
        operation.description,
        `[${method.toUpperCase()} ${path}]`,
      ]
        .filter(Boolean)
        .join("\n\n");

      toolOperations.set(toolName, { method, path, operation });

      tools.push({
        name: toolName,
        description,
        inputSchema: buildInputSchema(operation, openApiSpec),
      });
    }
  }

  return tools;
}

/**
 * Execute an API call based on tool name and arguments
 */
async function executeToolCall(
  toolName: string,
  args: Record<string, unknown>
): Promise<unknown> {
  const toolOp = toolOperations.get(toolName);
  if (!toolOp) {
    throw new Error(`Unknown tool: ${toolName}`);
  }

  const { method, path, operation } = toolOp;

  // Build URL with path parameters replaced
  let url = `${CONFIG.url}/api${path}`;
  const queryParams: Record<string, string> = {};
  const bodyParams: Record<string, unknown> = {};

  // Categorize arguments into path, query, and body params
  if (operation.parameters) {
    for (const param of operation.parameters) {
      const value = args[param.name];
      if (value !== undefined) {
        if (param.in === "path") {
          url = url.replace(`{${param.name}}`, encodeURIComponent(String(value)));
        } else if (param.in === "query") {
          queryParams[param.name] = String(value);
        }
      }
    }
  }

  // Remaining args go to body (for POST/PUT/PATCH)
  const paramNames = new Set(
    (operation.parameters || []).map((p) => p.name)
  );
  for (const [key, value] of Object.entries(args)) {
    if (!paramNames.has(key)) {
      bodyParams[key] = value;
    }
  }

  // Build query string
  const queryString = new URLSearchParams(queryParams).toString();
  if (queryString) {
    url += `?${queryString}`;
  }

  // Make the request
  const fetchOptions: RequestInit = {
    method: method.toUpperCase(),
    headers: {
      Authorization: `Bearer ${CONFIG.token}`,
      "Content-Type": "application/json",
    },
  };

  if (
    ["post", "put", "patch"].includes(method) &&
    Object.keys(bodyParams).length > 0
  ) {
    fetchOptions.body = JSON.stringify(bodyParams);
  }

  console.error(`[MCP] ${method.toUpperCase()} ${url}`);

  const response = await fetch(url, fetchOptions);

  // Handle non-OK responses before trying to parse JSON
  if (!response.ok) {
    const text = await response.text();
    console.error(`[MCP] Error ${response.status}: ${text.substring(0, 200)}`);

    // Try to parse as JSON for structured error, fall back to text
    let errorMessage: string;
    try {
      const errorData = JSON.parse(text);
      errorMessage = JSON.stringify(errorData);
    } catch {
      errorMessage = text.substring(0, 500);
    }
    throw new Error(`API error ${response.status}: ${errorMessage}`);
  }

  const data = await response.json();
  return data;
}

// ============== Main ==============

async function main() {
  // Load configuration from ~/.claude/.env
  CONFIG = loadConfig();

  // Fetch OpenAPI spec from Ship instance
  const openApiSpec = await fetchOpenAPISpec(CONFIG.url);

  // Generate tools from spec
  const mcpTools = generateTools(openApiSpec);
  console.error(`Generated ${mcpTools.length} tools from OpenAPI spec`);

  // Create the MCP server
  const server = new Server(
    {
      name: "ship",
      version: "1.0.0",
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  // Handle list tools request
  server.setRequestHandler(ListToolsRequestSchema, async () => {
    return { tools: mcpTools };
  });

  // Handle tool calls
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;

    try {
      const result = await executeToolCall(
        name,
        (args || {})
      );

      return {
        content: [
          {
            type: "text",
            text:
              typeof result === "string"
                ? result
                : JSON.stringify(result, null, 2),
          },
        ],
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : "Unknown error";
      return {
        content: [
          {
            type: "text",
            text: `Error: ${message}`,
          },
        ],
        isError: true,
      };
    }
  });

  // Connect transport and start
  const transport = new StdioServerTransport();
  await server.connect(transport);
  console.error(`Ship MCP server running on ${CONFIG.url}`);
}

main().catch((error) => {
  console.error("Failed to start Ship MCP server:", error);
  process.exit(1);
});

import { Request, Response, NextFunction } from 'express';
import { pool } from '../db/client.js';
import { ERROR_CODES, HTTP_STATUS } from '@ship/shared';
import { sessionCookieOptions } from '../config/session-cookies.js';
import { validateAuthenticatedSession, type SessionValidationFailure } from '../services/session-auth.js';
import { validateApiToken } from '../security/tokens.js';
import { logAuditEvent, type AuditEventInput } from '../services/audit.js';
import { logHotError } from '../utils/hot-log.js';

function recordAuditEvent(input: AuditEventInput): void {
  void logAuditEvent(input).catch((error) => {
    logHotError('audit', 'Failed to log audit event', error, { action: input.action });
  });
}

declare global {
  namespace Express {
    interface Request {
      sessionId?: string;
      userId?: string;
      workspaceId?: string;
      isSuperAdmin?: boolean;
      isApiToken?: boolean; // True when authenticated via API token
      apiTokenId?: string;
    }
  }
}

type SessionExpiredReason = Extract<
  SessionValidationFailure,
  'absolute_timeout' | 'inactivity_timeout' | 'binding_mismatch'
>;

const SESSION_EXPIRED_MESSAGES: Record<SessionExpiredReason, string> = {
  binding_mismatch: 'Session security changed. Please log in again.',
  absolute_timeout: 'Session expired. Please log in again.',
  inactivity_timeout: 'Session expired due to inactivity',
};

function isSessionExpiredReason(reason: SessionValidationFailure): reason is SessionExpiredReason {
  return reason in SESSION_EXPIRED_MESSAGES;
}

export async function authMiddleware(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  // Check for Bearer token first (API token auth)
  const authHeader = req.headers?.authorization;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.slice(7);

    try {
      const tokenData = await validateApiToken(token);

      if (!tokenData) {
        res.status(HTTP_STATUS.UNAUTHORIZED).json({
          success: false,
          error: {
            code: ERROR_CODES.UNAUTHORIZED,
            message: 'Invalid or expired API token',
          },
        });
        return;
      }

      // Attach token info to request
      req.userId = tokenData.userId;
      req.workspaceId = tokenData.workspaceId;
      req.isSuperAdmin = tokenData.isSuperAdmin;
      req.isApiToken = true;
      req.apiTokenId = tokenData.tokenId;
      req.apiTokenScopes = tokenData.scopes;
      req.principal = tokenData;

      next();
      return;
    } catch (error) {
      logHotError('auth.token', 'API token auth failed', error);
      res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
        success: false,
        error: {
          code: ERROR_CODES.INTERNAL_ERROR,
          message: 'Authentication failed',
        },
      });
      return;
    }
  }

  // Fall back to session cookie auth
  const sessionId = req.cookies?.session_id;

  if (!sessionId) {
    res.status(HTTP_STATUS.UNAUTHORIZED).json({
      success: false,
      error: {
        code: ERROR_CODES.UNAUTHORIZED,
        message: 'No session found',
      },
    });
    return;
  }

  try {
    const userAgentHeader = req.headers?.['user-agent'];
    const validation = await validateAuthenticatedSession(sessionId, {
      updateActivity: true,
      userAgent: Array.isArray(userAgentHeader) ? userAgentHeader[0] : userAgentHeader || null,
      ipAddress: req.ip || req.socket?.remoteAddress || null,
    });

    if (!validation.ok) {
      if (validation.reason === 'membership_revoked') {
        res.status(HTTP_STATUS.FORBIDDEN).json({
          success: false,
          error: {
            code: ERROR_CODES.FORBIDDEN,
            message: 'Access to this workspace has been revoked',
          },
        });
        return;
      }

      if (isSessionExpiredReason(validation.reason)) {
        res.status(HTTP_STATUS.UNAUTHORIZED).json({
          success: false,
          error: {
            code: ERROR_CODES.SESSION_EXPIRED,
            message: SESSION_EXPIRED_MESSAGES[validation.reason],
          },
        });
        return;
      }

      res.status(HTTP_STATUS.UNAUTHORIZED).json({
        success: false,
        error: {
          code: ERROR_CODES.UNAUTHORIZED,
          message: 'Invalid session',
        },
      });
      return;
    }

    if (validation.session.sessionId === sessionId && validation.activityUpdated) {
      res.cookie('session_id', sessionId, sessionCookieOptions());
    }
    if (validation.bindingDecision?.level === 'suspicious') {
      recordAuditEvent({
        workspaceId: validation.session.workspaceId ?? undefined,
        actorUserId: validation.session.userId,
        action: 'auth.session_anomaly',
        details: { reasons: validation.bindingDecision?.reasons },
        req,
      });
    }

    req.sessionId = validation.session.sessionId;
    req.userId = validation.session.userId;
    req.workspaceId = validation.session.workspaceId ?? undefined;
    req.isSuperAdmin = validation.session.isSuperAdmin;
    if (validation.session.workspaceId) {
      req.principal = {
        kind: 'session',
        sessionId: validation.session.sessionId,
        userId: validation.session.userId,
        workspaceId: validation.session.workspaceId,
        isSuperAdmin: validation.session.isSuperAdmin,
      };
    }

    next();
  } catch (error) {
    logHotError('auth.session', 'Session auth middleware failed', error);
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
      success: false,
      error: {
        code: ERROR_CODES.INTERNAL_ERROR,
        message: 'Authentication failed',
      },
    });
  }
}

// Middleware that requires super-admin access
export async function superAdminMiddleware(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  if (req.isApiToken) {
    res.status(HTTP_STATUS.FORBIDDEN).json({
      success: false,
      error: {
        code: ERROR_CODES.FORBIDDEN,
        message: 'API tokens cannot access super-admin routes',
      },
    });
    return;
  }

  if (!req.isSuperAdmin) {
    res.status(HTTP_STATUS.FORBIDDEN).json({
      success: false,
      error: {
        code: ERROR_CODES.FORBIDDEN,
        message: 'Super-admin access required',
      },
    });
    return;
  }

  next();
}

// Middleware that requires workspace admin access (or super-admin)
export async function workspaceAdminMiddleware(
  req: Request,
  res: Response,
  next: NextFunction
): Promise<void> {
  // Super-admins always have access
  if (req.isSuperAdmin) {
    next();
    return;
  }

  const workspaceId = req.params.id || req.workspaceId;

  if (!workspaceId) {
    res.status(HTTP_STATUS.BAD_REQUEST).json({
      success: false,
      error: {
        code: ERROR_CODES.VALIDATION_ERROR,
        message: 'Workspace ID required',
      },
    });
    return;
  }

  try {
    const result = await pool.query(
      'SELECT role FROM workspace_memberships WHERE workspace_id = $1 AND user_id = $2',
      [workspaceId, req.userId]
    );

    const membership = result.rows[0];

    if (!membership || membership.role !== 'admin') {
      res.status(HTTP_STATUS.FORBIDDEN).json({
        success: false,
        error: {
          code: ERROR_CODES.FORBIDDEN,
          message: 'Workspace admin access required',
        },
      });
      return;
    }

    next();
  } catch (error) {
    logHotError('auth.workspace_admin', 'Workspace admin check failed', error, {
      workspaceId,
      userId: req.userId,
    });
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
      success: false,
      error: {
        code: ERROR_CODES.INTERNAL_ERROR,
        message: 'Authorization check failed',
      },
    });
  }
}

import { pool } from '../db/client.js';

/**
 * Check if user is a workspace admin
 */
export async function isWorkspaceAdmin(userId: string, workspaceId: string): Promise<boolean> {
  const result = await pool.query(
    'SELECT role FROM workspace_memberships WHERE workspace_id = $1 AND user_id = $2',
    [workspaceId, userId]
  );
  return result.rows[0]?.role === 'admin';
}

/**
 * Get visibility filter context for SQL queries.
 * Returns the isAdmin boolean that should be used with visibility filter SQL.
 *
 * The visibility filter pattern is:
 *   (visibility = 'workspace' OR created_by = $userId OR $isAdmin = TRUE)
 *
 * This allows:
 * - All workspace-visible documents to be seen by everyone
 * - Private documents to be seen only by their creator
 * - Admins to see all documents
 */
export async function getVisibilityContext(
  userId: string,
  workspaceId: string
): Promise<{ isAdmin: boolean }> {
  const isAdmin = await isWorkspaceAdmin(userId, workspaceId);
  return { isAdmin };
}

/**
 * SQL fragment for visibility filtering.
 * Use with parameterized queries where:
 * - $N is userId
 * - $N+1 is isAdmin boolean
 *
 * Example:
 *   const { isAdmin } = await getVisibilityContext(userId, workspaceId);
 *   const query = `
 *     SELECT * FROM documents d
 *     WHERE d.workspace_id = $1
 *       AND ${VISIBILITY_FILTER_SQL('d', '$2', '$3')}
 *   `;
 *   await pool.query(query, [workspaceId, userId, isAdmin]);
 */
export function VISIBILITY_FILTER_SQL(
  tableAlias: string,
  userIdParam: string,
  isAdminParam: string
): string {
  return `(${tableAlias}.visibility = 'workspace' OR ${tableAlias}.created_by = ${userIdParam} OR ${isAdminParam} = TRUE)`;
}

import { describe, it, expect } from 'vitest';
import express from 'express';
import request from 'supertest';
import { z } from 'zod';

import { generateOpenAPIDocument } from './registry.js';
import { defineRoute } from './define-route.js';

describe('defineRoute', () => {
  it('registers OpenAPI metadata for a typed route definition', () => {
    const PingSchema = z.object({ ok: z.literal(true) }).openapi('DefineRoutePing');

    defineRoute({
      method: 'get',
      path: '/define-route-test/ping',
      tags: ['Tests'],
      summary: 'defineRoute registration smoke test',
      responses: {
        200: { schema: PingSchema, description: 'Ping' },
      },
      handler: (_req, res) => {
        res.json({ ok: true });
      },
    });

    const spec = generateOpenAPIDocument();
    const operation = spec.paths?.['/define-route-test/ping']?.get;
    expect(operation?.responses?.['200']).toBeDefined();
  });

  it('returns the standard validation envelope for invalid params', async () => {
    const app = express();
    app.get('/test/:id', defineRoute({
      method: 'get',
      path: '/define-route-test/param-validation',
      tags: ['Tests'],
      summary: 'param validation test',
      request: {
        params: z.object({ id: z.string().uuid() }),
      },
      responses: {
        200: { schema: z.object({ ok: z.literal(true) }).openapi('ParamValidationOk') },
      },
      handler: (_req, res) => {
        res.json({ ok: true });
      },
    }));

    const response = await request(app).get('/test/not-a-uuid');

    expect(response.status).toBe(400);
    expect(response.body.success).toBe(false);
    expect(response.body.error.code).toBe('VALIDATION_ERROR');
    expect(response.body.error.message).toContain('params validation failed');
  });

  it('returns the standard validation envelope by default', async () => {
    const app = express();
    app.use(express.json());
    app.post('/test', defineRoute({
      method: 'post',
      path: '/define-route-test/default-validation',
      tags: ['Tests'],
      summary: 'default validation test',
      request: {
        body: z.object({ title: z.string().min(1) }),
      },
      responses: {
        200: { schema: z.object({ ok: z.literal(true) }).openapi('DefaultValidationOk') },
      },
      handler: (_req, res) => {
        res.json({ ok: true });
      },
    }));

    const response = await request(app).post('/test').send({ title: '' });

    expect(response.status).toBe(400);
    expect(response.body.success).toBe(false);
    expect(response.body.error.code).toBe('VALIDATION_ERROR');
  });

  it('can preserve a legacy validation envelope for migrated routes', async () => {
    const app = express();
    app.use(express.json());
    app.post('/test', defineRoute({
      method: 'post',
      path: '/define-route-test/legacy-validation',
      tags: ['Tests'],
      summary: 'legacy validation test',
      request: {
        body: z.object({ title: z.string().min(1) }),
      },
      responses: {
        200: { schema: z.object({ ok: z.literal(true) }).openapi('LegacyValidationOk') },
      },
      validationError: (res, error) => {
        res.status(400).json({ error: 'Invalid input', details: error.zodError.errors });
      },
      handler: (_req, res) => {
        res.json({ ok: true });
      },
    }));

    const response = await request(app).post('/test').send({ title: '' });

    expect(response.status).toBe(400);
    expect(response.body.error).toBe('Invalid input');
    expect(response.body.details).toEqual(expect.any(Array));
  });

  it('documents the actual session cookie name', () => {
    const spec = generateOpenAPIDocument();
    expect(spec.components?.securitySchemes?.cookieAuth).toMatchObject({
      type: 'apiKey',
      in: 'cookie',
      name: 'session_id',
    });
  });
});

/**
 * Typed route wrapper: registers OpenAPI paths and parses request inputs once.
 * Pilot for collapsing split-brain between route handlers and OpenAPI schemas.
 */

import type { Request, RequestHandler, Response } from 'express';
import type { z } from 'zod';

import { ERROR_CODES } from '@ship/shared';
import { registry } from './registry.js';

export type HttpMethod = 'get' | 'post' | 'put' | 'patch' | 'delete';

type RouteRequestSchemas = {
  params?: z.ZodTypeAny;
  query?: z.ZodTypeAny;
  body?: z.ZodTypeAny;
};

type RouteResponseSchema = {
  schema: z.ZodTypeAny;
  description?: string;
};

type InferParsedPart<TPart> = NonNullable<TPart> extends z.ZodTypeAny
  ? z.infer<NonNullable<TPart>>
  : undefined;

export type DefineRouteConfig<TParsed extends RouteRequestSchemas> = {
  method: HttpMethod;
  path: string;
  tags: string[];
  summary: string;
  description?: string;
  operationId?: string;
  security?: Array<Record<string, string[]>>;
  request?: TParsed;
  responses: Record<number, RouteResponseSchema>;
  validationError?: (res: Response, error: RouteValidationError) => void;
  handler: (
    req: Request,
    res: Response,
    parsed: {
      params: InferParsedPart<TParsed['params']>;
      query: InferParsedPart<TParsed['query']>;
      body: InferParsedPart<TParsed['body']>;
    }
  ) => void | Promise<void>;
};

export type DefinedRouteMetadata = {
  method: HttpMethod;
  path: string;
  responses: Record<number, { openApiSchemaName: string; schema: z.ZodTypeAny }>;
};

function registerOpenApiResponses(
  config: DefineRouteConfig<RouteRequestSchemas>
): DefinedRouteMetadata['responses'] {
  const metadata: DefinedRouteMetadata['responses'] = {};

  const openApiResponses: Record<number, { description: string; content?: Record<string, { schema: z.ZodTypeAny }> }> = {};
  for (const [statusCode, responseConfig] of Object.entries(config.responses)) {
    const status = Number(statusCode);
    const schema = responseConfig.schema;
    const schemaName = schema._def.openapi?.metadata?.refId ?? schema._def.openapi?.metadata?.title;
    if (typeof schemaName === 'string') {
      metadata[status] = { openApiSchemaName: schemaName, schema };
    }
    openApiResponses[status] = {
      description: responseConfig.description ?? `Response ${status}`,
      content: {
        'application/json': { schema },
      },
    };
  }

  const pathConfig: Parameters<typeof registry.registerPath>[0] = {
    method: config.method,
    path: config.path,
    tags: config.tags,
    summary: config.summary,
    security: config.security,
    request: config.request
      ? ({
          params: config.request.params,
          query: config.request.query,
          body: config.request.body
            ? { required: true, content: { 'application/json': { schema: config.request.body } } }
            : undefined,
        } as Parameters<typeof registry.registerPath>[0]['request'])
      : undefined,
    responses: openApiResponses,
  };

  if (config.description !== undefined) {
    pathConfig.description = config.description;
  }
  if (config.operationId !== undefined) {
    pathConfig.operationId = config.operationId;
  }

  registry.registerPath(pathConfig);

  return metadata;
}

function parsePart<T extends z.ZodTypeAny | undefined>(
  value: unknown,
  schema: T,
  label: string
): T extends z.ZodTypeAny ? z.infer<T> : undefined {
  if (!schema) {
    return undefined as T extends z.ZodTypeAny ? z.infer<T> : undefined;
  }
  const parsed = schema.safeParse(value);
  if (!parsed.success) {
    const message = parsed.error.issues.map((issue) => `${issue.path.join('.')}: ${issue.message}`).join('; ');
    throw new RouteValidationError(`${label} validation failed: ${message}`, parsed.error);
  }
  return parsed.data;
}

export class RouteValidationError extends Error {
  readonly statusCode = 400;

  constructor(message: string, readonly zodError: z.ZodError) {
    super(message);
  }
}

export function defineRoute<T extends RouteRequestSchemas>(
  config: DefineRouteConfig<T>
): RequestHandler & { openApi: DefinedRouteMetadata } {
  const openApiResponses = registerOpenApiResponses(config);

  const handler: RequestHandler = async (req, res) => {
    try {
      await config.handler(req, res, {
        params: parsePart(req.params, config.request?.params, 'params'),
        query: parsePart(req.query, config.request?.query, 'query'),
        body: parsePart(req.body, config.request?.body, 'body'),
      });
    } catch (error) {
      if (error instanceof RouteValidationError) {
        if (config.validationError) {
          config.validationError(res, error);
          return;
        }
        res.status(error.statusCode).json({
          success: false,
          error: {
            code: ERROR_CODES.VALIDATION_ERROR,
            message: error.message,
          },
        });
        return;
      }
      throw error;
    }
  };

  return Object.assign(handler, {
    openApi: {
      method: config.method,
      path: config.path,
      responses: openApiResponses,
    },
  });
}

import type { OpenAPIObject } from 'openapi3-ts/oas30';

type JsonRecord = Record<string, unknown>;

function isRecord(value: unknown): value is JsonRecord {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isNullableRefAllOf(value: unknown): value is {
  allOf: [{ $ref: string }, { nullable: true }];
} {
  if (!isRecord(value) || !Array.isArray(value.allOf) || value.allOf.length !== 2) {
    return false;
  }

  const [first, second] = value.allOf;
  return (
    isRecord(first)
    && typeof first.$ref === 'string'
    && isRecord(second)
    && second.nullable === true
    && Object.keys(second).length === 1
  );
}

function normalizeNullableRefNode(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(normalizeNullableRefNode);
  }

  if (!isRecord(value)) {
    return value;
  }

  if (isNullableRefAllOf(value)) {
    const [refPart] = value.allOf;
    return {
      nullable: true,
      allOf: [refPart],
    };
  }

  const normalized: JsonRecord = {};
  for (const [key, child] of Object.entries(value)) {
    normalized[key] = normalizeNullableRefNode(child);
  }
  return normalized;
}

export function normalizeNullableRefs(document: OpenAPIObject): OpenAPIObject {
  return normalizeNullableRefNode(document) as OpenAPIObject;
}

