export default router;

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { requireFirstRow, type IdRow } from '../test/pg-result.js';

describe('AI route validation security', () => {
  const app = createApp();
  const runId = Date.now().toString(36);
  let workspaceId: string;
  let userId: string;
  let cookie: string;
  let csrfToken: string;

  beforeAll(async () => {
    const workspace = await pool.query<IdRow>(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [`ai-security-${runId}`]
    );
    workspaceId = requireFirstRow(workspace.rows).id;

    const user = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'AI Security User') RETURNING id`,
      [`ai-security-${runId}@ship.local`]
    );
    userId = requireFirstRow(user.rows).id;

    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [workspaceId, userId]
    );

    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at, last_activity, user_agent, ip_address)
       VALUES ($1, $2, $3, now() + interval '1 hour', now(), $4, $5)`,
      [sessionId, userId, workspaceId, 'ai-security-agent', '::ffff:127.0.0.1']
    );
    cookie = `session_id=${sessionId}`;

    const csrf = await request(app)
      .get('/api/csrf-token')
      .set('Cookie', cookie)
      .set('User-Agent', 'ai-security-agent');
    csrfToken = csrf.body.token;
    const connectSidCookie = csrf.headers['set-cookie']?.[0]?.split(';')[0] || '';
    if (connectSidCookie) cookie = `${cookie}; ${connectSidCookie}`;
  });

  afterAll(async () => {
    await pool.query('DELETE FROM sessions WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [workspaceId]);
  });

  it('reports AI availability with the documented shape', async () => {
    const response = await request(app)
      .get('/api/ai/status')
      .set('Cookie', cookie)
      .set('User-Agent', 'ai-security-agent');

    expect(response.status).toBe(200);
    expect(response.body).toEqual(expect.objectContaining({ available: expect.any(Boolean) }));
  });

  it('rejects malformed analyze-plan bodies before analysis', async () => {
    for (const body of [{}, { content: 123 }, { content: '' }, { content: 'x'.repeat(50_001) }]) {
      const response = await request(app)
        .post('/api/ai/analyze-plan')
        .set('Cookie', cookie)
        .set('User-Agent', 'ai-security-agent')
        .set('x-csrf-token', csrfToken)
        .send(body);

      expect(response.status).toBe(400);
    }
  });

  it('rejects malformed analyze-retro bodies before analysis', async () => {
    for (const body of [{}, { retro_content: 123, plan_content: 'plan' }, { retro_content: 'retro', plan_content: '' }]) {
      const response = await request(app)
        .post('/api/ai/analyze-retro')
        .set('Cookie', cookie)
        .set('User-Agent', 'ai-security-agent')
        .set('x-csrf-token', csrfToken)
        .send(body);

      expect(response.status).toBe(400);
    }
  });

  it('accepts valid string AI analysis bodies', async () => {
    const response = await request(app)
      .post('/api/ai/analyze-plan')
      .set('Cookie', cookie)
      .set('User-Agent', 'ai-security-agent')
      .set('x-csrf-token', csrfToken)
      .send({ content: 'Ship one measurable thing.' });

    expect(response.status).toBe(200);
    expect(response.body).not.toHaveProperty('details');
  });

  it('rejects cross-site cookie-auth mutations even with a CSRF token', async () => {
    const response = await request(app)
      .post('/api/ai/analyze-plan')
      .set('Cookie', cookie)
      .set('User-Agent', 'ai-security-agent')
      .set('Origin', 'https://evil.example')
      .set('x-csrf-token', csrfToken)
      .send({ content: 'Ship one measurable thing.' });

    expect(response.status).toBe(403);
    expect(response.body).toEqual({ error: 'Cross-site request rejected' });
  });
});

import { Router, Request, Response } from 'express';
import { z } from 'zod';
import { pool } from '../db/client.js';
import { authMiddleware } from '../middleware/auth.js';
import { ERROR_CODES, HTTP_STATUS } from '@ship/shared';
import { logAuditEvent } from '../services/audit.js';
import { getAuthenticatedRouteContext } from '../utils/auth-context.js';
import { authorize } from '../security/capabilities.js';
import { DEFAULT_API_TOKEN_SCOPES, generateApiToken, hashToken } from '../security/tokens.js';
import { principalFromRequest, type ApiTokenScope } from '../security/principal.js';

const router = Router();
export { hashToken };

function denyWorkspaceAdminTokenAction(res: Response, action: 'create' | 'revoke'): void {
  res.status(HTTP_STATUS.FORBIDDEN).json({
    success: false,
    error: {
      code: ERROR_CODES.FORBIDDEN,
      message: `Workspace admin access required to ${action} API tokens`,
    },
  });
}

const createTokenSchema = z.object({
  name: z.string().min(1).max(100),
  expires_in_days: z.number().int().positive().max(365).optional(),
  scopes: z.array(z.enum([
    'documents:read',
    'documents:write',
    'documents:content',
    'documents:governance',
    'files:read',
    'files:write',
    'collaboration:join',
    'admin:workspace',
  ])).optional(),
});

router.post('/', authMiddleware, async (req: Request, res: Response): Promise<void> => {
  const { userId, workspaceId } = getAuthenticatedRouteContext(req);
  const principal = principalFromRequest(req);
  const parseResult = createTokenSchema.safeParse(req.body);

  if (!parseResult.success) {
    res.status(HTTP_STATUS.BAD_REQUEST).json({
      success: false,
      error: {
        code: ERROR_CODES.VALIDATION_ERROR,
        message: 'Invalid request',
        details: parseResult.error.flatten(),
      },
    });
    return;
  }

  const { name, expires_in_days } = parseResult.data;
  const scopes = parseResult.data.scopes ?? DEFAULT_API_TOKEN_SCOPES;

  try {
    const capability = await authorize(pool, principal, { resource: 'api_token', action: 'create' });
    if (!capability.allowed) {
      denyWorkspaceAdminTokenAction(res, 'create');
      return;
    }

    const existingResult = await pool.query(
      `SELECT id FROM api_tokens
       WHERE user_id = $1 AND workspace_id = $2 AND name = $3 AND revoked_at IS NULL`,
      [userId, workspaceId, name]
    );

    if (existingResult.rows.length > 0) {
      res.status(HTTP_STATUS.CONFLICT).json({
        success: false,
        error: {
          code: ERROR_CODES.ALREADY_EXISTS,
          message: `An active token named "${name}" already exists. Revoke it first or choose a different name.`,
        },
      });
      return;
    }

    const { token, hash, prefix } = generateApiToken();
    const expiresAt = new Date(Date.now() + (expires_in_days ?? 30) * 24 * 60 * 60 * 1000);

    const result = await pool.query(
      `INSERT INTO api_tokens (user_id, workspace_id, name, token_hash, token_prefix, expires_at, scopes)
       VALUES ($1, $2, $3, $4, $5, $6, $7)
       RETURNING id, name, token_prefix, expires_at, created_at`,
      [userId, workspaceId, name, hash, prefix, expiresAt, scopes]
    );

    await logAuditEvent({
      workspaceId,
      actorUserId: userId,
      action: 'api_token.created',
      resourceType: 'api_token',
      resourceId: result.rows[0].id,
      details: { name, expires_at: expiresAt, scopes },
      req,
    });

    // Return the full token ONLY on creation (never stored or returned again)
    res.status(HTTP_STATUS.CREATED).json({
      success: true,
      data: {
        id: result.rows[0].id,
        name: result.rows[0].name,
        token: token, // ONLY returned here - user must save it
        token_prefix: result.rows[0].token_prefix,
        scopes,
        expires_at: result.rows[0].expires_at,
        created_at: result.rows[0].created_at,
        warning: 'Save this token now. It will not be shown again.',
      },
    });
  } catch (error) {
    console.error('Create API token error:', error);
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
      success: false,
      error: {
        code: ERROR_CODES.INTERNAL_ERROR,
        message: 'Failed to create API token',
      },
    });
  }
});

router.get('/', authMiddleware, async (req: Request, res: Response): Promise<void> => {
  const { userId, workspaceId } = getAuthenticatedRouteContext(req);

  try {
    const result = await pool.query(
      `SELECT id, name, token_prefix, scopes, last_used_at, expires_at, revoked_at, created_at
       FROM api_tokens
       WHERE user_id = $1 AND workspace_id = $2
       ORDER BY created_at DESC`,
      [userId, workspaceId]
    );

    res.json({
      success: true,
      data: result.rows.map(row => ({
        id: row.id,
        name: row.name,
        token_prefix: row.token_prefix,
        scopes: (row.scopes ?? ['legacy:full']) as ApiTokenScope[],
        last_used_at: row.last_used_at,
        expires_at: row.expires_at,
        is_active: !row.revoked_at && (!row.expires_at || new Date(row.expires_at) > new Date()),
        revoked_at: row.revoked_at,
        created_at: row.created_at,
      })),
    });
  } catch (error) {
    console.error('List API tokens error:', error);
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
      success: false,
      error: {
        code: ERROR_CODES.INTERNAL_ERROR,
        message: 'Failed to list API tokens',
      },
    });
  }
});

router.delete('/:id', authMiddleware, async (req: Request, res: Response): Promise<void> => {
  const { userId, workspaceId } = getAuthenticatedRouteContext(req);
  const principal = principalFromRequest(req);
  const id = String(req.params.id);

  try {
    const capability = await authorize(pool, principal, { resource: 'api_token', action: 'revoke' });
    if (!capability.allowed) {
      denyWorkspaceAdminTokenAction(res, 'revoke');
      return;
    }

    const tokenResult = await pool.query(
      `SELECT id, name FROM api_tokens
       WHERE id = $1 AND user_id = $2 AND workspace_id = $3`,
      [id, userId, workspaceId]
    );

    if (tokenResult.rows.length === 0) {
      res.status(HTTP_STATUS.NOT_FOUND).json({
        success: false,
        error: {
          code: ERROR_CODES.NOT_FOUND,
          message: 'API token not found',
        },
      });
      return;
    }

    await pool.query(
      `UPDATE api_tokens SET revoked_at = NOW() WHERE id = $1`,
      [id]
    );

    await logAuditEvent({
      workspaceId,
      actorUserId: userId,
      action: 'api_token.revoked',
      resourceType: 'api_token',
      resourceId: id,
      details: { name: tokenResult.rows[0].name },
      req,
    });

    res.json({
      success: true,
      data: { message: 'API token revoked' },
    });
  } catch (error) {
    console.error('Revoke API token error:', error);
    res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
      success: false,
      error: {
        code: ERROR_CODES.INTERNAL_ERROR,
        message: 'Failed to revoke API token',
      },
    });
  }
});

