import { Router, Request, Response } from 'express';
import { pool } from '../db/client.js';
import { z } from 'zod';
import { getVisibilityContext, VISIBILITY_FILTER_SQL } from '../middleware/visibility.js';
import { authMiddleware } from '../middleware/auth.js';
import { getAuthenticatedRouteContext } from '../utils/auth-context.js';
import { sendInternalError, sendValidationError } from '../utils/route-http.js';

const router = Router();

// Validation schema for updating links
const updateLinksSchema = z.object({
  target_ids: z.array(z.string().uuid()),
});

// GET /api/documents/:id/backlinks - Get documents that link to this one
router.get('/:id/backlinks', authMiddleware, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { userId, workspaceId } = getAuthenticatedRouteContext(req);

    // Get visibility context for filtering
    const { isAdmin } = await getVisibilityContext(userId, workspaceId);

    // Verify the document exists and user can access it
    const docResult = await pool.query(
      `SELECT id FROM documents
       WHERE id = $1 AND workspace_id = $2
         AND ${VISIBILITY_FILTER_SQL('documents', '$3', '$4')}`,
      [id, workspaceId, userId, isAdmin]
    );

    if (docResult.rows.length === 0) {
      res.status(404).json({ error: 'Document not found' });
      return;
    }

    // Get all documents that link to this document (only visible ones)
    const result = await pool.query(
      `SELECT d.id, d.document_type, d.title, d.ticket_number, prog_da.related_id as program_id, d.properties,
              p.properties->>'prefix' as program_prefix
       FROM document_links dl
       JOIN documents d ON dl.source_id = d.id
       LEFT JOIN document_associations prog_da ON d.id = prog_da.document_id AND prog_da.relationship_type = 'program'
       LEFT JOIN documents p ON prog_da.related_id = p.id AND p.document_type = 'program'
       WHERE dl.target_id = $1 AND d.workspace_id = $2
         AND ${VISIBILITY_FILTER_SQL('d', '$3', '$4')}
       ORDER BY dl.created_at DESC`,
      [id, workspaceId, userId, isAdmin]
    );

    // Format the response with display_id for issues
    const backlinks = result.rows.map(row => ({
      id: row.id,
      document_type: row.document_type,
      title: row.title,
      display_id: row.ticket_number && row.document_type === 'issue'
        ? `#${row.ticket_number}`
        : undefined,
    }));

    res.json(backlinks);
  } catch (err) {
    sendInternalError(res, err, 'Get backlinks error:');
  }
});

// POST /api/documents/:id/links - Update links for a document
router.post('/:id/links', authMiddleware, async (req: Request, res: Response) => {
  try {
    const { id } = req.params;
    const { userId, workspaceId } = getAuthenticatedRouteContext(req);

    const parsed = updateLinksSchema.safeParse(req.body);
    if (!parsed.success) {
      sendValidationError(res, parsed.error);
      return;
    }

    const { target_ids } = parsed.data;

    // Get visibility context for filtering
    const { isAdmin } = await getVisibilityContext(userId, workspaceId);

    // Verify the source document exists and user can access it
    const docResult = await pool.query(
      `SELECT id FROM documents
       WHERE id = $1 AND workspace_id = $2
         AND ${VISIBILITY_FILTER_SQL('documents', '$3', '$4')}`,
      [id, workspaceId, userId, isAdmin]
    );

    if (docResult.rows.length === 0) {
      res.status(404).json({ error: 'Document not found' });
      return;
    }

    // Verify all target documents exist and user can access them
    if (target_ids.length > 0) {
      const targetResult = await pool.query(
        `SELECT id FROM documents
         WHERE id = ANY($1) AND workspace_id = $2
           AND ${VISIBILITY_FILTER_SQL('documents', '$3', '$4')}`,
        [target_ids, workspaceId, userId, isAdmin]
      );

      if (targetResult.rows.length !== target_ids.length) {
        res.status(400).json({ error: 'One or more target documents not found' });
        return;
      }
    }

    // Start transaction
    const client = await pool.connect();
    try {
      await client.query('BEGIN');

      // Delete existing links for this source document
      await client.query(
        'DELETE FROM document_links WHERE source_id = $1',
        [id]
      );

      // Insert new links (if any)
      if (target_ids.length > 0) {
        const values = target_ids.map((targetId, idx) =>
          `($1, $${idx + 2})`
        ).join(', ');

        await client.query(
          `INSERT INTO document_links (source_id, target_id)
           VALUES ${values}
           ON CONFLICT (source_id, target_id) DO NOTHING`,
          [id, ...target_ids]
        );
      }

      await client.query('COMMIT');
      res.json({ success: true });
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  } catch (err) {
    sendInternalError(res, err, 'Update links error:');
  }
});

export default router;

/** Bootstrap route tests — authenticated app-shell hydration payload shape. */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import type { z } from 'zod';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { BootstrapResponseSchema } from '../openapi/schemas/bootstrap.js';
import { expectOpenApiResponse } from '../test/openapi-response.js';

type BootstrapData = z.infer<typeof BootstrapResponseSchema>['data'];

describe('Bootstrap API', () => {
  const app = createApp('http://localhost:5173');
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const testEmail = `bootstrap-${testRunId}@ship.local`;
  const testWorkspaceName = `Bootstrap Test ${testRunId}`;

  let sessionCookie: string;
  let testWorkspaceId: string;
  let testUserId: string;

  beforeAll(async () => {
    const workspaceResult = await pool.query(
      `INSERT INTO workspaces (name, sprint_start_date)
       VALUES ($1, CURRENT_DATE)
       RETURNING id`,
      [testWorkspaceName]
    );
    testWorkspaceId = workspaceResult.rows[0].id;

    const userResult = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Bootstrap Test User')
       RETURNING id`,
      [testEmail]
    );
    testUserId = userResult.rows[0].id;

    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    );

    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [sessionId, testUserId, testWorkspaceId]
    );
    sessionCookie = `session_id=${sessionId}`;

    const projectResult = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, created_by)
       VALUES ($1, 'project', 'Bootstrap Active Project', $2)
       RETURNING id`,
      [testWorkspaceId, testUserId]
    );
    const projectId = projectResult.rows[0].id;

    const sprintResult = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, properties, created_by)
       VALUES ($1, 'wiki', 'Bootstrap Wiki', '{}', $2),
              ($1, 'issue', 'Bootstrap Issue', '{"state":"backlog","priority":"medium"}', $2),
              ($1, 'sprint', 'Bootstrap Sprint', $3, $2)
       RETURNING id, document_type`,
      [
        testWorkspaceId,
        testUserId,
        JSON.stringify({
          sprint_number: 1,
          assignee_ids: [testUserId],
        }),
      ]
    );

    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'project')`,
      [sprintResult.rows[2].id, projectId]
    );
  });

  afterAll(async () => {
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [testWorkspaceId]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM workspace_memberships WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM users WHERE id = $1', [testUserId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId]);
  });

  it('GET /api/bootstrap requires auth', async () => {
    const res = await request(app).get('/api/bootstrap');

    expect(res.status).toBe(401);
  });

  it('GET /api/bootstrap returns app-shell data without drifting project status', async () => {
    const res = await request(app)
      .get('/api/bootstrap')
      .set('Cookie', sessionCookie);

    const bootstrap = expectOpenApiResponse({
      method: 'get',
      path: '/bootstrap',
      status: 200,
      response: res,
      openApiSchemaName: 'BootstrapResponse',
      schema: BootstrapResponseSchema,
    });

    const data: BootstrapData = bootstrap.data;
    expect(data.user.email).toBe(testEmail);
    expect(data.currentWorkspace.id).toBe(testWorkspaceId);
    expect(data.documents.some((doc) => doc.title === 'Bootstrap Wiki')).toBe(true);
    expect(data.documents.find((doc) => doc.title === 'Bootstrap Wiki')?.properties).toEqual(null);
    expect(data.issues.some((issue) => issue.title === 'Bootstrap Issue')).toBe(true);
    expect(data.issues.find((issue) => issue.title === 'Bootstrap Issue')).not.toHaveProperty('content');
    expect(data.actionItems).toMatchObject({ items: expect.any(Array), total: expect.any(Number) });

    // Risk: bootstrap seeds the project list cache, so it must match /api/projects status inference.
    const project = data.projects.find((item) => item.title === 'Bootstrap Active Project');
    expect(project).toBeDefined();
    if (!project) {
      throw new Error('Expected Bootstrap Active Project in bootstrap payload');
    }
    expect(project.inferred_status).toBe('active');
    expect(project).not.toHaveProperty('plan');
    expect(project).not.toHaveProperty('plan_approval');
    expect(project).not.toHaveProperty('retro_approval');
    expect(project).not.toHaveProperty('design_review_notes');
  });
});

import { Router, Request, Response } from 'express';
import { pool } from '../db/client.js';
import { authMiddleware } from '../middleware/auth.js';
import { getVisibilityContext, VISIBILITY_FILTER_SQL } from '../middleware/visibility.js';
import {
  computeICEScore,
  DEFAULT_PROJECT_PROPERTIES,
  type InferredProjectStatus,
  type ProjectRouteProperties,
} from '@ship/shared';
import { getBelongsToAssociationsBatch } from '../utils/document-crud.js';
import { mapIssueListItem } from '../utils/issue-response.js';
import { getAuthenticatedRouteContext } from '../utils/auth-context.js';
import { sendInternalError } from '../utils/route-http.js';
import { INFERRED_PROJECT_STATUS_SUBQUERY } from '../sql/bootstrap-queries.js';
import { pickBootstrapDocumentProperties } from '../constants/bootstrap-document.js';
import { listIssuesMetadata } from '../db/documents-repository.js';
import { visibleAssociatedDocumentCountSql } from '../services/document-graph-visibility.js';

const router = Router();

type DocumentListRow = {
  id: string;
  workspace_id: string;
  document_type: string;
  title: string;
  parent_id: string | null;
  position: number | null;
  ticket_number: number | null;
  properties: Record<string, unknown> | null;
  created_at: Date;
  updated_at: Date;
  created_by: string;
  visibility: 'private' | 'workspace';
};

type ProgramRow = {
  id: string;
  title: string;
  properties: {
    color?: string;
    emoji?: string | null;
    owner_id?: string | null;
    accountable_id?: string | null;
    consulted_ids?: string[];
    informed_ids?: string[];
  } | null;
  archived_at: Date | null;
  created_at: Date;
  updated_at: Date;
  issue_count?: string | number | null;
  sprint_count?: string | number | null;
  owner_id?: string | null;
  owner_name?: string | null;
  owner_email?: string | null;
};

type ProjectRow = {
  id: string;
  title: string;
  properties: ProjectRouteProperties | null;
  program_id?: string | null;
  archived_at: Date | null;
  created_at: Date;
  updated_at: Date;
  owner_id?: string | null;
  owner_name?: string | null;
  owner_email?: string | null;
  sprint_count?: string | number | null;
  issue_count?: string | number | null;
  inferred_status?: InferredProjectStatus | null;
  converted_from_id?: string | null;
};

function mapProgram(row: ProgramRow) {
  const props = row.properties || {};
  return {
    id: row.id,
    name: row.title,
    color: props.color || '#6366f1',
    emoji: props.emoji || null,
    archived_at: row.archived_at,
    created_at: row.created_at,
    updated_at: row.updated_at,
    issue_count: row.issue_count,
    sprint_count: row.sprint_count,
    owner: row.owner_name ? {
      id: row.owner_id,
      name: row.owner_name,
      email: row.owner_email,
    } : null,
    owner_id: props.owner_id || null,
    accountable_id: props.accountable_id || null,
    consulted_ids: props.consulted_ids || [],
    informed_ids: props.informed_ids || [],
  };
}

function mapProject(row: ProjectRow) {
  const props = row.properties || {};
  const impact = props.impact !== undefined ? props.impact : null;
  const confidence = props.confidence !== undefined ? props.confidence : null;
  const ease = props.ease !== undefined ? props.ease : null;

  return {
    id: row.id,
    title: row.title,
    impact,
    confidence,
    ease,
    ice_score: computeICEScore(impact, confidence, ease),
    color: props.color || DEFAULT_PROJECT_PROPERTIES.color,
    emoji: props.emoji || null,
    program_id: row.program_id || null,
    archived_at: row.archived_at,
    created_at: row.created_at,
    updated_at: row.updated_at,
    owner: row.owner_name ? {
      id: row.owner_id,
      name: row.owner_name,
      email: row.owner_email,
    } : null,
    sprint_count: parseInt(String(row.sprint_count || 0), 10) || 0,
    issue_count: parseInt(String(row.issue_count || 0), 10) || 0,
    is_complete: props.is_complete ?? null,
    missing_fields: props.missing_fields ?? [],
    inferred_status: row.inferred_status || 'backlog',
    converted_from_id: row.converted_from_id || null,
    owner_id: props.owner_id || null,
    accountable_id: props.accountable_id || null,
    consulted_ids: props.consulted_ids || [],
    informed_ids: props.informed_ids || [],
    has_retro: props.has_retro ?? false,
    target_date: props.target_date || null,
    has_design_review: props.has_design_review ?? null,
  };
}

function mapBootstrapDocument(row: DocumentListRow) {
  return {
    id: row.id,
    workspace_id: row.workspace_id,
    document_type: row.document_type,
    title: row.title,
    parent_id: row.parent_id,
    position: row.position,
    ticket_number: row.ticket_number,
    properties: pickBootstrapDocumentProperties(row.properties),
    created_at: row.created_at,
    updated_at: row.updated_at,
    created_by: row.created_by,
    visibility: row.visibility,
  };
}

const EMPTY_ACTION_ITEMS_RESPONSE = {
  items: [],
  total: 0,
  has_overdue: false,
  has_due_today: false,
};

const STALE_STANDUP_STATUS = {
  due: false,
  lastPosted: null,
};

router.get('/', authMiddleware, async (req: Request, res: Response): Promise<void> => {
  try {
    const { userId, workspaceId } = getAuthenticatedRouteContext(req);
    const { isAdmin } = await getVisibilityContext(userId, workspaceId);

    const [
      userResult,
      workspacesResult,
      currentWorkspaceResult,
      documentsResult,
      programsResult,
      projectsResult,
      issuesResult,
    ] = await Promise.all([
      pool.query('SELECT id, email, name, is_super_admin FROM users WHERE id = $1', [userId]),
      pool.query(
        `SELECT w.id, w.name, wm.role
         FROM workspaces w
         JOIN workspace_memberships wm ON w.id = wm.workspace_id
         WHERE wm.user_id = $1 AND w.archived_at IS NULL
         ORDER BY w.name`,
        [userId]
      ),
      pool.query(
        `SELECT w.id, w.name, wm.role
         FROM workspaces w
         LEFT JOIN workspace_memberships wm ON w.id = wm.workspace_id AND wm.user_id = $2
         WHERE w.id = $1`,
        [workspaceId, userId]
      ),
      pool.query<DocumentListRow>(
        `SELECT id, workspace_id, document_type, title, parent_id, position,
                ticket_number, properties, created_at, updated_at, created_by, visibility
         FROM documents
         WHERE workspace_id = $1
           AND document_type = 'wiki'
           AND archived_at IS NULL
           AND deleted_at IS NULL
           AND ${VISIBILITY_FILTER_SQL('documents', '$2', '$3')}
         ORDER BY position ASC, created_at ASC`,
        [workspaceId, userId, isAdmin]
      ),
      pool.query<ProgramRow>(
        `SELECT d.id, d.title, d.properties, d.archived_at, d.created_at, d.updated_at,
                COALESCE((d.properties->>'owner_id')::uuid, d.created_by) as owner_id,
                u.name as owner_name, u.email as owner_email,
                (${visibleAssociatedDocumentCountSql('i', 'program', 'issue', 'd', '$2', '$3')}) as issue_count,
                (${visibleAssociatedDocumentCountSql('s', 'program', 'sprint', 'd', '$2', '$3')}) as sprint_count
         FROM documents d
         LEFT JOIN users u ON u.id = COALESCE((d.properties->>'owner_id')::uuid, d.created_by)
         WHERE d.workspace_id = $1 AND d.document_type = 'program'
           AND d.archived_at IS NULL
           AND ${VISIBILITY_FILTER_SQL('d', '$2', '$3')}
         ORDER BY d.created_at DESC`,
        [workspaceId, userId, isAdmin]
      ),
      pool.query<ProjectRow>(
        `SELECT d.id, d.title, d.properties, prog.id as program_id,
                d.archived_at, d.created_at, d.updated_at, d.converted_from_id,
                (d.properties->>'owner_id')::uuid as owner_id,
                u.name as owner_name, u.email as owner_email,
                (${visibleAssociatedDocumentCountSql('s', 'project', 'sprint', 'd', '$2', '$3')}) as sprint_count,
                (${visibleAssociatedDocumentCountSql('i', 'project', 'issue', 'd', '$2', '$3')}) as issue_count,
                (${INFERRED_PROJECT_STATUS_SUBQUERY}) as inferred_status
         FROM documents d
         LEFT JOIN users u ON u.id = (d.properties->>'owner_id')::uuid
         LEFT JOIN document_associations prog_da ON prog_da.document_id = d.id AND prog_da.relationship_type = 'program'
         LEFT JOIN documents prog ON prog.id = prog_da.related_id
          AND prog.workspace_id = d.workspace_id
          AND prog.document_type = 'program'
          AND prog.archived_at IS NULL
          AND prog.deleted_at IS NULL
          AND ${VISIBILITY_FILTER_SQL('prog', '$2', '$3')}
         WHERE d.workspace_id = $1 AND d.document_type = 'project'
           AND d.archived_at IS NULL
           AND ${VISIBILITY_FILTER_SQL('d', '$2', '$3')}
         ORDER BY ((COALESCE((d.properties->>'impact')::int, 3) * COALESCE((d.properties->>'confidence')::int, 3) * COALESCE((d.properties->>'ease')::int, 3))) DESC`,
        [workspaceId, userId, isAdmin]
      ),
      listIssuesMetadata(workspaceId, userId, isAdmin),
    ]);

    const user = userResult.rows[0];
    if (!user) {
      res.status(404).json({ success: false, error: { code: 'NOT_FOUND', message: 'User not found' } });
      return;
    }

    const currentWorkspaceRow = currentWorkspaceResult.rows[0];
    const currentWorkspace = currentWorkspaceRow ? {
      id: currentWorkspaceRow.id,
      name: currentWorkspaceRow.name,
      role: currentWorkspaceRow.role || 'admin',
    } : null;

    const issueIds = issuesResult.map(row => row.id);
    const associationsMap = await getBelongsToAssociationsBatch(issueIds);
    const issues = issuesResult.map(row => mapIssueListItem(row, associationsMap.get(row.id) || []));

    res.json({
      success: true,
      data: {
        user: {
          id: user.id,
          email: user.email,
          name: user.name,
          isSuperAdmin: user.is_super_admin,
        },
        currentWorkspace,
        workspaces: workspacesResult.rows.map(w => ({
          id: w.id,
          name: w.name,
          role: w.role,
        })),
        pendingAccountabilityItems: [],
        documents: documentsResult.rows.map(mapBootstrapDocument),
        programs: programsResult.rows.map(mapProgram),
        projects: projectsResult.rows.map(mapProject),
        issues,
        standupStatus: STALE_STANDUP_STATUS,
        actionItems: EMPTY_ACTION_ITEMS_RESPONSE,
      },
    });
  } catch (error) {
    sendInternalError(res, error, 'Bootstrap error', {
      success: false,
      error: { code: 'INTERNAL_ERROR', message: 'Failed to load bootstrap data' },
    });
  }
});

