// API tests: governance fields blocked on generic PATCH; allowed via set_governance command.
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { IdRow, requireFirstRow } from '../test/pg-result.js';

describe('Documents API — governance field mass assignment', () => {
  const app = createApp();
  const testRunId = Date.now().toString(36);
  let workspaceId: string;
  let userId: string;
  let sprintId: string;
  let sessionCookie: string;
  let csrfToken: string;

  beforeAll(async () => {
    const workspaceResult = await pool.query<IdRow>(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [`Gov Patch ${testRunId}`]
    );
    workspaceId = requireFirstRow(workspaceResult.rows).id;

    const userResult = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Member')
       RETURNING id`,
      [`gov-patch-${testRunId}@ship.local`]
    );
    userId = requireFirstRow(userResult.rows).id;

    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [workspaceId, userId]
    );

    const sprintResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by)
       VALUES ($1, 'sprint', 'Gov Sprint', 'workspace', $2)
       RETURNING id`,
      [workspaceId, userId]
    );
    sprintId = requireFirstRow(sprintResult.rows).id;

    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at, last_activity)
       VALUES ($1, $2, $3, now() + interval '1 hour', now())`,
      [sessionId, userId, workspaceId]
    );
    sessionCookie = `session_id=${sessionId}`;

    const csrfRes = await request(app).get('/api/csrf-token').set('Cookie', sessionCookie);
    csrfToken = csrfRes.body.token;
    const connectSid = csrfRes.headers['set-cookie']?.[0]?.split(';')[0];
    if (connectSid) sessionCookie = `${sessionCookie}; ${connectSid}`;
  });

  afterAll(async () => {
    await pool.query('DELETE FROM sessions WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM users WHERE id = $1', [userId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [workspaceId]);
  });

  it('rejects member PATCH that injects review_approval and submitted_at', async () => {
    const res = await request(app)
      .patch(`/api/documents/${sprintId}`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Origin', 'http://localhost:5173')
      .send({
        properties: {
          review_approval: { state: 'approved' },
          submitted_at: new Date().toISOString(),
        },
      });

    expect(res.status).toBe(403);
    expect(res.body.error).toMatch(/governance fields/i);
  });

  it('rejects workspace admin PATCH that injects plan_approval', async () => {
    await pool.query(
      `UPDATE workspace_memberships SET role = 'admin' WHERE workspace_id = $1 AND user_id = $2`,
      [workspaceId, userId]
    );

    const res = await request(app)
      .patch(`/api/documents/${sprintId}`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Origin', 'http://localhost:5173')
      .send({
        properties: {
          plan_approval: {
            state: 'approved',
            approved_by: userId,
            approved_at: new Date().toISOString(),
          },
        },
      });

    expect(res.status).toBe(403);
    expect(res.body.error).toMatch(/governance fields/i);
  });

  it('allows workspace admin set_governance command while blocking generic PATCH', async () => {
    await pool.query(
      `UPDATE workspace_memberships SET role = 'admin' WHERE workspace_id = $1 AND user_id = $2`,
      [workspaceId, userId]
    );

    const res = await request(app)
      .post(`/api/documents/${sprintId}/commands`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Origin', 'http://localhost:5173')
      .send({
        type: 'set_governance',
        properties: { public_feedback_enabled: true },
      });

    expect(res.status).toBe(200);
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { IdRow, requireFirstRow } from '../test/pg-result.js';

describe('Documents API — API token scopes at mutation entry', () => {
  const app = createApp();
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const testEmail = `docs-token-${testRunId}@ship.local`;

  let testWorkspaceId: string;
  let testUserId: string;
  let testWikiId: string;
  let readOnlyToken: string;
  let writeToken: string;

  beforeAll(async () => {
    const workspaceResult = await pool.query<IdRow>(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [`Docs Token Scope ${testRunId}`]
    );
    testWorkspaceId = requireFirstRow(workspaceResult.rows).id;

    const userResult = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Test User')
       RETURNING id`,
      [testEmail]
    );
    testUserId = requireFirstRow(userResult.rows).id;

    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'admin')`,
      [testWorkspaceId, testUserId]
    );

    const wikiResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by, content)
       VALUES ($1, 'wiki', 'Token Scope Wiki', 'workspace', $2, '{"type":"doc","content":[]}')
       RETURNING id`,
      [testWorkspaceId, testUserId]
    );
    testWikiId = requireFirstRow(wikiResult.rows).id;

    readOnlyToken = `ship_${crypto.randomBytes(32).toString('hex')}`;
    await pool.query(
      `INSERT INTO api_tokens (user_id, workspace_id, name, token_hash, token_prefix, scopes)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [
        testUserId,
        testWorkspaceId,
        `Read ${testRunId}`,
        crypto.createHash('sha256').update(readOnlyToken).digest('hex'),
        readOnlyToken.slice(0, 8),
        ['documents:read'],
      ]
    );

    writeToken = `ship_${crypto.randomBytes(32).toString('hex')}`;
    await pool.query(
      `INSERT INTO api_tokens (user_id, workspace_id, name, token_hash, token_prefix, scopes)
       VALUES ($1, $2, $3, $4, $5, $6)`,
      [
        testUserId,
        testWorkspaceId,
        `Write ${testRunId}`,
        crypto.createHash('sha256').update(writeToken).digest('hex'),
        writeToken.slice(0, 8),
        ['documents:write'],
      ]
    );
  });

  afterAll(async () => {
    await pool.query('DELETE FROM api_tokens WHERE workspace_id = $1', [testWorkspaceId]);
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [testWorkspaceId]);
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [testWorkspaceId]);
    await pool.query('DELETE FROM users WHERE id = $1', [testUserId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId]);
  });

  it('denies PATCH content for read-only API tokens', async () => {
    const res = await request(app)
      .patch(`/api/documents/${testWikiId}/content`)
      .set('Authorization', `Bearer ${readOnlyToken}`)
      .send({ content: { type: 'doc', content: [] } });

    expect(res.status).toBe(403);
    expect(res.body.error).toBe('token_scope_denied');
  });

  it('denies governance commands for write-only API tokens', async () => {
    const res = await request(app)
      .post(`/api/documents/${testWikiId}/commands`)
      .set('Authorization', `Bearer ${writeToken}`)
      .send({ type: 'set_governance', properties: { accountable_id: testUserId } });

    expect(res.status).toBe(403);
    expect(res.body.error).toBe('token_scope_denied');
  });

  it('allows write-scoped tokens to patch content', async () => {
    const res = await request(app)
      .patch(`/api/documents/${testWikiId}/content`)
      .set('Authorization', `Bearer ${writeToken}`)
      .send({ content: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'scoped' }] }] } });

    expect(res.status).toBe(200);
  });
});

