import { authMiddleware } from '../middleware/auth.js';
import { sendInternalError, sendValidationError } from '../utils/route-http.js';
import { defineRoute } from '../openapi/define-route.js';
import {
  CreateFeedbackRequestSchema,
  FeedbackItemSchema,
  FeedbackIdParamsSchema,
  FeedbackLegacyErrorSchema,
  FeedbackProgramParamsSchema,
  FeedbackProgramPublicSchema,
} from '../openapi/schemas/feedback.js';
import { getActor, getDocumentAccessContext, visibilityPredicate } from '../services/document-access.js';
import { getAuthenticatedRouteContext } from '../utils/auth-context.js';

// Public routes - no auth/CSRF required
export const publicFeedbackRouter: ExpressRouter = Router();

const publicFeedbackSubmitLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: isTestEnv() ? 1000 : 10,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many feedback submissions. Please try again later.' },
});

// Protected routes - auth/CSRF required
const router = Router();

type FeedbackRow = {
  id: string;
  title: string;
  properties: Record<string, unknown> | null;
  ticket_number: number | null;
  program_id?: string | null;
  content: unknown;
  created_at: Date | string;
  updated_at: Date | string;
  created_by: string | null;
  program_name?: string | null;
  program_prefix?: string | null;
  program_color?: string | null;
  created_by_name?: string | null;
};

// Helper to extract feedback from row
function extractFeedbackFromRow(row: FeedbackRow, programPrefix?: string | null) {
  const props = row.properties || {};
  return {
    id: row.id,
    title: row.title,
    state: props.state || 'triage',
    priority: props.priority || 'medium',
    source: props.source || 'external',
    rejection_reason: props.rejection_reason || null,
    assignee_id: props.assignee_id || null,
    ticket_number: row.ticket_number,
    program_id: row.program_id,
    content: row.content,
    created_at: row.created_at,
    updated_at: row.updated_at,
    created_by: row.created_by,
    program_name: row.program_name,
    program_prefix: row.program_prefix || programPrefix,
    program_color: row.program_color,
    created_by_name: row.created_by_name,
    display_id: `#${row.ticket_number}`,
  };
}

// Create feedback - PUBLIC endpoint (no auth required)
// Creates an issue with source='external', state='triage'
publicFeedbackRouter.post(
  '/',
  publicFeedbackSubmitLimiter,
  defineRoute({
    method: 'post',
    path: '/feedback',
    tags: ['Feedback'],
    summary: 'Submit public feedback',
    security: [],
    request: {
      body: CreateFeedbackRequestSchema,
    },
    responses: {
      201: { schema: FeedbackItemSchema, description: 'Feedback created' },
      400: { schema: FeedbackLegacyErrorSchema, description: 'Validation error' },
      404: { schema: FeedbackLegacyErrorSchema, description: 'Program not found' },
      500: { schema: FeedbackLegacyErrorSchema, description: 'Internal server error' },
    },
    validationError: (res, error) => sendValidationError(res, error.zodError),
    handler: async (_req: Request, res: Response, { body }) => {
      try {
        const { title, program_id, submitter_email, content } = body;

        // Verify public feedback is enabled for this workspace-visible program.
        const programResult = await pool.query(
          `SELECT id, workspace_id, properties->>'prefix' as prefix
           FROM documents
           WHERE id = $1
             AND document_type = 'program'
             AND visibility = 'workspace'
             AND archived_at IS NULL
             AND deleted_at IS NULL
             AND properties->>'public_feedback_enabled' = 'true'`,
          [program_id]
        );

        if (programResult.rows.length === 0) {
          res.status(404).json({ error: 'Program not found' });
          return;
        }

        const workspaceId = programResult.rows[0].workspace_id;
        const programPrefix = programResult.rows[0].prefix;

        // Get next ticket number for workspace
        const ticketResult = await pool.query(
          `SELECT COALESCE(MAX(ticket_number), 0) + 1 as next_number
           FROM documents
           WHERE workspace_id = $1 AND document_type = 'issue'`,
          [workspaceId]
        );
        const ticketNumber = ticketResult.rows[0].next_number;

        // Build properties JSONB - external feedback goes directly to triage
        const properties = {
          state: 'triage',
          priority: 'medium',
          source: 'external',
          submitter_email: submitter_email || null,
          assignee_id: null,
          rejection_reason: null,
        };

        // Create the feedback issue (no created_by for public submissions)
        const result = await pool.query(
          `INSERT INTO documents (workspace_id, document_type, title, properties, ticket_number, content)
           VALUES ($1, 'issue', $2, $3, $4, $5)
           RETURNING *`,
          [workspaceId, title, JSON.stringify(properties), ticketNumber, content ? JSON.stringify(content) : null]
        );

        const feedbackId = result.rows[0].id;

        // Create program association via document_associations
        await pool.query(
          `INSERT INTO document_associations (document_id, related_id, relationship_type)
           VALUES ($1, $2, 'program') ON CONFLICT DO NOTHING`,
          [feedbackId, program_id]
        );

        res.status(201).json({ ...extractFeedbackFromRow(result.rows[0], programPrefix), program_id });
      } catch (err) {
        sendInternalError(res, err, 'Create feedback error');
      }
    },
  })
);

// Get program info for public feedback form (no auth required)
publicFeedbackRouter.get(
  '/program/:programId',
  defineRoute({
    method: 'get',
    path: '/feedback/program/{programId}',
    tags: ['Feedback'],
    summary: 'Get public program info for feedback form',
    security: [],
    request: {
      params: FeedbackProgramParamsSchema,
    },
    responses: {
      200: { schema: FeedbackProgramPublicSchema, description: 'Program metadata' },
      404: { schema: FeedbackLegacyErrorSchema, description: 'Program not found' },
      500: { schema: FeedbackLegacyErrorSchema, description: 'Internal server error' },
    },
    validationError: (res) => {
      res.status(404).json({ error: 'Program not found' });
    },
    handler: async (_req: Request, res: Response, { params }) => {
      try {
        const { programId } = params;

        const result = await pool.query(
          `SELECT id, title as name, properties->>'prefix' as prefix, properties->>'color' as color
           FROM documents
           WHERE id = $1
             AND document_type = 'program'
             AND visibility = 'workspace'
             AND archived_at IS NULL
             AND deleted_at IS NULL
             AND properties->>'public_feedback_enabled' = 'true'`,
          [programId]
        );

        if (result.rows.length === 0) {
          res.status(404).json({ error: 'Program not found' });
          return;
        }

        res.json(result.rows[0]);
      } catch (err) {
        sendInternalError(res, err, 'Get program for feedback error');
      }
    },
  })
);

// Get single feedback item
router.get(
  '/:id',
  authMiddleware,
  defineRoute({
    method: 'get',
    path: '/feedback/{id}',
    tags: ['Feedback'],
    summary: 'Get feedback by ID',
    request: {
      params: FeedbackIdParamsSchema,
    },
    responses: {
      200: { schema: FeedbackItemSchema, description: 'Feedback details' },
      404: { schema: FeedbackLegacyErrorSchema, description: 'Feedback not found' },
    },
    handler: async (req, res, { params }) => {
      try {
        const { id } = params;
        const { userId, workspaceId } = getAuthenticatedRouteContext(req);
        const actor = getActor(req);
        const { isAdmin } = await getDocumentAccessContext(actor);

        const result = await pool.query(
          `SELECT d.id, d.title, d.properties, d.ticket_number,
              prog_da.related_id as program_id,
              d.content, d.created_at, d.updated_at, d.created_by,
              p.title as program_name,
              p.properties->>'prefix' as program_prefix,
              p.properties->>'color' as program_color,
              creator.name as created_by_name
       FROM documents d
       LEFT JOIN document_associations prog_da ON d.id = prog_da.document_id AND prog_da.relationship_type = 'program'
       LEFT JOIN documents p ON prog_da.related_id = p.id AND p.document_type = 'program'
       LEFT JOIN users creator ON d.created_by = creator.id
       WHERE d.id = $1
         AND d.workspace_id = $2
         AND d.document_type = 'issue'
         AND d.properties->>'source' = 'external'
         AND d.archived_at IS NULL
         AND d.deleted_at IS NULL
         AND ${visibilityPredicate('d', '$3', '$4')}`,
          [id, workspaceId, userId, isAdmin]
        );

        if (result.rows.length === 0) {
          res.status(404).json({ error: 'Feedback not found' });
          return;
        }

        res.json(extractFeedbackFromRow(result.rows[0]));
      } catch (err) {
        sendInternalError(res, err, 'Get feedback error');
      }
    },
  })
);

// Note: Accept and reject actions are now handled via /api/issues/:id/accept and /api/issues/:id/reject

export default router;

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { UploadResponseSchema } from '../openapi/schemas/files.js';
import { expectOpenApiResponse } from '../test/openapi-response.js';

describe('Files API', () => {
  const app = createApp('http://localhost:5173');
  // Use unique identifiers to avoid conflicts between concurrent test runs
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const testEmail = `files-${testRunId}@ship.local`;
  const testWorkspaceName = `Files Test ${testRunId}`;

  let sessionCookie: string;
  let csrfToken: string;
  let testWorkspaceId: string;
  let testUserId: string;
  let testFileId: string;

  async function createUpload(filename: string, mimeType: string, sizeBytes: number) {
    const res = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({ filename, mimeType, sizeBytes });
    expect(res.status).toBe(200);
    return { fileId: res.body.fileId as string, uploadUrl: res.body.uploadUrl as string };
  }

  beforeAll(async () => {
    // Create test workspace
    const workspaceResult = await pool.query(
      `INSERT INTO workspaces (name) VALUES ($1)
       RETURNING id`,
      [testWorkspaceName]
    );
    testWorkspaceId = workspaceResult.rows[0].id;

    // Create test user
    const userResult = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Files Test User')
       RETURNING id`,
      [testEmail]
    );
    testUserId = userResult.rows[0].id;

    // Create workspace membership
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    );

    // Create session (sessions.id is TEXT not UUID, generated from crypto.randomBytes)
    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [sessionId, testUserId, testWorkspaceId]
    );
    sessionCookie = `session_id=${sessionId}`;

    // Get CSRF token
    const csrfRes = await request(app)
      .get('/api/csrf-token')
      .set('Cookie', sessionCookie);
    csrfToken = csrfRes.body.token;
    // Add connect.sid cookie for CSRF token storage
    const connectSidCookie = csrfRes.headers['set-cookie']?.[0]?.split(';')[0] || '';
    if (connectSidCookie) {
      sessionCookie = `${sessionCookie}; ${connectSidCookie}`;
    }
  });

  afterAll(async () => {
    // Clean up test data in correct order (foreign keys)
    await pool.query('DELETE FROM files WHERE workspace_id = $1', [testWorkspaceId]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM workspace_memberships WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM users WHERE id = $1', [testUserId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId]);
    // Don't close pool - it's shared across test files
  });

  it('POST /api/files/upload returns 403 without valid session (CSRF blocks first)', async () => {
    const res = await request(app)
      .post('/api/files/upload')
      .set('x-csrf-token', 'invalid-token')
      .send({
        filename: 'test.png',
        mimeType: 'image/png',
        sizeBytes: 1024,
      });

    // CSRF protection returns 403 before auth middleware can return 401
    expect(res.status).toBe(403);
  });

  it('POST /api/files/upload creates file record and returns upload URL', async () => {
    const res = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'test.png',
        mimeType: 'image/png',
        sizeBytes: 1024,
      });

    const upload = expectOpenApiResponse({
      method: 'post',
      path: '/files/upload',
      status: 200,
      response: res,
      openApiSchemaName: 'UploadResponse',
      schema: UploadResponseSchema,
    });
    expect(upload.fileId).toBeTruthy();
    expect(upload.uploadUrl).toBeTruthy();

    // Save fileId for later tests
    testFileId = upload.fileId;

    // Verify file record was created in database
    const dbResult = await pool.query(
      'SELECT * FROM files WHERE id = $1',
      [testFileId]
    );
    expect(dbResult.rows.length).toBe(1);
    expect(dbResult.rows[0].status).toBe('pending');
    expect(dbResult.rows[0].filename).toBe('test.png');
    expect(dbResult.rows[0].mime_type).toBe('image/png');
  });

  it('POST /api/files/upload rejects blocked file types', async () => {
    const res = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'malware.exe',
        mimeType: 'application/octet-stream',
        sizeBytes: 1024,
      });

    expect(res.status).toBe(400);
    expect(res.body).toHaveProperty('error');
    expect(res.body.error).toContain('not allowed');
  });

  it('POST /api/files/upload rejects dangerous multi-extension filenames', async () => {
    const res = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'malware.exe.txt',
        mimeType: 'text/plain',
        sizeBytes: 1024,
      });

    expect(res.status).toBe(400);
    expect(res.body.error).toContain('not allowed');
  });

  it('POST /api/files/:id/local-upload rejects bytes that do not match declared size', async () => {
    const { fileId, uploadUrl } = await createUpload('size-check.html', 'text/html', 2048);

    const res = await request(app)
      .post(uploadUrl)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Content-Type', 'text/html')
      .send('<h1>short</h1>');

    expect(res.status).toBe(400);
    expect(res.body.error).toContain('size');

    const dbResult = await pool.query('SELECT status FROM files WHERE id = $1', [fileId]);
    expect(dbResult.rows[0].status).toBe('pending');
  });

  it('GET /api/files/:id/serve downloads uploaded HTML with nosniff', async () => {
    const body = '<h1>cat8</h1>';
    const { fileId, uploadUrl } = await createUpload('safe-download.html', 'text/html', Buffer.byteLength(body));

    const uploadRes = await request(app)
      .post(uploadUrl)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Content-Type', 'text/html')
      .send(body);
    expect(uploadRes.status).toBe(200);

    const serveRes = await request(app)
      .get(`/api/files/${fileId}/serve`)
      .set('Cookie', sessionCookie);

    expect(serveRes.status).toBe(200);
    expect(serveRes.headers['content-disposition']).toContain('attachment');
    expect(serveRes.headers['x-content-type-options']).toBe('nosniff');
  });

  it('returns a generic 400 for malformed JSON bodies', async () => {
    const res = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .set('Content-Type', 'application/json')
      .send('{"broken":');

    expect(res.status).toBe(400);
    expect(res.body).toEqual({ error: 'Malformed JSON request body' });
    expect(res.text).not.toMatch(/stack|node_modules|\/Users\/|DATABASE_URL/i);
  });

  it('POST /api/files/:id/confirm updates file status and returns CDN URL', async () => {
    // First create a file
    const uploadRes = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'confirm-test.png',
        mimeType: 'image/png',
        sizeBytes: 2048,
      });

    const fileId = uploadRes.body.fileId;

    // Confirm the upload
    const confirmRes = await request(app)
      .post(`/api/files/${fileId}/confirm`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken);

    expect(confirmRes.status).toBe(200);
    expect(confirmRes.body).toHaveProperty('fileId');
    expect(confirmRes.body).toHaveProperty('cdnUrl');
    expect(confirmRes.body).toHaveProperty('status');
    expect(confirmRes.body.status).toBe('uploaded');
    expect(confirmRes.body.cdnUrl).toContain(`/api/files/${fileId}/serve`);

    // Verify database was updated
    const dbResult = await pool.query(
      'SELECT * FROM files WHERE id = $1',
      [fileId]
    );
    expect(dbResult.rows[0].status).toBe('uploaded');
    expect(dbResult.rows[0].cdn_url).toBeTruthy();
  });

  it('POST /api/files/:id/confirm returns 404 for non-existent file', async () => {
    const fakeId = crypto.randomUUID();
    const res = await request(app)
      .post(`/api/files/${fakeId}/confirm`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken);

    expect(res.status).toBe(404);
  });

  it('GET /api/files/:id returns file metadata', async () => {
    // First create and confirm a file
    const uploadRes = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'metadata-test.png',
        mimeType: 'image/png',
        sizeBytes: 3072,
      });

    const fileId = uploadRes.body.fileId;

    await request(app)
      .post(`/api/files/${fileId}/confirm`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken);

    // Get file metadata
    const res = await request(app)
      .get(`/api/files/${fileId}`)
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('id');
    expect(res.body).toHaveProperty('filename');
    expect(res.body).toHaveProperty('mime_type');
    expect(res.body).toHaveProperty('size_bytes');
    expect(res.body).toHaveProperty('cdn_url');
    expect(res.body).toHaveProperty('status');
    expect(res.body.filename).toBe('metadata-test.png');
  });

  it('DELETE /api/files/:id deletes file record', async () => {
    // First create a file
    const uploadRes = await request(app)
      .post('/api/files/upload')
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken)
      .send({
        filename: 'delete-test.png',
        mimeType: 'image/png',
        sizeBytes: 4096,
      });

    const fileId = uploadRes.body.fileId;

    // Delete the file
    const deleteRes = await request(app)
      .delete(`/api/files/${fileId}`)
      .set('Cookie', sessionCookie)
      .set('x-csrf-token', csrfToken);

    expect(deleteRes.status).toBe(200);
    expect(deleteRes.body).toHaveProperty('success', true);

    // Verify file was deleted from database
    const dbResult = await pool.query(
      'SELECT * FROM files WHERE id = $1',
      [fileId]
    );
    expect(dbResult.rows.length).toBe(0);
  });
});

// File upload routes: presigned S3/local uploads, confirm, serve, and delete with capability checks.
import { Router, type Router as ExpressRouter, Request, Response } from 'express';
import express from 'express';
import { pool } from '../db/client.js';
import { z } from 'zod';
import { randomUUID } from 'crypto';
import { mkdir, writeFile, unlink } from 'fs/promises';
import { basename, join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { authMiddleware } from '../middleware/auth.js';
import { getActor, getDocumentAccessContext } from '../services/document-access.js';
import { authorize, type Capability } from '../security/capabilities.js';
import { principalFromRequest } from '../security/principal.js';
import { useS3Uploads } from '../config/runtime.js';
import { sendInternalError, sendLegacyError, sendValidationError } from '../utils/route-http.js';
import { S3Client, PutObjectCommand, DeleteObjectCommand, HeadObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// Local uploads directory (for development)
const UPLOADS_DIR = join(__dirname, '../../uploads');

// S3 configuration
const S3_BUCKET_NAME = process.env.S3_UPLOADS_BUCKET || '';
const AWS_REGION = process.env.AWS_REGION || 'us-east-1';

// Max file size: 1GB (1073741824 bytes)
const MAX_FILE_SIZE = 1073741824;

// Presigned URL expiration: 15 minutes
const PRESIGNED_URL_EXPIRES_IN = 15 * 60;

// Initialize S3 client (only when bucket is configured)
let s3Client: S3Client | null = null;
function getS3Client(): S3Client {
  if (!s3Client) {
    s3Client = new S3Client({ region: AWS_REGION });
  }
  return s3Client;
}

// UUID validation regex - prevents path traversal by ensuring ID is valid UUID
const UUID_REGEX = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function isValidUUID(id: string | string[] | undefined): id is string {
  if (!id || Array.isArray(id)) return false;
  return UUID_REGEX.test(id);
}

export const filesRouter: ExpressRouter = Router();

// Validation schemas
const uploadRequestSchema = z.object({
  filename: z.string().min(1).max(255),
  mimeType: z.string().min(1).max(100),
  sizeBytes: z.number().int().positive().max(MAX_FILE_SIZE, {
    message: `File size exceeds maximum allowed (${MAX_FILE_SIZE / (1024 * 1024 * 1024)}GB)`,
  }),
  documentId: z.string().uuid().optional(),
});

/**
 * Blocked file extensions for security (executables and scripts)
 * We allow ANY file type EXCEPT these dangerous extensions.
 * Check by extension, not MIME type (MIME types are unreliable and can be spoofed).
 */
const BLOCKED_EXTENSIONS = new Set([
  // Windows executables
  '.exe', '.bat', '.cmd', '.com', '.msi', '.scr', '.pif',
  // Windows scripts
  '.vbs', '.vbe', '.js', '.jse', '.ws', '.wsf', '.wsc', '.wsh',
  // Windows system files
  '.dll', '.sys', '.drv', '.cpl', '.ocx',
  // Windows shortcuts and config
  '.lnk', '.inf', '.reg', '.msc',
  // macOS executables
  '.app', '.dmg', '.pkg',
  // Linux executables and packages
  '.sh', '.bash', '.deb', '.rpm', '.run',
  // Cross-platform
  '.jar', '.ps1', '.psm1', '.psd1',
]);

function isAllowedFile(filename: string, _mimeType: string): boolean {
  const safeName = basename(filename).toLowerCase();
  const extensions = safeName.split('.').slice(1).map((ext) => `.${ext}`);
  return extensions.every((ext) => !BLOCKED_EXTENSIONS.has(ext));
}

function safeAttachmentFilename(filename: string): string {
  return basename(filename).replace(/[\r\n"]/g, '_').trim() || 'download';
}

function authorizeRequest(req: Request, capability: Capability) {
  return authorize(pool, principalFromRequest(req), capability);
}

// POST /api/files/upload - Get presigned URL for upload
// For local dev: returns a mock upload URL
// For production: would return S3 presigned URL
filesRouter.post('/upload', authMiddleware, async (req: Request, res: Response) => {
  try {
    const validation = uploadRequestSchema.safeParse(req.body);
    if (!validation.success) {
      sendValidationError(res, validation.error);
      return;
    }

    const { filename, mimeType, sizeBytes, documentId } = validation.data;
    const workspaceId = req.workspaceId;
    const userId = req.userId;

    // Validate file type
    if (!isAllowedFile(filename, mimeType)) {
      sendLegacyError(res, 400, 'File type not allowed');
      return;
    }

    if (documentId) {
      const decision = await authorizeRequest(req, {
        resource: 'file',
        action: 'create_upload',
        documentId,
      });
      if (!decision.allowed) {
        res.status(403).json({ error: 'Document not accessible' });
        return;
      }
    }

    // Generate unique S3 key / local path
    const fileId = randomUUID();
    const ext = filename.slice(filename.lastIndexOf('.'));
    const s3Key = `${workspaceId}/${fileId}${ext}`;

    // Create file record with 'pending' status
    const result = await pool.query(
      `INSERT INTO files (id, workspace_id, uploaded_by, filename, mime_type, size_bytes, s3_key, status, document_id)
       VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', $8)
       RETURNING id`,
      [fileId, workspaceId, userId, filename, mimeType, sizeBytes, s3Key, documentId ?? null]
    );

    // Use S3 when configured; otherwise use local storage for lightweight deployments.
    const uploadUrl = useS3Uploads()
      ? await generateS3PresignedUrl(s3Key, mimeType, sizeBytes)
      : `/api/files/${fileId}/local-upload`;

    res.json({
      fileId: result.rows[0].id,
      uploadUrl,
      s3Key,
    });
  } catch (error) {
    sendInternalError(res, error, 'Error creating upload:', { error: 'Failed to create upload' });
  }
});

