      const { isAdmin } = await getDocumentAccessContext(actor);
      if (file.uploaded_by !== req.userId && !isAdmin && !req.isSuperAdmin) {
        res.status(403).json({ error: 'Only the uploader or an admin can delete this file' });
        return;
      }
    }

