      ]
    );
    const titleResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
       VALUES ($1, 'wiki', 'RankNeedleBeta Title Ranked Doc', $2, $3)
