    expect(res.status).toBe(200);
    const body = res.body as ContentSearchResponse;
    const ids = body.documents.map((doc) => doc.id);
    expect(ids.indexOf(requireFirstRow(titleResult.rows).id)).toBeLessThan(ids.indexOf(requireFirstRow(bodyResult.rows).id));
  });

  it('GET /api/search/content filters by document type', async () => {
    const wikiResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
       VALUES ($1, 'wiki', 'Type Content Wiki', $2, $3)
       RETURNING id`,
      [
        testWorkspaceId,
        JSON.stringify({ type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'TypeNeedleGamma' }] }] }),
        testUserId,
      ]
    );
    const issueResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
       VALUES ($1, 'issue', 'Type Content Issue', $2, $3)
       RETURNING id`,
      [
        testWorkspaceId,
        JSON.stringify({ type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'TypeNeedleGamma' }] }] }),
        testUserId,
      ]
    );
    await rebuildSearchIndex();

    const res = await request(app)
      .get('/api/search/content?q=TypeNeedleGamma&type=issue')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    const body = res.body as ContentSearchResponse;
    const ids = body.documents.map((doc) => doc.id);
    expect(ids).toContain(requireFirstRow(issueResult.rows).id);
    expect(ids).not.toContain(requireFirstRow(wikiResult.rows).id);
    expect(body.documents.every((doc) => doc.document_type === 'issue')).toBe(true);
  });

  it('GET /api/search/content validates document type', async () => {
    const res = await request(app)
      .get('/api/search/content?q=test&type=made_up')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(400);
    expect(res.body.error).toBe('Invalid document type');
  });

  it('GET /api/search/content applies visibility before limit', async () => {
    const privateResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, visibility, created_by)
       VALUES ($1, 'wiki', 'Private LimitVisibilityNeedleDelta LimitVisibilityNeedleDelta', $2, 'private', $3)
       RETURNING id`,
      [
        testWorkspaceId,
        JSON.stringify({
          type: 'doc',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'LimitVisibilityNeedleDelta LimitVisibilityNeedleDelta' }] }],
        }),
        secondTestUserId,
      ]
    );
    const visibleResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, visibility, created_by)
       VALUES ($1, 'wiki', 'Visible Limit Doc', $2, 'workspace', $3)
       RETURNING id`,
      [
        testWorkspaceId,
        JSON.stringify({
          type: 'doc',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'LimitVisibilityNeedleDelta' }] }],
        }),
        testUserId,
      ]
    );
    await rebuildSearchIndex();

    const userRes = await request(app)
      .get('/api/search/content?q=LimitVisibilityNeedleDelta&limit=1')
      .set('Cookie', sessionCookie);

    expect(userRes.status).toBe(200);
    expect(userRes.body.documents).toHaveLength(1);
    expect(userRes.body.documents[0].id).toBe(requireFirstRow(visibleResult.rows).id);

    const secondUserRes = await request(app)
      .get('/api/search/content?q=LimitVisibilityNeedleDelta&limit=1')
      .set('Cookie', secondUserSessionCookie);

    expect(secondUserRes.status).toBe(200);
    expect(secondUserRes.body.documents[0].id).toBe(requireFirstRow(privateResult.rows).id);
  });

  it('GET /api/search/content respects limit and offset', async () => {
    await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, content, created_by, updated_at)
       VALUES ($1, 'wiki', 'OffsetNeedleEpsilon A', '{"type":"doc","content":[]}', $2, now() - interval '3 minutes'),
              ($1, 'wiki', 'OffsetNeedleEpsilon B', '{"type":"doc","content":[]}', $2, now() - interval '2 minutes'),
              ($1, 'wiki', 'OffsetNeedleEpsilon C', '{"type":"doc","content":[]}', $2, now() - interval '1 minute')`,
      [testWorkspaceId, testUserId]
    );
    await rebuildSearchIndex();

    const res = await request(app)
      .get('/api/search/content?q=OffsetNeedleEpsilon&limit=1&offset=1')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    expect(res.body).toMatchObject({
      total: 3,
      limit: 1,
      offset: 1,
    });
    expect(res.body.documents).toHaveLength(1);
    expect(res.body.documents[0].title).toBe('OffsetNeedleEpsilon B');
  });

  it('REST document content updates refresh the search index', async () => {
    const createRes = await request(app)
      .post('/api/documents')
      .set('Authorization', `Bearer ${testApiToken}`)
      .send({
        title: 'REST Search Indexed',
        document_type: 'wiki',
      });

    expect(createRes.status).toBe(201);
    const docId = createRes.body.id;

    const firstUpdate = await request(app)
      .patch(`/api/documents/${docId}/content`)
      .set('Authorization', `Bearer ${testApiToken}`)
      .send({
        content: {
          type: 'doc',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'RestNeedleZeta' }] }],
        },
      });

    expect(firstUpdate.status).toBe(200);

    const firstSearch = await request(app)
      .get('/api/search/content?q=RestNeedleZeta')
      .set('Cookie', sessionCookie);

    expect(firstSearch.status).toBe(200);
    const firstBody = firstSearch.body as ContentSearchResponse;
    expect(firstBody.documents.map((doc) => doc.id)).toContain(docId);

    const secondUpdate = await request(app)
      .patch(`/api/documents/${docId}/content`)
      .set('Authorization', `Bearer ${testApiToken}`)
      .send({
        content: {
          type: 'doc',
          content: [{ type: 'paragraph', content: [{ type: 'text', text: 'ReplacementNeedleEta' }] }],
        },
      });

    expect(secondUpdate.status).toBe(200);

    const oldTermSearch = await request(app)
      .get('/api/search/content?q=RestNeedleZeta')
      .set('Cookie', sessionCookie);
    const newTermSearch = await request(app)
      .get('/api/search/content?q=ReplacementNeedleEta')
      .set('Cookie', sessionCookie);

    expect(oldTermSearch.status).toBe(200);
    expect(newTermSearch.status).toBe(200);
    const oldBody = oldTermSearch.body as ContentSearchResponse;
    const newBody = newTermSearch.body as ContentSearchResponse;
    expect(oldBody.documents.map((doc) => doc.id)).not.toContain(docId);
    expect(newBody.documents.map((doc) => doc.id)).toContain(docId);
  });
});

describe('Search Learnings API', () => {
  const app = createApp('http://localhost:5173');
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  const testEmail = `learning-${testRunId}@ship.local`;
  const testWorkspaceName = `Learning Test ${testRunId}`;

  let sessionCookie: string;
  let testWorkspaceId: string;
  let testUserId: string;
  let learningDocId: string;
  let regularWikiId: string;

  beforeAll(async () => {
    // Create test workspace
    const workspaceResult = await pool.query<IdRow>(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [testWorkspaceName]
    );
    testWorkspaceId = requireFirstRow(workspaceResult.rows).id;

    // Create test user
    const userResult = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Learning Test User')
       RETURNING id`,
      [testEmail]
    );
    testUserId = requireFirstRow(userResult.rows).id;

    // Create workspace membership
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    );

    // Create session
    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [sessionId, testUserId, testWorkspaceId]
    );
    sessionCookie = `session_id=${sessionId}`;

    // Create learning document (title starts with "Learning:")
    const learningResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, properties, content, created_by)
       VALUES ($1, 'wiki', 'Learning: API Token Authentication', $2, '{"type":"doc","content":[]}', $3)
       RETURNING id`,
      [testWorkspaceId, JSON.stringify({ tags: ['security', 'api'], category: 'authentication', source_prd: 'test-prd' }), testUserId]
    );
    learningDocId = requireFirstRow(learningResult.rows).id;

    // Create regular wiki document (should not appear in learnings search)
    const regularResult = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
       VALUES ($1, 'wiki', 'Regular Wiki Document', '{}', $2)
       RETURNING id`,
      [testWorkspaceId, testUserId]
    );
    regularWikiId = requireFirstRow(regularResult.rows).id;
  });

  afterAll(async () => {
    await pool.query('DELETE FROM documents WHERE id IN ($1, $2)', [learningDocId, regularWikiId]);
    await pool.query('DELETE FROM sessions WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM workspace_memberships WHERE user_id = $1', [testUserId]);
    await pool.query('DELETE FROM users WHERE id = $1', [testUserId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId]);
  });

  it('GET /api/search/learnings returns 401 without auth', async () => {
    const res = await request(app).get('/api/search/learnings');
    expect(res.status).toBe(401);
  });

  it('GET /api/search/learnings returns learnings by title', async () => {
    const res = await request(app)
      .get('/api/search/learnings')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    expect(res.body).toHaveProperty('learnings');
    expect(res.body).toHaveProperty('total');
    expect(Array.isArray(res.body.learnings)).toBe(true);

    // Should find our learning document
    const body = res.body as LearningSearchResponse;
    const learning = body.learnings.find((l) => l.id === learningDocId);
    expect(learning).toBeDefined();
    if (!learning) {
      throw new Error('Expected learning document in search results');
    }
    expect(learning.title).toBe('Learning: API Token Authentication');
  });

  it('GET /api/search/learnings filters by keyword', async () => {
    const res = await request(app)
      .get('/api/search/learnings?q=authentication')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    expect(res.body.learnings.length).toBeGreaterThan(0);
    expect(res.body.learnings[0].category).toBe('authentication');
  });

  it('GET /api/search/learnings returns tags and metadata', async () => {
    const res = await request(app)
      .get('/api/search/learnings?q=API')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    const body = res.body as LearningSearchResponse;
    const learning = body.learnings.find((l) => l.id === learningDocId);
    expect(learning).toBeDefined();
    if (!learning) {
      throw new Error('Expected learning document in search results');
    }
    expect(learning.tags).toContain('security');
    expect(learning.source_prd).toBe('test-prd');
  });

  it('GET /api/search/learnings excludes non-learning wiki docs', async () => {
    const res = await request(app)
      .get('/api/search/learnings?q=Regular')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    // Regular wiki doc should not appear
    const body = res.body as LearningSearchResponse;
    const regularDoc = body.learnings.find((l) => l.id === regularWikiId);
    expect(regularDoc).toBeUndefined();
  });

  it('GET /api/search/learnings respects limit parameter', async () => {
    const res = await request(app)
      .get('/api/search/learnings?limit=1')
      .set('Cookie', sessionCookie);

    expect(res.status).toBe(200);
    expect(res.body.learnings.length).toBeLessThanOrEqual(1);
  });
});

import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import request from 'supertest';
import crypto from 'crypto';
import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { requireFirstRow, type IdRow } from '../test/pg-result.js';

describe('security graph visibility regressions', () => {
  const app = createApp();
  const runId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);

  let workspaceId: string;
  let memberId: string;
  let otherUserId: string;
  let memberPersonId: string;
  let memberCookie: string;
  let csrfToken: string;

  beforeAll(async () => {
    const workspace = await pool.query<IdRow>(
      `INSERT INTO workspaces (name, sprint_start_date) VALUES ($1, CURRENT_DATE) RETURNING id`,
      [`Security Graph ${runId}`]
    );
    workspaceId = requireFirstRow(workspace.rows).id;

    const member = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Graph Member') RETURNING id`,
      [`graph-member-${runId}@ship.local`]
    );
    memberId = requireFirstRow(member.rows).id;

    const other = await pool.query<IdRow>(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Graph Other') RETURNING id`,
      [`graph-other-${runId}@ship.local`]
    );
    otherUserId = requireFirstRow(other.rows).id;

    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member'), ($1, $3, 'member')`,
      [workspaceId, memberId, otherUserId]
    );

    const person = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by, properties)
       VALUES ($1, 'person', 'Graph Member Person', 'workspace', $2, $3)
       RETURNING id`,
      [workspaceId, memberId, JSON.stringify({ user_id: memberId, email: `graph-member-${runId}@ship.local` })]
    );
    memberPersonId = requireFirstRow(person.rows).id;

    const sessionId = crypto.randomBytes(32).toString('hex');
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [sessionId, memberId, workspaceId]
    );
    memberCookie = `session_id=${sessionId}`;

    const csrf = await request(app).get('/api/csrf-token').set('Cookie', memberCookie);
    csrfToken = csrf.body.token;
    const connectSidCookie = csrf.headers['set-cookie']?.[0]?.split(';')[0] || '';
    if (connectSidCookie) memberCookie = `${memberCookie}; ${connectSidCookie}`;
  });

  afterAll(async () => {
    await pool.query(
      `DELETE FROM document_associations
       WHERE document_id IN (SELECT id FROM documents WHERE workspace_id = $1)
          OR related_id IN (SELECT id FROM documents WHERE workspace_id = $1)`,
      [workspaceId]
    );
    await pool.query('DELETE FROM document_links WHERE source_id IN (SELECT id FROM documents WHERE workspace_id = $1)', [workspaceId]);
    await pool.query('DELETE FROM sessions WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM workspace_memberships WHERE workspace_id = $1', [workspaceId]);
    await pool.query('DELETE FROM users WHERE id IN ($1, $2)', [memberId, otherUserId]);
    await pool.query('DELETE FROM workspaces WHERE id = $1', [workspaceId]);
  });

  it('does not echo association metadata and omits hidden related documents', async () => {
    const source = await insertDoc('wiki', 'Visible Source', memberId, 'workspace');
    const visibleProgram = await insertDoc('program', 'Visible Program', memberId, 'workspace');
    const privateProgram = await insertDoc('program', 'Secret Program', otherUserId, 'private');

    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type, metadata)
       VALUES ($1, $2, 'program', $3), ($1, $4, 'program', $5)`,
      [
        source,
        visibleProgram,
        JSON.stringify({ secret: 'visible-internal' }),
        privateProgram,
        JSON.stringify({ secret: 'private-internal' }),
      ]
    );

    const response = await request(app)
      .get(`/api/documents/${source}/associations`)
      .set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    expect(response.body).toHaveLength(1);
    expect(response.body[0].related_id).toBe(visibleProgram);
    expect(JSON.stringify(response.body)).not.toContain(privateProgram);
    expect(JSON.stringify(response.body)).not.toContain('internal');
    expect(response.body[0].metadata).toBeUndefined();
  });

  it('omits hidden program ids from document context breadcrumbs', async () => {
    const issue = await insertDoc('issue', 'Visible Issue', memberId, 'workspace');
    const privateProgram = await insertDoc('program', 'Hidden Breadcrumb Program', otherUserId, 'private');
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'program')`,
      [issue, privateProgram]
    );

    const response = await request(app)
      .get(`/api/documents/${issue}/context`)
      .set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    expect(JSON.stringify(response.body)).not.toContain(privateProgram);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Breadcrumb Program');
  });

  it('counts only visible associated documents in bootstrap aggregates', async () => {
    const program = await insertDoc('program', 'Counted Program', memberId, 'workspace');
    const visibleIssue = await insertDoc('issue', 'Visible Count Issue', memberId, 'workspace');
    const privateIssue = await insertDoc('issue', 'Hidden Count Issue', otherUserId, 'private');
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $3, 'program'), ($2, $3, 'program')`,
      [visibleIssue, privateIssue, program]
    );

    const response = await request(app).get('/api/bootstrap').set('Cookie', memberCookie);
    expect(response.status).toBe(200);
    const found = response.body.data.programs.find((item: { id: string }) => item.id === program);
    expect(Number(found.issue_count)).toBe(1);
    expect(JSON.stringify(found)).not.toContain('Hidden Count Issue');
  });

  it('does not reveal hidden program ids from visible bootstrap projects', async () => {
    const privateProgram = await insertDoc('program', 'Hidden Bootstrap Program', otherUserId, 'private');
    const project = await insertDoc('project', 'Visible Bootstrap Project', memberId, 'workspace');
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'program')`,
      [project, privateProgram]
    );

    const response = await request(app).get('/api/bootstrap').set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    const found = response.body.data.projects.find((item: { id: string }) => item.id === project);
    expect(found).toBeTruthy();
    expect(found.program_id).toBeNull();
    expect(JSON.stringify(response.body)).not.toContain(privateProgram);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Bootstrap Program');
  });

  it('does not reveal hidden program metadata from team project options', async () => {
    const privateProgram = await insertDoc('program', 'Hidden Team Project Program', otherUserId, 'private', {
      emoji: 'HIDDEN',
      color: '#f00',
    });
    const project = await insertDoc('project', 'Visible Team Project Option', memberId, 'workspace');
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'program')`,
      [project, privateProgram]
    );

    const response = await request(app).get('/api/team/projects').set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    const found = response.body.find((item: { id: string }) => item.id === project);
    expect(found).toBeTruthy();
    expect(found.programId).toBeNull();
    expect(JSON.stringify(response.body)).not.toContain(privateProgram);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Team Project Program');
    expect(JSON.stringify(response.body)).not.toContain('HIDDEN');
  });

  it('does not reveal hidden project metadata from explicit team assignments', async () => {
    const privateProject = await insertDoc('project', 'Hidden Explicit Assignment Project', otherUserId, 'private');
    await insertDoc('sprint', 'Visible Explicit Assignment Sprint', memberId, 'workspace', {
      sprint_number: 1,
      project_id: privateProject,
      assignee_ids: [memberPersonId],
    });

    const response = await request(app).get('/api/team/assignments').set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    expect(JSON.stringify(response.body)).not.toContain(privateProject);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Explicit Assignment Project');
  });

  it('does not reveal hidden project metadata from inferred team assignments', async () => {
    const sprint = await insertDoc('sprint', 'Visible Inferred Assignment Sprint', memberId, 'workspace', {
      start_date: new Date().toISOString().split('T')[0],
    });
    const privateProject = await insertDoc('project', 'Hidden Inferred Assignment Project', otherUserId, 'private');
    const issue = await insertDoc('issue', 'Visible Inferred Assignment Issue', memberId, 'workspace', {
      assignee_id: memberId,
    });
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'sprint'), ($1, $3, 'project')`,
      [issue, sprint, privateProject]
    );

    const response = await request(app).get('/api/team/assignments').set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    expect(JSON.stringify(response.body)).not.toContain(privateProject);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Inferred Assignment Project');
  });

  it('does not reveal private program metadata in team grid', async () => {
    const privateProgram = await insertDoc('program', 'Hidden Team Program', otherUserId, 'private', {
      emoji: 'LOCK',
      color: '#ff0000',
    });
    const sprint = await insertDoc('sprint', 'Visible Sprint', memberId, 'workspace', {
      start_date: new Date().toISOString().split('T')[0],
      end_date: new Date().toISOString().split('T')[0],
    });
    const issue = await insertDoc('issue', 'Visible Team Issue', memberId, 'workspace', {
      assignee_id: memberId,
      state: 'todo',
    });
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'sprint'), ($1, $3, 'program')`,
      [issue, sprint, privateProgram]
    );

    const response = await request(app)
      .get('/api/team/grid?fromSprint=1&toSprint=2')
      .set('Cookie', memberCookie);

    expect(response.status).toBe(200);
    expect(JSON.stringify(response.body)).not.toContain(privateProgram);
    expect(JSON.stringify(response.body)).not.toContain('Hidden Team Program');
    expect(JSON.stringify(response.body)).not.toContain('LOCK');
  });

  it('shows only visible incomplete children in parent close warnings', async () => {
    const parent = await insertDoc('issue', 'Closable Parent', memberId, 'workspace', { state: 'todo' });
    const visibleChild = await insertDoc('issue', 'Visible Child Warning', memberId, 'workspace', { state: 'todo' });
    const privateChild = await insertDoc('issue', 'Private Child Warning', otherUserId, 'private', { state: 'todo' });
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $3, 'parent'), ($2, $3, 'parent')`,
      [visibleChild, privateChild, parent]
    );

    const response = await request(app)
      .patch(`/api/issues/${parent}`)
      .set('Cookie', memberCookie)
      .set('x-csrf-token', csrfToken)
      .send({ state: 'done' });

    expect(response.status).toBe(409);
    expect(response.body.incomplete_children).toHaveLength(1);
    expect(response.body.incomplete_children[0].id).toBe(visibleChild);
    expect(JSON.stringify(response.body)).not.toContain(privateChild);
    expect(JSON.stringify(response.body)).not.toContain('Private Child Warning');
  });

  it('blocks member public feedback enablement through generic document PATCH', async () => {
    const program = await insertDoc('program', 'Feedback Program', memberId, 'workspace', {
      public_feedback_enabled: false,
    });

    const response = await request(app)
      .patch(`/api/documents/${program}`)
      .set('Cookie', memberCookie)
      .set('x-csrf-token', csrfToken)
      .send({ properties: { public_feedback_enabled: true } });

    expect(response.status).toBe(403);

    const stored = await pool.query<{ properties: Record<string, unknown> }>(
      `SELECT properties FROM documents WHERE id = $1`,
      [program]
    );
    expect(stored.rows[0]?.properties.public_feedback_enabled).toBe(false);
  });

  async function insertDoc(
    type: string,
    title: string,
    createdBy: string,
    visibility: 'private' | 'workspace',
    properties: Record<string, unknown> = {}
  ): Promise<string> {
    const result = await pool.query<IdRow>(
      `INSERT INTO documents (workspace_id, document_type, title, visibility, created_by, properties)
       VALUES ($1, $2, $3, $4, $5, $6)
       RETURNING id`,
      [workspaceId, type, title, visibility, createdBy, JSON.stringify(properties)]
    );
    return requireFirstRow(result.rows).id;
  }
});

import { describe, it, expect } from 'vitest';
import request from 'supertest';

import { createApp } from '../app.js';
import { pool } from '../db/client.js';
import { SetupInitializeResponseSchema } from '../openapi/schemas/setup.js';
import { expectOpenApiResponse } from '../test/openapi-response.js';

function cookieHeader(response: request.Response): string {
  return response.headers['set-cookie']?.map((cookie: string) => cookie.split(';')[0]).join('; ') ?? '';
}

async function csrf(agent: request.SuperAgentTest) {
  const response = await agent.get('/api/csrf-token');
  return {
    token: response.body.token,
    cookie: cookieHeader(response),
  };
}

describe('Setup API', () => {
  const app = createApp();

  it('requires the one-time setup token when configured', async () => {
    const previous = process.env.SHIP_SETUP_TOKEN;
    process.env.SHIP_SETUP_TOKEN = 'expected-setup-token';
    const agent = request.agent(app);
    const csrfToken = await csrf(agent);

    try {
      const response = await agent
        .post('/api/setup/initialize')
        .set('Cookie', csrfToken.cookie)
        .set('x-csrf-token', csrfToken.token)
        .send({
          email: 'setup-token-denied@ship.local',
          password: 'setup-password',
          name: 'Setup Token Denied',
        });

      expect(response.status).toBe(403);
      const counts = await pool.query('SELECT COUNT(*)::int AS users FROM users');
      expect(counts.rows[0]).toEqual({ users: 0 });
    } finally {
      if (previous === undefined) {
        delete process.env.SHIP_SETUP_TOKEN;
      } else {
        process.env.SHIP_SETUP_TOKEN = previous;
      }
    }
  });

  it('allows only one concurrent first-run initialization', async () => {
    const agentA = request.agent(app);
    const agentB = request.agent(app);
    const csrfA = await csrf(agentA);
    const csrfB = await csrf(agentB);

    const [responseA, responseB] = await Promise.all([
      agentA
        .post('/api/setup/initialize')
        .set('Cookie', csrfA.cookie)
        .set('x-csrf-token', csrfA.token)
        .send({
          email: 'setup-race-a@ship.local',
          password: 'setup-password-a',
          name: 'Setup Race A',
        }),
      agentB
        .post('/api/setup/initialize')
        .set('Cookie', csrfB.cookie)
        .set('x-csrf-token', csrfB.token)
        .send({
          email: 'setup-race-b@ship.local',
          password: 'setup-password-b',
          name: 'Setup Race B',
        }),
    ]);

    const statuses = [responseA.status, responseB.status].sort((a, b) => a - b);
    expect(statuses).toEqual([201, 403]);

    const created = responseA.status === 201 ? responseA : responseB;
    const setup = expectOpenApiResponse({
      method: 'post',
      path: '/setup/initialize',
      status: 201,
      response: created,
      openApiSchemaName: 'SetupInitializeResponse',
      schema: SetupInitializeResponseSchema,
    });
    expect(setup.data.user.isSuperAdmin).toBe(true);

    const counts = await pool.query(`
      SELECT
        (SELECT COUNT(*)::int FROM users) AS users,
        (SELECT COUNT(*)::int FROM workspaces) AS workspaces,
        (SELECT COUNT(*)::int FROM workspace_memberships) AS memberships
    `);
    expect(counts.rows[0]).toEqual({ users: 1, workspaces: 1, memberships: 1 });
  });
});

import { Router } from 'express';
import bcrypt from 'bcryptjs';
import { pool } from '../db/client.js';
import { ERROR_CODES, HTTP_STATUS, PASSWORD_BCRYPT_ROUNDS } from '@ship/shared';
import { WELCOME_DOCUMENT_TITLE, WELCOME_DOCUMENT_CONTENT } from '../db/welcomeDocument.js';
import { defineRoute } from '../openapi/define-route.js';
import { ApiErrorResponseSchema } from '../openapi/schemas/common.js';
import {
  SetupInitializeRequestSchema,
  SetupInitializeResponseSchema,
  SetupStatusResponseSchema,
} from '../openapi/schemas/setup.js';
import { authorize } from '../security/capabilities.js';
import { setupPrincipalFromRequest } from '../security/setup-access.js';

const router = Router();

async function ensureSetupAuthorized(
  req: { headers: Record<string, unknown>; principal?: import('../security/principal.js').Principal },
  body?: { setup_token?: string }
): Promise<{ allowed: true } | { allowed: false; message: string }> {
  const principal = setupPrincipalFromRequest(req, body);
  req.principal = principal;
  const decision = await authorize(pool, principal, { resource: 'setup', action: 'initialize' });
  if (decision.allowed) {
    return { allowed: true };
  }
  return {
    allowed: false,
    message: decision.reason === 'setup_token_required' ? 'Setup token required' : 'Setup not authorized',
  };
}

router.get(
  '/status',
  defineRoute({
    method: 'get',
    path: '/setup/status',
    tags: ['Setup'],
    summary: 'Check whether initial setup is required',
    security: [],
    responses: {
      200: { schema: SetupStatusResponseSchema, description: 'Setup status' },
      500: { schema: ApiErrorResponseSchema, description: 'Internal server error' },
    },
    handler: async (req, res) => {
      try {
        const result = await pool.query('SELECT COUNT(*) as count FROM users');
        const userCount = parseInt(result.rows[0].count);
        const needsSetup = userCount === 0;
        const auth = await ensureSetupAuthorized(req);

        res.json({
          success: true,
          data: {
            needsSetup: needsSetup && auth.allowed,
          },
        });
      } catch (error) {
        console.error('Setup status error:', error);
        res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
          success: false,
          error: {
            code: ERROR_CODES.INTERNAL_ERROR,
            message: 'Failed to check setup status',
          },
        });
      }
    },
  })
);

router.post(
  '/initialize',
  defineRoute({
    method: 'post',
    path: '/setup/initialize',
    tags: ['Setup'],
    summary: 'Create first super admin and workspace',
    security: [],
    request: {
      body: SetupInitializeRequestSchema,
    },
    responses: {
      201: { schema: SetupInitializeResponseSchema, description: 'Setup complete' },
      400: { schema: ApiErrorResponseSchema, description: 'Validation error' },
      403: { schema: ApiErrorResponseSchema, description: 'Setup already completed' },
      500: { schema: ApiErrorResponseSchema, description: 'Internal server error' },
    },
    handler: async (req, res, { body }) => {
      const { email, password, name } = body;

      const auth = await ensureSetupAuthorized(req, body);
      if (!auth.allowed) {
        res.status(HTTP_STATUS.FORBIDDEN).json({
          success: false,
          error: {
            code: ERROR_CODES.FORBIDDEN,
            message: auth.message,
          },
        });
        return;
      }

      if (password.length < 8) {
        res.status(HTTP_STATUS.BAD_REQUEST).json({
          success: false,
          error: {
            code: ERROR_CODES.VALIDATION_ERROR,
            message: 'Password must be at least 8 characters',
          },
        });
        return;
      }

      const passwordHash = await bcrypt.hash(password, PASSWORD_BCRYPT_ROUNDS);
      const client = await pool.connect();

      try {
        await client.query('BEGIN');
        await client.query(`SELECT pg_advisory_xact_lock(hashtext('ship_setup_initialize'))`);

        const countResult = await client.query('SELECT COUNT(*) as count FROM users');
        const userCount = parseInt(countResult.rows[0].count);

        if (userCount > 0) {
          await client.query('ROLLBACK');
          res.status(HTTP_STATUS.FORBIDDEN).json({
            success: false,
            error: {
              code: ERROR_CODES.FORBIDDEN,
              message: 'Setup has already been completed',
            },
          });
          return;
        }

        const workspaceResult = await client.query(
          `INSERT INTO workspaces (name)
           VALUES ($1)
           RETURNING id`,
          [`${name}'s Workspace`]
        );
        const workspaceId = workspaceResult.rows[0].id;

        const userResult = await client.query(
          `INSERT INTO users (email, password_hash, name, is_super_admin, last_workspace_id)
           VALUES ($1, $2, $3, true, $4)
           RETURNING id, email, name, is_super_admin`,
          [email.toLowerCase(), passwordHash, name, workspaceId]
        );
        const user = userResult.rows[0];

        await client.query(
          `INSERT INTO workspace_memberships (workspace_id, user_id, role)
           VALUES ($1, $2, 'admin')`,
          [workspaceId, user.id]
        );

        await client.query(
          `INSERT INTO documents (workspace_id, document_type, title, properties, created_by)
           VALUES ($1, 'person', $2, $3, $4)`,
          [workspaceId, name, JSON.stringify({ user_id: user.id, email: email.toLowerCase() }), user.id]
        );

        await client.query(
          `INSERT INTO documents (workspace_id, document_type, title, content, created_by)
           VALUES ($1, 'wiki', $2, $3, $4)`,
          [workspaceId, WELCOME_DOCUMENT_TITLE, JSON.stringify(WELCOME_DOCUMENT_CONTENT), user.id]
        );

        await client.query('COMMIT');

        console.log(`Initial setup complete: ${email} is now super admin`);

        res.status(HTTP_STATUS.CREATED).json({
          success: true,
          data: {
            user: {
              id: user.id,
              email: user.email,
              name: user.name,
              isSuperAdmin: user.is_super_admin,
            },
            message: 'Setup complete! You can now log in.',
          },
        });
      } catch (error) {
        try {
          await client.query('ROLLBACK');
        } catch {
          // Ignore rollback errors after a failed transaction or closed client.
        }
        console.error('Setup initialization error:', error);
        res.status(HTTP_STATUS.INTERNAL_SERVER_ERROR).json({
          success: false,
          error: {
            code: ERROR_CODES.INTERNAL_ERROR,
            message: 'Failed to complete setup',
          },
        });
      } finally {
        client.release();
      }
    },
  })
);

export default router;

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest'
import request from 'supertest'
import crypto from 'crypto'
import { createApp } from '../app.js'
import { pool } from '../db/client.js'

describe('Sprint Reviews API', () => {
  const app = createApp()
  const testRunId = Date.now().toString(36) + Math.random().toString(36).slice(2, 6)
  const testEmail = `sprint-reviews-${testRunId}@ship.local`
  const otherEmail = `sprint-reviews-other-${testRunId}@ship.local`
  const testWorkspaceName = `Sprint Reviews Test ${testRunId}`

  let sessionCookie: string
  let otherSessionCookie: string
  let csrfToken: string
  let otherCsrfToken: string
  let testWorkspaceId: string
  let testUserId: string
  let otherUserId: string
  let testSprintId: string
  let testProgramId: string

  beforeAll(async () => {
    // Create test workspace
    const workspaceResult = await pool.query(
      `INSERT INTO workspaces (name) VALUES ($1) RETURNING id`,
      [testWorkspaceName]
    )
    testWorkspaceId = workspaceResult.rows[0].id

    // Create test user
    const userResult = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Test User')
       RETURNING id`,
      [testEmail]
    )
    testUserId = userResult.rows[0].id

    // Create other user
    const otherUserResult = await pool.query(
      `INSERT INTO users (email, password_hash, name)
       VALUES ($1, 'test-hash', 'Other User')
       RETURNING id`,
      [otherEmail]
    )
    otherUserId = otherUserResult.rows[0].id

    // Create workspace memberships
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [testWorkspaceId, testUserId]
    )
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, 'member')`,
      [testWorkspaceId, otherUserId]
    )

    // Create sessions
    const sessionId = crypto.randomBytes(32).toString('hex')
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [sessionId, testUserId, testWorkspaceId]
    )
    sessionCookie = `session_id=${sessionId}`

    const otherSessionId = crypto.randomBytes(32).toString('hex')
    await pool.query(
      `INSERT INTO sessions (id, user_id, workspace_id, expires_at)
       VALUES ($1, $2, $3, now() + interval '1 hour')`,
      [otherSessionId, otherUserId, testWorkspaceId]
    )
    otherSessionCookie = `session_id=${otherSessionId}`

    // Get CSRF tokens
    const csrfRes = await request(app)
      .get('/api/csrf-token')
      .set('Cookie', sessionCookie)
    csrfToken = csrfRes.body.token
    const connectSidCookie = csrfRes.headers['set-cookie']?.[0]?.split(';')[0] || ''
    if (connectSidCookie) {
      sessionCookie = `${sessionCookie}; ${connectSidCookie}`
    }

    const otherCsrfRes = await request(app)
      .get('/api/csrf-token')
      .set('Cookie', otherSessionCookie)
    otherCsrfToken = otherCsrfRes.body.token
    const otherConnectSidCookie = otherCsrfRes.headers['set-cookie']?.[0]?.split(';')[0] || ''
    if (otherConnectSidCookie) {
      otherSessionCookie = `${otherSessionCookie}; ${otherConnectSidCookie}`
    }

    // Create a program
    const programResult = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, created_by, visibility)
       VALUES ($1, 'program', 'Test Program', $2, 'workspace')
       RETURNING id`,
      [testWorkspaceId, testUserId]
    )
    testProgramId = programResult.rows[0].id
  })

  afterAll(async () => {
    await pool.query('DELETE FROM sessions WHERE user_id IN ($1, $2)', [testUserId, otherUserId])
    await pool.query('DELETE FROM documents WHERE workspace_id = $1', [testWorkspaceId])
    await pool.query('DELETE FROM workspace_memberships WHERE user_id IN ($1, $2)', [testUserId, otherUserId])
    await pool.query('DELETE FROM users WHERE id IN ($1, $2)', [testUserId, otherUserId])
    await pool.query('DELETE FROM workspaces WHERE id = $1', [testWorkspaceId])
  })

  beforeEach(async () => {
    // Clean up associations first, then documents
    await pool.query(
      `DELETE FROM document_associations WHERE document_id IN (SELECT id FROM documents WHERE workspace_id = $1 AND document_type IN ('sprint', 'weekly_review', 'issue'))`,
      [testWorkspaceId]
    )
    await pool.query(
      `DELETE FROM documents WHERE workspace_id = $1 AND document_type IN ('sprint', 'weekly_review', 'issue')`,
      [testWorkspaceId]
    )
    // Create fresh sprint
    const sprintResult = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, created_by, visibility, properties)
       VALUES ($1, 'sprint', 'Test Sprint', $2, 'workspace', $3)
       RETURNING id`,
      [testWorkspaceId, testUserId, JSON.stringify({ plan: 'Test plan for sprint' })]
    )
    testSprintId = sprintResult.rows[0].id
    // Create program association for sprint
    await pool.query(
      `INSERT INTO document_associations (document_id, related_id, relationship_type)
       VALUES ($1, $2, 'program')`,
      [testSprintId, testProgramId]
    )
  })

  describe('GET /api/weeks/:id/review', () => {
    it('returns pre-filled draft with is_draft: true for new sprint', async () => {
      const response = await request(app)
        .get(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)

      expect(response.status).toBe(200)
      expect(response.body.is_draft).toBe(true)
      expect(response.body.content).toBeDefined()
      expect(response.body.content.type).toBe('doc')
    })

    it('returns existing review with is_draft: false after POST', async () => {
      // First create a review
      await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({
          content: { type: 'doc', content: [{ type: 'paragraph' }] },
          plan_validated: true
        })

      // Then GET should return existing review
      const response = await request(app)
        .get(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)

      expect(response.status).toBe(200)
      expect(response.body.is_draft).toBe(false)
      expect(response.body.plan_validated).toBe(true)
    })

    it('pre-fill content includes issues information', async () => {
      // Create some issues for the sprint
      const doneIssueResult = await pool.query(
        `INSERT INTO documents (workspace_id, document_type, title, created_by, visibility, properties)
         VALUES ($1, 'issue', 'Done Issue', $2, 'workspace', $3)
         RETURNING id`,
        [testWorkspaceId, testUserId, JSON.stringify({ state: 'done' })]
      )
      const inProgressIssueResult = await pool.query(
        `INSERT INTO documents (workspace_id, document_type, title, created_by, visibility, properties)
         VALUES ($1, 'issue', 'In Progress Issue', $2, 'workspace', $3)
         RETURNING id`,
        [testWorkspaceId, testUserId, JSON.stringify({ state: 'in_progress' })]
      )

      // Create document_associations for sprint relationship
      await pool.query(
        `INSERT INTO document_associations (document_id, related_id, relationship_type)
         VALUES ($1, $2, 'sprint'), ($3, $2, 'sprint')`,
        [doneIssueResult.rows[0].id, testSprintId, inProgressIssueResult.rows[0].id]
      )

      const response = await request(app)
        .get(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)

      expect(response.status).toBe(200)
      expect(response.body.is_draft).toBe(true)
      expect(response.body.content).toBeDefined()
      // Content should include issues in the pre-filled text
      const contentStr = JSON.stringify(response.body.content)
      expect(contentStr).toContain('Done Issue')
    })

    it('returns 404 for non-existent sprint', async () => {
      const fakeSprintId = '00000000-0000-0000-0000-000000000000'
      const response = await request(app)
        .get(`/api/weeks/${fakeSprintId}/review`)
        .set('Cookie', sessionCookie)

      expect(response.status).toBe(404)
    })
  })

  describe('POST /api/weeks/:id/review', () => {
    it('creates weekly_review document with owner_id', async () => {
      const response = await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({
          content: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Review content' }] }] },
          plan_validated: true
        })

      expect(response.status).toBe(201)
      expect(response.body.owner_id).toBe(testUserId)
      expect(response.body.sprint_id).toBe(testSprintId)
      expect(response.body.plan_validated).toBe(true)
    })

    it('returns 403 without auth (CSRF check first)', async () => {
      const response = await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .send({ content: { type: 'doc', content: [] } })

      expect(response.status).toBe(403)
    })

    it('returns 409 if review already exists', async () => {
      // Create first review
      await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({ content: { type: 'doc', content: [] } })

      // Try to create second review
      const response = await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({ content: { type: 'doc', content: [] } })

      expect(response.status).toBe(409)
    })
  })

  describe('PATCH /api/weeks/:id/review', () => {
    beforeEach(async () => {
      // Create a review to update
      await request(app)
        .post(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({
          content: { type: 'doc', content: [] },
          plan_validated: null
        })
    })

    it('updates plan_validated and content', async () => {
      const newContent = { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: 'Updated' }] }] }
      const response = await request(app)
        .patch(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({
          content: newContent,
          plan_validated: false
        })

      expect(response.status).toBe(200)
      expect(response.body.plan_validated).toBe(false)
      expect(response.body.content).toEqual(newContent)
    })

    it('returns 403 for non-owner', async () => {
      const response = await request(app)
        .patch(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', otherSessionCookie)
        .set('x-csrf-token', otherCsrfToken)
        .send({ plan_validated: true })

      expect(response.status).toBe(403)
    })

    it('returns 404 when no review exists', async () => {
      // Delete the review first
      await pool.query(
        `DELETE FROM documents WHERE document_type = 'weekly_review' AND properties->>'sprint_id' = $1`,
        [testSprintId]
      )

      const response = await request(app)
        .patch(`/api/weeks/${testSprintId}/review`)
        .set('Cookie', sessionCookie)
        .set('x-csrf-token', csrfToken)
        .send({ plan_validated: true })

      expect(response.status).toBe(404)
    })
  })
})

import { describe, it, expect, beforeAll, afterAll, beforeEach } from 'vitest'
