async function guardMutationCapability(
  db: QueryRunner,
  principal: Principal,
  spec: DocumentMutationCapability,
  notFoundMessage = 'Document not found'
): Promise<MutationResult<never> | null> {
  const guard = await guardDocumentMutation(db, principal, spec, { notFoundMessage });
  if (guard.ok) return null;
  return mutationGuardDenial(guard);
}

function defaultWriteCapability(documentId: string): DocumentMutationCapability {
  return { action: 'write', documentId };
}

function creatorWriteCapability(documentId: string, includeArchived = false): DocumentMutationCapability {
  return { action: 'write', documentId, enforce: 'creator_or_admin', includeArchived };
}

async function loadAccessibleDocument(
  db: QueryRunner,
  principal: Principal,
  documentId: string,
  options: { includeArchived?: boolean } = {}
): Promise<DocumentAccessRow | null> {
  const guard = await guardDocumentMutation(db, principal, {
    action: 'write',
    documentId,
    includeArchived: options.includeArchived,
  });
  if (!guard.ok || principal.kind === 'setup') {
    return null;
  }

  const result = await db.query<DocumentAccessRow>(
    `SELECT id, workspace_id, document_type, title, parent_id, position, ticket_number,
            properties, content, created_at, updated_at, created_by, visibility,
            archived_at, deleted_at, converted_to_id, converted_by
       FROM documents
      WHERE id = $1 AND workspace_id = $2 AND deleted_at IS NULL`,
    [documentId, principal.workspaceId]
  );

  return result.rows[0] ?? null;
}

async function nextIssueTicketNumber(client: PoolClient, workspaceId: string): Promise<number> {
  const workspaceIdHex = workspaceId.replace(/-/g, '').substring(0, 15);
  const lockKey = parseInt(workspaceIdHex, 16);
  await client.query('SELECT pg_advisory_xact_lock($1)', [lockKey]);
  const ticketResult = await client.query<{ next_number: number }>(
    `SELECT COALESCE(MAX(ticket_number), 0) + 1 as next_number
     FROM documents
     WHERE workspace_id = $1 AND document_type = 'issue'`,
    [workspaceId]
  );
  return ticketResult.rows[0]?.next_number ?? 1;
}

async function removeAssociationsByRelatedId(
  client: PoolClient,
  relatedId: string,
  relationshipType: 'program' | 'project' | 'sprint' | 'parent'
): Promise<void> {
  await client.query(
    `DELETE FROM document_associations
     WHERE related_id = $1 AND relationship_type = $2`,
    [relatedId, relationshipType]
  );
}

async function validateReferences(
  db: QueryRunner,
  principal: Principal,
  references: Array<{ id: string; type?: 'program' | 'project' | 'sprint' | 'parent'; label: string }>
): Promise<{ ok: true } | { ok: false; error: string }> {
  for (const reference of references) {
    if (!reference.type) continue;
    const decision = await authorize(db, principal, {
      resource: 'document_reference',
      action: 'link',
      targetId: reference.id,
      relationship: reference.type,
    });
    if (!decision.allowed) {
      return { ok: false, error: `${reference.label} not found` };
    }
  }
  return { ok: true };
}

function validateTipTapContent(content: { type?: unknown; content?: unknown }): MutationResult<never> | null {
  if (!content || typeof content !== 'object') {
    return { ok: false, status: 400, body: { error: 'Content is required and must be a valid TipTap JSON object' } };
  }

  if (content.type !== 'doc' || !Array.isArray(content.content)) {
    return {
      ok: false,
      status: 400,
      body: {
        error: 'Invalid content structure. Content must be a TipTap document with type "doc" and a content array.',
        expected: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: '...' }] }] },
        received: { type: content.type, hasContentArray: Array.isArray(content.content) },
      },
    };
  }

  return null;
}

function extractedContentProperties(content: unknown) {
  return {
    plan: extractHypothesisFromContent(content),
    success_criteria: extractSuccessCriteriaFromContent(content),
    vision: extractVisionFromContent(content),
    goals: extractGoalsFromContent(content),
  };
}

export async function updateDocumentContentMutation({
  actor,
  principal,
  documentId,
  content,
}: UpdateDocumentContentInput): Promise<MutationResult<DocumentContentRow>> {
  const denied = await guardMutationCapability(pool, principal, defaultWriteCapability(documentId));
  if (denied) return denied;

  const validationError = validateTipTapContent(content);
  if (validationError) return validationError;

  const client = await pool.connect();
  let resubmissionTarget: { sprintId: string; reviewerUserId: string | null } | null = null;

  try {
    const existing = await loadAccessibleDocument(client, principal, documentId, { includeArchived: true });
    if (!existing) {
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }

    const contentChanged = JSON.stringify(content) !== JSON.stringify(existing.content ?? null);
    const newProps = stampWeeklyAccountabilitySubmittedAt(
      existing.document_type,
      {
        ...(existing.properties || {}),
        ...extractedContentProperties(content),
      },
      contentChanged
    );

    await client.query('BEGIN');
    await client.query(
      `UPDATE documents
       SET content = $1, yjs_state = $2, properties = $3, updated_at = now()
       WHERE id = $4 AND workspace_id = $5`,
      [JSON.stringify(content), null, JSON.stringify(newProps), documentId, actor.workspaceId]
    );
    resubmissionTarget = await resetWeeklyApprovalAfterResubmission(client, actor, existing);

    const result = await client.query<DocumentContentRow>(
      `SELECT id, title, content FROM documents WHERE id = $1 AND workspace_id = $2`,
      [documentId, actor.workspaceId]
    );

    await client.query('COMMIT');

    invalidateDocumentCache(documentId);
    await upsertDocumentSearchIndex(documentId);

    if (resubmissionTarget) {
      broadcastToUser(actor.userId, 'accountability:updated', {
        type: existing.document_type,
        targetId: resubmissionTarget.sprintId,
      });
      if (resubmissionTarget.reviewerUserId && resubmissionTarget.reviewerUserId !== actor.userId) {
        broadcastToUser(resubmissionTarget.reviewerUserId, 'accountability:updated', {
          type: existing.document_type,
          targetId: resubmissionTarget.sprintId,
        });
      }
    }

    const updated = result.rows[0];
    if (!updated) {
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }

    return { ok: true, status: 200, body: updated };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

function collectTopLevelProperties(data: UpdateDocumentPatch, existingType: DocumentType): Record<string, unknown> {
  const topLevelProps: Record<string, unknown> = {};
  if (data.state !== undefined) topLevelProps.state = data.state;
  if (data.priority !== undefined) topLevelProps.priority = data.priority;
  if (data.estimate !== undefined) topLevelProps.estimate = data.estimate;
  if (data.assignee_id !== undefined) topLevelProps.assignee_id = data.assignee_id;
  if (data.source !== undefined) topLevelProps.source = data.source;
  if (data.rejection_reason !== undefined) topLevelProps.rejection_reason = data.rejection_reason;
  if (data.impact !== undefined) topLevelProps.impact = data.impact;
  if (data.confidence !== undefined) topLevelProps.confidence = data.confidence;
  if (data.ease !== undefined) topLevelProps.ease = data.ease;
  if (data.color !== undefined) topLevelProps.color = data.color;
  if (data.owner_id !== undefined) topLevelProps.owner_id = data.owner_id;
  if (data.accountable_id !== undefined) topLevelProps.accountable_id = data.accountable_id;
  if (data.consulted_ids !== undefined) topLevelProps.consulted_ids = data.consulted_ids;
  if (data.informed_ids !== undefined) topLevelProps.informed_ids = data.informed_ids;
  if (data.has_design_review !== undefined) topLevelProps.has_design_review = data.has_design_review;
  if (data.design_review_notes !== undefined) topLevelProps.design_review_notes = data.design_review_notes;
  if (data.owner_id !== undefined && existingType === 'sprint') {
    topLevelProps.assignee_ids = data.owner_id ? [data.owner_id] : [];
  }
  if (data.status !== undefined) topLevelProps.status = data.status;
  if (data.hypothesis !== undefined) topLevelProps.plan = data.hypothesis;
  if (data.plan !== undefined) topLevelProps.plan = data.plan;
  return topLevelProps;
}

async function resetWeeklyApprovalAfterResubmission(
  client: PoolClient,
  actor: DocumentActor,
  existing: DocumentAccessRow
): Promise<{ sprintId: string; reviewerUserId: string | null } | null> {
  if (existing.document_type !== 'weekly_plan' && existing.document_type !== 'weekly_retro') {
    return null;
  }

  const docProps = existing.properties || {};
  const personId = typeof docProps.person_id === 'string' ? docProps.person_id : null;
  const projectId = typeof docProps.project_id === 'string' ? docProps.project_id : null;
  const rawWeekNumber = docProps.week_number;
  const weekNumber = typeof rawWeekNumber === 'number'
    ? rawWeekNumber
    : typeof rawWeekNumber === 'string'
      ? Number.parseInt(rawWeekNumber, 10)
      : NaN;

  if (!personId || !projectId || !Number.isFinite(weekNumber)) {
    return null;
  }

  const sprintResult = await client.query<{ id: string; properties: unknown }>(
    `SELECT id, properties
       FROM documents
      WHERE workspace_id = $1
        AND document_type = 'sprint'
        AND deleted_at IS NULL
        AND (properties->>'project_id') = $2
        AND (properties->>'sprint_number')::int = $3
        AND (
          properties->>'owner_id' = $4
          OR EXISTS (
            SELECT 1
              FROM jsonb_array_elements_text(COALESCE(properties->'assignee_ids', '[]'::jsonb)) AS assignee_id
             WHERE assignee_id = $4
          )
        )
      ORDER BY updated_at DESC
      LIMIT 1`,
    [actor.workspaceId, projectId, weekNumber, personId]
  );

  const sprint = sprintResult.rows[0];
  if (!sprint) {
    return null;
  }

  const sprintProps = asDocumentProperties(sprint.properties);
  const approvalKey = existing.document_type === 'weekly_plan' ? 'plan_approval' : 'review_approval';
  const approval = asApprovalRecord(sprintProps[approvalKey]);
  if (approval?.state !== 'changes_requested') {
    return null;
  }

  await client.query(
    `UPDATE documents SET properties = $1, updated_at = now()
     WHERE id = $2 AND document_type = 'sprint'`,
    [
      JSON.stringify({
        ...sprintProps,
        [approvalKey]: { ...approval, state: 'changed_since_approved' },
      }),
      sprint.id,
    ]
  );

  return {
    sprintId: String(sprint.id),
    reviewerUserId: typeof approval.approved_by === 'string' ? approval.approved_by : null,
  };
}

async function projectOwnerForResponse(ownerId: unknown, workspaceId: string): Promise<PersonOwnerRow | null> {
  if (!ownerId) return null;
  const ownerResult = await pool.query<PersonOwnerRow>(
    `SELECT (d.properties->>'user_id')::text as id, d.title as name, COALESCE(d.properties->>'email', u.email) as email
     FROM documents d
     LEFT JOIN users u ON u.id = (d.properties->>'user_id')::uuid
     WHERE (d.properties->>'user_id')::uuid = $1 AND d.workspace_id = $2 AND d.document_type = 'person'`,
    [ownerId, workspaceId]
  );
  return ownerResult.rows[0] ?? null;
}

export async function createDocumentMutation({
  actor,
  principal,
  input,
}: CreateDocumentInput): Promise<MutationResult<DocumentAccessRow>> {
  const denied = await guardMutationCapability(pool, principal, { action: 'write' });
  if (denied) return denied;

  const client = await pool.connect();

  try {
    const { isAdmin } = await getDocumentAccessContext(actor, client);
    const {
      document_type,
      parent_id,
      program_id,
      sprint_id,
      properties,
      content,
      belongs_to,
    } = input;
    let { visibility } = input;

    const forbiddenOnCreate = findForbiddenGovernanceKeys(properties);
    if (forbiddenOnCreate.length > 0) {
      return {
        ok: false,
        status: 403,
        body: { error: `Cannot set governance fields via this endpoint: ${formatForbiddenGovernanceKeys(forbiddenOnCreate)}` },
      };
    }

    const forbiddenRaciOnCreate = isAdmin ? [] : findForbiddenRaciKeys(properties);
    if (forbiddenRaciOnCreate.length > 0) {
      return {
        ok: false,
        status: 403,
        body: { error: `Cannot set RACI fields via this endpoint: ${forbiddenRaciOnCreate.join(', ')}` },
      };
    }

    if (parent_id && !visibility) {
      const parent = await getReadableDocument(client, actor, parent_id);
      if (!parent) {
        return { ok: false, status: 404, body: { error: 'Parent document not found' } };
      }
      visibility = parent.visibility;
    }

    const references = [
      ...(parent_id ? [{ id: parent_id, type: 'parent' as const, label: 'Parent document' }] : []),
      ...(program_id ? [{ id: program_id, type: 'program' as const, label: 'Program' }] : []),
      ...(sprint_id ? [{ id: sprint_id, type: 'sprint' as const, label: 'Sprint' }] : []),
      ...((belongs_to || []).map((association) => ({
        id: association.id,
        type: association.type,
        label: `${association.type} document`,
      }))),
    ];
    const referencesResult = await validateReferences(client, principal, references);
    if (!referencesResult.ok) {
      return { ok: false, status: 404, body: { error: referencesResult.error } };
    }

    await client.query('BEGIN');

    const ticketNumber = document_type === 'issue'
      ? await nextIssueTicketNumber(client, actor.workspaceId)
      : null;

    const result = await client.query<DocumentAccessRow>(
      `INSERT INTO documents (workspace_id, document_type, title, parent_id, properties, created_by, visibility, content, ticket_number)
       VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
       RETURNING *`,
      [
        actor.workspaceId,
        document_type,
        'Untitled',
        parent_id || null,
        JSON.stringify(properties || {}),
        actor.userId,
        visibility || 'workspace',
        content ? JSON.stringify(content) : null,
        ticketNumber,
      ]
    );

    const newDoc = result.rows[0];
    if (!newDoc) {
      await client.query('ROLLBACK');
      return { ok: false, status: 500, body: { error: 'Failed to create document' } };
    }

    if (belongs_to && belongs_to.length > 0) {
      await syncBelongsToAssociations(newDoc.id, belongs_to, client);
    }

    if (sprint_id) {
      await addBelongsToAssociation(newDoc.id, sprint_id, 'sprint', client);
    }

    if (program_id) {
      await addBelongsToAssociation(newDoc.id, program_id, 'program', client);
    }

    await client.query('COMMIT');
    await upsertDocumentSearchIndex(newDoc.id);

    if (document_type === 'weekly_plan' || (properties && 'outcome' in properties)) {
      broadcastToUser(actor.userId, 'accountability:updated', { documentId: newDoc.id, documentType: document_type });
    }

    return { ok: true, status: 201, body: newDoc };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

function flattenDocumentResponse(updatedDoc: DocumentAccessRow, owner: PersonOwnerRow | null) {
  const props = updatedDoc.properties || {};
  return {
    ...updatedDoc,
    state: props.state,
    priority: props.priority,
    estimate: props.estimate,
    assignee_id: props.assignee_id,
    source: props.source,
    impact: props.impact,
    confidence: props.confidence,
    ease: props.ease,
    owner_id: props.owner_id,
    owner,
    prefix: props.prefix,
    color: props.color,
    status: props.status,
    plan: props.plan,
    plan_approval: props.plan_approval,
    review_approval: props.review_approval,
    review_rating: props.review_rating,
  };
}

export async function updateDocumentMutation({
  actor,
  principal,
  documentId,
  patch,
  capability,
}: UpdateDocumentInput): Promise<MutationResult<ReturnType<typeof flattenDocumentResponse>>> {
  const denied = await guardMutationCapability(
    pool,
    principal,
    capability ?? defaultWriteCapability(documentId),
  );
  if (denied) return denied;

  const client = await pool.connect();
  let contentUpdated = false;
  let visibilityChanged: { next: DocumentVisibility; previousCreatedBy: string } | null = null;
  let resubmissionTarget: { sprintId: string; reviewerUserId: string | null } | null = null;

  try {
    const existing = await loadAccessibleDocument(client, principal, documentId, { includeArchived: true });
    if (!existing) {
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }

    const { isAdmin } = await getDocumentAccessContext(actor, client);
    const isGovernanceCommand = capability?.action === 'governance';

    const forbiddenGovernanceKeys = isGovernanceCommand
      ? []
      : findForbiddenGovernanceKeys(patch.properties);
    if (forbiddenGovernanceKeys.length > 0) {
      return {
        ok: false,
        status: 403,
        body: { error: `Cannot modify governance fields via this endpoint: ${formatForbiddenGovernanceKeys(forbiddenGovernanceKeys)}` },
      };
    }

    const forbiddenRaciKeys = isAdmin ? [] : findForbiddenRaciKeys(patch.properties);
    if (forbiddenRaciKeys.length > 0) {
      return { ok: false, status: 403, body: { error: `Cannot modify RACI fields via this endpoint: ${forbiddenRaciKeys.join(', ')}` } };
    }

    if (!isAdmin) {
      if (patch.accountable_id !== undefined) {
        return { ok: false, status: 403, body: { error: 'Only workspace admins can change accountable_id' } };
      }
      const topLevelRaciKeys = [
        ...(patch.owner_id !== undefined ? ['owner_id'] : []),
        ...(patch.consulted_ids !== undefined ? ['consulted_ids'] : []),
        ...(patch.informed_ids !== undefined ? ['informed_ids'] : []),
      ];
      if (topLevelRaciKeys.length > 0) {
        return { ok: false, status: 403, body: { error: `Cannot modify RACI fields via this endpoint: ${topLevelRaciKeys.join(', ')}` } };
      }
      if (existing.document_type === 'sprint' && patch.status !== undefined) {
        return { ok: false, status: 403, body: { error: 'Sprint status cannot be changed via this endpoint' } };
      }
      if (existing.document_type === 'sprint' && patch.properties?.status !== undefined) {
        return { ok: false, status: 403, body: { error: 'Sprint status cannot be changed via this endpoint' } };
      }
    }

    const references = [
      ...(patch.parent_id ? [{ id: patch.parent_id, type: 'parent' as const, label: 'Parent document' }] : []),
      ...(patch.program_id ? [{ id: patch.program_id, type: 'program' as const, label: 'Program' }] : []),
      ...(patch.sprint_id ? [{ id: patch.sprint_id, type: 'sprint' as const, label: 'Sprint' }] : []),
      ...((patch.belongs_to || []).map((association) => ({
        id: association.id,
        type: association.type,
        label: `${association.type} document`,
      }))),
    ];
    const referencesResult = await validateReferences(client, principal, references);
    if (!referencesResult.ok) {
      return { ok: false, status: 404, body: { error: referencesResult.error } };
    }

    if (patch.visibility !== undefined && patch.visibility !== existing.visibility) {
      const visibilityDecision = await authorizeDocumentMutation(client, principal, {
        action: 'write',
        documentId,
        enforce: 'creator_or_admin',
        includeArchived: true,
      });
      if (!visibilityDecision.allowed) {
        return { ok: false, status: 403, body: { error: 'Only the creator or admin can change document visibility' } };
      }
    }

    if (patch.parent_id !== undefined && patch.parent_id !== null && patch.visibility === undefined) {
      const parent = await getReadableDocument(client, actor, patch.parent_id);
      if (parent?.visibility === 'workspace' && existing.visibility === 'private') {
        patch.visibility = 'workspace';
      }
    }

    if (existing.document_type === 'person' && patch.properties?.reports_to !== undefined) {
      const adminDecision = await authorizeDocumentMutation(client, principal, {
        action: 'governance',
        documentId,
        enforce: 'workspace_admin',
        includeArchived: true,
      });
      if (!adminDecision.allowed) {
        return { ok: false, status: 403, body: { error: 'Only workspace admins can set the reports_to field' } };
      }
    }

    await client.query('BEGIN');

    const updates: string[] = [];
    const values: unknown[] = [];
    let paramIndex = 1;
    let extractedProps: Record<string, unknown> = {};

    if (patch.title !== undefined) {
      updates.push(`title = $${paramIndex++}`);
      values.push(patch.title);
    }
    if (patch.content !== undefined) {
      updates.push(`content = $${paramIndex++}`);
      values.push(JSON.stringify(patch.content));
      updates.push('yjs_state = NULL');
      extractedProps = extractedContentProperties(patch.content);
      contentUpdated = true;
    }
    if (patch.parent_id !== undefined) {
      updates.push(`parent_id = $${paramIndex++}`);
      values.push(patch.parent_id);
    }
    if (patch.position !== undefined) {
      updates.push(`position = $${paramIndex++}`);
      values.push(patch.position);
    }

    const topLevelProps = collectTopLevelProperties(patch, existing.document_type);
    const hasTopLevelProps = Object.keys(topLevelProps).length > 0;
    if (patch.properties !== undefined || contentUpdated || hasTopLevelProps) {
      const dataProps = patch.properties || {};
      let newProps = {
        ...(existing.properties || {}),
        ...dataProps,
        ...topLevelProps,
        ...(contentUpdated ? extractedProps : {}),
      };
      if (!isGovernanceCommand) {
        newProps = stripForbiddenGovernanceKeys(newProps);
      }

      if (existing.document_type === 'project' || existing.document_type === 'sprint') {
        let linkedIssuesCount = 0;
        if (existing.document_type === 'sprint') {
          const issueCountResult = await client.query<{ count: string }>(
            `SELECT COUNT(*) as count FROM documents d
             JOIN document_associations da ON da.document_id = d.id
             WHERE da.related_id = $1 AND da.relationship_type = 'sprint' AND d.document_type = $2`,
            [documentId, 'issue']
          );
          linkedIssuesCount = parseInt(issueCountResult.rows[0]?.count || '0', 10);
        }

        const completeness = checkDocumentCompleteness(existing.document_type, newProps, linkedIssuesCount);
        newProps = {
          ...newProps,
          is_complete: completeness.isComplete,
          missing_fields: completeness.missingFields,
        };
      }

      updates.push(`properties = $${paramIndex++}`);
      values.push(JSON.stringify(newProps));
    }
    if (patch.visibility !== undefined) {
      updates.push(`visibility = $${paramIndex++}`);
      values.push(patch.visibility);
    }

    if (patch.document_type !== undefined && patch.document_type !== existing.document_type) {
      const convertDecision = await authorizeDocumentMutation(client, principal, {
        action: 'write',
        documentId,
        enforce: 'creator_or_admin',
        includeArchived: true,
      });
      if (!convertDecision.allowed) {
        await client.query('ROLLBACK');
        return { ok: false, status: 403, body: { error: 'Only the document creator can change its type' } };
      }

      const restrictedTypes = ['program', 'person'];
      if (restrictedTypes.includes(existing.document_type) || restrictedTypes.includes(patch.document_type)) {
        await client.query('ROLLBACK');
        return { ok: false, status: 400, body: { error: 'Cannot change to or from program or person document types' } };
      }

      updates.push(`document_type = $${paramIndex++}`);
      values.push(patch.document_type);

      if (patch.document_type === 'issue' && !existing.ticket_number) {
        updates.push(`ticket_number = $${paramIndex++}`);
        values.push(await nextIssueTicketNumber(client, actor.workspaceId));
      }
    }

    const hasBelongsToUpdate = patch.belongs_to !== undefined;
    const hasProgramIdUpdate = patch.program_id !== undefined;
    const hasSprintIdUpdate = patch.sprint_id !== undefined;
    if (hasBelongsToUpdate && (hasProgramIdUpdate || hasSprintIdUpdate)) {
      await client.query('ROLLBACK');
      return {
        ok: false,
        status: 400,
        body: { error: 'Use either belongs_to or program_id/sprint_id association fields, not both' },
      };
    }
    if (updates.length === 0 && !hasBelongsToUpdate && !hasProgramIdUpdate && !hasSprintIdUpdate) {
      await client.query('ROLLBACK');
      return { ok: false, status: 400, body: { error: 'No fields to update' } };
    }

    if (hasBelongsToUpdate) {
      await syncBelongsToAssociations(documentId, patch.belongs_to || [], client);
    }
    if (patch.sprint_id !== undefined && !hasBelongsToUpdate) {
      await updateSprintAssociation(documentId, null, client);
      if (patch.sprint_id !== null) {
        await addBelongsToAssociation(documentId, patch.sprint_id, 'sprint', client);
      }
    }
    if (patch.program_id !== undefined && !hasBelongsToUpdate) {
      await updateProgramAssociation(documentId, null, client);
      if (patch.program_id !== null) {
        await addBelongsToAssociation(documentId, patch.program_id, 'program', client);
      }
    }

    updates.push('updated_at = now()');
    const result = await client.query<DocumentAccessRow>(
      `UPDATE documents SET ${updates.join(', ')} WHERE id = $${paramIndex} AND workspace_id = $${paramIndex + 1} RETURNING *`,
      [...values, documentId, actor.workspaceId]
    );

    if (contentUpdated) {
      resubmissionTarget = await resetWeeklyApprovalAfterResubmission(client, actor, existing);
    }

    if (patch.visibility !== undefined && patch.visibility !== existing.visibility) {
      await client.query(
        `WITH RECURSIVE descendants AS (
          SELECT id FROM documents WHERE parent_id = $1
          UNION ALL
          SELECT d.id FROM documents d
          INNER JOIN descendants descendant ON d.parent_id = descendant.id
        )
        UPDATE documents SET visibility = $2, updated_at = now()
        WHERE id IN (SELECT id FROM descendants)`,
        [documentId, patch.visibility]
      );
      visibilityChanged = { next: patch.visibility, previousCreatedBy: existing.created_by };
    }

    if (visibilityChanged && existing.document_type === 'issue') {
      await enqueueFleetGraphIssueAttentionEvents({
        workspaceId: actor.workspaceId,
        issueIds: [documentId],
        eventType: 'issue_visibility_changed',
        reason: 'issue_visibility_changed',
        db: client,
        logger: console,
      });
    }

    await client.query('COMMIT');
    await upsertDocumentSearchIndex(documentId);

    if (contentUpdated) {
      invalidateDocumentCache(documentId);
    }

    if (visibilityChanged) {
      handleVisibilityChange(documentId, visibilityChanged.next, visibilityChanged.previousCreatedBy).catch((err) => {
        console.error('Failed to handle visibility change for collaboration:', err);
      });
    }

    if (resubmissionTarget) {
      broadcastToUser(actor.userId, 'accountability:updated', {
        type: existing.document_type,
        targetId: resubmissionTarget.sprintId,
      });
      if (resubmissionTarget.reviewerUserId && resubmissionTarget.reviewerUserId !== actor.userId) {
        broadcastToUser(resubmissionTarget.reviewerUserId, 'accountability:updated', {
          type: existing.document_type,
          targetId: resubmissionTarget.sprintId,
        });
      }
    }

    const updatedDoc = result.rows[0];
    if (!updatedDoc) {
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }
    const owner = updatedDoc.document_type === 'project'
      ? await projectOwnerForResponse(updatedDoc.properties?.owner_id, actor.workspaceId)
      : null;

    return { ok: true, status: 200, body: flattenDocumentResponse(updatedDoc, owner) };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

export async function deleteDocumentMutation({
  actor,
  principal,
  documentId,
}: DeleteDocumentInput): Promise<MutationResult<null>> {
  const denied = await guardMutationCapability(
    pool,
    principal,
    creatorWriteCapability(documentId, true),
  );
  if (denied) return denied;

  const existing = await loadAccessibleDocument(pool, principal, documentId, { includeArchived: true });
  if (!existing) {
    return { ok: false, status: 404, body: { error: 'Document not found' } };
  }

  const result = await pool.query<{ id: string }>(
    `UPDATE documents
     SET deleted_at = COALESCE(deleted_at, now()), updated_at = now()
     WHERE id = $1 AND workspace_id = $2 AND deleted_at IS NULL
     RETURNING id`,
    [documentId, actor.workspaceId]
  );

  if (result.rows.length === 0) {
    return { ok: false, status: 404, body: { error: 'Document not found' } };
  }

  return { ok: true, status: 204, body: null };
}

export async function convertDocumentMutation({
  actor,
  principal,
  documentId,
  targetType,
}: ConvertDocumentInput): Promise<MutationResult<Record<string, unknown>>> {
  const denied = await guardMutationCapability(
    pool,
    principal,
    creatorWriteCapability(documentId, true),
  );
  if (denied) return denied;

  const client = await pool.connect();

  try {
    const doc = await loadAccessibleDocument(client, principal, documentId, { includeArchived: true });
    if (!doc) {
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }

    if (doc.created_by !== actor.userId) {
      return { ok: false, status: 403, body: { error: 'Only the document creator can convert it' } };
    }

    if (doc.document_type !== 'issue' && doc.document_type !== 'project') {
      return { ok: false, status: 400, body: { error: 'Only issues and projects can be converted' } };
    }

    if (doc.document_type === targetType) {
      return { ok: false, status: 400, body: { error: `Document is already a ${targetType}` } };
    }

    if (doc.archived_at) {
      return { ok: false, status: 400, body: { error: 'Cannot convert an archived document' } };
    }

    await client.query('BEGIN');

    const currentProps = doc.properties || {};
    const sourceType = doc.document_type;

    await client.query(
      `INSERT INTO document_snapshots (
        document_id, document_type, title, properties, ticket_number,
        snapshot_reason, created_by
      )
      VALUES ($1, $2, $3, $4, $5, 'conversion', $6)`,
      [
        documentId,
        sourceType,
        doc.title,
        JSON.stringify(currentProps),
        doc.ticket_number,
        actor.userId,
      ]
    );

    let newProperties: Record<string, unknown>;
    let newTicketNumber: number | null = null;

    if (targetType === 'project') {
      newProperties = {
        ...currentProps,
        impact: 3,
        confidence: 3,
        ease: 3,
        color: '#6366f1',
        owner_id: actor.userId,
        program_id: currentProps.program_id || null,
        promoted_from_ticket: doc.ticket_number,
      };
      newTicketNumber = null;
    } else {
      newTicketNumber = await nextIssueTicketNumber(client, actor.workspaceId);

      newProperties = {
        ...currentProps,
        state: 'backlog',
        priority: 'medium',
        source: 'internal',
        assignee_id: null,
        rejection_reason: null,
        program_id: currentProps.program_id || null,
        demoted_from_project: true,
      };

      await removeAssociationsByRelatedId(client, documentId, 'project');
    }

    const updateResult = await client.query<DocumentAccessRow>(
      `UPDATE documents
       SET document_type = $1,
           properties = $2,
           ticket_number = $3,
           original_type = COALESCE(original_type, $4),
           conversion_count = COALESCE(conversion_count, 0) + 1,
           converted_from_id = $5,
           converted_at = NOW(),
           converted_by = $6,
           updated_at = NOW()
       WHERE id = $7 AND workspace_id = $8
       RETURNING *`,
      [
        targetType,
        JSON.stringify(newProperties),
        newTicketNumber,
        sourceType,
        documentId,
        actor.userId,
        documentId,
        actor.workspaceId,
      ]
    );

    const updatedDoc = updateResult.rows[0];
    if (!updatedDoc) {
      await client.query('ROLLBACK');
      return { ok: false, status: 404, body: { error: 'Document not found' } };
    }

    if (targetType === 'project') {
      await removeAssociationsByType(documentId, 'project', client);
      await removeAssociationsByType(documentId, 'sprint', client);
      await removeAssociationsByType(documentId, 'parent', client);
    }

    await client.query('COMMIT');

    invalidateDocumentCache(documentId);
    handleDocumentConversion(documentId, documentId, sourceType, targetType);

    const props = updatedDoc.properties || {};
    return {
      ok: true,
      status: 200,
      body: {
        ...updatedDoc,
        ...(targetType === 'issue' && {
          state: props.state,
          priority: props.priority,
          assignee_id: props.assignee_id,
          source: props.source,
        }),
        ...(targetType === 'project' && {
          impact: props.impact,
          confidence: props.confidence,
          ease: props.ease,
          color: props.color,
          owner_id: props.owner_id,
        }),
        program_id: props.program_id,
        converted_from_type: sourceType,
      },
    };
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

import { pool } from '../db/client.js';

interface User {
  id: string;
  name: string;
}

interface Invite {
  id: string;
  workspace_id: string;
  email: string | null;
  role: string;
}

/**
 * Links a user to a workspace via an invite, handling person document creation/update.
 *
 * This is the single source of truth for invite acceptance logic, used by both:
 * - Password auth (invites.ts)
 * - PIV/CAIA auth (caia-auth.ts)
 *
 * Handles:
 * 1. Creating workspace membership
 * 2. Finding/updating person doc by EMAIL (not user_id) to handle orphaned docs
 * 3. Marking invite as used
 * 4. Cleaning up orphaned pending person docs
 */
export async function linkUserToWorkspaceViaInvite(
  user: User,
  invite: Invite
): Promise<{ personDocId: string; isNewMembership: boolean }> {
  // Email is required for person doc lookup - invites always have email
  const email = invite.email;
  if (!email) {
    throw new Error('Invite email is required for workspace linking');
  }

  // Check if user is already a member
  const existingMembership = await pool.query(
    'SELECT id FROM workspace_memberships WHERE workspace_id = $1 AND user_id = $2',
    [invite.workspace_id, user.id]
  );

  const isNewMembership = !existingMembership.rows[0];

  if (isNewMembership) {
    // Create membership
    await pool.query(
      `INSERT INTO workspace_memberships (workspace_id, user_id, role)
       VALUES ($1, $2, $3)`,
      [invite.workspace_id, user.id, invite.role]
    );
  }

  // Find existing person doc by EMAIL (handles orphaned docs from deleted users)
  const existingPersonDoc = await pool.query(
    `SELECT id FROM documents
     WHERE workspace_id = $1
       AND document_type = 'person'
       AND LOWER(properties->>'email') = LOWER($2)
       AND archived_at IS NULL
     ORDER BY
       CASE WHEN properties->>'pending' = 'true' THEN 1 ELSE 0 END,
       created_at DESC
     LIMIT 1`,
    [invite.workspace_id, email]
  );

  let personDocId: string;

  if (existingPersonDoc.rows[0]) {
    // Update existing person doc (reuse orphaned or pending doc)
    personDocId = existingPersonDoc.rows[0].id;
    await pool.query(
      `UPDATE documents
       SET title = $1,
           properties = jsonb_set(
             jsonb_set(
               properties - 'pending' - 'invite_id',
               '{user_id}', $2::jsonb
             ),
             '{email}', $3::jsonb
           )
       WHERE id = $4`,
      [user.name, JSON.stringify(user.id), JSON.stringify(email), personDocId]
    );
  } else {
    // Create new person doc
    const newDoc = await pool.query(
      `INSERT INTO documents (workspace_id, document_type, title, properties)
       VALUES ($1, 'person', $2, $3)
       RETURNING id`,
      [invite.workspace_id, user.name, JSON.stringify({ user_id: user.id, email })]
    );
    personDocId = newDoc.rows[0].id;
  }

  // Mark invite as used
  await pool.query(
    'UPDATE workspace_invites SET used_at = NOW() WHERE id = $1',
    [invite.id]
  );

  // Defensive cleanup: Archive any other pending person docs for this email
  await pool.query(
    `UPDATE documents SET archived_at = NOW()
     WHERE workspace_id = $1
       AND document_type = 'person'
       AND properties->>'pending' = 'true'
       AND archived_at IS NULL
       AND LOWER(properties->>'email') = LOWER($2)
       AND id != $3`,
    [invite.workspace_id, email, personDocId]
  );

  return { personDocId, isNewMembership };
}

// Issue mutation services own document-backed issue writes, associations, history, and iteration evidence.
import type { Pool, PoolClient } from 'pg';
import type { BelongsTo, IssueProperties } from '@ship/shared';
import { pool } from '../db/client.js';
import { extractIssueFromRow, type IssueDocumentRow } from '../db/documents-repository.js';
import type { Principal } from '../security/principal.js';
import { guardIssueCreate, guardIssueMutation } from './issue-mutation-guards.js';
export { bulkUpdateIssuesMutation, type BulkUpdateIssuesInput } from './issue-bulk-mutations.js';
import {
  logDocumentChange,
  getTimestampUpdates,
  getBelongsToAssociations,
  syncBelongsToAssociations,
} from '../utils/document-crud.js';
import { broadcastToUser } from '../collaboration/index.js';
import {
  expectedTypeForRelationship,
  getDocumentAccessContext,
  requireReferenceableDocument,
  type DocumentActor,
} from './document-access.js';
import { VISIBILITY_FILTER_SQL } from '../middleware/visibility.js';
import {
  mapListedIssueIterationRow,
  mapStoredIssueIterationRow,
  type IssueIterationAuthorRow,
  type IssueIterationListRow,
  type IssueStoredIterationRow,
} from '../utils/issue-response.js';
import { requireFirstRow } from '../utils/query-rows.js';
import { enqueueFleetGraphIssueAttentionEvents } from '../fleetgraph/events.js';
import {
  type createIssueRequestSchema,
  type updateIssueRequestSchema,
} from '../schemas/document-boundary.js';
import type { z } from 'zod';

type QueryRunner = Pick<Pool | PoolClient, 'query'>;

export type IssueMutationResult<T> =
  | { ok: true; status: number; body: T }
  | { ok: false; status: number; body: Record<string, unknown> };

type TicketNumberRow = { next_number: number };
type CountRow = { count: string | number };
type IssueTitlePropertiesRow = {
  id: string;
  title: string;
  properties: IssueProperties | Record<string, unknown> | null;
};
type IssuePropertiesRow = {
  id: string;
  properties: IssueProperties | Record<string, unknown> | null;
};
type IncompleteChildRow = {
  id: string;
  title: string;
  ticket_number: number | null;
  state: string | null;
};
type OldSprintRow = {
  sprint_number: string | null;
  sprint_start_date: Date | string | null;
};

export type CreateIssueInput = {
  client: PoolClient;
  actor: DocumentActor;
  principal: Principal;
  userId: string;
  workspaceId: string;
  data: z.infer<typeof createIssueRequestSchema>;
};

export type UpdateIssueInput = {
  client: PoolClient;
  actor: DocumentActor;
  principal: Principal;
  userId: string;
  workspaceId: string;
  issueId: string;
  data: z.infer<typeof updateIssueRequestSchema>;
};

function toCount(value: string | number): number {
  return typeof value === 'number' ? value : Number(value);
}

async function workspaceAdvisoryLock(client: PoolClient, workspaceId: string): Promise<void> {
  const workspaceIdHex = workspaceId.replace(/-/g, '').substring(0, 15);
  const lockKey = parseInt(workspaceIdHex, 16);
  await client.query('SELECT pg_advisory_xact_lock($1)', [lockKey]);
}

export async function createIssueMutation(
  input: CreateIssueInput
): Promise<IssueMutationResult<Record<string, unknown>>> {
  const { client, actor, principal, userId, workspaceId, data } = input;

  const denied = await guardIssueCreate(client, principal);
  if (denied) return denied;
  const {
    title,
    state,
    priority,
    assignee_id,
    belongs_to,
    source,
    due_date,
    is_system_generated,
    accountability_target_id,
    accountability_type,
  } = data;

  await client.query('BEGIN');
  await workspaceAdvisoryLock(client, workspaceId);

  const ticketResult = await client.query<TicketNumberRow>(
    `SELECT COALESCE(MAX(ticket_number), 0) + 1 as next_number
     FROM documents
     WHERE workspace_id = $1 AND document_type = 'issue'`,
    [workspaceId]
  );
  const ticketNumber = requireFirstRow(ticketResult.rows).next_number;

  const properties = {
    state: state || 'backlog',
    priority: priority || 'medium',
    source: source || 'internal',
    assignee_id: assignee_id || null,
    rejection_reason: null,
    due_date: due_date || null,
    is_system_generated: is_system_generated || false,
    accountability_target_id: accountability_target_id || null,
    accountability_type: accountability_type || null,
  };

  const result = await client.query<IssueDocumentRow>(
    `INSERT INTO documents (workspace_id, document_type, title, properties, ticket_number, created_by)
     VALUES ($1, 'issue', $2, $3, $4, $5)
     RETURNING *`,
    [workspaceId, title, JSON.stringify(properties), ticketNumber, userId]
  );

  const newIssueId = requireFirstRow(result.rows).id;

  for (const assoc of belongs_to) {
    try {
      await requireReferenceableDocument(
        client,
        actor,
        assoc.id,
        expectedTypeForRelationship(assoc.type)
      );
    } catch (error) {
      if (error instanceof Error && error.message === 'DOCUMENT_NOT_READABLE') {
        await client.query('ROLLBACK');
        return { ok: false, status: 404, body: { error: 'Referenced document not found' } };
      }
      throw error;
    }
  }

  await syncBelongsToAssociations(
    newIssueId,
    belongs_to.map((assoc) => ({ id: assoc.id, type: assoc.type })),
    client
  );

  const sprintAssociations = belongs_to.filter((bt) => bt.type === 'sprint');
  await client.query('COMMIT');

  await enqueueFleetGraphIssueAttentionEvents({
    workspaceId,
    issueIds: [newIssueId],
    eventType: sprintAssociations.length > 0 ? 'issue_week_changed' : 'issue_changed',
    reason: 'issue_created',
  });

  for (const sprintAssoc of sprintAssociations) {
    const issueCountResult = await pool.query<CountRow>(
      `SELECT COUNT(*) as count FROM document_associations
       WHERE related_id = $1 AND relationship_type = 'sprint'`,
      [sprintAssoc.id]
    );
    const issueCount = toCount(requireFirstRow(issueCountResult.rows).count);
    if (issueCount === 1) {
      broadcastToUser(userId, 'accountability:updated', { type: 'week_issues', targetId: sprintAssoc.id });
    }
  }

  const belongsToResult = await getBelongsToAssociations(newIssueId);
  const row = requireFirstRow(result.rows);
  const issue = extractIssueFromRow(row);
  return {
    ok: true,
    status: 201,
    body: {
      ...issue,
      display_id: `#${ticketNumber}`,
      belongs_to: belongsToResult,
    },
  };
}

export async function updateIssueMutation(
  input: UpdateIssueInput
): Promise<IssueMutationResult<Record<string, unknown>>> {
  const { client, actor, principal, userId, workspaceId, issueId: id, data } = input;

  const denied = await guardIssueMutation(client, principal, {
    action: 'write',
    documentId: id,
    expectedType: 'issue',
  });
  if (denied) return denied;

  const { isAdmin } = await getDocumentAccessContext(actor, client);

  const existing = await client.query<IssueTitlePropertiesRow>(
    `SELECT id, title, properties
     FROM documents
     WHERE id = $1 AND workspace_id = $2 AND document_type = 'issue'`,
    [id, workspaceId]
  );

  if (existing.rows.length === 0) {
    return { ok: false, status: 404, body: { error: 'Issue not found' } };
  }

  const existingIssue = requireFirstRow(existing.rows);
  const currentProps = (existingIssue.properties ?? {}) as Partial<IssueProperties>;
  const updates: string[] = [];
  const values: unknown[] = [];
  let paramIndex = 1;

  if (data.belongs_to) {
    const hasSprintAssociation = data.belongs_to.some((bt) => bt.type === 'sprint');
    if (hasSprintAssociation) {
      const effectiveEstimate = data.estimate !== undefined ? data.estimate : currentProps.estimate;
      if (!effectiveEstimate) {
        return { ok: false, status: 400, body: { error: 'Estimate is required before assigning to a week' } };
      }
    }
  }

  const isClosingIssue = data.state && (data.state === 'done' || data.state === 'cancelled');
  const wasNotClosed = currentProps.state !== 'done' && currentProps.state !== 'cancelled';

  if (isClosingIssue && wasNotClosed) {
    const childrenResult = await client.query<IncompleteChildRow>(
      `SELECT d.id, d.title, d.ticket_number, d.properties->>'state' as state
       FROM documents d
       JOIN document_associations da ON da.document_id = d.id
       WHERE da.related_id = $1
         AND da.relationship_type = 'parent'
         AND d.workspace_id = $2
         AND d.document_type = 'issue'
         AND d.archived_at IS NULL
         AND d.deleted_at IS NULL
         AND ${VISIBILITY_FILTER_SQL('d', '$3', '$4')}`,
      [id, workspaceId, userId, isAdmin]
    );

    const incompleteChildren = childrenResult.rows.filter(
      (child) => child.state !== 'done' && child.state !== 'cancelled'
    );

    if (incompleteChildren.length > 0 && !data.confirm_orphan_children) {
      return {
        ok: false,
        status: 409,
        body: {
          error: 'incomplete_children',
          message: `This issue has ${incompleteChildren.length} incomplete sub-issue(s). Closing it will remove their parent association.`,
          incomplete_children: incompleteChildren.map((child) => ({
            id: child.id,
            title: child.title,
            ticket_number: child.ticket_number,
            state: child.state,
          })),
          confirm_action: 'Set confirm_orphan_children: true to proceed',
        },
      };
    }

    if (incompleteChildren.length > 0 && data.confirm_orphan_children) {
      await client.query(
        `DELETE FROM document_associations
         WHERE related_id = $1
           AND relationship_type = 'parent'`,
        [id]
      );
    }
  }

  const changes: Array<{ field: string; oldValue: string | null; newValue: string | null }> = [];

  if (data.title !== undefined && data.title !== existingIssue.title) {
    updates.push(`title = $${paramIndex++}`);
    values.push(data.title);
    changes.push({ field: 'title', oldValue: existingIssue.title, newValue: data.title });
  }

  const newProps = { ...currentProps };
  let propsChanged = false;

  if (data.state !== undefined && data.state !== currentProps.state) {
    changes.push({ field: 'state', oldValue: currentProps.state || null, newValue: data.state });
    newProps.state = data.state;
    propsChanged = true;
    const timestampUpdates = getTimestampUpdates(currentProps.state || null, data.state);
    for (const [col, expr] of Object.entries(timestampUpdates)) {
      updates.push(`${col} = ${expr}`);
    }
  }
  if (data.priority !== undefined && data.priority !== currentProps.priority) {
    changes.push({ field: 'priority', oldValue: currentProps.priority || null, newValue: data.priority });
    newProps.priority = data.priority;
    propsChanged = true;
  }
  if (data.assignee_id !== undefined && data.assignee_id !== currentProps.assignee_id) {
    changes.push({ field: 'assignee_id', oldValue: currentProps.assignee_id || null, newValue: data.assignee_id });
    newProps.assignee_id = data.assignee_id;
    propsChanged = true;
  }
  if (data.estimate !== undefined && data.estimate !== currentProps.estimate) {
    changes.push({
      field: 'estimate',
      oldValue: currentProps.estimate?.toString() || null,
      newValue: data.estimate?.toString() || null,
    });
    newProps.estimate = data.estimate;
    propsChanged = true;
  }

  if (data.claude_metadata) {
    newProps.claude_metadata = {
      ...data.claude_metadata,
      updated_at: new Date().toISOString(),
    };
    propsChanged = true;
  }

  let propsValueIndex = -1;
  if (propsChanged) {
    updates.push(`properties = $${paramIndex++}`);
    propsValueIndex = values.length;
    values.push(JSON.stringify(newProps));
  }

  let belongsToChanged = false;
  let oldBelongsTo: BelongsTo[] = [];
  let newBelongsTo: BelongsTo[] = [];

  if (data.belongs_to !== undefined) {
    oldBelongsTo = await getBelongsToAssociations(id);
    newBelongsTo = data.belongs_to;

    const oldIds = oldBelongsTo.map((bt) => `${bt.type}:${bt.id}`).sort().join(',');
    const newIds = newBelongsTo.map((bt) => `${bt.type}:${bt.id}`).sort().join(',');

    if (oldIds !== newIds) {
      belongsToChanged = true;

      const oldSprintAssoc = oldBelongsTo.find((bt) => bt.type === 'sprint');
      const newSprintAssoc = newBelongsTo.find((bt) => bt.type === 'sprint');

      if (oldSprintAssoc && newSprintAssoc && oldSprintAssoc.id !== newSprintAssoc.id && currentProps.state !== 'done') {
        const oldSprintResult = await client.query<OldSprintRow>(
          `SELECT properties->>'sprint_number' as sprint_number, w.sprint_start_date
           FROM documents d
           JOIN workspaces w ON d.workspace_id = w.id
           WHERE d.id = $1 AND d.document_type = 'sprint'`,
          [oldSprintAssoc.id]
        );

        if (oldSprintResult.rows.length > 0) {
          const oldSprint = requireFirstRow(oldSprintResult.rows);
          const sprintNumber = parseInt(oldSprint.sprint_number ?? '', 10);
          const rawStartDate = oldSprint.sprint_start_date;
          const sprintDuration = 7;

          let startDate: Date;
          if (rawStartDate instanceof Date) {
            startDate = new Date(Date.UTC(rawStartDate.getFullYear(), rawStartDate.getMonth(), rawStartDate.getDate()));
          } else if (typeof rawStartDate === 'string') {
            startDate = new Date(rawStartDate + 'T00:00:00Z');
          } else {
            startDate = new Date();
          }

          const sprintEndDate = new Date(startDate);
          sprintEndDate.setUTCDate(sprintEndDate.getUTCDate() + sprintNumber * sprintDuration - 1);

          if (new Date() > sprintEndDate) {
            newProps.carryover_from_sprint_id = oldSprintAssoc.id;
            propsChanged = true;
          }
        }
      } else if (oldSprintAssoc && !newSprintAssoc) {
        delete newProps.carryover_from_sprint_id;
        propsChanged = true;
      }

      changes.push({
        field: 'belongs_to',
        oldValue: JSON.stringify(oldBelongsTo.map((bt) => ({ id: bt.id, type: bt.type }))),
        newValue: JSON.stringify(newBelongsTo.map((bt) => ({ id: bt.id, type: bt.type }))),
      });
    }
  }

  if (propsChanged && propsValueIndex === -1) {
    updates.push(`properties = $${paramIndex++}`);
    propsValueIndex = values.length;
    values.push(JSON.stringify(newProps));
  } else if (propsChanged && propsValueIndex >= 0) {
    values[propsValueIndex] = JSON.stringify(newProps);
  }

  if (updates.length === 0 && !belongsToChanged) {
    return { ok: false, status: 400, body: { error: 'No fields to update' } };
  }

  await client.query('BEGIN');

  const automatedBy = data.claude_metadata?.updated_by;
  for (const change of changes) {
    await logDocumentChange(id, change.field, change.oldValue, change.newValue, userId, automatedBy, client);
  }

  if (updates.length > 0) {
    updates.push(`updated_at = now()`);
    await client.query(
      `UPDATE documents SET ${updates.join(', ')} WHERE id = $${paramIndex} AND workspace_id = $${paramIndex + 1}`,
      [...values, id, workspaceId]
    );
  }

  if (belongsToChanged) {
    for (const assoc of newBelongsTo) {
      try {
        await requireReferenceableDocument(
          client,
          actor,
          assoc.id,
          expectedTypeForRelationship(assoc.type)
        );
      } catch (error) {
        if (error instanceof Error && error.message === 'DOCUMENT_NOT_READABLE') {
          await client.query('ROLLBACK');
          return { ok: false, status: 404, body: { error: 'Referenced document not found' } };
        }
        throw error;
      }
    }

    await syncBelongsToAssociations(
      id,
      newBelongsTo.map((assoc) => ({ id: assoc.id, type: assoc.type })),
      client
    );
  }

  const result = await client.query<IssueDocumentRow>(
    `SELECT * FROM documents WHERE id = $1 AND workspace_id = $2`,
    [id, workspaceId]
  );

  await client.query('COMMIT');

  await enqueueFleetGraphIssueAttentionEvents({
    workspaceId,
    issueIds: [id],
    eventType: belongsToChanged ? 'issue_week_changed' : 'issue_changed',
    reason: belongsToChanged ? 'issue_belongs_to_changed' : 'issue_updated',
  });

  if (belongsToChanged) {
    const oldSprintIds = oldBelongsTo.filter((bt) => bt.type === 'sprint').map((bt) => bt.id);
    const newSprintIds = newBelongsTo.filter((bt) => bt.type === 'sprint').map((bt) => bt.id);
    const addedSprintIds = newSprintIds.filter((sprintId) => !oldSprintIds.includes(sprintId));

    for (const sprintId of addedSprintIds) {
      const issueCountResult = await pool.query<CountRow>(
        `SELECT COUNT(*) as count FROM document_associations
         WHERE related_id = $1 AND relationship_type = 'sprint'`,
        [sprintId]
      );
      const issueCount = toCount(requireFirstRow(issueCountResult.rows).count);
      if (issueCount === 1) {
        broadcastToUser(userId, 'accountability:updated', { type: 'week_issues', targetId: sprintId });
      }
    }
  }

  const row = requireFirstRow(result.rows);
  const issue = extractIssueFromRow(row);
  const belongsTo = await getBelongsToAssociations(id);

  if (isClosingIssue && wasNotClosed) {
    const props = (row.properties ?? {}) as Partial<IssueProperties>;
    if (props.source === 'action_items') {
      const assigneeId = props.assignee_id || userId;
      broadcastToUser(assigneeId, 'accountability:updated', { issueId: id, state: data.state });
    }
  }

  return {
    ok: true,
    status: 200,
    body: { ...issue, display_id: `#${row.ticket_number}`, belongs_to: belongsTo },
  };
}

export async function acceptIssueMutation(input: {
  issueId: string;
  principal: Principal;
  userId: string;
  workspaceId: string;
}): Promise<IssueMutationResult<Record<string, unknown>>> {
  const { issueId: id, principal, userId, workspaceId } = input;

  const denied = await guardIssueMutation(pool, principal, {
    action: 'write',
    documentId: id,
    expectedType: 'issue',
  });
  if (denied) return denied;

  const existing = await pool.query<IssuePropertiesRow>(
    `SELECT id, properties FROM documents
     WHERE id = $1 AND workspace_id = $2 AND document_type = 'issue'`,
    [id, workspaceId]
  );

  if (existing.rows.length === 0) {
    return { ok: false, status: 404, body: { error: 'Issue not found' } };
  }

  const props = (requireFirstRow(existing.rows).properties ?? {}) as Partial<IssueProperties>;
  if (props.state !== 'triage') {
    return { ok: false, status: 400, body: { error: 'Issue must be in triage state to be accepted' } };
  }

  const newProps = { ...props, state: 'backlog' as const };
  const result = await pool.query<IssueDocumentRow>(
    `UPDATE documents
     SET properties = $3, updated_at = now()
     WHERE id = $1 AND workspace_id = $2
     RETURNING *`,
    [id, workspaceId, JSON.stringify(newProps)]
  );

  await logDocumentChange(id, 'state', 'triage', 'backlog', userId);
  await enqueueFleetGraphIssueAttentionEvents({
    workspaceId,
    issueIds: [id],
    eventType: 'issue_changed',
    reason: 'issue_accepted',
  });
  const issue = extractIssueFromRow(requireFirstRow(result.rows));
  return { ok: true, status: 200, body: { ...issue, display_id: `#${issue.ticket_number}` } };
}

export async function rejectIssueMutation(input: {
  issueId: string;
  principal: Principal;
  userId: string;
  workspaceId: string;
  reason: string;
}): Promise<IssueMutationResult<Record<string, unknown>>> {
  const { issueId: id, principal, userId, workspaceId, reason } = input;

  const denied = await guardIssueMutation(pool, principal, {
    action: 'write',
    documentId: id,
    expectedType: 'issue',
  });
  if (denied) return denied;

  const existing = await pool.query<IssuePropertiesRow>(
    `SELECT id, properties FROM documents
     WHERE id = $1 AND workspace_id = $2 AND document_type = 'issue'`,
    [id, workspaceId]
  );

  if (existing.rows.length === 0) {
    return { ok: false, status: 404, body: { error: 'Issue not found' } };
  }

  const props = (requireFirstRow(existing.rows).properties ?? {}) as Partial<IssueProperties>;
  if (props.state !== 'triage') {
    return { ok: false, status: 400, body: { error: 'Issue must be in triage state to be rejected' } };
  }

  const newProps = { ...props, state: 'cancelled' as const, rejection_reason: reason };
  const result = await pool.query<IssueDocumentRow>(
    `UPDATE documents
     SET properties = $3, cancelled_at = NOW(), updated_at = now()
     WHERE id = $1 AND workspace_id = $2
     RETURNING *`,
    [id, workspaceId, JSON.stringify(newProps)]
  );

  await logDocumentChange(id, 'state', 'triage', 'cancelled', userId);
  await enqueueFleetGraphIssueAttentionEvents({
    workspaceId,
    issueIds: [id],
    eventType: 'issue_changed',
    reason: 'issue_rejected',
  });
  const issue = extractIssueFromRow(requireFirstRow(result.rows));
  return { ok: true, status: 200, body: { ...issue, display_id: `#${issue.ticket_number}` } };
}

export async function createIssueIterationMutation(input: {
  issueId: string;
  principal: Principal;
  userId: string;
  workspaceId: string;
  status: 'pass' | 'fail' | 'in_progress';
  what_attempted?: string;
  blockers_encountered?: string;
}): Promise<IssueMutationResult<ReturnType<typeof mapStoredIssueIterationRow>>> {
  const { issueId, principal, userId, workspaceId, status, what_attempted, blockers_encountered } = input;

  const denied = await guardIssueMutation(pool, principal, {
    action: 'write',
    documentId: issueId,
    expectedType: 'issue',
  });
  if (denied) return denied;

  const result = await pool.query<IssueStoredIterationRow>(
    `INSERT INTO issue_iterations
     (issue_id, workspace_id, status, what_attempted, blockers_encountered, author_id)
     VALUES ($1, $2, $3, $4, $5, $6)
     RETURNING *`,
    [issueId, workspaceId, status, what_attempted || null, blockers_encountered || null, userId]
  );

  const authorResult = await pool.query<IssueIterationAuthorRow>(
    'SELECT id, name, email FROM users WHERE id = $1',
    [userId]
  );

  const iteration = requireFirstRow(result.rows);
  const author = requireFirstRow(authorResult.rows);
  await enqueueFleetGraphIssueAttentionEvents({
    workspaceId,
    issueIds: [issueId],
    eventType: 'issue_iteration_added',
    reason: 'issue_iteration_added',
  });
  return { ok: true, status: 201, body: mapStoredIssueIterationRow(iteration, author) };
}

export async function listIssueIterations(
  db: QueryRunner,
  input: {
    issueId: string;
    principal: Principal;
    workspaceId: string;
    status?: 'pass' | 'fail' | 'in_progress';
  }
): Promise<IssueMutationResult<ReturnType<typeof mapListedIssueIterationRow>[]>> {
  const { issueId, principal, workspaceId, status } = input;

  const denied = await guardIssueMutation(db, principal, {
    action: 'read',
    documentId: issueId,
    expectedType: 'issue',
  });
  if (denied) return denied;

  let query = `
    SELECT i.*, u.name as author_name, u.email as author_email
    FROM issue_iterations i
    JOIN users u ON i.author_id = u.id
    WHERE i.issue_id = $1 AND i.workspace_id = $2
  `;
  const params: unknown[] = [issueId, workspaceId];
  let paramIndex = 3;

  if (status) {
    query += ` AND i.status = $${paramIndex++}`;
    params.push(status);
  }

  query += ' ORDER BY i.created_at DESC';

  const result = await db.query<IssueIterationListRow>(query, params);
  return { ok: true, status: 200, body: result.rows.map(mapListedIssueIterationRow) };
}

/**
 * Shared OAuth State Management
 *
 * Provides secure storage and retrieval of OAuth state parameters.
 * Used by both PIV (FPKI) and CAIA authentication flows.
 *
 * Security features:
 * - Cryptographically secure state generation
 * - Database storage (survives server restarts)
 * - One-time use (consumed on retrieval)
 * - Automatic expiration (10 minutes)
 * - State format validation
 */

import crypto from 'crypto';
import { pool } from '../db/client.js';

// OAuth state expiry (10 minutes - OAuth flows should complete quickly)
const OAUTH_STATE_TTL_MS = 10 * 60 * 1000;

/**
 * Validate that a state string is safe and reasonable
 *
 * Accepts multiple formats since different SDKs generate states differently:
 * - 64-char hex (our internal format, crypto.randomBytes)
 * - base64url (OIDC standard, openid-client/generators.state())
 * - UUID format (some OAuth libraries)
 *
 * Security is provided by:
 * - Cryptographic randomness (SDK responsibility)
 * - One-time use (consumed on retrieval)
 * - 10-minute expiration
 * - Server-side storage (not in cookies)
 */
export function isValidStateFormat(state: string): boolean {
  // Minimum 16 chars, maximum 256 chars
  // Allow alphanumeric, dash, underscore (covers hex, base64url, UUID)
  return state.length >= 16 && state.length <= 256 && /^[a-zA-Z0-9_-]+$/.test(state);
}

/**
 * Generate cryptographically secure session ID
 */
export function generateSecureSessionId(): string {
  return crypto.randomBytes(32).toString('hex');
}

/**
 * Store OAuth state in database (survives server restarts)
 *
 * @throws Error if state format is invalid
 */
export async function storeOAuthState(
  state: string,
  nonce: string,
  codeVerifier: string
): Promise<void> {
  // Validate state format (defense in depth)
  if (!isValidStateFormat(state)) {
    throw new Error('Invalid state format');
  }

  const expiresAt = new Date(Date.now() + OAUTH_STATE_TTL_MS);

  // Clean up expired states opportunistically (every ~10th request)
  if (Math.random() < 0.1) {
    await pool.query('DELETE FROM oauth_state WHERE expires_at < NOW()').catch(() => {});
  }

  await pool.query(
    'INSERT INTO oauth_state (state_id, nonce, code_verifier, expires_at) VALUES ($1, $2, $3, $4)',
    [state, nonce, codeVerifier, expiresAt]
  );
}

/**
 * Retrieve and delete OAuth state from database (one-time use)
 *
 * @returns State data if valid and not expired, null otherwise
 */
export async function consumeOAuthState(
  state: string
): Promise<{ nonce: string; codeVerifier: string } | null> {
  // Validate state format before database query
  if (!isValidStateFormat(state)) {
    return null;
  }

  const result = await pool.query(
    'DELETE FROM oauth_state WHERE state_id = $1 AND expires_at > NOW() RETURNING nonce, code_verifier',
    [state]
  );

  if (result.rows.length === 0) {
    return null;
  }

  return {
    nonce: result.rows[0].nonce,
    codeVerifier: result.rows[0].code_verifier,
  };
}

/**
 * Swagger/OpenAPI Setup
 *
 * This module configures Swagger UI and serves the OpenAPI specification.
 * Schemas are auto-generated from Zod validators via @asteasolutions/zod-to-openapi.
 */

import swaggerUi from 'swagger-ui-express';
import { Express, type RequestHandler } from 'express';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import type { OpenAPIObject } from 'openapi3-ts/oas30';
import prettier from 'prettier';

// Import the OpenAPI module to register all schemas
import { generateOpenAPIDocument } from './openapi/index.js';
import { normalizeNullableRefs } from './openapi/normalize-nullable-refs.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Generate the OpenAPI spec from registered schemas
export const swaggerSpec: OpenAPIObject = normalizeNullableRefs(generateOpenAPIDocument());

export function setupSwagger(app: Express, guard?: RequestHandler): void {
  const guards = guard ? [guard] : [];
  // Serve swagger UI at /api/docs
  app.use('/api/docs', ...guards, swaggerUi.serve, swaggerUi.setup(swaggerSpec, {
    customCss: '.swagger-ui .topbar { display: none }',
    customSiteTitle: 'Ship API Documentation',
    swaggerOptions: {
      persistAuthorization: true,
      docExpansion: 'list',
      filter: true,
      tagsSorter: 'alpha',
      operationsSorter: 'method',
    },
  }));

  // Serve the raw OpenAPI spec
  app.get('/api/openapi.json', ...guards, (req, res) => {
    res.setHeader('Content-Type', 'application/json');
    res.send(swaggerSpec);
  });

  app.get('/api/openapi.yaml', ...guards, (req, res) => {
    res.setHeader('Content-Type', 'text/yaml');
    const yaml = jsonToYaml(swaggerSpec);
    res.send(yaml);
  });
}

// Simple JSON to YAML converter (no external dependency needed)
function jsonToYaml(obj: unknown, indent = 0): string {
  const spaces = '  '.repeat(indent);

  if (obj === null) return 'null';
  if (obj === undefined) return '';
  if (typeof obj === 'string') {
    if (obj.includes('\n')) {
      const blockIndent = `${spaces}  `;
      const lines = obj.split('\n').map(line => `${blockIndent}${line}`);
      return `|\n${lines.join('\n')}`;
    }
    if (obj.includes(':') || obj.includes('#')) {
      return `"${obj.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
    }
    return obj;
  }
  if (typeof obj === 'number' || typeof obj === 'boolean') return String(obj);

  if (Array.isArray(obj)) {
    if (obj.length === 0) return '[]';
    return obj.map(item => {
      if (typeof item === 'object' && item !== null) {
        const value = jsonToYaml(item, indent + 1).trim();
        const [firstLine, ...rest] = value.split('\n');
        return `${spaces}- ${firstLine}${rest.length ? `\n${rest.join('\n')}` : ''}`;
      }
      const value = jsonToYaml(item, indent + 1);
      return `${spaces}- ${value}`;
    }).join('\n');
  }

  if (typeof obj === 'object') {
    const entries = Object.entries(obj);
    if (entries.length === 0) return '{}';
    return entries.map(([key, value]) => {
      if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
        if (Object.keys(value).length === 0) {
          return `${spaces}${key}: {}`;
        }
        return `${spaces}${key}:\n${jsonToYaml(value, indent + 1)}`;
      } else if (Array.isArray(value)) {
        if (value.length === 0) {
          return `${spaces}${key}: []`;
        }
        return `${spaces}${key}:\n${jsonToYaml(value, indent + 1)}`;
      } else {
        return `${spaces}${key}: ${jsonToYaml(value, indent)}`;
      }
    }).join('\n');
  }

  return String(obj);
}

// Generate static openapi.yaml file
export async function generateOpenApiFile(): Promise<void> {
  const yaml = await prettier.format(jsonToYaml(swaggerSpec), { parser: 'yaml' });
  const outputPath = path.join(__dirname, '..', 'openapi.yaml');
  fs.writeFileSync(outputPath, yaml, 'utf-8');
  console.log(`OpenAPI spec written to ${outputPath}`);

  // Also generate JSON version
  const jsonPath = path.join(__dirname, '..', 'openapi.json');
  fs.writeFileSync(jsonPath, JSON.stringify(swaggerSpec, null, 2), 'utf-8');
  console.log(`OpenAPI spec written to ${jsonPath}`);
}

type QueryIntegerOptions = {
  defaultValue: number;
  min?: number;
  max?: number;
};

export function getQueryString(value: unknown, fallback = ''): string {
  if (Array.isArray(value)) {
    const firstValue = value[0];
    return typeof firstValue === 'string' ? firstValue : fallback;
  }

  return typeof value === 'string' ? value : fallback;
}

export function getOptionalQueryString(value: unknown): string | undefined {
  const queryValue = getQueryString(value);
  return queryValue === '' ? undefined : queryValue;
}

export function getTrimmedQueryString(value: unknown, fallback = ''): string {
  return getQueryString(value, fallback).trim();
}

export function getClampedIntegerQuery(value: unknown, options: QueryIntegerOptions): number {
  const parsedValue = parseInt(getQueryString(value), 10);
  const valueOrDefault = parsedValue || options.defaultValue;
  const minBounded = options.min === undefined ? valueOrDefault : Math.max(valueOrDefault, options.min);
  return options.max === undefined ? minBounded : Math.min(minBounded, options.max);
}

/**
 * Transform issue reference patterns in TipTap JSON content to clickable links.
 *
 * Detects patterns:
 * - #123
 * - issue #123
 * - ISS-123
 *
 * Replaces with TipTap link marks pointing to /issues/:id
 */

import { pool } from '../db/client.js';

interface TipTapNode {
  type: string;
  content?: TipTapNode[];
  text?: string;
  marks?: Array<{ type: string; attrs?: Record<string, unknown> }>;
  attrs?: Record<string, unknown>;
}

interface TipTapDoc {
  type: 'doc';
  content?: TipTapNode[];
}

interface IssueInfo {
  id: string;
  ticket_number: number;
}

// Pattern to match issue references: #123, issue #123, ISS-123
// Captures the full match and the number
const ISSUE_PATTERN = /(?:#(\d+)|issue\s+#?(\d+)|ISS-(\d+))/gi;

/**
 * Look up issues by ticket numbers in a workspace
 */
async function lookupIssuesByTicketNumbers(
  workspaceId: string,
  ticketNumbers: number[]
): Promise<Map<number, IssueInfo>> {
  if (ticketNumbers.length === 0) return new Map();

  const result = await pool.query(
    `SELECT id, ticket_number FROM documents
     WHERE workspace_id = $1
       AND document_type = 'issue'
       AND ticket_number = ANY($2::int[])`,
    [workspaceId, ticketNumbers]
  );

  const issueMap = new Map<number, IssueInfo>();
  for (const row of result.rows) {
    issueMap.set(row.ticket_number, {
      id: row.id,
      ticket_number: row.ticket_number,
    });
  }

  return issueMap;
}

/**
 * Extract ticket numbers from text
 */
function extractTicketNumbers(text: string): number[] {
  const numbers: number[] = [];
  let match;
  const pattern = new RegExp(ISSUE_PATTERN.source, 'gi');

  while ((match = pattern.exec(text)) !== null) {
    // Match groups: #123 → [1], issue #123 → [2], ISS-123 → [3]
    const num = parseInt(match[1] ?? match[2] ?? match[3] ?? '', 10);
    if (!isNaN(num) && !numbers.includes(num)) {
      numbers.push(num);
    }
  }

  return numbers;
}

/**
 * Recursively extract all ticket numbers from TipTap content
 */
function extractAllTicketNumbers(nodes: TipTapNode[]): number[] {
  const numbers: number[] = [];

  for (const node of nodes) {
    if (node.type === 'text' && node.text) {
      numbers.push(...extractTicketNumbers(node.text));
    }
    if (node.content) {
      numbers.push(...extractAllTicketNumbers(node.content));
    }
  }

  return [...new Set(numbers)];
}

/**
 * Transform text node by replacing issue patterns with link marks
 */
function transformTextNode(
  text: string,
  issueMap: Map<number, IssueInfo>
): TipTapNode[] {
  const result: TipTapNode[] = [];
  let lastIndex = 0;
  const pattern = new RegExp(ISSUE_PATTERN.source, 'gi');
  let match;

  while ((match = pattern.exec(text)) !== null) {
    const num = parseInt(match[1] ?? match[2] ?? match[3] ?? '', 10);
    const issue = issueMap.get(num);

    // Add text before the match
    if (match.index > lastIndex) {
      result.push({
        type: 'text',
        text: text.slice(lastIndex, match.index),
      });
    }

    // If issue exists, add as link; otherwise, add as plain text
    if (issue) {
      result.push({
        type: 'text',
        text: match[0],
        marks: [
          {
            type: 'link',
            attrs: {
              href: `/issues/${issue.id}`,
              target: '_self',
            },
          },
        ],
      });
    } else {
      result.push({
        type: 'text',
        text: match[0],
      });
    }

    lastIndex = match.index + match[0].length;
  }

  // Add remaining text
  if (lastIndex < text.length) {
    result.push({
      type: 'text',
      text: text.slice(lastIndex),
    });
  }

  return result;
}

/**
 * Recursively transform nodes
 */
function transformNodes(
  nodes: TipTapNode[],
  issueMap: Map<number, IssueInfo>
): TipTapNode[] {
  const result: TipTapNode[] = [];

  for (const node of nodes) {
    if (node.type === 'text' && node.text) {
      // Don't transform text that already has marks (like existing links)
      if (node.marks && node.marks.length > 0) {
        result.push(node);
      } else {
        // Transform this text node
        const transformed = transformTextNode(node.text, issueMap);
        result.push(...transformed);
      }
    } else if (node.content) {
      // Recursively transform child content
      result.push({
        ...node,
        content: transformNodes(node.content, issueMap),
      });
    } else {
      result.push(node);
    }
  }

  return result;
}

/**
 * Transform issue reference patterns in TipTap JSON content to clickable links.
 *
 * @param content - TipTap JSON document
 * @param workspaceId - Workspace ID for issue lookup
 * @param preloadedIssueMap - Optional pre-fetched issue map to avoid N+1 queries in batch scenarios
 * @returns Transformed TipTap JSON with issue links
 */
export async function transformIssueLinks(
  content: unknown,
  workspaceId: string,
  preloadedIssueMap?: Map<number, IssueInfo>
): Promise<unknown> {
  if (!content || typeof content !== 'object') return content;

  const doc = content as TipTapDoc;
  if (doc.type !== 'doc' || !Array.isArray(doc.content)) return content;

  // Extract all ticket numbers from content
  const ticketNumbers = extractAllTicketNumbers(doc.content);
  if (ticketNumbers.length === 0) return content;

  // Use preloaded map if provided, otherwise look up
  let issueMap: Map<number, IssueInfo>;
  if (preloadedIssueMap) {
    // Filter the preloaded map to only include ticket numbers found in this content
    issueMap = new Map();
    for (const num of ticketNumbers) {
      const issue = preloadedIssueMap.get(num);
      if (issue) {
        issueMap.set(num, issue);
      }
    }
  } else {
    issueMap = await lookupIssuesByTicketNumbers(workspaceId, ticketNumbers);
  }

  if (issueMap.size === 0) return content;

  // Transform the content
  return {
    ...doc,
    content: transformNodes(doc.content, issueMap),
  };
}

/**
 * Extract all ticket numbers from multiple TipTap JSON documents.
 * Useful for batch pre-loading issue data to avoid N+1 queries.
 *
 * @param contents - Array of TipTap JSON documents
 * @returns Deduplicated list of ticket numbers
 */
export function extractTicketNumbersFromContents(contents: unknown[]): number[] {
  const allNumbers: number[] = [];

  for (const content of contents) {
    if (!content || typeof content !== 'object') continue;

    const doc = content as TipTapDoc;
    if (doc.type !== 'doc' || !Array.isArray(doc.content)) continue;

    allNumbers.push(...extractAllTicketNumbers(doc.content));
  }

  return [...new Set(allNumbers)];
}

/**
 * Batch lookup issues by ticket numbers.
 * Use this to pre-fetch issue data before calling transformIssueLinks multiple times.
 *
 * @param workspaceId - Workspace ID for issue lookup
 * @param ticketNumbers - Array of ticket numbers to look up
 * @returns Map of ticket number to issue info
 */
export async function batchLookupIssues(
  workspaceId: string,
  ticketNumbers: number[]
): Promise<Map<number, IssueInfo>> {
  return lookupIssuesByTicketNumbers(workspaceId, ticketNumbers);
}

