      headers: { 'x-csrf-token': cleanupCsrfToken },
      data: {
        personId: personDocId,
        sprintNumber: sprintNumber
      }
    })
  })

  test('UI shows allocation for pending user, then shows active user after acceptance', async ({ page }) => {
