import { ConversionDialog } from '@/components/dialogs/ConversionDialog';
import { BacklogPickerModal } from '@/components/dialogs/BacklogPickerModal';
import { useSelectionPersistenceOptional } from '@/contexts/SelectionPersistenceContext';
import type { UseSelectionReturn } from '@/components/SelectableList';
import { ALL_COLUMNS, DEFAULT_FILTER_TABS, SORT_OPTIONS } from '@/components/issues/issues-list-constants';
import { IssuesTableView } from '@/components/issues/IssuesTableView';
import { IssuesKanbanView } from '@/components/issues/IssuesKanbanView';
import { IssuesListContextMenu } from '@/components/issues/IssuesListContextMenu';
import { IssuesListFilterCombobox, IssuesListHeader } from '@/components/issues/IssuesListHeader';
import { useIssuesListFilters } from '@/hooks/useIssuesListFilters';
import { useIssuesBulkActions } from '@/hooks/useIssuesBulkActions';
import { useFleetGraphPageContextRegistration } from '@/contexts/FleetGraphPageContext';

export type { IssueListItem, Issue } from '@/contexts/IssuesContext';
export { StatusBadge, PriorityBadge } from '@/components/issues/issue-badges';
export { ALL_COLUMNS, DEFAULT_FILTER_TABS, SORT_OPTIONS } from '@/components/issues/issues-list-constants';

export interface IssuesListProps {
  issues?: IssueListItem[];
  loading?: boolean;
  onUpdateIssue?: (id: string, updates: Partial<Issue>) => Promise<Issue | null>;
  onCreateIssue?: () => Promise<Issue | null>;
  onRefreshIssues?: () => Promise<void>;
  storageKeyPrefix?: string;
  filterTabs?: FilterTab[] | null;
  initialStateFilter?: string;
  onStateFilterChange?: (filter: string) => void;
  urlParamPrefix?: string;
  showProgramFilter?: boolean;
  showProjectFilter?: boolean;
  showSprintFilter?: boolean;
  lockedProgramId?: string;
  lockedProjectId?: string;
  lockedSprintId?: string;
  inheritedContext?: {
    programId?: string;
    projectId?: string;
    sprintId?: string;
    assigneeId?: string;
  };
  showCreateButton?: boolean;
  createButtonLabel?: string;
  createButtonTestId?: string;
  viewModes?: ViewMode[];
  initialViewMode?: ViewMode;
  defaultColumns?: string[];
  enableKeyboardNavigation?: boolean;
  emptyState?: React.ReactNode;
  showPromoteToProject?: boolean;
  className?: string;
  headerContent?: React.ReactNode;
  hideHeader?: boolean;
  toolbarContent?: React.ReactNode;
  selectionPersistenceKey?: string;
  enableInlineSprintAssignment?: boolean;
  showBacklogPicker?: boolean;
  allowShowAllIssues?: boolean;
}

export function IssuesList({
  issues: issuesProp,
  loading: loadingProp = false,
  onUpdateIssue,
  onCreateIssue,
  onRefreshIssues,
  storageKeyPrefix = 'issues-list',
  filterTabs = DEFAULT_FILTER_TABS,
  initialStateFilter = '',
  onStateFilterChange,
  urlParamPrefix,
  showProgramFilter = false,
  showProjectFilter = true,
  showSprintFilter = true,
  lockedProgramId,
  lockedProjectId,
  lockedSprintId,
  inheritedContext,
  showCreateButton = true,
  createButtonLabel = 'New Issue',
  createButtonTestId,
  viewModes = ['list', 'kanban'],
  initialViewMode = 'list',
  defaultColumns,
  enableKeyboardNavigation = true,
  emptyState,
  showPromoteToProject = true,
  className,
  headerContent,
  hideHeader = false,
  toolbarContent,
  selectionPersistenceKey,
  enableInlineSprintAssignment = false,
  showBacklogPicker = false,
  allowShowAllIssues = false,
}: IssuesListProps) {
  const navigate = useNavigate();
  const location = useLocation();
  const updateIssueMutation = useUpdateIssue();
  const { data: teamMembers = [] } = useAssignableMembersQuery();
  const { data: projects = [] } = useProjectsQuery();
  const { showToast } = useToast();
  const queryClient = useQueryClient();

  const { data: sprintsData } = useSprintsQuery(lockedProgramId);
  const availableSprints = useMemo(() => {
    if (!sprintsData?.weeks) return [];
    return sprintsData.weeks.map(s => ({ id: s.id, name: s.name }));
  }, [sprintsData]);

  const shouldSelfFetch = Boolean(lockedProgramId || lockedProjectId || lockedSprintId);
  const [showAllIssues, setShowAllIssues] = useState(false);

  const { data: fetchedIssues, isLoading: isFetchingIssues } = useIssuesQuery(
    shouldSelfFetch ? {
      programId: lockedProgramId,
      projectId: lockedProjectId,
      sprintId: lockedSprintId,
    } : {},
    { enabled: shouldSelfFetch }
  );

  const { data: allIssuesData, isLoading: isLoadingAllIssues } = useIssuesQuery(
    {},
    { enabled: allowShowAllIssues && showAllIssues && shouldSelfFetch }
  );

  const createIssueMutation = useCreateIssue();

  const effectiveContext = useMemo(() => {
    const projectId = inheritedContext?.projectId ?? lockedProjectId;
    const sprintId = inheritedContext?.sprintId ?? lockedSprintId;
    let programId = inheritedContext?.programId ?? lockedProgramId;

    if (projectId && !programId) {
      const project = projects.find(p => p.id === projectId);
      if (project?.program_id) {
        programId = project.program_id;
      }
    }

    return {
      programId,
      projectId,
      sprintId,
      assigneeId: inheritedContext?.assigneeId,
    };
  }, [inheritedContext, lockedProgramId, lockedProjectId, lockedSprintId, projects]);

  const buildBelongsTo = useCallback((): BelongsTo[] => {
    const belongs_to: BelongsTo[] = [];
    if (effectiveContext.programId) {
      belongs_to.push({ id: effectiveContext.programId, type: 'program' });
    }
    if (effectiveContext.projectId) {
      belongs_to.push({ id: effectiveContext.projectId, type: 'project' });
    }
    if (effectiveContext.sprintId) {
      belongs_to.push({ id: effectiveContext.sprintId, type: 'sprint' });
    }
    return belongs_to;
  }, [effectiveContext]);

  const inContextIssues = shouldSelfFetch ? (fetchedIssues ?? []) : (issuesProp ?? []);
  const loading = shouldSelfFetch ? (isFetchingIssues || (showAllIssues && isLoadingAllIssues)) : loadingProp;

  const inContextIds = useMemo(() => new Set(inContextIssues.map(i => i.id)), [inContextIssues]);

  const issues = useMemo(() => {
    if (!showAllIssues || !allIssuesData) {
      return inContextIssues;
    }
    const outOfContextIssues = allIssuesData.filter(issue => !inContextIds.has(issue.id));
    return [...inContextIssues, ...outOfContextIssues];
  }, [showAllIssues, inContextIssues, allIssuesData, inContextIds]);

  const { sortBy, setSortBy, viewMode, setViewMode } = useListFilters({
    sortOptions: SORT_OPTIONS,
    defaultSort: 'updated',
    defaultViewMode: initialViewMode,
  });

  const { visibleColumns, columns, hiddenCount, toggleColumn } = useColumnVisibility({
    columns: ALL_COLUMNS,
    storageKey: `${storageKeyPrefix}-column-visibility`,
    defaultVisible: defaultColumns,
  });

  const {
    stateFilter,
    programFilter,
    setProgramFilter,
    projectFilter,
    setProjectFilter,
    sprintFilter,
    setSprintFilter,
    programOptions,
    projectOptions,
    sprintOptions,
    filteredIssues,
    handleFilterChange,
    stateFilterChanged,
  } = useIssuesListFilters({
    issues,
    initialStateFilter,
    onStateFilterChange,
    urlParamPrefix,
  });

  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; selection: UseSelectionReturn } | null>(null);
  const [convertingIssue, setConvertingIssue] = useState<IssueListItem | null>(null);
  const [isConverting, setIsConverting] = useState(false);
  const [isBacklogPickerOpen, setIsBacklogPickerOpen] = useState(false);

  const selectionPersistence = useSelectionPersistenceOptional();
  const getInitialSelection = useCallback((): Set<string> => {
    if (selectionPersistenceKey && selectionPersistence) {
      return selectionPersistence.getSelection(selectionPersistenceKey).selectedIds;
    }
    return new Set();
  }, [selectionPersistenceKey, selectionPersistence]);

  const [selectedIds, setSelectedIds] = useState<Set<string>>(getInitialSelection);
  const selectionRef = useRef<UseSelectionReturn | null>(null);
  const [, forceUpdate] = useState(0);

  useEffect(() => {
    if (selectionPersistenceKey && selectionPersistence) {
      selectionPersistence.setSelection(selectionPersistenceKey, {
        selectedIds,
        lastSelectedId: null,
      });
    }
  }, [selectedIds, selectionPersistenceKey, selectionPersistence]);

  const scopedIssuesList = Boolean(lockedProjectId || lockedProgramId || lockedSprintId);
  const fleetGraphPageContext = useMemo(() => buildIssuesListPageContext({
    location,
    scoped: scopedIssuesList,
    stateFilter,
    programFilter,
    projectFilter,
    sprintFilter,
    effectiveProgramId: effectiveContext.programId,
    effectiveProjectId: effectiveContext.projectId,
    showAllIssues,
    sortBy,
    viewMode,
    totalCount: issues.length,
    filteredCount: filteredIssues.length,
    selectedCount: selectedIds.size,
    visibleIssues: filteredIssues,
    selectedIds,
  }), [
    effectiveContext.programId,
    effectiveContext.projectId,
    filteredIssues,
    issues.length,
    location,
    lockedProgramId,
    lockedProjectId,
    lockedSprintId,
    programFilter,
    projectFilter,
    scopedIssuesList,
    selectedIds,
    showAllIssues,
    sortBy,
    sprintFilter,
    stateFilter,
    viewMode,
  ]);

  useFleetGraphPageContextRegistration(fleetGraphPageContext);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
    selectionRef.current?.clearSelection();
    setContextMenu(null);
  }, []);

  useEffect(() => {
    if (stateFilterChanged) {
      clearSelection();
    }
  }, [stateFilterChanged, clearSelection]);

  const {
    bulkUpdate,
    executeUndo,
    undoStateRef,
    handleBulkArchive,
    handleBulkDelete,
    handleBulkMoveToSprint,
    handleBulkChangeStatus,
    handleBulkAssign,
    handleBulkAssignProject,
    handleInlineSprintChange,
  } = useIssuesBulkActions({
    issues,
    selectedIds,
    clearSelection,
    onRefreshIssues,
    lockedSprintId,
    lockedProjectId,
    availableSprints,
    teamMembers,
    projects,
  });

  const handleCreateIssue = useCallback(async () => {
    if (shouldSelfFetch) {
      const belongs_to = buildBelongsTo();
      const issue = await createIssueMutation.mutateAsync({ belongs_to });
      if (issue) {
        navigate(`/documents/${issue.id}`);
      }
      return;
    }
    if (!onCreateIssue) return;
    const issue = await onCreateIssue();
    if (issue) {
      navigate(`/documents/${issue.id}`);
    }
  }, [shouldSelfFetch, buildBelongsTo, createIssueMutation, onCreateIssue, navigate]);

  const handleAddIssueToContext = useCallback(async (issue: IssueListItem) => {
    const existingBelongsTo = issue.belongs_to || [];
    const newBelongsTo = [...existingBelongsTo];

    if (effectiveContext.sprintId && !existingBelongsTo.some(b => b.id === effectiveContext.sprintId)) {
      newBelongsTo.push({ id: effectiveContext.sprintId, type: 'sprint' });
    }
    if (effectiveContext.projectId && !existingBelongsTo.some(b => b.id === effectiveContext.projectId)) {
      newBelongsTo.push({ id: effectiveContext.projectId, type: 'project' });
    }
    if (effectiveContext.programId && !existingBelongsTo.some(b => b.id === effectiveContext.programId)) {
      newBelongsTo.push({ id: effectiveContext.programId, type: 'program' });
    }

    try {
      await updateIssueMutation.mutateAsync({ id: issue.id, updates: { belongs_to: newBelongsTo } });
      showToast(`Added "${issue.title}" to context`, 'success');
      if (effectiveContext.sprintId) {
        queryClient.invalidateQueries({ queryKey: issueKeys.list({ sprintId: effectiveContext.sprintId }) });
      }
      if (effectiveContext.projectId) {
        queryClient.invalidateQueries({ queryKey: issueKeys.list({ projectId: effectiveContext.projectId }) });
      }
    } catch {
      showToast('Failed to add issue', 'error');
    }
  }, [effectiveContext, updateIssueMutation, queryClient, showToast]);

  const handleUpdateIssue = useCallback(async (id: string, updates: { state: IssueState }) => {
    if (onUpdateIssue) {
      await onUpdateIssue(id, updates);
    }
  }, [onUpdateIssue]);

  const handlePromoteToProject = useCallback((issue: IssueListItem) => {
    setConvertingIssue(issue);
    setContextMenu(null);
  }, []);

  const executeConversion = useCallback(async () => {
    if (!convertingIssue) return;
    setIsConverting(true);
    try {
      const res = await apiPost(`/api/documents/${convertingIssue.id}/convert`, { target_type: 'project' });
      if (res.ok) {
        const data = await readJson<{ id: string }>(res);
        await Promise.all([
          queryClient.invalidateQueries({ queryKey: issueKeys.lists() }),
          queryClient.invalidateQueries({ queryKey: projectKeys.lists() }),
        ]);
        showToast(`Issue promoted to project: ${convertingIssue.title}`, 'success');
        navigate(`/documents/${data.id}`, { replace: true });
      } else {
        const error = await readJson<LegacyErrorResponse>(res);
        showToast(error.error || 'Failed to convert issue to project', 'error');
        setIsConverting(false);
        setConvertingIssue(null);
      }
    } catch (err) {
      console.error('Failed to convert issue:', err);
      showToast('Failed to convert issue to project', 'error');
      setIsConverting(false);
      setConvertingIssue(null);
    }
  }, [convertingIssue, navigate, showToast, queryClient]);

  const handleSelectionChange = useCallback((newSelectedIds: Set<string>, newSelection: UseSelectionReturn) => {
    setSelectedIds(newSelectedIds);
    selectionRef.current = newSelection;
    forceUpdate(n => n + 1);
  }, []);

  useGlobalListNavigation({
    selection: selectionRef.current,
    selectionRef,
    enabled: enableKeyboardNavigation && viewMode === 'list',
    onEnter: useCallback((focusedId: string) => {
      navigate(`/documents/${focusedId}`);
    }, [navigate]),
  });

  const handleKanbanCheckboxClick = useCallback((id: string) => {
    setSelectedIds(prev => {
      const newSet = new Set(prev);
      if (newSet.has(id)) {
        newSet.delete(id);
      } else {
        newSet.add(id);
      }
      return newSet;
    });
  }, []);

  const handleKanbanContextMenu = useCallback((event: { x: number; y: number; issueId: string }) => {
    if (!selectedIds.has(event.issueId)) {
      setSelectedIds(new Set([event.issueId]));
    }
    const effectiveIds = selectedIds.has(event.issueId) ? selectedIds : new Set([event.issueId]);
    const mockSelection: UseSelectionReturn = {
      selectedIds: effectiveIds,
      focusedId: event.issueId,
      selectedCount: effectiveIds.size,
      hasSelection: effectiveIds.size > 0,
      isSelected: (id: string) => effectiveIds.has(id),
      isFocused: (id: string) => id === event.issueId,
      toggleSelection: () => {},
      toggleInGroup: () => {},
      selectAll: () => {},
      clearSelection: () => setSelectedIds(new Set()),
      selectRange: () => {},
      setFocusedId: () => {},
      moveFocus: () => {},
      extendSelection: () => {},
      handleClick: () => {},
      handleKeyDown: () => {},
    };
    selectionRef.current = mockSelection;
    setContextMenu({ x: event.x, y: event.y, selection: mockSelection });
  }, [selectedIds]);

  const handleContextMenu = useCallback((e: React.MouseEvent, _item: IssueListItem, selection: UseSelectionReturn) => {
    selectionRef.current = selection;
    setContextMenu({ x: e.clientX, y: e.clientY, selection });
  }, []);

  const canCreateIssue = Boolean(onCreateIssue || shouldSelfFetch);

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) {
        return;
      }
      if (e.key === 'z' && (e.metaKey || e.ctrlKey) && !e.shiftKey && undoStateRef.current) {
        e.preventDefault();
        executeUndo();
        return;
      }
      if (e.key === 'c' && !e.metaKey && !e.ctrlKey && canCreateIssue) {
        e.preventDefault();
        void handleCreateIssue();
      }
    };

    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [handleCreateIssue, canCreateIssue, executeUndo, undoStateRef]);

  const defaultEmptyState = useMemo(() => (
    <div className="text-center">
      <p className="text-muted">No issues found</p>
      {canCreateIssue && (
        <button
          onClick={() => void handleCreateIssue()}
          className="mt-2 text-sm text-accent hover:underline"
        >
          Create an issue
        </button>
      )}
    </div>
  ), [handleCreateIssue, canCreateIssue]);

  if (loading) {
    return <IssuesListSkeleton />;
  }

  const programFilterContent = showProgramFilter && !lockedProgramId ? (
    <IssuesListFilterCombobox
      storageKeyPrefix={storageKeyPrefix}
      suffix="program"
      options={programOptions}
      value={programFilter}
      onChange={setProgramFilter}
      placeholder="All Programs"
      ariaLabel="Filter issues by program"
    />
  ) : null;

  const projectFilterContent = showProjectFilter && !lockedProjectId ? (
    <IssuesListFilterCombobox
      storageKeyPrefix={storageKeyPrefix}
      suffix="project"
      options={projectOptions}
      value={projectFilter}
      onChange={setProjectFilter}
      placeholder="All Projects"
      ariaLabel="Filter issues by project"
    />
  ) : null;

  const sprintFilterContent = showSprintFilter && !lockedSprintId ? (
    <IssuesListFilterCombobox
      storageKeyPrefix={storageKeyPrefix}
      suffix="sprint"
      options={sprintOptions}
      value={sprintFilter}
      onChange={setSprintFilter}
      placeholder="All Weeks"
      ariaLabel="Filter issues by week"
    />
  ) : null;

  return (
    <div className={cn('flex h-full flex-col', className)}>
      {!hideHeader && (
        <IssuesListHeader
          headerContent={headerContent}
          sortBy={sortBy}
          onSortChange={setSortBy}
          viewModes={viewModes}
          viewMode={viewMode}
          onViewModeChange={setViewMode}
          visibleColumns={visibleColumns}
          onToggleColumn={toggleColumn}
          hiddenCount={hiddenCount}
          programFilterContent={programFilterContent}
          projectFilterContent={projectFilterContent}
          sprintFilterContent={sprintFilterContent}
          toolbarContent={toolbarContent}
          showBacklogPicker={showBacklogPicker}
          canShowBacklogPicker={Boolean(effectiveContext.sprintId || effectiveContext.projectId || effectiveContext.programId)}
          onOpenBacklogPicker={() => setIsBacklogPickerOpen(true)}
          allowShowAllIssues={allowShowAllIssues}
          shouldSelfFetch={shouldSelfFetch}
          showAllIssues={showAllIssues}
          onToggleShowAllIssues={() => setShowAllIssues(prev => !prev)}
          showCreateButton={showCreateButton}
          canCreateIssue={canCreateIssue}
          onCreateIssue={() => void handleCreateIssue()}
          createButtonLabel={createButtonLabel}
          createButtonTestId={createButtonTestId}
        />
      )}

      {selectedIds.size > 0 ? (
        <BulkActionBar
          selectedCount={selectedIds.size}
          onClearSelection={clearSelection}
          onArchive={handleBulkArchive}
          onDelete={handleBulkDelete}
          onChangeStatus={handleBulkChangeStatus}
          onMoveToSprint={handleBulkMoveToSprint}
          onAssign={handleBulkAssign}
          onAssignProject={handleBulkAssignProject}
          sprints={availableSprints}
          teamMembers={teamMembers}
          projects={projects}
          loading={bulkUpdate.isPending}
        />
      ) : filterTabs ? (
        <FilterTabs
          tabs={filterTabs}
          activeId={stateFilter}
          onChange={handleFilterChange}
          ariaLabel="Issue filters"
        />
      ) : null}

      {viewMode === 'kanban' ? (
        <IssuesKanbanView
          issues={filteredIssues}
          selectedIds={selectedIds}
          onUpdateIssue={handleUpdateIssue}
          onIssueClick={(id) => navigate(`/documents/${id}`)}
          onCheckboxClick={handleKanbanCheckboxClick}
          onContextMenu={handleKanbanContextMenu}
        />
      ) : (
        <IssuesTableView
          issues={filteredIssues}
          columns={columns}
          visibleColumns={visibleColumns}
          emptyState={emptyState || defaultEmptyState}
          initialSelectedIds={selectedIds}
          onItemClick={(issue) => navigate(`/documents/${issue.id}`)}
          onSelectionChange={handleSelectionChange}
          onContextMenu={handleContextMenu}
          enableInlineSprintAssignment={enableInlineSprintAssignment}
          availableSprints={availableSprints}
          onInlineSprintChange={handleInlineSprintChange}
          allowShowAllIssues={allowShowAllIssues}
          showAllIssues={showAllIssues}
          inContextIds={inContextIds}
          onAddIssueToContext={handleAddIssueToContext}
        />
      )}

      {contextMenu && (
        <IssuesListContextMenu
          x={contextMenu.x}
          y={contextMenu.y}
          selection={contextMenu.selection}
          filteredIssues={filteredIssues}
          showPromoteToProject={showPromoteToProject}
          onClose={() => setContextMenu(null)}
          onArchive={handleBulkArchive}
          onDelete={handleBulkDelete}
          onChangeStatus={handleBulkChangeStatus}
          onMoveToSprint={handleBulkMoveToSprint}
          onPromoteToProject={handlePromoteToProject}
        />
      )}

      {convertingIssue && (
        <ConversionDialog
          isOpen={!!convertingIssue}
          onClose={() => setConvertingIssue(null)}
          onConvert={executeConversion}
          sourceType="issue"
          title={convertingIssue.title}
          isConverting={isConverting}
        />
      )}

      {showBacklogPicker && (
        <BacklogPickerModal
          isOpen={isBacklogPickerOpen}
          onClose={() => setIsBacklogPickerOpen(false)}
          context={{
            sprintId: effectiveContext.sprintId,
            projectId: effectiveContext.projectId,
            programId: effectiveContext.programId,
          }}
          onIssuesAdded={() => {
            queryClient.invalidateQueries({ queryKey: issueKeys.all });
            if (effectiveContext.sprintId) {
              queryClient.invalidateQueries({ queryKey: issueKeys.list({ sprintId: effectiveContext.sprintId }) });
            }
            if (effectiveContext.projectId) {
              queryClient.invalidateQueries({ queryKey: issueKeys.list({ projectId: effectiveContext.projectId }) });
            }
          }}
        />
      )}
    </div>
  );
}

import { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { cn } from '@/lib/cn';
import { createOrGetWeeklyDocumentId } from '@/lib/accountability';
import { formatDateRange } from '@/lib/date-utils';

const API_URL = import.meta.env.VITE_API_URL ?? '';

type Status = 'done' | 'due' | 'late' | 'future' | 'changes_requested';

interface Week {
  number: number;
  name: string;
  startDate: string;
  endDate: string;
  isCurrent: boolean;
}

interface PersonWeekData {
  projectId: string | null;
  projectName: string | null;
  projectColor: string | null;
  planId: string | null;
  planStatus: Status | null;
  retroId: string | null;
  retroStatus: Status | null;
}

interface Person {
  id: string;
  name: string;
  weeks: Record<number, PersonWeekData>;
}

interface Program {
  id: string;
  name: string;
  color: string;
  people: Person[];
}

interface AccountabilityGridV3Data {
  programs: Program[];
  weeks: Week[];
  currentSprintNumber: number;
}

// Status colors
const STATUS_COLORS: Record<Status, string> = {
  done: '#22c55e',   // green
  due: '#eab308',    // yellow
  late: '#ef4444',   // red
  changes_requested: '#ea580c', // orange
  future: '#6b7280', // gray
};

// User-friendly status text for tooltips
const STATUS_TEXT: Record<Status, string> = {
  done: 'done',
  due: 'due this week',
  late: 'late',
  changes_requested: 'changes requested',
  future: 'not yet due',
};

/**
 * StatusCell - Shows Plan/Retro status as two colored squares
 * For person-centric view: shows status based on allocated project
 */
function StatusCell({
  weekData,
  onPlanClick,
  onRetroClick,
  isNavigating,
}: {
  weekData: PersonWeekData;
  onPlanClick?: () => void;
  onRetroClick?: () => void;
  isNavigating?: 'plan' | 'retro' | null;
}) {
  // If no allocation for this week, show empty state
  if (!weekData.projectId || !weekData.planStatus || !weekData.retroStatus) {
    return (
      <div className="flex w-full h-full items-center justify-center">
        <span className="text-xs text-muted">-</span>
      </div>
    );
  }

  const projectTooltip = weekData.projectName ? ` (${weekData.projectName})` : '';

  return (
    <div className="flex w-full h-full">
      {/* Plan status (left half) */}
      <button
        onClick={onPlanClick}
        disabled={isNavigating !== null}
        className={cn(
          'flex-1 h-full cursor-pointer transition-all hover:brightness-110 border-r border-white/20',
          isNavigating === 'plan' && 'animate-pulse'
        )}
        style={{ backgroundColor: STATUS_COLORS[weekData.planStatus] }}
        title={`Weekly Plan (${STATUS_TEXT[weekData.planStatus]})${projectTooltip}`}
        aria-label={`Weekly Plan (${STATUS_TEXT[weekData.planStatus]})${projectTooltip}`}
      />
      {/* Retro status (right half) */}
      <button
        onClick={onRetroClick}
        disabled={isNavigating !== null}
        className={cn(
          'flex-1 h-full cursor-pointer transition-all hover:brightness-110',
          isNavigating === 'retro' && 'animate-pulse'
        )}
        style={{ backgroundColor: STATUS_COLORS[weekData.retroStatus] }}
        title={`Weekly Retro (${STATUS_TEXT[weekData.retroStatus]})${projectTooltip}`}
        aria-label={`Weekly Retro (${STATUS_TEXT[weekData.retroStatus]})${projectTooltip}`}
      />
    </div>
  );
}

interface StatusOverviewHeatmapProps {
  showArchived?: boolean;
}

export function StatusOverviewHeatmap({ showArchived = false }: StatusOverviewHeatmapProps) {
  const navigate = useNavigate();
  const [data, setData] = useState<AccountabilityGridV3Data | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedPrograms, setExpandedPrograms] = useState<Set<string>>(new Set());
  const [navigatingCell, setNavigatingCell] = useState<{
    personId: string;
    weekNumber: number;
    type: 'plan' | 'retro';
  } | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const hasScrolledToCurrentRef = useRef(false);

  // Fetch data
  useEffect(() => {
    async function fetchData() {
      try {
        setLoading(true);
        const params = new URLSearchParams();
        if (showArchived) params.set('showArchived', 'true');
        const url = `${API_URL}/api/team/accountability-grid-v3${params.toString() ? `?${params}` : ''}`;
        const res = await fetch(url, { credentials: 'include' });

        if (!res.ok) {
          if (res.status === 403) {
            setError('Admin access required to view accountability grid');
          } else {
            setError('Failed to load accountability data');
          }
          return;
        }

        const json: AccountabilityGridV3Data = await res.json();
        setData(json);

        // Auto-expand all programs by default
        setExpandedPrograms(new Set(json.programs.map(p => p.id)));
      } catch {
        setError('Failed to load accountability data');
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, [showArchived]);

  // Scroll to current week on initial load
  useEffect(() => {
    if (data && scrollContainerRef.current && !hasScrolledToCurrentRef.current) {
      const currentWeekIndex = data.weeks.findIndex(w => w.isCurrent);
      if (currentWeekIndex >= 0) {
        requestAnimationFrame(() => {
          if (scrollContainerRef.current) {
            const columnWidth = 100;
            const scrollPosition = Math.max(0, (currentWeekIndex - 2) * columnWidth);
            scrollContainerRef.current.scrollLeft = scrollPosition;
            hasScrolledToCurrentRef.current = true;
          }
        });
      }
    }
  }, [data]);

  // Navigate to weekly plan or retro
  async function handleNavigate(
    personId: string,
    weekNumber: number,
    type: 'plan' | 'retro',
    existingDocId: string | null,
    projectId: string | null
  ) {
    if (existingDocId) {
      navigate(`/documents/${existingDocId}`);
      return;
    }

    setNavigatingCell({ personId, weekNumber, type });
    try {
      const documentId = await createOrGetWeeklyDocumentId({
        kind: type,
        personId,
        projectId: projectId || undefined,
        weekNumber,
      });
      if (documentId) {
        navigate(`/documents/${documentId}`);
      } else {
        console.error(`Failed to create weekly ${type}: request returned no document id`);
      }
    } catch (err) {
      console.error(`Failed to create weekly ${type}:`, err);
    } finally {
      setNavigatingCell(null);
    }
  }

  function toggleProgram(programId: string) {
    setExpandedPrograms(prev => {
      const next = new Set(prev);
      if (next.has(programId)) {
        next.delete(programId);
      } else {
        next.add(programId);
      }
      return next;
    });
  }

  // Build row structure: Program → Person (no project level)
  const rowStructure = useMemo(() => {
    if (!data) return [];

    const rows: Array<{
      type: 'program' | 'person';
      id: string;
      name: string;
      color?: string;
      depth: number;
      personData?: Person;
    }> = [];

    for (const program of data.programs) {
      rows.push({
        type: 'program',
        id: program.id,
        name: program.name,
        color: program.color,
        depth: 0,
      });

      if (expandedPrograms.has(program.id)) {
        for (const person of program.people) {
          rows.push({
            type: 'person',
            id: person.id,
            name: person.name,
            depth: 1,
            personData: person,
          });
        }
      }
    }

    return rows;
  }, [data, expandedPrograms]);

  if (loading) {
    return (
      <div className="flex flex-1 items-center justify-center">
        <div className="flex items-center gap-2 text-muted">
          <svg className="w-5 h-5 animate-spin" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
          </svg>
          Loading...
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-1 items-center justify-center">
        <span className="text-sm text-red-500">{error}</span>
      </div>
    );
  }

  if (!data || data.programs.length === 0) {
    return (
      <div className="flex flex-1 flex-col items-center justify-center text-muted p-8">
        <svg className="w-16 h-16 mb-4 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <path strokeLinecap="round" strokeLinejoin="round" d="M18 18.72a9.094 9.094 0 003.741-.479 3 3 0 00-4.682-2.72m.94 3.198l.001.031c0 .225-.012.447-.037.666A11.944 11.944 0 0112 21c-2.17 0-4.207-.576-5.963-1.584A6.062 6.062 0 016 18.719m12 0a5.971 5.971 0 00-.941-3.197m0 0A5.995 5.995 0 0012 12.75a5.995 5.995 0 00-5.058 2.772m0 0a3 3 0 00-4.681 2.72 8.986 8.986 0 003.74.477m.94-3.197a5.971 5.971 0 00-.94 3.197M15 6.75a3 3 0 11-6 0 3 3 0 016 0zm6 3a2.25 2.25 0 11-4.5 0 2.25 2.25 0 014.5 0zm-13.5 0a2.25 2.25 0 11-4.5 0 2.25 2.25 0 014.5 0z" />
        </svg>
        <p className="text-lg font-medium mb-2">No team members with allocations</p>
        <p className="text-sm text-center max-w-md">
          Assign team members to projects in the Allocation view to see their plan/retro status here.
        </p>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      {/* Legend */}
      <div className="flex items-center gap-4 px-4 py-2 border-b border-border text-xs">
        <span className="text-muted">Status:</span>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.done }} />
          <span>Done</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.due }} />
          <span>Due</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.late }} />
          <span>Late</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.future }} />
          <span>Future</span>
        </div>
        <span className="text-muted ml-4">|</span>
        <span className="text-muted">Left = Plan, Right = Retro</span>
      </div>

      {/* Grid container */}
      <div ref={scrollContainerRef} className="flex-1 overflow-auto pb-20">
        <div className="inline-flex min-w-full">
          {/* Sticky left column - Hierarchy */}
          <div className="flex flex-col sticky left-0 z-20 bg-background border-r border-border">
            {/* Header cell */}
            <div className="flex h-10 w-[240px] items-center border-b border-border px-3 sticky top-0 z-30 bg-background">
              <span className="text-xs font-medium text-muted">Program / Person</span>
            </div>

            {/* Hierarchy rows */}
            {rowStructure.map((row, index) => {
              if (row.type === 'program') {
                return (
                  <button
                    key={`program-${row.id}`}
                    onClick={() => toggleProgram(row.id)}
                    className="flex h-10 w-[240px] items-center gap-2 border-b border-border bg-border/30 px-3 hover:bg-border/50 text-left"
                  >
                    <svg
                      className={cn('w-3 h-3 transition-transform', expandedPrograms.has(row.id) && 'rotate-90')}
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                    >
                      <path d="M9 18l6-6-6-6" />
                    </svg>
                    <span
                      className="shrink-0 rounded px-1.5 py-0.5 text-[10px] font-bold text-white"
                      style={{ backgroundColor: row.color || '#6b7280' }}
                    >
                      {row.name.charAt(0).toUpperCase()}
                    </span>
                    <span className="truncate text-xs font-medium">{row.name}</span>
                    <span className="ml-auto text-[10px] text-muted">
                      {data.programs.find(p => p.id === row.id)?.people.length || 0}
                    </span>
                  </button>
                );
              }

              // Person row
              return (
                <div
                  key={`person-${row.id}-${index}`}
                  className="flex h-10 w-[240px] items-center gap-2 border-b border-border pl-6 pr-3 bg-background"
                >
                  <div className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full text-xs font-medium text-white bg-accent/80">
                    {row.name.charAt(0).toUpperCase()}
                  </div>
                  <span className="truncate text-xs text-foreground">{row.name}</span>
                </div>
              );
            })}
          </div>

          {/* Week columns */}
          <div className="flex">
            {data.weeks.map((week) => (
              <div key={week.number} className="flex flex-col">
                {/* Week header */}
                <div
                  className={cn(
                    'flex h-10 w-[100px] flex-col items-center justify-center border-b border-r border-border px-2 sticky top-0 z-10 bg-background',
                    week.isCurrent && 'ring-1 ring-inset ring-accent/30'
                  )}
                >
                  <span className={cn('text-xs font-medium', week.isCurrent ? 'text-accent' : 'text-foreground')}>
                    {week.name}
                  </span>
                  <span className="text-[10px] text-muted">
                    {formatDateRange(week.startDate, week.endDate)}
                  </span>
                </div>

                {/* Cells for each row */}
                {rowStructure.map((row, index) => {
                  if (row.type === 'program') {
                    // Empty cell for program header row
                    return (
                      <div
                        key={`program-${row.id}-week-${week.number}`}
                        className={cn(
                          'h-10 w-[100px] border-b border-r border-border bg-border/30',
                          week.isCurrent && 'bg-accent/5'
                        )}
                      />
                    );
                  }

                  // Person cell - get their allocation data for this week
                  const person = row.personData;
                  const weekData = person?.weeks[week.number];

                  if (!weekData) {
                    return (
                      <div
                        key={`person-${row.id}-week-${week.number}-${index}`}
                        className={cn(
                          'flex h-10 w-[100px] items-center justify-center border-b border-r border-border',
                          week.isCurrent && 'bg-accent/5'
                        )}
                      >
                        <span className="text-xs text-muted">-</span>
                      </div>
                    );
                  }

                  return (
                    <div
                      key={`person-${row.id}-week-${week.number}-${index}`}
                      className={cn(
                        'flex h-10 w-[100px] border-b border-r border-border overflow-hidden',
                        week.isCurrent && 'ring-1 ring-inset ring-accent/20'
                      )}
                    >
                      <StatusCell
                        weekData={weekData}
                        onPlanClick={() =>
                          handleNavigate(row.id, week.number, 'plan', weekData.planId, weekData.projectId)
                        }
                        onRetroClick={() =>
                          handleNavigate(row.id, week.number, 'retro', weekData.retroId, weekData.projectId)
                        }
                        isNavigating={
                          navigatingCell?.personId === row.id &&
                          navigatingCell?.weekNumber === week.number
                            ? navigatingCell.type
                            : null
                        }
                      />
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

export default StatusOverviewHeatmap;

