import { useState, useEffect, useRef, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { cn } from '@/lib/cn';
import { createOrGetWeeklyDocumentId } from '@/lib/accountability';
import { formatDateRange } from '@/lib/date-utils';
import type { DocumentTabProps } from '@/lib/document-tabs';

const API_URL = import.meta.env.VITE_API_URL ?? '';

type Status = 'done' | 'due' | 'late' | 'future';

interface Week {
  number: number;
  name: string;
  startDate: string;
  endDate: string;
  isCurrent: boolean;
}

interface PersonWeekData {
  isAllocated: boolean;
  planId: string | null;
  planStatus: Status;
  retroId: string | null;
  retroStatus: Status;
}

interface Person {
  id: string;
  name: string;
  weeks: Record<number, PersonWeekData>;
}

interface AllocationGridData {
  projectId: string;
  projectTitle: string;
  currentSprintNumber: number;
  weeks: Week[];
  people: Person[];
}

// Status colors
const STATUS_COLORS: Record<Status, string> = {
  done: '#22c55e',   // green
  due: '#eab308',    // yellow
  late: '#ef4444',   // red
  future: '#6b7280', // gray
};

// User-friendly status text for tooltips
const STATUS_TEXT: Record<Status, string> = {
  done: 'done',
  due: 'due this week',
  late: 'late',
  future: 'not yet due',
};

/**
 * StatusCell - Shows Plan/Retro status as two colored squares
 */
function StatusCell({
  planStatus,
  retroStatus,
  onPlanClick,
  onRetroClick,
  isNavigating,
}: {
  planStatus: Status;
  retroStatus: Status;
  onPlanClick?: () => void;
  onRetroClick?: () => void;
  isNavigating?: 'plan' | 'retro' | null;
}) {
  return (
    <div className="flex w-full h-full">
      {/* Plan status (left half) */}
      <button
        onClick={onPlanClick}
        disabled={isNavigating !== null}
        className={cn(
          'flex-1 h-full cursor-pointer transition-all hover:brightness-110 border-r border-white/20',
          isNavigating === 'plan' && 'animate-pulse'
        )}
        style={{ backgroundColor: STATUS_COLORS[planStatus] }}
        title={`Weekly Plan (${STATUS_TEXT[planStatus]})`}
      />
      {/* Retro status (right half) */}
      <button
        onClick={onRetroClick}
        disabled={isNavigating !== null}
        className={cn(
          'flex-1 h-full cursor-pointer transition-all hover:brightness-110',
          isNavigating === 'retro' && 'animate-pulse'
        )}
        style={{ backgroundColor: STATUS_COLORS[retroStatus] }}
        title={`Weekly Retro (${STATUS_TEXT[retroStatus]})`}
      />
    </div>
  );
}

/**
 * ProjectWeeksTab - Shows plan/retro status for team members allocated to this project
 *
 * Each cell shows two colored squares:
 * - Left: Weekly Plan status
 * - Right: Weekly Retro status
 *
 * Colors: green (done), yellow (due), red (late), gray (future)
 */
export default function ProjectWeeksTab({ documentId }: DocumentTabProps) {
  const navigate = useNavigate();
  const [data, setData] = useState<AllocationGridData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [navigatingCell, setNavigatingCell] = useState<{
    personId: string;
    weekNumber: number;
    type: 'plan' | 'retro';
  } | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const hasScrolledToCurrentRef = useRef(false);

  /**
   * Navigate to a weekly plan or retro document.
   * Creates the document if it doesn't exist yet.
   */
  async function handleNavigate(
    personId: string,
    weekNumber: number,
    type: 'plan' | 'retro',
    existingDocId: string | null
  ) {
    // If document already exists, navigate directly
    if (existingDocId) {
      navigate(`/documents/${existingDocId}`);
      return;
    }

    // Create the document first
    setNavigatingCell({ personId, weekNumber, type });
    try {
      const createdDocumentId = await createOrGetWeeklyDocumentId({
        kind: type,
        personId,
        projectId: documentId || undefined,
        weekNumber,
      });
      if (createdDocumentId) {
        navigate(`/documents/${createdDocumentId}`);
      } else {
        console.error(`Failed to create weekly ${type}: request returned no document id`);
      }
    } catch (err) {
      console.error(`Failed to create weekly ${type}:`, err);
    } finally {
      setNavigatingCell(null);
    }
  }

  // Fetch data on mount
  useEffect(() => {
    async function fetchData() {
      try {
        setLoading(true);
        const res = await fetch(
          `${API_URL}/api/weekly-plans/project-allocation-grid/${documentId}`,
          { credentials: 'include' }
        );

        if (!res.ok) {
          throw new Error('Failed to load allocation data');
        }

        const gridData: AllocationGridData = await res.json();
        setData(gridData);
      } catch {
        setError('Failed to load allocation data');
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, [documentId]);

  // Filter to only show weeks where at least one person is allocated
  const visibleWeeks = useMemo(() => {
    if (!data) return [];
    return data.weeks;
  }, [data]);

  // Scroll to current week on initial load
  useEffect(() => {
    if (data && scrollContainerRef.current && !hasScrolledToCurrentRef.current && data.people.length > 0) {
      const currentWeekIndex = visibleWeeks.findIndex((w) => w.isCurrent);
      if (currentWeekIndex >= 0) {
        requestAnimationFrame(() => {
          if (scrollContainerRef.current) {
            const columnWidth = 140;
            const scrollPosition = currentWeekIndex * columnWidth;
            scrollContainerRef.current.scrollLeft = scrollPosition;
            hasScrolledToCurrentRef.current = true;
          }
        });
      }
    }
  }, [data, visibleWeeks]);

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="flex items-center gap-2 text-muted">
          <svg className="w-5 h-5 animate-spin" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
          </svg>
          Loading...
        </div>
      </div>
    );
  }

  if (error && !data) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-red-500">{error}</div>
      </div>
    );
  }

  // Empty state when no allocations
  if (!data || data.people.length === 0) {
    return (
      <div className="flex h-full flex-col items-center justify-center text-muted p-8">
        <svg className="w-16 h-16 mb-4 opacity-50" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">
          <path strokeLinecap="round" strokeLinejoin="round" d="M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z" />
        </svg>
        <p className="text-lg font-medium mb-2">No team allocations</p>
        <p className="text-sm text-center max-w-md">
          Assign team members to this project in Team → Allocation to see them here.
        </p>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      {/* Legend */}
      <div className="flex items-center gap-4 px-4 py-2 border-b border-border text-xs">
        <span className="text-muted">Status:</span>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.done }} />
          <span>Done</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.due }} />
          <span>Due</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.late }} />
          <span>Late</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: STATUS_COLORS.future }} />
          <span>Future</span>
        </div>
        <span className="text-muted ml-4">|</span>
        <span className="text-muted">Left = Plan, Right = Retro</span>
      </div>

      {/* Grid container */}
      <div ref={scrollContainerRef} className="flex-1 overflow-auto pb-20">
        <div className="inline-flex min-w-full">
          {/* Sticky left column - Team members */}
          <div className="flex flex-col sticky left-0 z-20 bg-background border-r border-border">
            {/* Header cell */}
            <div className="flex h-10 w-[180px] items-center border-b border-border px-3 sticky top-0 z-30 bg-background">
              <span className="text-xs font-medium text-muted">Team Member</span>
            </div>

            {/* Users */}
            {data.people.map((person) => (
              <div
                key={person.id}
                className="flex h-12 w-[180px] items-center border-b border-border px-3 bg-background"
              >
                <div className="flex items-center gap-2 overflow-hidden">
                  <div className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full text-xs font-medium text-white bg-accent/80">
                    {person.name.charAt(0).toUpperCase()}
                  </div>
                  <span className="truncate text-sm text-foreground">
                    {person.name}
                  </span>
                </div>
              </div>
            ))}
          </div>

          {/* Week columns */}
          <div className="flex">
            {visibleWeeks.map((week) => (
              <div key={week.number} className="flex flex-col">
                {/* Week header */}
                <div
                  className={cn(
                    'flex h-10 w-[140px] flex-col items-center justify-center border-b border-r border-border px-2 sticky top-0 z-10 bg-background',
                    week.isCurrent && 'ring-1 ring-inset ring-accent/30'
                  )}
                >
                  <span className={cn('text-xs font-medium', week.isCurrent ? 'text-accent' : 'text-foreground')}>
                    {week.name}
                  </span>
                  <span className="text-[10px] text-muted">
                    {formatDateRange(week.startDate, week.endDate)}
                  </span>
                </div>

                {/* User cells for this week */}
                {data.people.map((person) => {
                  const weekData = person.weeks[week.number];

                  // If not allocated to this project this week, show empty cell
                  if (!weekData?.isAllocated) {
                    return (
                      <div
                        key={person.id}
                        className={cn(
                          'flex h-12 w-[140px] items-center justify-center border-b border-r border-border',
                          week.isCurrent && 'bg-accent/5'
                        )}
                      >
                        <span className="text-xs text-muted">-</span>
                      </div>
                    );
                  }

                  return (
                    <div
                      key={person.id}
                      className={cn(
                        'flex h-12 w-[140px] border-b border-r border-border overflow-hidden',
                        week.isCurrent && 'bg-accent/5'
                      )}
                    >
                      <StatusCell
                        planStatus={weekData.planStatus}
                        retroStatus={weekData.retroStatus}
                        onPlanClick={() =>
                          handleNavigate(person.id, week.number, 'plan', weekData.planId)
                        }
                        onRetroClick={() =>
                          handleNavigate(person.id, week.number, 'retro', weekData.retroId)
                        }
                        isNavigating={
                          navigatingCell?.personId === person.id &&
                          navigatingCell?.weekNumber === week.number
                            ? navigatingCell.type
                            : null
                        }
                      />
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { UnifiedEditor } from '@/components/UnifiedEditor';
import type { UnifiedDocument, SidebarData } from '@/components/UnifiedEditor';
import { useAuth } from '@/hooks/useAuth';
import { useAssignableMembersQuery } from '@/hooks/useTeamMembersQuery';
import { useActiveWeeksQuery } from '@/hooks/useWeeksQuery';
import { apiPatch, apiDelete } from '@/lib/api';
import type { DocumentTabProps } from '@/lib/document-tabs';
import { getSprintView } from '@/lib/document-view-mapper';

/**
 * SprintOverviewTab - Renders the sprint document in the UnifiedEditor
 *
 * This is the "Overview" tab content when viewing a sprint document.
 * Shows the sprint plan and description.
 */
export default function SprintOverviewTab({ documentId, document }: DocumentTabProps) {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { user } = useAuth();

  // Fetch team members for owner selection
  const { data: teamMembersData = [] } = useAssignableMembersQuery();
  const people = useMemo(() => teamMembersData.map(m => ({
    id: m.id,
    user_id: m.user_id,
    name: m.name,
  })), [teamMembersData]);

  // Fetch active sprints for availability calculation
  const { data: activeSprintsData } = useActiveWeeksQuery();
  const existingSprints = useMemo(() =>
    (activeSprintsData?.weeks ?? []).map(s => ({ owner: s.owner })),
    [activeSprintsData]
  );

  // Update mutation with optimistic updates
  const updateMutation = useMutation({
    mutationFn: async (updates: Partial<UnifiedDocument>) => {
      const response = await apiPatch(`/api/documents/${documentId}`, updates);
      if (!response.ok) {
        throw new Error('Failed to update document');
      }
      return response.json();
    },
    onMutate: async (updates) => {
      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: ['document', documentId] });
      await queryClient.cancelQueries({ queryKey: ['sprints'] });

      // Snapshot the previous value
      const previousDocument = queryClient.getQueryData<Record<string, unknown>>(['document', documentId]);

      // Optimistically update the document cache
      if (previousDocument) {
        const sprintUpdates = updates as Record<string, unknown>;
        queryClient.setQueryData(['document', documentId], { ...previousDocument, ...sprintUpdates });
      }

      // Return context with the previous value for rollback
      return { previousDocument };
    },
    onError: (_err, _updates, context) => {
      // Rollback to the previous value on error
      if (context?.previousDocument) {
        queryClient.setQueryData(['document', documentId], context.previousDocument);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['document', documentId] });
      queryClient.invalidateQueries({ queryKey: ['sprints'] });
    },
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async () => {
      const response = await apiDelete(`/api/documents/${documentId}`);
      if (!response.ok) {
        throw new Error('Failed to delete document');
      }
    },
    onSuccess: () => {
      navigate('/team/allocation');
    },
  });

  // Handle back navigation
  const handleBack = useCallback(() => {
    navigate('/team/allocation');
  }, [navigate]);

  // Handle update
  const handleUpdate = useCallback(async (updates: Partial<UnifiedDocument>) => {
    await updateMutation.mutateAsync(updates);
  }, [updateMutation]);

  // Handle delete
  const handleDelete = useCallback(async () => {
    if (!window.confirm('Are you sure you want to delete this week?')) return;
    await deleteMutation.mutateAsync();
  }, [deleteMutation]);

  // Build sidebar data with people and existing sprints for owner selection
  const sidebarData: SidebarData = useMemo(() => ({
    people,
    existingSprints,
  }), [people, existingSprints]);

  // Transform to UnifiedDocument format
  const unifiedDocument: UnifiedDocument = useMemo(() => getSprintView(document), [document]);

  if (!user) return null;

  return (
    <UnifiedEditor
      document={unifiedDocument}
      sidebarData={sidebarData}
      onUpdate={handleUpdate}
      onBack={handleBack}
      backLabel="weeks"
      onDelete={handleDelete}
      showTypeSelector={false}
    />
  );
}

import { Extension } from '@tiptap/core';
import type { Node as ProseMirrorNode } from '@tiptap/pm/model';
import { Plugin, PluginKey } from '@tiptap/pm/state';
import { Decoration, DecorationSet } from '@tiptap/pm/view';

/**
 * AIScoringDisplay — Renders inline AI quality feedback as widget decorations
 * after each plan/retro list item, following the CommentDisplay pattern.
 *
 * Reads analysis data from extension storage (set by the parent component
 * when AI analysis completes). Matches analysis items to document list items
 * by text similarity, then renders score indicators and feedback inline.
 */

interface PlanItemAnalysis {
  text: string;
  score: number;
  feedback: string;
  issues: string[];
  conciseness_score?: number;
  is_verbose?: boolean;
  conciseness_feedback?: string;
}

interface PlanAnalysisData {
  overall_score: number;
  items: PlanItemAnalysis[];
  workload_assessment: string;
  workload_feedback: string;
}

interface RetroItemAnalysis {
  plan_item: string;
  addressed: boolean;
  has_evidence: boolean;
  feedback: string;
}

interface RetroAnalysisData {
  overall_score: number;
  plan_coverage: RetroItemAnalysis[];
  suggestions: string[];
}

export interface AIScoringStorage {
  planAnalysis: PlanAnalysisData | null;
  retroAnalysis: RetroAnalysisData | null;
}

export const aiScoringPluginKey = new PluginKey('aiScoringDisplay');

function escapeHtml(str: string): string {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

/** Extract plain text from a ProseMirror node */
function extractNodeText(node: ProseMirrorNode): string {
  let text = '';
  node.descendants((child: ProseMirrorNode) => {
    if (child.isText) text += child.text;
  });
  return text.trim();
}

/** Normalize text for matching */
function normalizeText(text: string): string {
  return text.toLowerCase().trim().replace(/\s+/g, ' ');
}

/**
 * Find list items in the document and return their positions and text.
 * Returns array of { pos: end position of list item block, text: extracted text }
 */
function findListItems(doc: ProseMirrorNode): Array<{ endPos: number; text: string }> {
  const items: Array<{ endPos: number; text: string }> = [];

  doc.descendants((node: ProseMirrorNode, pos: number) => {
    if (node.type.name === 'listItem' || node.type.name === 'taskItem') {
      const text = extractNodeText(node);
      if (text) {
        const endPos = pos + node.nodeSize;
        items.push({ endPos, text });
      }
      return false;
    }
  });

  return items;
}

/**
 * Find planReference nodes in the document (for retro documents).
 * Returns array of { endPos, text } using the planItemText attribute.
 */
function findPlanReferenceNodes(doc: ProseMirrorNode): Array<{ endPos: number; text: string }> {
  const items: Array<{ endPos: number; text: string }> = [];

  doc.descendants((node: ProseMirrorNode, pos: number) => {
    if (node.type.name === 'planReference') {
      const text = node.attrs.planItemText || '';
      if (text) {
        const endPos = pos + node.nodeSize;
        items.push({ endPos, text });
      }
      return false;
    }
  });

  return items;
}

/**
 * Match analysis items to document list items by text similarity.
 * Returns a map of listItemIndex -> analysisItemIndex.
 */
function matchAnalysisToListItems(
  listItems: Array<{ endPos: number; text: string }>,
  analysisItems: Array<{ text: string }>
): Map<number, number> {
  const matches = new Map<number, number>();
  const usedAnalysis = new Set<number>();

  // First pass: exact normalized matches
  for (let li = 0; li < listItems.length; li++) {
    const listItem = listItems[li];
    if (!listItem) continue;
    const normalizedLi = normalizeText(listItem.text);
    for (let ai = 0; ai < analysisItems.length; ai++) {
      if (usedAnalysis.has(ai)) continue;
      const analysisItem = analysisItems[ai];
      if (!analysisItem) continue;
      const normalizedAi = normalizeText(analysisItem.text);
      if (normalizedLi === normalizedAi) {
        matches.set(li, ai);
        usedAnalysis.add(ai);
        break;
      }
    }
  }

  // Second pass: prefix/substring matching for unmatched items
  for (let li = 0; li < listItems.length; li++) {
    if (matches.has(li)) continue;
    const listItem = listItems[li];
    if (!listItem) continue;
    const normalizedLi = normalizeText(listItem.text);

    for (let ai = 0; ai < analysisItems.length; ai++) {
      if (usedAnalysis.has(ai)) continue;
      const analysisItem = analysisItems[ai];
      if (!analysisItem) continue;
      const normalizedAi = normalizeText(analysisItem.text);

      if (normalizedLi.startsWith(normalizedAi) || normalizedAi.startsWith(normalizedLi)) {
        matches.set(li, ai);
        usedAnalysis.add(ai);
        break;
      }
    }
  }

  // Third pass: positional fallback for remaining items
  for (let li = 0; li < listItems.length; li++) {
    if (matches.has(li)) continue;
    if (li < analysisItems.length && !usedAnalysis.has(li)) {
      matches.set(li, li);
      usedAnalysis.add(li);
    }
  }

  return matches;
}

/** Create DOM element for plan item feedback widget */
function createPlanFeedbackWidget(item: PlanItemAnalysis): HTMLElement {
  const container = document.createElement('div');
  container.className = 'ai-scoring-inline';
  container.contentEditable = 'false';

  const scorePercent = Math.round(item.score * 10);
  const colorClass = item.score >= 0.7 ? 'green' : item.score >= 0.4 ? 'yellow' : 'red';

  let conciseness = '';
  if (item.is_verbose && item.conciseness_feedback) {
    conciseness = `<span class="ai-scoring-conciseness">${escapeHtml(item.conciseness_feedback)}</span>`;
  }

  container.innerHTML = `
    <div class="ai-scoring-feedback ai-scoring-${colorClass}">
      <span class="ai-scoring-badge">${scorePercent}</span>
      <span class="ai-scoring-text">${escapeHtml(item.feedback)}</span>
      ${conciseness}
    </div>
  `;

  return container;
}

/** Create DOM element for retro item coverage widget */
function createRetroCoverageWidget(item: RetroItemAnalysis): HTMLElement {
  const container = document.createElement('div');
  container.className = 'ai-scoring-inline';
  container.contentEditable = 'false';

  const statusClass = item.addressed && item.has_evidence ? 'green'
    : item.addressed ? 'yellow'
    : 'red';

  const statusIcon = item.addressed && item.has_evidence ? '&#10003;'
    : item.addressed ? '&#9888;'
    : '&#10007;';

  container.innerHTML = `
    <div class="ai-scoring-feedback ai-scoring-${statusClass}">
      <span class="ai-scoring-status-icon">${statusIcon}</span>
      <span class="ai-scoring-text">${escapeHtml(item.feedback)}</span>
    </div>
  `;

  return container;
}

export const AIScoringDisplayExtension = Extension.create<Record<string, never>, AIScoringStorage>({
  name: 'aiScoringDisplay',

  addStorage() {
    return {
      planAnalysis: null,
      retroAnalysis: null,
    };
  },

  addProseMirrorPlugins() {
    const storage = this.storage;

    return [
      new Plugin({
        key: aiScoringPluginKey,
        props: {
          decorations: (state) => {
            const { doc } = state;
            const decorations: Decoration[] = [];

            const { planAnalysis, retroAnalysis } = storage;

            if (planAnalysis && planAnalysis.items.length > 0) {
              const listItems = findListItems(doc);
              const matches = matchAnalysisToListItems(listItems, planAnalysis.items);

              for (const [listIdx, analysisIdx] of matches) {
                const listItem = listItems[listIdx];
                const analysisItem = planAnalysis.items[analysisIdx];
                if (!listItem || !analysisItem) continue;

                const widget = Decoration.widget(listItem.endPos, () => {
                  return createPlanFeedbackWidget(analysisItem);
                }, {
                  side: 1,
                  key: `ai-plan-${listIdx}-${analysisItem.score}`,
                });

                decorations.push(widget);
              }
            }

            if (retroAnalysis && retroAnalysis.plan_coverage.length > 0) {
              // For retros, prefer planReference nodes (auto-populated retros),
              // fall back to regular list items (free-form retros)
              const planRefNodes = findPlanReferenceNodes(doc);
              const listItems = planRefNodes.length > 0 ? planRefNodes : findListItems(doc);
              const coverageItems = retroAnalysis.plan_coverage.map(c => ({ text: c.plan_item }));
              const matches = matchAnalysisToListItems(listItems, coverageItems);

              for (const [listIdx, coverageIdx] of matches) {
                const listItem = listItems[listIdx];
                const coverageItem = retroAnalysis.plan_coverage[coverageIdx];
                if (!listItem || !coverageItem) continue;

                const widget = Decoration.widget(listItem.endPos, () => {
                  return createRetroCoverageWidget(coverageItem);
                }, {
                  side: 1,
                  key: `ai-retro-${listIdx}-${coverageItem.addressed}`,
                });

                decorations.push(widget);
              }
            }

            return DecorationSet.create(doc, decorations);
          },
        },
      }),
    ];
  },
});

import { Extension } from '@tiptap/core';
import type { Node as ProseMirrorNode } from '@tiptap/pm/model';
import { Plugin, PluginKey } from '@tiptap/pm/state';
import { Decoration, DecorationSet } from '@tiptap/pm/view';
import { Comment } from '@/hooks/useCommentsQuery';
import { formatRelativeTime } from '@/lib/date-utils';

/**
 * Groups comments by their comment_id (thread identifier).
 * Returns a map of commentId -> array of comments (root + replies).
 */
function groupByThread(comments: Comment[]): Map<string, Comment[]> {
  const threads = new Map<string, Comment[]>();
  for (const comment of comments) {
    const existing = threads.get(comment.comment_id) || [];
    existing.push(comment);
    threads.set(comment.comment_id, existing);
  }
  return threads;
}

/**
 * Find all comment mark positions in the document.
 * Returns a map of commentId -> end position of the containing block.
 */
function findCommentPositions(doc: ProseMirrorNode): Map<string, number> {
  const positions = new Map<string, number>();

  doc.descendants((node: ProseMirrorNode, pos: number) => {
    if (node.isText) {
      for (const mark of node.marks) {
        if (mark.type.name === 'commentMark' && mark.attrs.commentId) {
          const commentId = mark.attrs.commentId;
          // Always overwrite — doc.descendants iterates in document order,
          // so the last block containing the mark wins.
          const $pos = doc.resolve(pos);
          const blockEnd = $pos.end(Math.max(1, $pos.depth));
          positions.set(commentId, blockEnd);
        }
      }
    }
  });

  return positions;
}

export const commentDisplayPluginKey = new PluginKey('commentDisplay');

export interface CommentDisplayStorage {
  comments: Comment[];
  onReply: ((commentId: string, content: string) => void) | null;
  onResolve: ((commentId: string, resolved: boolean) => void) | null;
  pendingCommentId: string | null;
  onSubmitComment: ((commentId: string, content: string) => void) | null;
  onCancelComment: ((commentId: string) => void) | null;
}

/**
 * InlineCommentThread component rendered inside widget decorations.
 * Displays a GitHub-style comment card that breaks the document flow.
 */
function InlineCommentThread({
  thread,
  quotedText,
  onReply: _onReply,
  onResolve: _onResolve,
}: {
  thread: Comment[];
  quotedText: string;
  onReply: ((commentId: string, content: string) => void) | null;
  onResolve: ((commentId: string, resolved: boolean) => void) | null;
}) {
  const root = thread[0];
  const replies = thread.slice(1);
  const resolvedAt = root.resolved_at;
  const isResolved = resolvedAt !== null;

  const container = document.createElement('div');

  // Create a simple DOM structure (no React inside decorations for simplicity)
  container.className = 'comment-thread-inline';
  container.setAttribute('data-comment-thread', root.comment_id);
  container.contentEditable = 'false';

  if (isResolved) {
    container.innerHTML = `
      <div class="comment-thread-resolved" data-comment-id="${escapeHtml(root.comment_id)}">
        <span class="comment-resolved-icon">✓</span>
        <span class="comment-resolved-text">Resolved by ${escapeHtml(root.author.name)} · ${formatRelativeTime(resolvedAt)}</span>
        <span class="comment-resolved-toggle">Show thread</span>
      </div>
    `;
  } else {
    const quotedHtml = quotedText
      ? `<div class="comment-quoted-text">"${escapeHtml(quotedText)}"</div>`
      : '';

    let repliesHtml = '';
    for (const reply of replies) {
      repliesHtml += `
        <div class="comment-reply">
          <div class="comment-header">
            <span class="comment-author">${escapeHtml(reply.author.name)}</span>
            <span class="comment-time">${formatRelativeTime(reply.created_at)}</span>
          </div>
          <div class="comment-body">${escapeHtml(reply.content)}</div>
        </div>
      `;
    }

    container.innerHTML = `
      ${quotedHtml}
      <div class="comment-root">
        <div class="comment-header">
          <span class="comment-author">${escapeHtml(root.author.name)}</span>
          <span class="comment-time">${formatRelativeTime(root.created_at)}</span>
          <button class="comment-resolve-btn" data-comment-id="${escapeHtml(root.comment_id)}" title="Resolve">✓</button>
        </div>
        <div class="comment-body">${escapeHtml(root.content)}</div>
      </div>
      ${repliesHtml}
      <div class="comment-reply-area">
        <input type="text" class="comment-reply-input" placeholder="Reply..." data-comment-id="${escapeHtml(root.comment_id)}" />
      </div>
    `;
  }

  return container;
}

function escapeHtml(str: string): string {
  const div = document.createElement('div');
  div.textContent = str;
  return div.innerHTML;
}

/**
 * CommentDisplay extension - Renders inline comment threads as widget decorations.
 *
 * Comments appear as bordered cards between content blocks, pushing content down
 * (like GitHub code review). The extension reads comment data from its storage,
 * which is updated by the parent Editor component via React Query.
 */
export const CommentDisplayExtension = Extension.create<Record<string, never>, CommentDisplayStorage>({
  name: 'commentDisplay',

  addStorage() {
    return {
      comments: [],
      onReply: null,
      onResolve: null,
      pendingCommentId: null,
      onSubmitComment: null,
      onCancelComment: null,
    };
  },

  addProseMirrorPlugins() {
    const storage = this.storage;

    return [
      new Plugin({
        key: commentDisplayPluginKey,
        props: {
          decorations: (state) => {
            const { doc } = state;
            const comments = storage.comments;
            const positions = findCommentPositions(doc);
            const decorations: Decoration[] = [];

            // Add pending comment input widget (before saved comments so it renders inline)
            const pendingId = storage.pendingCommentId;
            if (pendingId) {
              const pendingPos = positions.get(pendingId);
              if (pendingPos !== undefined) {
                const pendingWidget = Decoration.widget(pendingPos, () => {
                  const container = document.createElement('div');
                  container.className = 'comment-thread-inline comment-pending-input';
                  container.contentEditable = 'false';
                  container.innerHTML = `
                    <div class="comment-pending-label">Add your comment:</div>
                    <input type="text" class="comment-pending-field" placeholder="Write a comment..." data-pending-comment-id="${escapeHtml(pendingId)}" />
                    <div class="comment-pending-hint">Press Enter to submit, Escape to cancel</div>
                  `;
                  // Auto-focus the input after it's added to the DOM
                  requestAnimationFrame(() => {
                    const input = container.querySelector('.comment-pending-field') as HTMLInputElement;
                    input?.focus();
                  });
                  return container;
                }, {
                  side: 1,
                  key: `pending-comment-${pendingId}`,
                });
                decorations.push(pendingWidget);
              }
            }

            if (!comments || comments.length === 0) {
              return DecorationSet.create(doc, decorations);
            }

            const threads = groupByThread(comments);

            // Sort positions by document order (ascending)
            const sortedEntries = [...positions.entries()].sort(
              (a, b) => a[1] - b[1]
            );

            // Add inline decorations to dim resolved comment highlights
            for (const [commentId, thread] of threads.entries()) {
              const isResolved = thread[0].resolved_at !== null;
              if (isResolved) {
                doc.descendants((node: ProseMirrorNode, pos: number) => {
                  if (node.isText) {
                    for (const mark of node.marks) {
                      if (mark.type.name === 'commentMark' && mark.attrs.commentId === commentId) {
                        decorations.push(
                          Decoration.inline(pos, pos + node.nodeSize, {
                            class: 'comment-highlight-resolved',
                          })
                        );
                      }
                    }
                  }
                });
              }
            }

            for (const [commentId, blockEndPos] of sortedEntries) {
              const thread = threads.get(commentId);
              if (!thread || thread.length === 0) continue;

              // Find the quoted text for this comment
              let quotedText = '';
              doc.descendants((node: ProseMirrorNode) => {
                if (node.isText) {
                  for (const mark of node.marks) {
                    if (
                      mark.type.name === 'commentMark' &&
                      mark.attrs.commentId === commentId
                    ) {
                      quotedText += node.text;
                    }
                  }
                }
              });

              const widget = Decoration.widget(blockEndPos, () => {
                return InlineCommentThread({
                  thread,
                  quotedText,
                  onReply: storage.onReply,
                  onResolve: storage.onResolve,
                });
              }, {
                side: 1, // Render after the position
                key: `comment-${commentId}-${thread.length}-${thread[0].resolved_at || 'open'}`,
              });

              decorations.push(widget);
            }

            return DecorationSet.create(doc, decorations);
          },

          handleDOMEvents: {
            click: (view, event) => {
              const target = event.target as HTMLElement;

              // Handle resolve button click
              const resolveBtn = target.closest('.comment-resolve-btn') as HTMLElement;
              if (resolveBtn) {
                const commentId = resolveBtn.dataset.commentId;
                if (commentId && storage.onResolve) {
                  storage.onResolve(commentId, true);
                }
                event.preventDefault();
                return true;
              }

              // Handle "Show thread" click on resolved comments
              const resolvedToggle = target.closest('.comment-resolved-toggle') as HTMLElement;
              if (resolvedToggle) {
                const threadEl = resolvedToggle.closest('.comment-thread-inline') as HTMLElement;
                if (threadEl) {
                  const commentId = threadEl.dataset.commentThread;
                  if (commentId && storage.onResolve) {
                    storage.onResolve(commentId, false);
                  }
                }
                event.preventDefault();
                return true;
              }

              return false;
            },

            keydown: (view, event) => {
              const target = event.target as HTMLElement;

              // Cancel pending comment on Escape even if focus did not land in the widget input yet
              if (
                event.key === 'Escape' &&
                storage.pendingCommentId &&
                storage.onCancelComment
              ) {
                storage.onCancelComment(storage.pendingCommentId);
                event.preventDefault();
                return true;
              }

              // Handle Enter/Escape on pending comment input
              if (target.classList.contains('comment-pending-field')) {
                const input = target as HTMLInputElement;
                const commentId = input.dataset.pendingCommentId;

                if (event.key === 'Enter' && !event.shiftKey) {
                  const content = input.value.trim();
                  if (commentId && content && storage.onSubmitComment) {
                    storage.onSubmitComment(commentId, content);
                  }
                  event.preventDefault();
                  return true;
                }

                if (event.key === 'Escape') {
                  if (commentId && storage.onCancelComment) {
                    storage.onCancelComment(commentId);
                  }
                  event.preventDefault();
                  return true;
                }

                // Prevent other keys from propagating to ProseMirror
                event.stopPropagation();
                return true;
              }

              // Handle Enter on reply input
              if (
                target.classList.contains('comment-reply-input') &&
                event.key === 'Enter' &&
                !event.shiftKey
              ) {
                const input = target as HTMLInputElement;
                const commentId = input.dataset.commentId;
                const content = input.value.trim();

                if (commentId && content && storage.onReply) {
                  storage.onReply(commentId, content);
                  input.value = '';
                }
                event.preventDefault();
                return true;
              }

              return false;
            },
          },
        },
      }),
    ];
  },
});

import { Mark, mergeAttributes } from '@tiptap/core';

export interface CommentMarkOptions {
  HTMLAttributes: Record<string, unknown>;
  onAddComment?: (commentId: string) => void;
}

export interface CommentMarkStorage {
  activeCommentId: string | null;
}

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    commentMark: {
      setComment: (commentId: string) => ReturnType;
      unsetComment: (commentId: string) => ReturnType;
      addComment: () => ReturnType;
    };
  }
}

export const CommentMark = Mark.create<CommentMarkOptions, CommentMarkStorage>({
  name: 'commentMark',

  addOptions() {
    return {
      HTMLAttributes: {},
      onAddComment: undefined,
    };
  },

  addStorage() {
    return {
      activeCommentId: null,
    };
  },

  addAttributes() {
    return {
      commentId: {
        default: null,
        parseHTML: (element: HTMLElement) => element.getAttribute('data-comment-id'),
        renderHTML: (attributes: Record<string, unknown>) => {
          if (!attributes.commentId) return {};
          return { 'data-comment-id': attributes.commentId };
        },
      },
    };
  },

  // Don't extend the mark when typing at boundaries
  inclusive: false,

  // Allow overlapping comments on the same text
  excludes: '',

  parseHTML() {
    return [
      {
        tag: 'span[data-comment-id]',
      },
    ];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      'span',
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        class: 'comment-highlight',
      }),
      0,
    ];
  },

  addCommands() {
    return {
      setComment:
        (commentId: string) =>
        ({ commands }) => {
          return commands.setMark(this.name, { commentId });
        },
      unsetComment:
        (commentId: string) =>
        ({ tr, state, dispatch }) => {
          const { doc } = state;
          let modified = false;

          doc.descendants((node, pos) => {
            if (!node.isText) return;

            node.marks.forEach((mark) => {
              if (mark.type.name === this.name && mark.attrs.commentId === commentId) {
                const textLength = node.text?.length ?? 0;
                if (textLength === 0) return;
                // Text leaf nodeSize is 1 in the tree; use text length for doc positions.
                tr.removeMark(pos, pos + textLength, mark);
                modified = true;
              }
            });
          });

          if (modified && dispatch) {
            dispatch(tr);
          }

          return modified;
        },
      addComment:
        () =>
        ({ editor, commands }) => {
          if (editor.state.selection.empty) return false;
          const commentId = crypto.randomUUID();
          commands.setMark(this.name, { commentId });
          this.options.onAddComment?.(commentId);
          return true;
        },
    };
  },

  addKeyboardShortcuts() {
    return {
      'Mod-Shift-m': () => this.editor.commands.addComment(),
    };
  },

  onSelectionUpdate() {
    const { $from } = this.editor.state.selection;
    const marks = $from.marks();
    const commentMark = marks.find((mark) => mark.type.name === this.name);
    this.storage.activeCommentId = commentMark?.attrs.commentId ?? null;
  },
});

import { NodeViewWrapper, NodeViewContent, NodeViewProps } from '@tiptap/react';
