export function createSlashCommands({ onCreateSubDocument, onNavigateToDocument, documentType, documentId, abortSignal }: CreateSlashCommandsOptions) {
  const slashCommands: SlashCommandItem[] = [
    // Sub-document (requires async callback)
    {
      title: 'Sub-document',
      description: 'Create a nested document',
      aliases: ['doc', 'document', 'sub-document', 'page', 'sub-page', 'subpage', 'subdoc'],
      icon: icons.document,
      requiresSubDocumentCallback: true,
      command: async ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).run();
        const doc = await onCreateSubDocument?.();
        if (doc) {
          // Navigate to the new document immediately
          onNavigateToDocument?.(doc.id);
        }
      },
    },
    // Headings
    {
      title: 'Heading 1',
      description: 'Large section heading',
      aliases: ['h1', 'heading1', 'title'],
      icon: icons.heading1,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).setNode('heading', { level: 1 }).run();
      },
    },
    {
      title: 'Heading 2',
      description: 'Medium section heading',
      aliases: ['h2', 'heading2', 'subtitle'],
      icon: icons.heading2,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).setNode('heading', { level: 2 }).run();
      },
    },
    {
      title: 'Heading 3',
      description: 'Small section heading',
      aliases: ['h3', 'heading3'],
      icon: icons.heading3,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).setNode('heading', { level: 3 }).run();
      },
    },
    // Lists
    {
      title: 'Bullet List',
      description: 'Create a simple bullet list',
      aliases: ['ul', 'unordered', 'bullet', 'list', 'bullets'],
      icon: icons.bulletList,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).toggleBulletList().run();
      },
    },
    {
      title: 'Numbered List',
      description: 'Create a numbered list',
      aliases: ['ol', 'ordered', 'number', 'numbered'],
      icon: icons.numberedList,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).toggleOrderedList().run();
      },
    },
    {
      title: 'Task List',
      description: 'Create a checklist with checkboxes',
      aliases: ['task', 'tasks', 'todo', 'todos', 'checkbox', 'checklist', 'check'],
      icon: icons.taskList,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).toggleTaskList().run();
      },
    },
    // Blocks
    {
      title: 'Quote',
      description: 'Capture a quote',
      aliases: ['blockquote', 'quotation', 'cite'],
      icon: icons.quote,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).toggleBlockquote().run();
      },
    },
    {
      title: 'Code Block',
      description: 'Capture a code snippet',
      aliases: ['code', 'codeblock', 'pre', 'snippet'],
      icon: icons.code,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).toggleCodeBlock().run();
      },
    },
    {
      title: 'Divider',
      description: 'Visually divide content',
      aliases: ['hr', 'horizontal', 'rule', 'separator', 'line'],
      icon: icons.divider,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).setHorizontalRule().run();
      },
    },
    // Image upload
    {
      title: 'Image',
      description: 'Upload an image',
      aliases: ['img', 'picture', 'photo', 'upload'],
      icon: icons.image,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).run();
        // Trigger file picker
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.onchange = async () => {
          const file = input.files?.[0];
          if (!file) return;

          // Import and use upload service
          const { uploadFile } = await import('@/services/upload');

          // Create data URL for immediate preview
          const reader = new FileReader();
          reader.onload = async () => {
            // Check if aborted before processing
            if (abortSignal?.aborted) return;

            const dataUrl = reader.result as string;

            // Insert image with data URL preview
            editor.chain().focus().setImage({ src: dataUrl, alt: file.name }).run();

            try {
              // Upload and replace with CDN URL
              const result = await uploadFile(file, undefined, abortSignal, documentId);

              // Check if aborted before updating editor
              if (abortSignal?.aborted) {
                console.log('Slash command image upload completed but was cancelled - not updating editor');
                return;
              }

              // Find and update the image node
              const { state, view } = editor;
              let imagePos: number | null = null;

              state.doc.descendants((node: ProseMirrorNode, pos: number) => {
                if (node.type.name === 'image' && node.attrs.src === dataUrl) {
                  imagePos = pos;
                  return false;
                }
                return true;
              });

              if (imagePos !== null) {
                const cdnUrl = result.cdnUrl.startsWith('http')
                  ? result.cdnUrl
                  : `${API_URL}${result.cdnUrl}`;
                const transaction = state.tr.setNodeMarkup(imagePos, undefined, {
                  ...state.doc.nodeAt(imagePos)?.attrs,
                  src: cdnUrl,
                });
                view.dispatch(transaction);
              }
            } catch (error) {
              // Don't report cancellation as an error - it's intentional
              if (error instanceof DOMException && error.name === 'AbortError') {
                console.log('Slash command image upload cancelled');
                return;
              }
              console.error('Image upload failed:', error);
            }
          };
          reader.readAsDataURL(file);
        };
        input.click();
      },
    },
    // File attachment
    {
      title: 'File',
      description: 'Upload a file attachment',
      aliases: ['file', 'attachment', 'attach', 'pdf', 'doc', 'document'],
      icon: icons.file,
      command: async ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).run();
        // Import and trigger file upload
        const { triggerFileUpload } = await import('./FileAttachment');
        triggerFileUpload(editor, abortSignal, documentId);
      },
    },
    // Toggle/Details
    {
      title: 'Toggle',
      description: 'Create a collapsible section',
      aliases: ['toggle', 'collapsible', 'details', 'expand', 'collapse', 'accordion'],
      icon: icons.toggle,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).setDetails().run();
      },
    },
    // Table
    {
      title: 'Table',
      description: 'Insert a table',
      aliases: ['table', 'grid'],
      icon: icons.table,
      command: ({ editor, range }) => {
        editor.chain().focus().deleteRange(range).insertTable({ rows: 3, cols: 3, withHeaderRow: true }).run();
      },
    },
    // Table of Contents
    {
      title: 'Table of Contents',
      description: 'Insert a table of contents',
      aliases: ['toc', 'outline', 'contents'],
      icon: icons.tableOfContents,
      command: ({ editor, range }) => {
        editor
          .chain()
          .focus()
          .deleteRange(range)
          .insertContent({ type: 'tableOfContents' })
          .run();
      },
    },
    // Plan block (for Sprint and Project documents - syncs with properties.plan)
    {
      title: 'Plan',
      description: 'Add a plan block',
      aliases: ['plan', 'hypothesis', 'hypo', 'theory'],
      icon: icons.plan,
      documentTypes: ['sprint', 'project'],
      command: ({ editor, range }) => {
        editor
          .chain()
          .focus()
          .deleteRange(range)
          .insertContent({
            type: 'hypothesisBlock',
            attrs: { placeholder: 'What do you expect to accomplish?' },
          })
          .run();
      },
    },
    // Success Criteria section (for Project and Sprint documents)
    {
      title: 'Success Criteria',
      description: 'Add success criteria section',
      aliases: ['criteria', 'success', 'success-criteria', 'acceptance'],
      icon: icons.criteria,
      command: ({ editor, range }) => {
        editor
          .chain()
          .focus()
          .deleteRange(range)
          .insertContent([
            {
              type: 'heading',
              attrs: { level: 2 },
              content: [{ type: 'text', text: 'Success Criteria' }],
            },
            {
              type: 'paragraph',
            },
          ])
          .run();
        // Move cursor to the empty paragraph
        editor.commands.focus('end');
      },
    },
    // Vision section (Program documents only)
    {
      title: 'Vision',
      description: 'Add a vision statement section',
      aliases: ['vision', 'direction', 'strategy'],
      icon: icons.vision,
      documentTypes: ['program'],
      command: ({ editor, range }) => {
        editor
          .chain()
          .focus()
          .deleteRange(range)
          .insertContent([
            {
              type: 'heading',
              attrs: { level: 2 },
              content: [{ type: 'text', text: 'Vision' }],
            },
            {
              type: 'paragraph',
            },
          ])
          .run();
        // Move cursor to the empty paragraph
        editor.commands.focus('end');
      },
    },
    // Goals section (Program documents only)
    {
      title: 'Goals',
      description: 'Add program goals section',
      aliases: ['goals', 'objectives', 'targets'],
      icon: icons.goals,
      documentTypes: ['program'],
      command: ({ editor, range }) => {
        editor
          .chain()
          .focus()
          .deleteRange(range)
          .insertContent([
            {
              type: 'heading',
              attrs: { level: 2 },
              content: [{ type: 'text', text: 'Goals' }],
            },
            {
              type: 'paragraph',
            },
          ])
          .run();
        // Move cursor to the empty paragraph
        editor.commands.focus('end');
      },
    },
  ];

  return Extension.create({
    name: 'slashCommands',

    addOptions() {
      return {
        suggestion: {
          char: '/',
          command: ({ editor, range, props }: { editor: Editor; range: Range; props: SlashCommandItem }) => {
            props.command({ editor, range });
          },
        } as Partial<SuggestionOptions>,
      };
    },

    addProseMirrorPlugins() {
      return [
        Suggestion({
          editor: this.editor,
          ...this.options.suggestion,
          items: async ({ query }: { query: string }): Promise<SlashCommandItem[]> => {
            const search = query.toLowerCase();
            const filteredCommands = slashCommands.filter(
              (item) => {
                // Filter out commands that require callback when callback is not provided
                if (item.requiresSubDocumentCallback && !onCreateSubDocument) {
                  return false;
                }
                // Filter by document type if command has restrictions
                if (item.documentTypes && item.documentTypes.length > 0) {
                  if (!documentType || !item.documentTypes.includes(documentType)) {
                    return false;
                  }
                }
                // Filter by search query
                return item.title.toLowerCase().includes(search) ||
                  item.aliases.some((alias) => alias.toLowerCase().includes(search));
              }
            );

            // If query matches document-related terms, also fetch existing documents
            const docAliases = ['doc', 'document', 'embed', 'link'];
            const isDocQuery = docAliases.some((alias) => alias.includes(search) || search.includes(alias));

            if (isDocQuery && search.length > 0) {
              const documents = await fetchWikiDocumentsForEmbed(search);
              const documentItems: SlashCommandItem[] = documents.map((doc) => ({
                title: doc.title,
                description: 'Embed this document',
                aliases: [],
                icon: icons.document,
                command: ({ editor, range }) => {
                  editor
                    .chain()
                    .focus()
                    .deleteRange(range)
                    .insertContent({
                      type: 'documentEmbed',
                      attrs: {
                        documentId: doc.id,
                        title: doc.title,
                      },
                    })
                    .run();
                },
              }));

              // Return static commands first, then document suggestions
              return [...filteredCommands, ...documentItems];
            }

            return filteredCommands;
          },
          render: () => {
            let component: ReactRenderer<CommandListRef> | null = null;
            let popup: TippyInstance[] | null = null;

            return {
              onStart: (props: SuggestionProps<SlashCommandItem, SlashCommandItem>) => {
                const clientRect = props.clientRect;
                component = new ReactRenderer(CommandList, {
                  props,
                  editor: props.editor,
                });

                if (!clientRect) {
                  return;
                }

                popup = tippy('body', {
                  getReferenceClientRect: () => clientRect() ?? new DOMRect(),
                  appendTo: () => document.body,
                  content: component.element,
                  showOnCreate: true,
                  interactive: true,
                  trigger: 'manual',
                  placement: 'bottom-start',
                });
              },

              onUpdate(props: SuggestionProps<SlashCommandItem, SlashCommandItem>) {
                const clientRect = props.clientRect;
                component?.updateProps(props);

                if (!clientRect) {
                  return;
                }

                popup?.[0]?.setProps({
                  getReferenceClientRect: () => clientRect() ?? new DOMRect(),
                });
              },

              onKeyDown(props: SuggestionKeyDownProps) {
                if (props.event.key === 'Escape') {
                  popup?.[0]?.hide();
                  return true;
                }

                return component?.ref?.onKeyDown(props) ?? false;
              },

              onExit() {
                popup?.[0]?.destroy();
                component?.destroy();
              },
            };
          },
        }),
      ];
    },
  });
}

// Issue properties sidebar edits lifecycle fields, associations, and blocker evidence.
import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Combobox } from '@/components/ui/Combobox';
import { MultiAssociationChips } from '@/components/ui/MultiAssociationChips';
import { PropertyRow } from '@/components/ui/PropertyRow';
import { ConfirmDialog } from '@/components/ConfirmDialog';
import { isCascadeWarningError } from '@/hooks/useIssuesQuery';
import type { IncompleteChild } from '@ship/shared';
import { apiPost, apiDelete } from '@/lib/api';
import { readJson } from '@/api/read-json';
import type { SprintsResponse } from '@/hooks/useWeeksQuery';
import { formatDateRange } from '@/lib/date-utils';
import { ISSUE_STATE_OPTIONS, ISSUE_PRIORITY_OPTIONS_FULL, type BelongsTo, type BelongsToType } from '@ship/shared';

const API_URL = import.meta.env.VITE_API_URL ?? '';

interface Issue {
  id: string;
  state: string;
  priority: string;
  estimate: number | null;
  assignee_id: string | null;
  assignee_name?: string | null;
  assignee_archived?: boolean;
  source?: 'internal' | 'external';
  rejection_reason?: string | null;
  converted_from_id?: string | null;
  /** Multi-parent associations via junction table */
  belongs_to?: BelongsTo[];
}

interface IssueIteration {
  id: string;
  status: 'pass' | 'fail' | 'in_progress';
  what_attempted: string | null;
  blockers_encountered: string | null;
  author: {
    id: string;
    name: string;
    email: string;
  };
  created_at: string;
}

interface TeamMember {
  id: string;
  user_id: string;
  name: string;
}

interface Program {
  id: string;
  name: string;
  color?: string;
}

interface Project {
  id: string;
  title: string;
  color?: string;
}

interface Sprint {
  id: string;
  name: string;
  status: string;
  sprint_number: number;
}

interface IssueSidebarProps {
  issue: Issue;
  teamMembers: TeamMember[];
  programs: Program[];
  /** Available projects for multi-association */
  projects?: Project[];
  onUpdate: (updates: Partial<Issue>) => Promise<void>;
  /** Called after an association is added/removed via API */
  onAssociationChange?: () => void;
  onConvert?: () => void;
  onUndoConversion?: () => void;
  onAccept?: () => Promise<void>;
  onReject?: (reason: string) => Promise<void>;
  isConverting?: boolean;
  isUndoing?: boolean;
  /** Fields to highlight as missing (e.g., after type conversion) */
  highlightedFields?: string[];
}

// Compute sprint dates from sprint number (1-week sprints)
function computeSprintDates(sprintNumber: number, workspaceStartDate: Date): { start: Date; end: Date } {
  const start = new Date(workspaceStartDate);
  start.setDate(start.getDate() + (sprintNumber - 1) * 7);
  start.setHours(0, 0, 0, 0);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  end.setHours(23, 59, 59, 999);
  return { start, end };
}

export function IssueSidebar({
  issue,
  teamMembers,
  programs,
  projects = [],
  onUpdate,
  onAssociationChange,
  onConvert,
  onUndoConversion,
  onAccept,
  onReject,
  isConverting = false,
  isUndoing = false,
  highlightedFields = [],
}: IssueSidebarProps) {
  // Helper to check if a field should be highlighted
  const isHighlighted = (field: string) => highlightedFields.includes(field);
  const [sprints, setSprints] = useState<Sprint[]>([]);
  const [workspaceSprintStartDate, setWorkspaceSprintStartDate] = useState<Date | null>(null);
  const [sprintError, setSprintError] = useState<string | null>(null);
  const [showRejectDialog, setShowRejectDialog] = useState(false);
  const [rejectReason, setRejectReason] = useState('');
  const [iterations, setIterations] = useState<IssueIteration[]>([]);
  const [iterationsLoading, setIterationsLoading] = useState(false);
  const [iterationError, setIterationError] = useState<string | null>(null);
  const [blockerReason, setBlockerReason] = useState('');
  const [blockerSaving, setBlockerSaving] = useState(false);
  const activeIssueIdRef = useRef(issue.id);
  const iterationRequestRef = useRef(0);
  // Cascade warning state for closing parent with incomplete children
  const [cascadeWarning, setCascadeWarning] = useState<{
    open: boolean;
    pendingState: string | null;
    incompleteChildren: IncompleteChild[];
  }>({ open: false, pendingState: null, incompleteChildren: [] });

  // Get current associations from issue - memoize to prevent infinite re-renders
  const belongsTo = useMemo(() => issue.belongs_to || [], [issue.belongs_to]);
  const blockerIterations = useMemo(
    () => iterations.filter((iteration) => iteration.blockers_encountered?.trim()),
    [iterations]
  );
  const latestBlockerIteration = blockerIterations[0] ?? null;

  useEffect(() => {
    activeIssueIdRef.current = issue.id;
    setBlockerReason('');
    setBlockerSaving(false);
    setIterationsLoading(false);
  }, [issue.id]);

  // Handle state change with cascade warning detection
  const handleStateChange = async (newState: string) => {
    try {
      await onUpdate({ state: newState });
    } catch (error) {
      if (isCascadeWarningError(error)) {
        setCascadeWarning({
          open: true,
          pendingState: newState,
          incompleteChildren: error.warning.incomplete_children,
        });
      } else {
        throw error;
      }
    }
  };

  const loadIssueIterations = useCallback(async () => {
    const requestId = iterationRequestRef.current + 1;
    iterationRequestRef.current = requestId;
    const issueId = issue.id;

    const shouldApplyResult = () => (
      iterationRequestRef.current === requestId && activeIssueIdRef.current === issueId
    );

    if (issue.state !== 'blocked') {
      if (shouldApplyResult()) {
        setIterations([]);
        setIterationError(null);
      }
      return;
    }

    setIterationsLoading(true);
    setIterationError(null);
    try {
      const response = await fetch(`${API_URL}/api/issues/${issueId}/iterations`, {
        credentials: 'include',
      });
      if (!response.ok) {
        throw new Error('Failed to load blocker history');
      }
      const data = await readJson<IssueIteration[]>(response);
      if (shouldApplyResult()) {
        setIterations(data);
      }
    } catch (error) {
      if (shouldApplyResult()) {
        setIterations([]);
        setIterationError(error instanceof Error ? error.message : 'Failed to load blocker history');
      }
    } finally {
      if (shouldApplyResult()) {
        setIterationsLoading(false);
      }
    }
  }, [issue.id, issue.state]);

  const handleSaveBlockerReason = async () => {
    const trimmed = blockerReason.trim();
    if (!trimmed) return;
    const issueId = issue.id;
    const shouldApplyResult = () => activeIssueIdRef.current === issueId;

    setBlockerSaving(true);
    setIterationError(null);
    try {
      const response = await apiPost(`/api/issues/${issueId}/iterations`, {
        status: 'in_progress',
        what_attempted: 'Marked blocked from issue status UI',
        blockers_encountered: trimmed,
      });
      if (!response.ok) {
        throw new Error('Failed to save blocker reason');
      }
      if (shouldApplyResult()) {
        setBlockerReason('');
        await loadIssueIterations();
      }
    } catch (error) {
      if (shouldApplyResult()) {
        setIterationError(error instanceof Error ? error.message : 'Failed to save blocker reason');
      }
    } finally {
      if (shouldApplyResult()) {
        setBlockerSaving(false);
      }
    }
  };

  // Confirm closing parent with incomplete children
  const handleCascadeConfirm = async () => {
    if (cascadeWarning.pendingState) {
      await onUpdate({
        state: cascadeWarning.pendingState,
        confirm_orphan_children: true,
      } as Partial<Issue> & { confirm_orphan_children: boolean });
    }
    setCascadeWarning({ open: false, pendingState: null, incompleteChildren: [] });
  };

  // Cancel cascade warning
  const handleCascadeCancel = () => {
    setCascadeWarning({ open: false, pendingState: null, incompleteChildren: [] });
  };

  // Fetch sprints when issue's program changes
  useEffect(() => {
    // Get program from belongs_to
    const programAssoc = belongsTo.find(bt => bt.type === 'program');
    const programId = programAssoc?.id;

    if (!programId) {
      setSprints([]);
      setWorkspaceSprintStartDate(null);
      return;
    }

    let cancelled = false;

    fetch(`${API_URL}/api/programs/${programId}/sprints`, { credentials: 'include' })
      .then(async (res): Promise<SprintsResponse> => {
        if (!res.ok) return { weeks: [], workspace_sprint_start_date: '' };
        return readJson<SprintsResponse>(res);
      })
      .then(data => {
        if (!cancelled) {
          setSprints(data.weeks || []);
          if (data.workspace_sprint_start_date) {
            setWorkspaceSprintStartDate(new Date(data.workspace_sprint_start_date));
          }
        }
      })
      .catch(() => {
        if (!cancelled) {
          setSprints([]);
          setWorkspaceSprintStartDate(null);
        }
      });

    return () => { cancelled = true; };
  }, [belongsTo]);

  useEffect(() => {
    loadIssueIterations();
  }, [loadIssueIterations]);

  // Add association via junction table API
  const handleAddAssociation = useCallback(async (relatedId: string, type: BelongsToType) => {
    const response = await apiPost(`/api/documents/${issue.id}/associations`, {
      related_id: relatedId,
      relationship_type: type,
    });
    if (!response.ok) {
      throw new Error('Failed to add association');
    }
    // Trigger refetch of issue data
    onAssociationChange?.();
  }, [issue.id, onAssociationChange]);

  // Remove association via junction table API
  const handleRemoveAssociation = useCallback(async (relatedId: string, type: BelongsToType) => {
    const response = await apiDelete(`/api/documents/${issue.id}/associations/${relatedId}?type=${type}`);
    if (!response.ok) {
      throw new Error('Failed to remove association');
    }
    // Trigger refetch of issue data
    onAssociationChange?.();
  }, [issue.id, onAssociationChange]);

  // Legacy program change handler (updates belongs_to via onUpdate)
  const _handleProgramChange = async (programId: string | null) => {
    // Build new belongs_to array with updated program
    const newBelongsTo = belongsTo.filter(bt => bt.type !== 'program' && bt.type !== 'sprint');
    if (programId) {
      newBelongsTo.push({ id: programId, type: 'program' });
    }
    await onUpdate({ belongs_to: newBelongsTo });
  };

  // Legacy sprint change handler
  const handleSprintChange = async (sprintId: string | null) => {
    if (sprintId && !issue.estimate) {
      setSprintError('Please add an estimate before assigning to a week');
      return;
    }
    setSprintError(null);
    // Build new belongs_to array with updated sprint
    const newBelongsTo = belongsTo.filter(bt => bt.type !== 'sprint');
    if (sprintId) {
      newBelongsTo.push({ id: sprintId, type: 'sprint' });
    }
    await onUpdate({ belongs_to: newBelongsTo });
  };

  const handleReject = () => {
    if (rejectReason.trim() && onReject) {
      onReject(rejectReason.trim());
      setRejectReason('');
      setShowRejectDialog(false);
    }
  };

  // Get current program/sprint from belongs_to
  const currentProgramId = belongsTo.find(bt => bt.type === 'program')?.id ?? null;
  const currentSprintId = belongsTo.find(bt => bt.type === 'sprint')?.id ?? null;

  return (
    <div className="space-y-4 p-4">
      {/* Undo Conversion Banner */}
      {issue.converted_from_id && onUndoConversion && (
        <div className="mb-4 rounded-lg border border-blue-500/30 bg-blue-500/10 p-3">
          <p className="mb-2 text-sm text-blue-300">This issue was converted from a project.</p>
          <button
            onClick={onUndoConversion}
            disabled={isUndoing}
            className="w-full rounded bg-blue-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-blue-700 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
          >
            {isUndoing ? (
              <>
                <svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24" fill="none">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Undoing...
              </>
            ) : (
              <>
                <svg className="w-4 h-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M7.707 3.293a1 1 0 010 1.414L5.414 7H11a7 7 0 017 7v2a1 1 0 11-2 0v-2a5 5 0 00-5-5H5.414l2.293 2.293a1 1 0 11-1.414 1.414l-4-4a1 1 0 010-1.414l4-4a1 1 0 011.414 0z" clipRule="evenodd" />
                </svg>
                Undo Conversion
              </>
            )}
          </button>
          <p className="mt-1 text-xs text-blue-300/70 text-center">Restore the original project</p>
        </div>
      )}

      {/* Triage Actions */}
      {issue.state === 'triage' && onAccept && onReject && (
        <div className="mb-4 rounded-lg border border-amber-500/30 bg-amber-500/10 p-3">
          <p className="mb-3 text-sm font-medium text-amber-300">Needs Triage</p>
          {!showRejectDialog ? (
            <div className="flex gap-2">
              <button
                onClick={onAccept}
                className="flex-1 rounded bg-green-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-green-700 transition-colors"
              >
                Accept
              </button>
              <button
                onClick={() => setShowRejectDialog(true)}
                className="flex-1 rounded bg-red-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-red-700 transition-colors"
              >
                Reject
              </button>
            </div>
          ) : (
            <div className="space-y-2">
              <textarea
                value={rejectReason}
                onChange={(e) => setRejectReason(e.target.value)}
                placeholder="Reason for rejection..."
                className="w-full rounded border border-border bg-border/50 px-2 py-1.5 text-sm text-foreground placeholder:text-muted focus:outline-none focus:ring-1 focus:ring-accent"
                rows={2}
              />
              <div className="flex gap-2">
                <button
                  onClick={() => { setShowRejectDialog(false); setRejectReason(''); }}
                  className="flex-1 rounded bg-border px-2 py-1 text-sm text-muted hover:text-foreground transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleReject}
                  disabled={!rejectReason.trim()}
                  className="flex-1 rounded bg-red-600 px-2 py-1 text-sm font-medium text-white hover:bg-red-700 disabled:opacity-50 transition-colors"
                >
                  Reject
                </button>
              </div>
            </div>
          )}
        </div>
      )}

      <PropertyRow label="Status" highlighted={isHighlighted('state')}>
        <select
          value={issue.state}
          onChange={(e) => handleStateChange(e.target.value)}
          aria-label="Status"
          className={`w-full rounded px-2 py-1 text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-accent ${
            isHighlighted('state') ? 'bg-amber-500/20 border border-amber-500' : 'bg-border'
          }`}
        >
          {ISSUE_STATE_OPTIONS.map((s) => (
            <option key={s.value} value={s.value}>
              {s.label}
            </option>
          ))}
        </select>
      </PropertyRow>

      {issue.state === 'blocked' && (
        <div className="rounded border border-amber-500/30 bg-amber-500/10 p-3">
          <p className="text-sm font-medium text-amber-200">Blocked</p>
          {latestBlockerIteration ? (
            <p className="mt-1 text-xs text-amber-100/80">
              Latest blocker from {latestBlockerIteration.author.name}: {latestBlockerIteration.blockers_encountered}
            </p>
          ) : null}
          <textarea
            value={blockerReason}
            onChange={(event) => setBlockerReason(event.target.value)}
            placeholder="What is blocking this issue?"
            aria-label="Blocker reason"
            rows={3}
            className="mt-3 w-full rounded border border-amber-500/30 bg-background px-2 py-1.5 text-sm text-foreground placeholder:text-muted focus:outline-none focus:ring-1 focus:ring-amber-400"
          />
          <button
            type="button"
            onClick={handleSaveBlockerReason}
            disabled={!blockerReason.trim() || blockerSaving}
            className="mt-2 w-full rounded bg-amber-600 px-3 py-1.5 text-sm font-medium text-white transition-colors hover:bg-amber-700 disabled:opacity-50"
          >
            {blockerSaving ? 'Saving...' : 'Record blocker reason'}
          </button>
          {iterationsLoading && (
            <p className="mt-2 text-xs text-muted" role="status" aria-live="polite">Loading blocker history...</p>
          )}
          {iterationError && (
            <p className="mt-2 text-xs text-red-300" role="alert">{iterationError}</p>
          )}
        </div>
      )}

      <PropertyRow label="Priority" highlighted={isHighlighted('priority')}>
        <select
          value={issue.priority}
          onChange={(e) => onUpdate({ priority: e.target.value })}
          aria-label="Priority"
          className={`w-full rounded px-2 py-1 text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-accent ${
            isHighlighted('priority') ? 'bg-amber-500/20 border border-amber-500' : 'bg-border'
          }`}
        >
          {ISSUE_PRIORITY_OPTIONS_FULL.map((p) => (
            <option key={p.value} value={p.value}>
              {p.label}
            </option>
          ))}
        </select>
      </PropertyRow>

      <PropertyRow label="Estimate">
        <div className="flex items-center gap-2">
          <input
            type="number"
            step="0.5"
            min="0"
            placeholder="—"
            aria-label="Estimate in hours"
            value={issue.estimate ?? ''}
            onChange={(e) => {
              const value = e.target.value ? parseFloat(e.target.value) : null;
              onUpdate({ estimate: value });
              if (value) setSprintError(null);
            }}
            className="w-20 rounded bg-border px-2 py-1 text-sm text-foreground focus:outline-none focus:ring-1 focus:ring-accent"
          />
          <span className="text-xs text-muted">hours</span>
        </div>
      </PropertyRow>

      <PropertyRow label="Assignee">
        <Combobox
          options={(() => {
            const options = teamMembers.map((m) => ({ value: m.user_id, label: m.name }));
            // If current assignee is archived and not in the active team members list, add them
            if (issue.assignee_id && issue.assignee_archived && issue.assignee_name) {
              const exists = options.some(o => o.value === issue.assignee_id);
              if (!exists) {
                options.unshift({ value: issue.assignee_id, label: `${issue.assignee_name} (archived)` });
              }
            }
            return options;
          })()}
          value={issue.assignee_id}
          onChange={(value) => onUpdate({ assignee_id: value })}
          placeholder="Unassigned"
          clearLabel="Unassigned"
          searchPlaceholder="Search people..."
          emptyText="No people found"
          aria-label="Assignee"
        />
      </PropertyRow>

      {/* Projects - Multi-association chips */}
      <PropertyRow label="Projects">
        <MultiAssociationChips
          associations={belongsTo}
          options={projects.map(p => ({ id: p.id, name: p.title, color: p.color, href: `/documents/${p.id}` }))}
          type="project"
          onAdd={handleAddAssociation}
          onRemove={handleRemoveAssociation}
          placeholder={projects.length > 0 ? "Add project..." : "No projects yet"}
          aria-label="Projects"
        />
      </PropertyRow>

      {/* Programs - Multi-association chips */}
      <PropertyRow label="Programs">
        <MultiAssociationChips
          associations={belongsTo}
          options={programs.map(p => ({ id: p.id, name: p.name, color: p.color, href: `/programs/${p.id}` }))}
          type="program"
          onAdd={handleAddAssociation}
          onRemove={handleRemoveAssociation}
          placeholder="Add program..."
          aria-label="Programs"
        />
      </PropertyRow>

      {/* Week - still uses single-select since weeks depend on program selection */}
      {currentProgramId && (
        <PropertyRow label="Week">
          <Combobox
            options={sprints.map((s) => {
              let dateRange = '';
              if (workspaceSprintStartDate) {
                const { start, end } = computeSprintDates(s.sprint_number, workspaceSprintStartDate);
                dateRange = formatDateRange(start, end);
              }
              return { value: s.id, label: s.name, description: dateRange };
            })}
            value={currentSprintId}
            onChange={(value) => handleSprintChange(value)}
            placeholder="No Week"
            clearLabel="No Week"
            searchPlaceholder="Search weeks..."
            emptyText="No weeks found"
            aria-label="Week"
          />
          {sprintError && (
            <p className="mt-1 text-xs text-red-500">{sprintError}</p>
          )}
        </PropertyRow>
      )}

      <PropertyRow label="Source">
        <span className={`inline-flex items-center rounded px-2 py-0.5 text-xs font-medium whitespace-nowrap ${
          issue.source === 'external' ? 'bg-purple-500/20 text-purple-300' : 'bg-blue-500/20 text-blue-300'
        }`}>
          {issue.source === 'external' ? 'External' : 'Internal'}
        </span>
      </PropertyRow>

      {issue.state === 'cancelled' && issue.rejection_reason && (
        <PropertyRow label="Rejection Reason">
          <span className="text-sm text-red-300">{issue.rejection_reason}</span>
        </PropertyRow>
      )}

      {/* Document Conversion */}
      {onConvert && (
        <div className="pt-4 mt-4 border-t border-border">
          <button
            onClick={onConvert}
            disabled={isConverting}
            className="w-full rounded bg-accent/20 px-3 py-2 text-sm font-medium text-accent hover:bg-accent/30 disabled:opacity-50 transition-colors flex items-center justify-center gap-2"
          >
            {isConverting ? (
              <>
                <svg className="w-4 h-4 animate-spin" viewBox="0 0 24 24" fill="none">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Converting...
              </>
            ) : (
              <>
                <svg className="w-4 h-4" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-8.707l-3-3a1 1 0 00-1.414 1.414L10.586 9H7a1 1 0 100 2h3.586l-1.293 1.293a1 1 0 101.414 1.414l3-3a1 1 0 000-1.414z" clipRule="evenodd" />
                </svg>
                Promote to Project
              </>
            )}
          </button>
          <p className="mt-1 text-xs text-muted text-center">Convert this issue into a project</p>
        </div>
      )}

      {/* Cascade Warning Dialog */}
      <ConfirmDialog
        open={cascadeWarning.open}
        title="Incomplete Sub-Issues"
        description={`This issue has ${cascadeWarning.incompleteChildren.length} incomplete sub-issue(s). Closing it will remove their parent relationship, making them top-level issues.`}
        confirmLabel="Close Anyway"
        cancelLabel="Keep Open"
        variant="destructive"
        onConfirm={handleCascadeConfirm}
        onCancel={handleCascadeCancel}
      >
        <div className="max-h-32 overflow-y-auto">
          <ul className="space-y-1 text-sm">
            {cascadeWarning.incompleteChildren.map((child) => (
              <li key={child.id} className="flex items-center gap-2 text-muted">
                <span className="font-mono text-xs text-accent">#{child.ticket_number}</span>
                <span className="truncate">{child.title}</span>
                <span className="ml-auto rounded bg-border px-1.5 py-0.5 text-xs">
                  {child.state}
                </span>
              </li>
            ))}
          </ul>
        </div>
      </ConfirmDialog>
    </div>
  );
}

/**
 * Upload Context - Tracks active uploads for navigation warnings
 * Subscribes to the global upload tracker for real-time updates
 */
import { createContext, useContext, useEffect, ReactNode, useSyncExternalStore } from 'react';
import {
  getUploadCount,
  subscribeToUploads,
} from '@/services/uploadTracker';

interface UploadContextValue {
  uploadCount: number;
  isUploading: boolean;
}

const UploadContext = createContext<UploadContextValue | null>(null);

export function UploadProvider({ children }: { children: ReactNode }) {
  // Subscribe to global upload tracker using useSyncExternalStore
  const uploadCount = useSyncExternalStore(
    subscribeToUploads,
    getUploadCount,
    getUploadCount
  );

  const isUploading = uploadCount > 0;

  // Browser beforeunload warning
  useEffect(() => {
    if (!isUploading) return;

    const handleBeforeUnload = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      // Modern browsers ignore custom messages but still show a generic warning
      e.returnValue = `You have ${uploadCount} upload(s) in progress. Leaving will cancel them.`;
      return e.returnValue;
    };

    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [isUploading, uploadCount]);

  return (
    <UploadContext.Provider
      value={{
        uploadCount,
        isUploading,
      }}
    >
      {children}
    </UploadContext.Provider>
  );
}

export function useUploads() {
  const context = useContext(UploadContext);
  if (!context) {
    throw new Error('useUploads must be used within an UploadProvider');
  }
  return context;
}

/**
 * Hook for checking upload status
 * Note: In-app SPA navigation blocking requires migrating to createBrowserRouter.
 * Currently we only block browser navigation via beforeunload.
 */
export function useUploadNavigationWarning() {
  const { uploadCount } = useUploads();

  return {
    isBlocked: false, // Disabled until we migrate to data router
    uploadCount,
    proceed: () => {},
    reset: () => {},
  };
}

import { useEffect, useRef, useState } from 'react';
import * as Y from 'yjs';
import { WebsocketProvider } from 'y-websocket';
import { IndexeddbPersistence } from 'y-indexeddb';
import {
  COLLAB_MESSAGE_CLEAR_CACHE,
  COLLAB_CLOSE_CODE_ACCESS_REVOKED,
  COLLAB_CLOSE_CODE_CONVERSION,
  COLLAB_CLOSE_CODE_CONTENT_UPDATE,
  buildCollaborationRoomName,
  type ConversionDocumentType,
} from '@ship/shared';

export type CollabSyncStatus = 'connecting' | 'cached' | 'synced' | 'disconnected';

export interface CollabUser {
  name: string;
  color: string;
}

interface DocumentConversionInfo {
  newDocId?: string;
  newDocType?: ConversionDocumentType;
}

interface AwarenessState {
  user?: unknown;
}

function parseDocumentConversionInfo(reason: string): DocumentConversionInfo | null {
  try {
    const parsed: unknown = JSON.parse(reason || '{}');
    if (typeof parsed !== 'object' || parsed === null) return null;
    const obj = parsed as Record<string, unknown>;
    const newDocId = typeof obj.newDocId === 'string' ? obj.newDocId : undefined;
    const newDocType =
      obj.newDocType === 'issue' || obj.newDocType === 'project' ? obj.newDocType : undefined;
    return { newDocId, newDocType };
  } catch {
    return null;
  }
}

function isCollabUser(value: unknown): value is CollabUser {
  if (typeof value !== 'object' || value === null) return false;
  const obj = value as Record<string, unknown>;
  return typeof obj.name === 'string' && typeof obj.color === 'string';
}

export interface UseCollabSessionOptions {
  documentId: string;
  /** Authoritative document type for room naming (preferred over roomPrefix). */
  documentType?: string;
  roomPrefix?: string;
  userName: string;
  userColor: string;
  ydoc: Y.Doc;
  onBack?: () => void;
  onDocumentConverted?: (newDocId: string, newDocType: ConversionDocumentType) => void;
}

export interface UseCollabSessionResult {
  provider: WebsocketProvider | null;
  syncStatus: CollabSyncStatus;
  connectedUsers: CollabUser[];
  roomName: string;
}

function getCollaborationWsUrl(): string {
  const wsUrl = import.meta.env.VITE_WS_URL;
  if (typeof wsUrl === 'string' && wsUrl.length > 0) {
    return wsUrl.replace(/^http/, 'ws') + '/collaboration';
  }

  const apiUrl = import.meta.env.VITE_API_URL ?? '';
  const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  return apiUrl
    ? apiUrl.replace(/^http/, 'ws') + '/collaboration'
    : `${wsProtocol}//${window.location.host}/collaboration`;
}

/**
 * Owns IndexedDB persistence + WebSocket collaboration for one document.
 * Editor keeps TipTap/extensions; this hook owns transport only.
 */
export function useCollabSession({
  documentId,
  documentType,
  roomPrefix = 'doc',
  userName,
  userColor,
  ydoc,
  onBack,
  onDocumentConverted,
}: UseCollabSessionOptions): UseCollabSessionResult {
  const effectiveType = documentType ?? roomPrefix;
  const roomName = buildCollaborationRoomName(effectiveType, documentId);
  const cacheKey = `ship-${effectiveType}-${documentId}`;

  const [provider, setProvider] = useState<WebsocketProvider | null>(null);
  const [syncStatus, setSyncStatus] = useState<CollabSyncStatus>('connecting');
  const [connectedUsers, setConnectedUsers] = useState<CollabUser[]>([]);

  const onBackRef = useRef(onBack);
  const onDocumentConvertedRef = useRef(onDocumentConverted);
  onBackRef.current = onBack;
  onDocumentConvertedRef.current = onDocumentConverted;

  useEffect(() => {
    let wsProvider: WebsocketProvider | null = null;
    let hasCachedContent = false;
    let cancelled = false;
    let updateUsersCallback: (() => void) | null = null;
    let rawMessageHandler: ((event: MessageEvent) => void) | null = null;

    const indexeddbProvider = new IndexeddbPersistence(cacheKey, ydoc);

    const waitForCache = new Promise<void>((resolve) => {
      if (indexeddbProvider.synced) {
        hasCachedContent = true;
        setSyncStatus('cached');
        resolve();
        return;
      }

      const onSynced = () => {
        hasCachedContent = true;
        setSyncStatus((prev) => (prev === 'connecting' ? 'cached' : prev));
        resolve();
      };
      indexeddbProvider.on('synced', onSynced);

      setTimeout(() => {
        indexeddbProvider.off('synced', onSynced);
        resolve();
      }, 300);
    });

    waitForCache.then(() => {
      if (cancelled) return;

      const wsUrl = getCollaborationWsUrl();

      rawMessageHandler = (event: MessageEvent) => {
        if (cancelled) return;
        try {
          const data = new Uint8Array(event.data);
          if (data.length > 0 && data[0] === COLLAB_MESSAGE_CLEAR_CACHE) {
            ydoc.transact(() => {
              const fragment = ydoc.getXmlFragment('default');
              while (fragment.length > 0) {
                fragment.delete(0, 1);
              }
            });
            indexeddbProvider.clearData().then(() => {
              hasCachedContent = false;
            }).catch(() => {});
          }
        } catch {
          // non-binary messages ignored
        }
      };

	      wsProvider = new WebsocketProvider(wsUrl, roomName, ydoc, { connect: false });
	      const provider = wsProvider;

	      const attachRawMessageListener = () => {
	        if (provider.ws && rawMessageHandler) {
	          provider.ws.addEventListener('message', rawMessageHandler);
	        }
	      };

	      const originalConnect = provider.connect.bind(provider);
	      provider.connect = () => {
	        originalConnect();
	        attachRawMessageListener();
	      };

	      provider.on('status', (event: { status: string }) => {
        if (cancelled) return;
        if (event.status === 'connected') {
          attachRawMessageListener();
          setSyncStatus('synced');
        } else if (event.status === 'disconnected') {
          setSyncStatus(hasCachedContent ? 'cached' : 'disconnected');
        }
      });

	      provider.connect();

	      provider.on('connection-close', (event: CloseEvent | null) => {
	        if (cancelled) return;
	        if (event?.code === COLLAB_CLOSE_CODE_ACCESS_REVOKED) {
	          provider.shouldConnect = false;
	          alert('Access to this document has been revoked. The document is now private.');
	          onBackRef.current?.();
	        } else if (event?.code === COLLAB_CLOSE_CODE_CONVERSION) {
	          provider.shouldConnect = false;
          try {
            const conversionInfo = parseDocumentConversionInfo(event.reason || '');
            if (conversionInfo?.newDocId && conversionInfo.newDocType && onDocumentConvertedRef.current) {
              onDocumentConvertedRef.current(conversionInfo.newDocId, conversionInfo.newDocType);
            } else {
              alert('This document was converted. Please refresh to view the new document.');
              onBackRef.current?.();
            }
          } catch {
            alert('This document was converted. Please refresh to view the new document.');
            onBackRef.current?.();
          }
        } else if (event?.code === COLLAB_CLOSE_CODE_CONTENT_UPDATE) {
          indexeddbProvider.clearData().then(() => {
            hasCachedContent = false;
          }).catch(() => {});
        }
      });

	      provider.on('sync', (isSynced: boolean) => {
        if (cancelled) return;
        if (isSynced) {
          setSyncStatus('synced');
        }
      });

	      provider.awareness.setLocalStateField('user', {
        name: userName,
        color: userColor,
      });

      updateUsersCallback = () => {
	        if (cancelled) return;
	        const users: CollabUser[] = [];
	        const seenNames = new Set<string>();
	        provider.awareness.getStates().forEach((state: AwarenessState) => {
	          if (isCollabUser(state.user) && !seenNames.has(state.user.name)) {
            seenNames.add(state.user.name);
            users.push(state.user);
          }
        });
        setConnectedUsers(users);
      };

	      provider.awareness.on('change', updateUsersCallback);
	      updateUsersCallback();

	      if (!cancelled) {
	        setProvider(provider);
	      }
    });

    return () => {
      cancelled = true;
      if (wsProvider) {
        if (rawMessageHandler && wsProvider.ws) {
          wsProvider.ws.removeEventListener('message', rawMessageHandler);
        }
        wsProvider.awareness.setLocalState(null);
        if (updateUsersCallback) {
          wsProvider.awareness.off('change', updateUsersCallback);
        }
        wsProvider.destroy();
      }
      indexeddbProvider.destroy();
      setProvider(null);
      setConnectedUsers([]);
    };
  }, [documentId, documentType, roomPrefix, userName, userColor, ydoc, roomName, cacheKey]);

  return { provider, syncStatus, connectedUsers, roomName };
}

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useCallback,
  useState,
  type ReactNode,
} from 'react';
import type { RealtimeEvent, RealtimeEventType } from '@ship/shared';
import { useAuth } from './useAuth';

export type { RealtimeEvent, RealtimeEventType };

type EventCallback = (event: RealtimeEvent) => void;

interface RealtimeEventsContextType {
  isConnected: boolean;
  subscribe: (eventType: RealtimeEventType, callback: EventCallback) => () => void;
}

const RealtimeEventsContext = createContext<RealtimeEventsContextType | null>(null);

// WebSocket URLs for different environments
// VITE_WS_URL allows bypassing CloudFront (which doesn't support WebSocket)
// by connecting directly to the EB endpoint for real-time events
function getEventsWsUrl(): string {
  const wsUrl = import.meta.env.VITE_WS_URL;
  if (typeof wsUrl === 'string' && wsUrl.length > 0) {
    return wsUrl.replace(/^http/, 'ws') + '/events';
  }

  const apiUrl = import.meta.env.VITE_API_URL;
  const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
  if (typeof apiUrl === 'string' && apiUrl.length > 0) {
    return apiUrl.replace(/^http/, 'ws') + '/events';
  }
  return `${wsProtocol}//${window.location.host}/events`;
}

export function RealtimeEventsProvider({ children }: { children: ReactNode }) {
  const { user } = useAuth();
  const wsRef = useRef<WebSocket | null>(null);
  const userRef = useRef(user);
  const intentionalDisconnectRef = useRef(false);
  const reconnectTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const subscribersRef = useRef<Map<RealtimeEventType, Set<EventCallback>>>(new Map());
  const [isConnected, setIsConnected] = useState(false);

  useEffect(() => {
    userRef.current = user;
  }, [user]);

  // Subscribe to events
  const subscribe = useCallback((eventType: RealtimeEventType, callback: EventCallback) => {
    if (!subscribersRef.current.has(eventType)) {
      subscribersRef.current.set(eventType, new Set());
    }
    const subscribers = subscribersRef.current.get(eventType);
    if (!subscribers) return () => {};
    subscribers.add(callback);

    // Return unsubscribe function
    return () => {
      subscribersRef.current.get(eventType)?.delete(callback);
    };
  }, []);

  // Connect to WebSocket
  const connect = useCallback(() => {
    if (!userRef.current) return;
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current?.readyState === WebSocket.CONNECTING) return;
    if (wsRef.current?.readyState === WebSocket.CLOSING) return;

    intentionalDisconnectRef.current = false;
    const ws = new WebSocket(getEventsWsUrl());
    wsRef.current = ws;

    ws.onopen = () => {
      console.log('[RealtimeEvents] Connected');
      setIsConnected(true);
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data) as RealtimeEvent;
        console.log('[RealtimeEvents] Received:', data.type);

        // Notify subscribers
        const callbacks = subscribersRef.current.get(data.type);
        if (callbacks) {
          callbacks.forEach((callback) => callback(data));
        }
      } catch (err) {
        console.error('[RealtimeEvents] Failed to parse message:', err);
      }
    };

    ws.onclose = () => {
      console.log('[RealtimeEvents] Disconnected');
      setIsConnected(false);
      // Only nullify if this is still the current WebSocket
      // (avoids race where a new WS was created before old one finished closing)
      if (wsRef.current === ws) {
        wsRef.current = null;
      }

      // Reconnect after delay if user is still logged in.
      if (!intentionalDisconnectRef.current && userRef.current) {
        reconnectTimeoutRef.current = setTimeout(() => {
          if (!userRef.current) return;
          console.log('[RealtimeEvents] Reconnecting...');
          connect();
        }, 3000);
      }
    };

    ws.onerror = (err) => {
      console.error('[RealtimeEvents] Error:', err);
      ws.close();
    };
  }, []);

  // Disconnect from WebSocket
  const disconnect = useCallback(() => {
    intentionalDisconnectRef.current = true;
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    setIsConnected(false);
  }, []);

  // Connect when user logs in, disconnect when they log out
  useEffect(() => {
    if (user) {
      connect();
    } else {
      disconnect();
    }

    return () => {
      disconnect();
    };
  }, [user, connect, disconnect]);

  // Keepalive ping every 30 seconds
  useEffect(() => {
    if (!isConnected) return;

    const pingInterval = setInterval(() => {
      if (wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: 'ping' }));
      }
    }, 30000);

    return () => clearInterval(pingInterval);
  }, [isConnected]);

  return (
    <RealtimeEventsContext.Provider value={{ isConnected, subscribe }}>
      {children}
    </RealtimeEventsContext.Provider>
  );
}

export function useRealtimeEvents() {
  const context = useContext(RealtimeEventsContext);
  if (!context) {
    throw new Error('useRealtimeEvents must be used within RealtimeEventsProvider');
  }
  return context;
}

/**
 * Hook to listen for a specific realtime event type.
 * Automatically subscribes on mount and unsubscribes on unmount.
 */
export function useRealtimeEvent(eventType: RealtimeEventType, callback: EventCallback) {
  const { subscribe } = useRealtimeEvents();

  useEffect(() => {
    return subscribe(eventType, callback);
  }, [eventType, callback, subscribe]);
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';
import { useSessionTimeout } from './useSessionTimeout';
import * as api from '@/lib/api';
import { clearCsrfToken } from '@/lib/api';

/**
 * Unit Tests for useSessionTimeout Hook
 *
 * These tests verify the core timing and state logic of the session timeout hook.
 * They use fake timers to test time-sensitive behavior without waiting.
 */

// Time constants from the hook (in ms)
const SESSION_TIMEOUT_MS = 15 * 60 * 1000; // 15 minutes
const WARNING_THRESHOLD_MS = 60 * 1000; // 1 minute before timeout
const TIME_UNTIL_WARNING = SESSION_TIMEOUT_MS - WARNING_THRESHOLD_MS; // 14 minutes
const ABSOLUTE_SESSION_TIMEOUT_MS = 12 * 60 * 60 * 1000; // 12 hours
const ABSOLUTE_WARNING_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes before absolute timeout
const ACTIVITY_THROTTLE_MS = 30 * 1000; // 30 seconds

// Mock fetch globally
const mockFetch = vi.fn();

function jsonResponse(body: object, status = 200): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { 'content-type': 'application/json' },
  });
}

function sessionInfo(overrides: Partial<{ createdAt: string; expiresAt: string; lastActivity: string }> = {}) {
  return {
    success: true,
    data: {
      createdAt: new Date().toISOString(),
      expiresAt: new Date(Date.now() + SESSION_TIMEOUT_MS).toISOString(),
      lastActivity: new Date().toISOString(),
      ...overrides,
    },
  };
}

function mockSuccessfulSessionFetch(overrides?: Partial<{ createdAt: string; expiresAt: string; lastActivity: string }>) {
  mockFetch.mockImplementation(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === 'string' ? input : input.toString();

    if (url.endsWith('/api/auth/session')) {
      expect(init).toEqual({ credentials: 'include' });
      return jsonResponse(sessionInfo(overrides));
    }

    if (url.endsWith('/api/csrf-token')) {
      expect(init).toEqual({ credentials: 'include' });
      return jsonResponse({ token: 'test-csrf-token' });
    }

    if (url.endsWith('/api/auth/extend-session')) {
      expect(init).toMatchObject({
        method: 'POST',
        credentials: 'include',
        headers: expect.objectContaining({
          'X-CSRF-Token': 'test-csrf-token',
        }),
      });
      return jsonResponse({ success: true });
    }

    throw new Error(`Unexpected fetch: ${url}`);
  });
}

describe('useSessionTimeout', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    // Reset fetch mock
    mockFetch.mockReset();
    clearCsrfToken();
    mockSuccessfulSessionFetch();
    global.fetch = mockFetch;
    vi.spyOn(api, 'apiPost').mockResolvedValue(jsonResponse({ success: true }));
    // Mock document event listeners
    vi.spyOn(document, 'addEventListener');
    vi.spyOn(document, 'removeEventListener');
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  describe('Initial State', () => {
    it('starts with showWarning = false', () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      expect(result.current.showWarning).toBe(false);
    });

    it('starts with timeRemaining = null when not warning', () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      expect(result.current.timeRemaining).toBeNull();
    });

    it('starts tracking from current time on mount', () => {
      const now = Date.now();
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // lastActivity should be within a small margin of now
      expect(result.current.lastActivity).toBeGreaterThanOrEqual(now);
      expect(result.current.lastActivity).toBeLessThanOrEqual(now + 100);
    });
  });

  describe('Inactivity Timer', () => {
    it('shows warning after 14 minutes of inactivity', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance 14 minutes (time until warning)
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('inactivity');
    });

    it('does NOT show warning before 14 minutes', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance 13 minutes 59 seconds
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING - 1000);
      });

      expect(result.current.showWarning).toBe(false);
    });

    it('sets timeRemaining to 60 when warning appears', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.timeRemaining).toBe(60);
    });

    it('decrements timeRemaining every second during warning', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.timeRemaining).toBe(60);

      // Advance 5 more seconds
      await act(async () => {
        vi.advanceTimersByTime(5000);
      });

      expect(result.current.timeRemaining).toBe(55);
    });

    it('calls onTimeout when timeRemaining reaches 0', async () => {
      const onTimeout = vi.fn();
      renderHook(() => useSessionTimeout(onTimeout));

      // Advance to warning (14 min) + full countdown (60 sec)
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING + WARNING_THRESHOLD_MS);
      });

      expect(onTimeout).toHaveBeenCalledTimes(1);
    });

    it('does NOT call onTimeout if dismissed before 0', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);

      // Dismiss warning by calling resetTimer
      await act(async () => {
        await result.current.resetTimer();
      });

      // Advance past what would have been the timeout
      await act(async () => {
        vi.advanceTimersByTime(WARNING_THRESHOLD_MS);
      });

      expect(onTimeout).not.toHaveBeenCalled();
    });
  });

  describe('Activity Reset', () => {
    it('resetTimer() hides warning modal', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to show warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);

      // Reset timer
      await act(async () => {
        await result.current.resetTimer();
      });

      expect(result.current.showWarning).toBe(false);
    });

    it('resetTimer() resets lastActivity to now', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));
      const initialActivity = result.current.lastActivity;

      // Advance some time
      await act(async () => {
        vi.advanceTimersByTime(5 * 60 * 1000); // 5 minutes
      });

      // Call resetTimer
      await act(async () => {
        await result.current.resetTimer();
      });

      expect(result.current.lastActivity).toBeGreaterThan(initialActivity);
    });

    it('after resetTimer(), warning appears 14 min later (not sooner)', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance 10 minutes
      await act(async () => {
        vi.advanceTimersByTime(10 * 60 * 1000);
      });

      expect(result.current.showWarning).toBe(false);

      // Reset the timer
      await act(async () => {
        await result.current.resetTimer();
      });

      // Advance 10 more minutes (would be 20 min total, but only 10 from reset)
      await act(async () => {
        vi.advanceTimersByTime(10 * 60 * 1000);
      });

      // Should NOT show warning yet (only 10 min from reset, need 14)
      expect(result.current.showWarning).toBe(false);

      // Advance 4 more minutes (14 total from reset)
      await act(async () => {
        vi.advanceTimersByTime(4 * 60 * 1000);
      });

      expect(result.current.showWarning).toBe(true);
    });

    it('resetTimer() clears countdown interval', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to show warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.timeRemaining).toBe(60);

      // Advance a bit to start countdown
      await act(async () => {
        vi.advanceTimersByTime(5000);
      });

      expect(result.current.timeRemaining).toBe(55);

      // Reset timer
      await act(async () => {
        await result.current.resetTimer();
      });

      // timeRemaining should be null
      expect(result.current.timeRemaining).toBeNull();
    });
  });

  describe('Absolute Timeout', () => {
    it('shows absolute warning at 11:55 from session start', async () => {
      const sessionCreatedAt = new Date().toISOString();
      mockSuccessfulSessionFetch({ createdAt: sessionCreatedAt });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Let fetch resolve
      await act(async () => {
        await Promise.resolve();
      });

      // Advance to 11:55 (absolute warning time)
      const timeToAbsoluteWarning = ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS;
      await act(async () => {
        vi.advanceTimersByTime(timeToAbsoluteWarning);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('absolute');
    });

    it('absolute warning has 5-minute countdown', async () => {
      const sessionCreatedAt = new Date().toISOString();
      mockSuccessfulSessionFetch({ createdAt: sessionCreatedAt });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Advance to absolute warning (11:55)
      const timeToAbsoluteWarning = ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS;
      await act(async () => {
        vi.advanceTimersByTime(timeToAbsoluteWarning);
      });

      expect(result.current.timeRemaining).toBe(300); // 5 minutes in seconds
    });

    it('activity does NOT reset absolute timeout', async () => {
      const sessionCreatedAt = new Date().toISOString();
      mockSuccessfulSessionFetch({ createdAt: sessionCreatedAt });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Advance to 11:50
      await act(async () => {
        vi.advanceTimersByTime(ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS - 5 * 60 * 1000);
      });

      // Reset activity (inactivity timer)
      await act(async () => {
        await result.current.resetTimer();
      });

      // Advance 5 more minutes to reach 11:55
      await act(async () => {
        vi.advanceTimersByTime(5 * 60 * 1000);
      });

      // Absolute warning should still appear (resetTimer doesn't affect absolute timeout)
      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('absolute');
    });

    it('absolute timeout fires at 12 hours regardless of activity', async () => {
      // Session created 11:55 ago - just past absolute warning point
      // Absolute warning would have started, and countdown at 300 seconds
      const almostTwelveHoursAgo = new Date(
        Date.now() - (ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS)
      ).toISOString();
      mockSuccessfulSessionFetch({ createdAt: almostTwelveHoursAgo });

      const onTimeout = vi.fn();
      renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Absolute warning should show immediately (since session is 11:55 old)
      // Advance through the 5-minute countdown
      await act(async () => {
        vi.advanceTimersByTime(ABSOLUTE_WARNING_THRESHOLD_MS + 1000);
      });

      // onTimeout should have been called due to absolute timeout
      expect(onTimeout).toHaveBeenCalled();
    });
  });

  describe('Warning Type', () => {
    it('inactivity warning has type = "inactivity"', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.warningType).toBe('inactivity');
    });

    it('absolute warning has type = "absolute"', async () => {
      // Session created 11:54 ago - just before absolute warning point
      // This way when we advance 1 minute, absolute warning fires
      const almostAtAbsoluteWarning = new Date(
        Date.now() - (ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS - 60 * 1000)
      ).toISOString();
      mockSuccessfulSessionFetch({ createdAt: almostAtAbsoluteWarning });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Advance 1 minute - absolute warning should appear
      // Note: inactivity warning would fire at 14 min, but we're only advancing 1 min
      await act(async () => {
        vi.advanceTimersByTime(60 * 1000);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('absolute');
    });

    it('inactivity warning takes precedence if both imminent', async () => {
      // Session created 11:50 ago - both warnings would trigger soon
      const sessionCreatedAt = new Date(Date.now() - (ABSOLUTE_SESSION_TIMEOUT_MS - 10 * 60 * 1000)).toISOString();
      mockSuccessfulSessionFetch({ createdAt: sessionCreatedAt });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Advance 14 minutes - inactivity warning should fire first
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('inactivity');
    });
  });

  describe('Event Listeners', () => {
    it('registers activity listeners on mount', () => {
      const onTimeout = vi.fn();
      renderHook(() => useSessionTimeout(onTimeout));

      // Check that addEventListener was called for activity events
      expect(document.addEventListener).toHaveBeenCalledWith(
        'mousedown',
        expect.any(Function),
        expect.objectContaining({ passive: true, capture: true })
      );
      expect(document.addEventListener).toHaveBeenCalledWith(
        'keydown',
        expect.any(Function),
        expect.objectContaining({ passive: true, capture: true })
      );
      expect(document.addEventListener).toHaveBeenCalledWith(
        'scroll',
        expect.any(Function),
        expect.objectContaining({ passive: true, capture: true })
      );
    });

    it('removes activity listeners on unmount', () => {
      const onTimeout = vi.fn();
      const { unmount } = renderHook(() => useSessionTimeout(onTimeout));

      unmount();

      expect(document.removeEventListener).toHaveBeenCalledWith(
        'mousedown',
        expect.any(Function),
        expect.objectContaining({ capture: true })
      );
      expect(document.removeEventListener).toHaveBeenCalledWith(
        'keydown',
        expect.any(Function),
        expect.objectContaining({ capture: true })
      );
    });

    it('activity listener resets timer (throttled)', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      const initialActivity = result.current.lastActivity;

      // Advance past throttle period
      await act(async () => {
        vi.advanceTimersByTime(ACTIVITY_THROTTLE_MS + 1000);
      });

      // Simulate mousedown event
      await act(async () => {
        const event = new MouseEvent('mousedown');
        document.dispatchEvent(event);
      });

      // lastActivity should have been updated
      expect(result.current.lastActivity).toBeGreaterThan(initialActivity);
    });

    it('activity events are throttled to max once per 30 seconds', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance past initial throttle
      await act(async () => {
        vi.advanceTimersByTime(ACTIVITY_THROTTLE_MS + 1000);
      });

      // Fire first event
      await act(async () => {
        document.dispatchEvent(new MouseEvent('mousedown'));
      });

      const activityAfterFirst = result.current.lastActivity;

      // Fire many more events rapidly (within throttle window)
      for (let i = 0; i < 100; i++) {
        await act(async () => {
          document.dispatchEvent(new MouseEvent('mousedown'));
        });
      }

      // Activity should not have changed (within throttle period)
      expect(result.current.lastActivity).toBe(activityAfterFirst);

      // Now advance past throttle period
      await act(async () => {
        vi.advanceTimersByTime(ACTIVITY_THROTTLE_MS + 1000);
      });

      // Fire another event
      await act(async () => {
        document.dispatchEvent(new MouseEvent('mousedown'));
      });

      // Now it should have updated
      expect(result.current.lastActivity).toBeGreaterThan(activityAfterFirst);
    });
  });

  describe('Cleanup', () => {
    it('clears all timers on unmount', async () => {
      const onTimeout = vi.fn();
      const { unmount } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to show warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      // Unmount the hook
      unmount();

      // Advance more time - onTimeout should NOT be called since we unmounted
      await act(async () => {
        vi.advanceTimersByTime(WARNING_THRESHOLD_MS);
      });

      expect(onTimeout).not.toHaveBeenCalled();
    });

    it('clears interval when warning dismissed', async () => {
      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      // Advance to show warning
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.timeRemaining).toBe(60);

      // Dismiss the warning
      await act(async () => {
        await result.current.resetTimer();
      });

      // Verify countdown stopped
      expect(result.current.timeRemaining).toBeNull();
    });
  });

  describe('Session Info Integration', () => {
    it('fetches session info on mount', async () => {
      const onTimeout = vi.fn();
      renderHook(() => useSessionTimeout(onTimeout));

      // Let the effect run
      await act(async () => {
        await Promise.resolve();
      });

      expect(mockFetch).toHaveBeenCalledWith('/api/auth/session', {
        credentials: 'include',
      });
    });

    it('uses server createdAt for absolute timeout calculation', async () => {
      // Session was created 11:54 ago on the server
      // Even though this hook just mounted, absolute warning should fire in ~1 min
      const elevenFiftyFourAgo = new Date(
        Date.now() - (ABSOLUTE_SESSION_TIMEOUT_MS - ABSOLUTE_WARNING_THRESHOLD_MS - 60 * 1000)
      ).toISOString();
      mockSuccessfulSessionFetch({ createdAt: elevenFiftyFourAgo });

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Advance 1 minute - absolute warning should appear based on server createdAt
      await act(async () => {
        vi.advanceTimersByTime(60 * 1000);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('absolute');
    });

    it('handles session info fetch failure gracefully', async () => {
      // Make fetch fail
      mockFetch.mockRejectedValue(new Error('Network error'));

      const onTimeout = vi.fn();
      const { result } = renderHook(() => useSessionTimeout(onTimeout));

      await act(async () => {
        await Promise.resolve();
      });

      // Hook should still work - inactivity timeout should still function
      await act(async () => {
        vi.advanceTimersByTime(TIME_UNTIL_WARNING);
      });

      expect(result.current.showWarning).toBe(true);
      expect(result.current.warningType).toBe('inactivity');
    });
  });
});

describe('useSessionTimeout - Edge Cases', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    mockFetch.mockReset();
    clearCsrfToken();
    mockSuccessfulSessionFetch();
    global.fetch = mockFetch;
  });

  afterEach(() => {
    vi.useRealTimers();
    vi.restoreAllMocks();
  });

  it('handles time jump (computer wake from sleep)', async () => {
    const onTimeout = vi.fn();
    renderHook(() => useSessionTimeout(onTimeout));

    // Simulate visibility change after a long sleep (20 minutes)
    await act(async () => {
      vi.advanceTimersByTime(20 * 60 * 1000);
    });

    // Trigger visibility change (simulating wake from sleep)
    await act(async () => {
      Object.defineProperty(document, 'visibilityState', {
        value: 'visible',
        writable: true,
      });
      document.dispatchEvent(new Event('visibilitychange'));
    });

    // onTimeout should have been called because we jumped past the timeout
    expect(onTimeout).toHaveBeenCalled();
  });

  it('handles rapid mount/unmount without errors', async () => {
    const onTimeout = vi.fn();

    // Mount and unmount rapidly
    for (let i = 0; i < 10; i++) {
      const { unmount } = renderHook(() => useSessionTimeout(onTimeout));
      await act(async () => {
        vi.advanceTimersByTime(100);
      });
      unmount();
    }

    // No errors should have been thrown
    expect(true).toBe(true);
  });

  it('handles resetTimer called when not showing warning', async () => {
    const onTimeout = vi.fn();
    mockSuccessfulSessionFetch();

    const { result } = renderHook(() => useSessionTimeout(onTimeout));

    // Call resetTimer before any warning
    await act(async () => {
      await result.current.resetTimer();
    });

    // Should not throw and hook should still work
    expect(result.current.showWarning).toBe(false);
    expect(result.current.timeRemaining).toBeNull();
  });

  it('handles multiple resetTimer calls in quick succession', async () => {
    const onTimeout = vi.fn();
    mockSuccessfulSessionFetch();

    const { result } = renderHook(() => useSessionTimeout(onTimeout));

    // Show warning
    await act(async () => {
      vi.advanceTimersByTime(TIME_UNTIL_WARNING);
    });

    expect(result.current.showWarning).toBe(true);

    // Call resetTimer multiple times rapidly
    await act(async () => {
      // First call will succeed, others should be blocked by extendingSessionRef guard
      result.current.resetTimer();
      result.current.resetTimer();
      result.current.resetTimer();
      await Promise.resolve();
    });

    // Should work correctly without errors
    expect(result.current.showWarning).toBe(false);
  });

  it('survives component re-render without resetting timer', async () => {
    const onTimeout = vi.fn();
    const { result, rerender } = renderHook(() => useSessionTimeout(onTimeout));

    const initialActivity = result.current.lastActivity;

    // Advance some time
    await act(async () => {
      vi.advanceTimersByTime(5 * 60 * 1000);
    });

    // Re-render the hook (simulates parent re-render)
    rerender();

    // lastActivity should NOT have changed
    expect(result.current.lastActivity).toBe(initialActivity);
  });
});

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { cn } from '@/lib/cn';
import { apiGet } from '@/lib/api';
import { formatDate } from '@/lib/date-utils';

interface ConvertedDocument {
  original_id: string;
  original_title: string;
  original_type: string;
  original_ticket_number: number | null;
  converted_id: string;
  converted_title: string;
  converted_type: string;
  converted_ticket_number: number | null;
  converted_at: string | null;
  converted_by: string | null;
  converted_by_name: string | null;
}

type FilterType = 'all' | 'issue-to-project' | 'project-to-issue';

export function ConvertedDocumentsPage() {
  const { currentWorkspace } = useWorkspace();
  const [conversions, setConversions] = useState<ConvertedDocument[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<FilterType>('all');

  useEffect(() => {
    if (!currentWorkspace) return;
    loadConversions();
  }, [currentWorkspace, filter]);

  async function loadConversions() {
    setLoading(true);
    try {
      let url = '/api/documents/converted/list';
      const params = new URLSearchParams();

      if (filter === 'issue-to-project') {
        params.set('original_type', 'issue');
        params.set('converted_type', 'project');
      } else if (filter === 'project-to-issue') {
        params.set('original_type', 'project');
        params.set('converted_type', 'issue');
      }

      if (params.toString()) {
        url += `?${params.toString()}`;
      }

      const res = await apiGet(url);
      if (res.ok) {
        const data = await res.json();
        setConversions(data);
      }
    } catch (err) {
      console.error('Failed to load conversions:', err);
    }
    setLoading(false);
  }

  function getTypeIcon(type: string) {
    if (type === 'issue') {
      return <DocumentIcon className="h-4 w-4" />;
    }
    return <FolderIcon className="h-4 w-4" />;
  }

  function getTypeRoute(type: string, id: string) {
    if (type === 'issue') {
      return `/issues/${id}`;
    }
    return `/projects/${id}`;
  }

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-gray-100">
      <div className="mx-auto max-w-4xl px-4 py-8">
        <div className="mb-6">
          <h1 className="text-2xl font-semibold text-white">Converted Documents</h1>
          <p className="mt-1 text-sm text-gray-400">
            Documents that have been converted between issue and project types
          </p>
        </div>

        {/* Filter tabs */}
        <div className="mb-6 flex gap-2">
          <button
            onClick={() => setFilter('all')}
            className={cn(
              'rounded-lg px-4 py-2 text-sm font-medium transition-colors',
              filter === 'all'
                ? 'bg-white/10 text-white'
                : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'
            )}
          >
            All
          </button>
          <button
            onClick={() => setFilter('issue-to-project')}
            className={cn(
              'rounded-lg px-4 py-2 text-sm font-medium transition-colors',
              filter === 'issue-to-project'
                ? 'bg-white/10 text-white'
                : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'
            )}
          >
            Issues → Projects
          </button>
          <button
            onClick={() => setFilter('project-to-issue')}
            className={cn(
              'rounded-lg px-4 py-2 text-sm font-medium transition-colors',
              filter === 'project-to-issue'
                ? 'bg-white/10 text-white'
                : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'
            )}
          >
            Projects → Issues
          </button>
        </div>

        {/* Conversions list */}
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <div className="h-6 w-6 animate-spin rounded-full border-2 border-gray-600 border-t-white" />
          </div>
        ) : conversions.length === 0 ? (
          <div className="rounded-lg border border-gray-800 bg-[#1a1a1a] p-8 text-center">
            <p className="text-gray-400">No converted documents found</p>
          </div>
        ) : (
          <div className="space-y-3">
            {conversions.map((conversion) => (
              <div
                key={conversion.original_id}
                className="rounded-lg border border-gray-800 bg-[#1a1a1a] p-4"
              >
                <div className="flex items-center gap-3">
                  {/* Original document */}
                  <div className="flex-1">
                    <div className="flex items-center gap-2 text-gray-400">
                      {getTypeIcon(conversion.original_type)}
                      <span className="text-xs uppercase">{conversion.original_type}</span>
                      {conversion.original_ticket_number && (
                        <span className="text-xs text-gray-500">
                          #{conversion.original_ticket_number}
                        </span>
                      )}
                    </div>
                    <Link
                      to={getTypeRoute(conversion.original_type, conversion.original_id)}
                      className="mt-1 block text-sm text-gray-300 hover:text-white hover:underline"
                    >
                      {conversion.original_title}
                    </Link>
                    <span className="text-xs text-gray-500">(archived)</span>
                  </div>

                  {/* Arrow */}
                  <div className="flex-shrink-0">
                    <ArrowRightIcon className="h-5 w-5 text-gray-600" />
                  </div>

                  {/* Converted document */}
                  <div className="flex-1">
                    <div className="flex items-center gap-2 text-gray-400">
                      {getTypeIcon(conversion.converted_type)}
                      <span className="text-xs uppercase">{conversion.converted_type}</span>
                      {conversion.converted_ticket_number && (
                        <span className="text-xs text-gray-500">
                          #{conversion.converted_ticket_number}
                        </span>
                      )}
                    </div>
                    <Link
                      to={getTypeRoute(conversion.converted_type, conversion.converted_id)}
                      className="mt-1 block text-sm font-medium text-white hover:underline"
                    >
                      {conversion.converted_title}
                    </Link>
                    <span className="text-xs text-green-500">(active)</span>
                  </div>
                </div>

                {/* Metadata */}
                <div className="mt-3 flex items-center gap-4 border-t border-gray-800 pt-3 text-xs text-gray-500">
                  {conversion.converted_at && (
                    <div className="flex items-center gap-1">
                      <CalendarIcon className="h-3.5 w-3.5" />
                      <span>{formatDate(conversion.converted_at)}</span>
                    </div>
                  )}
                  {conversion.converted_by_name && (
                    <div className="flex items-center gap-1">
                      <UserIcon className="h-3.5 w-3.5" />
                      <span>{conversion.converted_by_name}</span>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

