import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { cn } from '@/lib/cn';
import { apiPost, apiGet, readJson } from '@/lib/api';
import { formatDateRange } from '@/lib/date-utils';
import { useAuth } from '@/hooks/useAuth';
import { useReviewQueue } from '@/contexts/ReviewQueueContext';
import type { QueueItem } from '@/contexts/ReviewQueueContext';

// OPM 5-level performance rating scale
const OPM_RATINGS = [
  { value: 5, label: 'Outstanding', color: 'text-green-500', bg: 'bg-green-500/10' },
  { value: 4, label: 'Exceeds Expectations', color: 'text-blue-500', bg: 'bg-blue-500/10' },
  { value: 3, label: 'Fully Successful', color: 'text-muted', bg: 'bg-border/50' },
  { value: 2, label: 'Minimally Satisfactory', color: 'text-orange-500', bg: 'bg-orange-500/10' },
  { value: 1, label: 'Unacceptable', color: 'text-red-500', bg: 'bg-red-500/10' },
] as const;

// Review status colors — matches StatusOverviewHeatmap's bold style
type ReviewStatus = 'approved' | 'needs_review' | 'late' | 'changed' | 'changes_requested' | 'empty';

const REVIEW_COLORS: Record<ReviewStatus, string> = {
  approved: '#22c55e',           // green — approved or rated
  needs_review: '#eab308',       // yellow — submitted, needs manager action
  late: '#ef4444',               // red — past due, nothing submitted
  changed: '#f97316',            // orange — changed since approved
  changes_requested: '#ea580c',  // orange — manager requested changes
  empty: '#6b7280',              // gray — no allocation or future
};

const REVIEW_STATUS_TEXT: Record<ReviewStatus, string> = {
  approved: 'approved',
  needs_review: 'needs review',
  late: 'late',
  changed: 'changed since approved',
  changes_requested: 'changes requested',
  empty: 'no submission',
};

function needsPlanReview(cell: ReviewCell | undefined): boolean {
  if (!cell?.sprintId || !cell.hasPlan) return false;
  const approvalState = cell.planApproval?.state;
  return approvalState !== 'approved' && approvalState !== 'changes_requested';
}

function needsRetroReview(cell: ReviewCell | undefined): boolean {
  if (!cell?.sprintId || !cell.hasRetro) return false;
  const approvalState = cell.reviewApproval?.state;
  return approvalState !== 'approved' && approvalState !== 'changes_requested';
}

interface Week {
  number: number;
  name: string;
  startDate: string;
  endDate: string;
  isCurrent: boolean;
}

interface ReviewPerson {
  personId: string;
  name: string;
  programId: string | null;
  programName: string | null;
  programColor: string | null;
  reportsTo?: string | null;
}

interface ApprovalInfo {
  state: string;
  approved_by?: string | null;
  approved_at?: string | null;
  approved_version_id?: number | null;
  feedback?: string | null;
  comment?: string | null;
}

interface RatingInfo {
  value: number;
  rated_by?: string;
  rated_at?: string;
}

interface ReviewCell {
  planApproval: ApprovalInfo | null;
  reviewApproval: ApprovalInfo | null;
  reviewRating: RatingInfo | null;
  hasPlan: boolean;
  hasRetro: boolean;
  sprintId: string | null;
  planDocId: string | null;
  retroDocId: string | null;
}

interface ReviewsData {
  people: ReviewPerson[];
  weeks: Week[];
  reviews: Record<string, Record<number, ReviewCell>>;
  currentSprintNumber: number;
}

interface ProgramGroup {
  programId: string | null;
  programName: string;
  programColor: string | null;
  people: ReviewPerson[];
}

/** Determine the review status color for a plan cell */
function getPlanStatus(cell: ReviewCell | undefined, weekIsPast: boolean): ReviewStatus {
  if (!cell || !cell.sprintId) return 'empty';
  if (cell.planApproval?.state === 'approved') return 'approved';
  if (cell.planApproval?.state === 'changes_requested') return 'changes_requested';
  if (cell.planApproval?.state === 'changed_since_approved') return 'changed';
  if (cell.hasPlan) return 'needs_review';
  if (weekIsPast) return 'late';
  return 'empty';
}

/** Determine the review status color for a retro cell */
function getRetroStatus(cell: ReviewCell | undefined, weekIsPast: boolean): ReviewStatus {
  if (!cell || !cell.sprintId) return 'empty';
  if (cell.reviewApproval?.state === 'changes_requested') return 'changes_requested';
  if (cell.reviewApproval?.state === 'changed_since_approved') return 'changed';
  if (cell.reviewRating) return 'approved';
  if (cell.reviewApproval?.state === 'approved') return 'approved';
  if (cell.hasRetro) return 'needs_review';
  if (weekIsPast) return 'late';
  return 'empty';
}

// Shape of a fetched weekly plan/retro document
interface WeeklyDoc {
  id: string;
  title: string;
  content: unknown;
  properties: Record<string, unknown>;
  person_name?: string;
  project_name?: string;
}

// Selected cell for the review panel
interface SelectedCell {
  personId: string;
  personName: string;
  weekNumber: number;
  weekName: string;
  type: 'plan' | 'retro';
  sprintId: string;
  cell: ReviewCell;
}

// Batch review mode state
interface BatchMode {
  type: 'plans' | 'retros';
  queue: SelectedCell[];
  currentIndex: number;
}

export function ReviewsPage() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const reviewQueue = useReviewQueue();
  const [data, setData] = useState<ReviewsData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [filterMode, setFilterMode] = useState<'my-team' | 'everyone' | null>(null);
  const [collapsedPrograms, setCollapsedPrograms] = useState<Set<string>>(new Set());
  const [selectedCell, setSelectedCell] = useState<SelectedCell | null>(null);
  const [batchMode, setBatchMode] = useState<BatchMode | null>(null);
  const [selectedPlanWeek, setSelectedPlanWeek] = useState<number | null>(null);
  const [selectedRetroWeek, setSelectedRetroWeek] = useState<number | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const hasScrolledToCurrentRef = useRef(false);

  // Smart default: if user has direct reports, default to "my-team"
  const hasDirectReports = useMemo(() => {
    if (!data || !user?.id) return false;
    return data.people.some(p => p.reportsTo === user.id);
  }, [data, user?.id]);

  useEffect(() => {
    if (data && filterMode === null) {
      setFilterMode(hasDirectReports ? 'my-team' : 'everyone');
    }
  }, [data, filterMode, hasDirectReports]);

  // Filter people based on filter mode
  const filteredPeople = useMemo(() => {
    if (!data) return [];
    if (filterMode === 'my-team' && user?.id) {
      return data.people.filter(p => p.reportsTo === user.id);
    }
    return data.people;
  }, [data, filterMode, user?.id]);

  // Recalculate manager action defaults when switching review scope.
  useEffect(() => {
    setSelectedPlanWeek(null);
    setSelectedRetroWeek(null);
  }, [filterMode]);

  useEffect(() => {
    fetchReviews();
  }, []);

  // Approve a plan optimistically
  const approvePlan = useCallback(async (personId: string, weekNumber: number, sprintId: string, comment?: string) => {
    if (!data) return;

    // Optimistic update
    setData(prev => {
      if (!prev) return prev;
      const updated = { ...prev, reviews: { ...prev.reviews } };
      updated.reviews[personId] = { ...updated.reviews[personId] };
      updated.reviews[personId][weekNumber] = {
        ...updated.reviews[personId][weekNumber],
        planApproval: {
          state: 'approved',
          approved_by: null,
          approved_at: new Date().toISOString(),
          comment: comment?.trim() || null,
        },
      };
      return updated;
    });

    try {
      const res = await apiPost(`/api/weeks/${sprintId}/approve-plan`, { comment });
      if (!res.ok) throw new Error('Failed to approve plan');
    } catch {
      // Revert on error
      fetchReviews();
    }
  }, [data]);

  // Request changes on a plan or retro
  const requestChanges = useCallback(async (personId: string, weekNumber: number, sprintId: string, type: 'plan' | 'retro', feedback: string) => {
    if (!data) return;

    const endpoint = type === 'plan' ? 'request-plan-changes' : 'request-retro-changes';
    const approvalField = type === 'plan' ? 'planApproval' : 'reviewApproval';

    // Optimistic update
    setData(prev => {
      if (!prev) return prev;
      const updated = { ...prev, reviews: { ...prev.reviews } };
      updated.reviews[personId] = { ...updated.reviews[personId] };
      updated.reviews[personId][weekNumber] = {
        ...updated.reviews[personId][weekNumber],
        [approvalField]: { state: 'changes_requested', approved_by: null, approved_at: new Date().toISOString(), feedback },
      };
      return updated;
    });

    try {
      const res = await apiPost(`/api/weeks/${sprintId}/${endpoint}`, { feedback });
      if (!res.ok) throw new Error('Failed to request changes');
    } catch {
      // Revert on error
      fetchReviews();
    }
  }, [data]);

  // Rate a retro (also approves it)
  const rateRetro = useCallback(async (personId: string, weekNumber: number, sprintId: string, rating: number, comment?: string) => {
    if (!data) return;

    // Optimistic update
    setData(prev => {
      if (!prev) return prev;
      const updated = { ...prev, reviews: { ...prev.reviews } };
      updated.reviews[personId] = { ...updated.reviews[personId] };
      updated.reviews[personId][weekNumber] = {
        ...updated.reviews[personId][weekNumber],
        reviewApproval: {
          state: 'approved',
          approved_by: null,
          approved_at: new Date().toISOString(),
          comment: comment?.trim() || null,
        },
        reviewRating: { value: rating, rated_by: '', rated_at: new Date().toISOString() },
      };
      return updated;
    });

    try {
      const res = await apiPost(`/api/weeks/${sprintId}/approve-review`, { rating, comment });
      if (!res.ok) throw new Error('Failed to rate retro');
    } catch {
      // Revert on error
      fetchReviews();
    }
  }, [data]);

  async function fetchReviews() {
    try {
      setLoading(true);
      const res = await apiGet(`/api/team/reviews?sprint_count=8`);
      if (!res.ok) throw new Error(`Failed to fetch: ${res.status}`);
      const json = await readJson<ReviewsData>(res);
      setData(json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load reviews');
    } finally {
      setLoading(false);
    }
  }

  // Group people by program
  const programGroups = useMemo((): ProgramGroup[] => {
    if (!data) return [];

    const groups = new Map<string, ProgramGroup>();
    const UNASSIGNED_KEY = '__unassigned__';

    for (const person of filteredPeople) {
      const groupKey = person.programId || UNASSIGNED_KEY;

      if (!groups.has(groupKey)) {
        groups.set(groupKey, {
          programId: person.programId,
          programName: person.programName || 'No Program',
          programColor: person.programColor,
          people: [],
        });
      }

      const group = groups.get(groupKey);
      if (group) {
        group.people.push(person);
      }
    }

    const sorted = Array.from(groups.values()).sort((a, b) => {
      if (a.programId === null) return 1;
      if (b.programId === null) return -1;
      return a.programName.localeCompare(b.programName);
    });

    for (const group of sorted) {
      group.people.sort((a, b) => a.name.localeCompare(b.name));
    }

    return sorted;
  }, [data, filteredPeople]);

  // Build row structure for synchronized scrolling
  const rowStructure = useMemo(() => {
    const rows: Array<{
      type: 'program' | 'person';
      id: string;
      name: string;
      color?: string | null;
      personId?: string;
      peopleCount?: number;
    }> = [];

    for (const group of programGroups) {
      const groupKey = group.programId || '__unassigned__';
      const isCollapsed = collapsedPrograms.has(groupKey);

      rows.push({
        type: 'program',
        id: groupKey,
        name: group.programName,
        color: group.programColor,
        peopleCount: group.people.length,
      });

      if (!isCollapsed) {
        for (const person of group.people) {
          rows.push({
            type: 'person',
            id: `${person.personId}`,
            name: person.name,
            personId: person.personId,
          });
        }
      }
    }

    return rows;
  }, [programGroups, collapsedPrograms]);

  // Per-week actionable review counts for manager actions
  const weekReviewCounts = useMemo((): Record<number, { plans: number; retros: number }> => {
    const counts: Record<number, { plans: number; retros: number }> = {};
    if (!data) return counts;

    for (const week of data.weeks) {
      counts[week.number] = { plans: 0, retros: 0 };
    }

    for (const person of filteredPeople) {
      for (const week of data.weeks) {
        const cell = data.reviews[person.personId]?.[week.number];
        if (needsPlanReview(cell)) counts[week.number].plans += 1;
        if (needsRetroReview(cell)) counts[week.number].retros += 1;
      }
    }

    return counts;
  }, [data, filteredPeople]);

  const weeksDescending = useMemo(() => {
    if (!data) return [];
    return [...data.weeks].sort((a, b) => b.number - a.number);
  }, [data]);

  const defaultPlanWeek = useMemo(() => {
    if (!data) return null;

    const currentWeekNumber = data.currentSprintNumber;
    if ((weekReviewCounts[currentWeekNumber]?.plans ?? 0) > 0) {
      return currentWeekNumber;
    }

    const latestWithPendingPlans = weeksDescending.find(week => (weekReviewCounts[week.number]?.plans ?? 0) > 0);
    return latestWithPendingPlans?.number ?? currentWeekNumber;
  }, [data, weekReviewCounts, weeksDescending]);

  const defaultRetroWeek = useMemo(() => {
    if (!data) return null;

    const currentWeekNumber = data.currentSprintNumber;
    const previousWeekNumber = currentWeekNumber - 1;
    const isMonday = new Date().getDay() === 1;

    if (isMonday && previousWeekNumber >= 1 && (weekReviewCounts[previousWeekNumber]?.retros ?? 0) > 0) {
      return previousWeekNumber;
    }

    const latestWithPendingRetros = weeksDescending.find(week => (weekReviewCounts[week.number]?.retros ?? 0) > 0);
    if (latestWithPendingRetros) {
      return latestWithPendingRetros.number;
    }

    if (previousWeekNumber >= 1 && data.weeks.some(week => week.number === previousWeekNumber)) {
      return previousWeekNumber;
    }

    return currentWeekNumber;
  }, [data, weekReviewCounts, weeksDescending]);

  useEffect(() => {
    if (!data || defaultPlanWeek === null) return;
    const selectedExists = selectedPlanWeek !== null && data.weeks.some(week => week.number === selectedPlanWeek);
    if (!selectedExists) {
      setSelectedPlanWeek(defaultPlanWeek);
    }
  }, [data, defaultPlanWeek, selectedPlanWeek]);

  useEffect(() => {
    if (!data || defaultRetroWeek === null) return;
    const selectedExists = selectedRetroWeek !== null && data.weeks.some(week => week.number === selectedRetroWeek);
    if (!selectedExists) {
      setSelectedRetroWeek(defaultRetroWeek);
    }
  }, [data, defaultRetroWeek, selectedRetroWeek]);

  const effectivePlanWeek = selectedPlanWeek ?? defaultPlanWeek ?? data?.currentSprintNumber ?? 1;
  const effectiveRetroWeek = selectedRetroWeek ?? defaultRetroWeek ?? data?.currentSprintNumber ?? 1;
  const selectedPlanPendingCount = weekReviewCounts[effectivePlanWeek]?.plans ?? 0;
  const selectedRetroPendingCount = weekReviewCounts[effectiveRetroWeek]?.retros ?? 0;
  const selectedPlanWeekLabel = data?.weeks.find(week => week.number === effectivePlanWeek)?.name ?? `Week ${effectivePlanWeek}`;
  const selectedRetroWeekLabel = data?.weeks.find(week => week.number === effectiveRetroWeek)?.name ?? `Week ${effectiveRetroWeek}`;

  // Build batch review queue for selected week data
  const buildBatchQueue = useCallback((type: 'plans' | 'retros', weekNumber: number): SelectedCell[] => {
    if (!data) return [];
    const selectedWeek = data.weeks.find(w => w.number === weekNumber);
    if (!selectedWeek) return [];

    const queue: SelectedCell[] = [];
    for (const group of programGroups) {
      for (const person of group.people) {
        const cell = data.reviews[person.personId]?.[selectedWeek.number];
        if (!cell?.sprintId) continue;

        if (type === 'plans' && needsPlanReview(cell)) {
          queue.push({
            personId: person.personId,
            personName: person.name,
            weekNumber: selectedWeek.number,
            weekName: selectedWeek.name,
            type: 'plan',
            sprintId: cell.sprintId,
            cell,
          });
        }
        if (type === 'retros' && needsRetroReview(cell)) {
          queue.push({
            personId: person.personId,
            personName: person.name,
            weekNumber: selectedWeek.number,
            weekName: selectedWeek.name,
            type: 'retro',
            sprintId: cell.sprintId,
            cell,
          });
        }
      }
    }
    return queue;
  }, [data, programGroups]);

  // Start batch review via queue context (navigates to documents)
  function startBatchReview(type: 'plans' | 'retros', weekNumber: number) {
    if (!reviewQueue || !data) return;
    const selectedCells = buildBatchQueue(type, weekNumber);
    if (selectedCells.length === 0) return;

    const queueItems: QueueItem[] = selectedCells
      .map(sc => {
        const docId = sc.type === 'plan' ? sc.cell.planDocId : sc.cell.retroDocId;
        if (!docId) return null;
        return {
          personId: sc.personId,
          personName: sc.personName,
          weekNumber: sc.weekNumber,
          weekName: sc.weekName,
          type: sc.type,
          sprintId: sc.sprintId,
          docId,
        };
      })
      .filter((item): item is QueueItem => item !== null);

    if (queueItems.length > 0) {
      reviewQueue.start(queueItems);
    }
  }

  // Advance to next item in batch mode
  function advanceBatch() {
    if (!batchMode) return;
    const nextIndex = batchMode.currentIndex + 1;
    if (nextIndex >= batchMode.queue.length) {
      // All done
      setBatchMode({ ...batchMode, currentIndex: nextIndex });
      setSelectedCell(null);
    } else {
      // Refresh the cell data from the latest state
      const nextItem = batchMode.queue[nextIndex];
      const freshCell = data?.reviews[nextItem.personId]?.[nextItem.weekNumber];
      const updatedItem = freshCell ? { ...nextItem, cell: freshCell } : nextItem;
      setBatchMode({ ...batchMode, currentIndex: nextIndex });
      setSelectedCell(updatedItem);
    }
  }

  // Exit batch mode
  function exitBatchMode() {
    setBatchMode(null);
    setSelectedCell(null);
  }

  // Scroll to current week on first render
  useEffect(() => {
    if (data && scrollContainerRef.current && !hasScrolledToCurrentRef.current) {
      const currentWeekIndex = data.weeks.findIndex(w => w.isCurrent);
      if (currentWeekIndex >= 0) {
        requestAnimationFrame(() => {
          if (scrollContainerRef.current) {
            const columnWidth = 100;
            const scrollPosition = Math.max(0, (currentWeekIndex - 2) * columnWidth);
            scrollContainerRef.current.scrollLeft = scrollPosition;
            hasScrolledToCurrentRef.current = true;
          }
        });
      }
    }
  }, [data]);

  // Handle Escape to close panel / exit batch mode (must be before ALL early returns)
  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === 'Escape') {
        if (batchMode) {
          exitBatchMode();
        } else if (selectedCell) {
          setSelectedCell(null);
        }
      }
    }
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [selectedCell, batchMode]);

  function toggleProgram(programId: string | null) {
    const key = programId || '__unassigned__';
    setCollapsedPrograms(prev => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }

  if (loading) {
    return (
      <div className="flex flex-1 items-center justify-center">
        <div className="flex items-center gap-2 text-muted">
          <svg className="w-5 h-5 animate-spin" viewBox="0 0 24 24" fill="none">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
          </svg>
          Loading...
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex flex-1 items-center justify-center">
        <span className="text-sm text-red-500">{error}</span>
      </div>
    );
  }

  if (!data) return null;

  return (
    <div className="flex h-full">
      {/* Main grid area */}
      <div className={cn('flex flex-col', selectedCell ? 'flex-1 min-w-0' : 'flex-1')}>
      {/* Status legend + filters */}
      <div className="border-b border-border px-4 py-2 text-xs">
        <div className="flex flex-wrap items-center gap-3">
        {/* My Team filter */}
        {hasDirectReports && (
          <>
            <div className="flex rounded-md border border-border">
              <button
                onClick={() => setFilterMode('my-team')}
                className={cn(
                  'px-2 py-0.5 transition-colors',
                  filterMode === 'my-team'
                    ? 'bg-accent text-white'
                    : 'text-muted hover:text-foreground'
                )}
              >
                My Team
              </button>
              <button
                onClick={() => setFilterMode('everyone')}
                className={cn(
                  'px-2 py-0.5 transition-colors',
                  filterMode === 'everyone'
                    ? 'bg-accent text-white'
                    : 'text-muted hover:text-foreground'
                )}
              >
                Everyone
              </button>
            </div>
            <div className="h-4 w-px bg-border" />
          </>
        )}
        <span className="text-muted">Review Status:</span>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.approved }} />
          <span>Approved</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.needs_review }} />
          <span>Needs Review</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.late }} />
          <span>Late</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.changed }} />
          <span>Changed</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.changes_requested }} />
          <span>Changes Requested</span>
        </div>
        <div className="flex items-center gap-1">
          <div className="w-3 h-3 rounded" style={{ backgroundColor: REVIEW_COLORS.empty }} />
          <span>No Submission</span>
        </div>
        <span className="text-muted">Left = Plan, Right = Retro</span>
        </div>
      </div>

      {/* Manager action bar */}
      <div className="border-b border-border bg-border/10 px-4 py-2">
        <div className="flex flex-wrap items-center gap-3">
          <span className="text-[11px] font-semibold uppercase tracking-wide text-muted">Manager Actions</span>

          <div className="flex flex-wrap items-center gap-2 rounded-md border border-border bg-background/70 px-2 py-1">
            <label htmlFor="plans-week-select" className="text-[11px] font-medium text-muted">Plans</label>
            <select
              id="plans-week-select"
              value={String(effectivePlanWeek)}
              onChange={e => setSelectedPlanWeek(Number(e.target.value))}
              className="h-7 rounded border border-border bg-background px-2 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-accent"
            >
              {weeksDescending.map(week => {
                const count = weekReviewCounts[week.number]?.plans ?? 0;
                return (
                  <option key={`plan-week-${week.number}`} value={week.number}>
                    {week.name} ({count})
                  </option>
                );
              })}
            </select>
            <button
              onClick={() => startBatchReview('plans', effectivePlanWeek)}
              disabled={selectedPlanPendingCount === 0}
              aria-label={`Review Plans for ${selectedPlanWeekLabel} (${selectedPlanPendingCount} pending)`}
              title={`Review Plans for ${selectedPlanWeekLabel} (${selectedPlanPendingCount} pending)`}
              className={cn(
                'h-7 rounded px-2.5 text-xs font-medium transition-colors',
                selectedPlanPendingCount > 0
                  ? 'bg-yellow-600 text-white hover:bg-yellow-500'
                  : 'bg-border/40 text-muted cursor-not-allowed'
              )}
            >
              Review Plans
            </button>
          </div>

          <div className="flex flex-wrap items-center gap-2 rounded-md border border-border bg-background/70 px-2 py-1">
            <label htmlFor="retros-week-select" className="text-[11px] font-medium text-muted">Retros</label>
            <select
              id="retros-week-select"
              value={String(effectiveRetroWeek)}
              onChange={e => setSelectedRetroWeek(Number(e.target.value))}
              className="h-7 rounded border border-border bg-background px-2 text-xs text-foreground focus:outline-none focus:ring-1 focus:ring-accent"
            >
              {weeksDescending.map(week => {
                const count = weekReviewCounts[week.number]?.retros ?? 0;
                return (
                  <option key={`retro-week-${week.number}`} value={week.number}>
                    {week.name} ({count})
                  </option>
                );
              })}
            </select>
            <button
              onClick={() => startBatchReview('retros', effectiveRetroWeek)}
              disabled={selectedRetroPendingCount === 0}
              aria-label={`Review Retros for ${selectedRetroWeekLabel} (${selectedRetroPendingCount} pending)`}
              title={`Review Retros for ${selectedRetroWeekLabel} (${selectedRetroPendingCount} pending)`}
              className={cn(
                'h-7 rounded px-2.5 text-xs font-medium transition-colors',
                selectedRetroPendingCount > 0
                  ? 'bg-yellow-600 text-white hover:bg-yellow-500'
                  : 'bg-border/40 text-muted cursor-not-allowed'
              )}
            >
              Review Retros
            </button>
          </div>

          {(selectedPlanPendingCount === 0 && selectedRetroPendingCount === 0) && (
            <span className="text-xs text-muted">No pending reviews in selected weeks.</span>
          )}
        </div>
      </div>

      {/* Grid container */}
      <div ref={scrollContainerRef} className="flex-1 overflow-auto pb-20">
        <div className="inline-flex min-w-full">
          {/* Sticky left column - Names */}
          <div className="flex flex-col sticky left-0 z-20 bg-background border-r border-border">
            {/* Header cell */}
            <div className="flex h-10 w-[240px] items-center border-b border-border px-3 sticky top-0 z-30 bg-background">
              <span className="text-xs font-medium text-muted">Program / Person</span>
            </div>

            {/* Rows */}
            {rowStructure.map((row, index) => {
              if (row.type === 'program') {
                return (
                  <button
                    key={`program-${row.id}`}
                    onClick={() => toggleProgram(row.id === '__unassigned__' ? null : row.id)}
                    className="flex h-10 w-[240px] items-center gap-2 border-b border-border bg-border/30 px-3 hover:bg-border/50 text-left"
                  >
                    <svg
                      className={cn('w-3 h-3 transition-transform', !collapsedPrograms.has(row.id) && 'rotate-90')}
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke="currentColor"
                      strokeWidth="2"
                    >
                      <path d="M9 18l6-6-6-6" />
                    </svg>
                    {row.color && (
                      <span
                        className="shrink-0 rounded px-1.5 py-0.5 text-[10px] font-bold text-white"
                        style={{ backgroundColor: row.color }}
                      >
                        {row.name.charAt(0).toUpperCase()}
                      </span>
                    )}
                    <span className="truncate text-xs font-medium">{row.name}</span>
                    <span className="ml-auto text-[10px] text-muted">{row.peopleCount}</span>
                  </button>
                );
              }

              // Person row
              return (
                <div
                  key={`person-${row.id}-${index}`}
                  className="flex h-10 w-[240px] items-center gap-2 border-b border-border pl-6 pr-3 bg-background"
                >
                  <div className="flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full text-xs font-medium text-white bg-accent/80">
                    {row.name.charAt(0).toUpperCase()}
                  </div>
                  <span className="truncate text-xs text-foreground">{row.name}</span>
                </div>
              );
            })}
          </div>

          {/* Week columns */}
          <div className="flex">
            {data.weeks.map(week => {
              const weekIsPast = week.number < data.currentSprintNumber;

              return (
                <div key={week.number} className="flex flex-col">
                  {/* Week header */}
                  <div
                    className={cn(
                      'flex h-10 w-[100px] flex-col items-center justify-center border-b border-r border-border px-2 sticky top-0 z-10 bg-background',
                      week.isCurrent && 'ring-1 ring-inset ring-accent/30'
                    )}
                  >
                    <span className={cn('text-xs font-medium', week.isCurrent ? 'text-accent' : 'text-foreground')}>
                      {week.name}
                    </span>
                    <span className="text-[10px] text-muted">
                      {formatDateRange(week.startDate, week.endDate)}
                    </span>
                  </div>

                  {/* Cells for each row */}
                  {rowStructure.map((row, index) => {
                    if (row.type === 'program') {
                      return (
                        <div
                          key={`program-${row.id}-week-${week.number}`}
                          className={cn(
                            'h-10 w-[100px] border-b border-r border-border bg-border/30',
                            week.isCurrent && 'bg-accent/5'
                          )}
                        />
                      );
                    }

                    const cell = row.personId ? data.reviews[row.personId]?.[week.number] : undefined;
                    const planStatus = getPlanStatus(cell, weekIsPast);
                    const retroStatus = getRetroStatus(cell, weekIsPast);

                    // Empty state - no sprint allocation
                    if (!cell || !cell.sprintId) {
                      return (
                        <div
                          key={`person-${row.id}-week-${week.number}-${index}`}
                          className={cn(
                            'flex h-10 w-[100px] items-center justify-center border-b border-r border-border',
                            week.isCurrent && 'bg-accent/5'
                          )}
                        >
                          <span className="text-xs text-muted">-</span>
                        </div>
                      );
                    }

                    return (
                      <div
                        key={`person-${row.id}-week-${week.number}-${index}`}
                        className={cn(
                          'flex h-10 w-[100px] border-b border-r border-border overflow-hidden',
                          week.isCurrent && 'ring-1 ring-inset ring-accent/20'
                        )}
                      >
                        {/* Plan status (left half) */}
                        <button
                          onClick={() => {
                            if (cell.hasPlan && cell.planDocId) {
                              navigate(`/documents/${cell.planDocId}?review=true&sprintId=${cell.sprintId}`);
                            }
                          }}
                          className={cn(
                            'flex-1 h-full cursor-pointer transition-all hover:brightness-110 border-r border-white/20',
                            selectedCell?.personId === row.personId && selectedCell?.weekNumber === week.number && selectedCell?.type === 'plan' && 'ring-2 ring-inset ring-white/60'
                          )}
                          style={{ backgroundColor: REVIEW_COLORS[planStatus] }}
                          title={`Plan: ${REVIEW_STATUS_TEXT[planStatus]}`}
                          aria-label={`Plan: ${REVIEW_STATUS_TEXT[planStatus]} - ${row.name}`}
                        />
                        {/* Retro status (right half) */}
                        <button
                          onClick={() => {
                            if (cell.hasRetro && cell.retroDocId) {
                              navigate(`/documents/${cell.retroDocId}?review=true&sprintId=${cell.sprintId}`);
                            }
                          }}
                          className={cn(
                            'flex-1 h-full cursor-pointer transition-all hover:brightness-110',
                            selectedCell?.personId === row.personId && selectedCell?.weekNumber === week.number && selectedCell?.type === 'retro' && 'ring-2 ring-inset ring-white/60'
                          )}
                          style={{ backgroundColor: REVIEW_COLORS[retroStatus] }}
                          title={`Retro: ${REVIEW_STATUS_TEXT[retroStatus]}`}
                          aria-label={`Retro: ${REVIEW_STATUS_TEXT[retroStatus]} - ${row.name}`}
                        />
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      </div>
      </div>

      {/* Review Panel - right side */}
      {selectedCell && (
        <ReviewPanel
          selectedCell={selectedCell}
          batchMode={batchMode}
          onClose={() => batchMode ? exitBatchMode() : setSelectedCell(null)}
          onApprovePlan={(personId, weekNumber, sprintId, comment) => {
            approvePlan(personId, weekNumber, sprintId, comment);
            setSelectedCell(prev => prev ? {
              ...prev,
              cell: {
                ...prev.cell,
                planApproval: {
                  state: 'approved',
                  approved_by: null,
                  approved_at: new Date().toISOString(),
                  comment: comment?.trim() || null,
                },
              },
            } : null);
            // Auto-advance in batch mode
            if (batchMode) setTimeout(advanceBatch, 300);
          }}
          onRateRetro={(personId, weekNumber, sprintId, rating, comment) => {
            rateRetro(personId, weekNumber, sprintId, rating, comment);
            setSelectedCell(prev => prev ? {
              ...prev,
              cell: {
                ...prev.cell,
                reviewApproval: {
                  state: 'approved',
                  approved_by: null,
                  approved_at: new Date().toISOString(),
                  comment: comment?.trim() || null,
                },
                reviewRating: { value: rating, rated_by: '', rated_at: new Date().toISOString() },
              },
            } : null);
            // Auto-advance in batch mode
            if (batchMode) setTimeout(advanceBatch, 300);
          }}
          onRequestChanges={(personId, weekNumber, sprintId, type, feedback) => {
            requestChanges(personId, weekNumber, sprintId, type, feedback);
            const approvalField = type === 'plan' ? 'planApproval' : 'reviewApproval';
            setSelectedCell(prev => prev ? {
              ...prev,
              cell: {
                ...prev.cell,
                [approvalField]: { state: 'changes_requested', approved_by: null, approved_at: new Date().toISOString(), feedback },
              },
            } : null);
            // Auto-advance in batch mode
            if (batchMode) setTimeout(advanceBatch, 300);
          }}
          onSkip={batchMode ? advanceBatch : undefined}
        />
      )}

      {/* Batch mode completion state */}
      {batchMode && batchMode.currentIndex >= batchMode.queue.length && (
        <div className="w-[400px] flex-shrink-0 border-l border-border bg-background flex flex-col items-center justify-center gap-4 p-8">
          <div className="flex h-16 w-16 items-center justify-center rounded-full bg-green-500/20">
            <svg className="w-8 h-8 text-green-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M20 6L9 17l-5-5" />
            </svg>
          </div>
          <div className="text-center">
            <div className="text-sm font-medium text-foreground">
              All {batchMode.type === 'plans' ? 'plans' : 'retros'} reviewed!
            </div>
            <div className="text-xs text-muted mt-1">
              {batchMode.queue.length} item{batchMode.queue.length !== 1 ? 's' : ''} processed
            </div>
          </div>
          <button
            onClick={exitBatchMode}
            className="rounded bg-accent px-4 py-2 text-xs font-medium text-white hover:bg-accent/80"
          >
            Done
          </button>
        </div>
      )}
    </div>
  );
}

/** Panel for reviewing plan/retro content */
function ReviewPanel({
  selectedCell,
  batchMode,
  onClose,
  onApprovePlan,
  onRateRetro,
  onRequestChanges,
  onSkip,
}: {
  selectedCell: SelectedCell;
  batchMode: BatchMode | null;
  onClose: () => void;
  onApprovePlan: (personId: string, weekNumber: number, sprintId: string, comment?: string) => void;
  onRateRetro: (personId: string, weekNumber: number, sprintId: string, rating: number, comment?: string) => void;
  onRequestChanges: (personId: string, weekNumber: number, sprintId: string, type: 'plan' | 'retro', feedback: string) => void;
  onSkip?: () => void;
}) {
  const [planDoc, setPlanDoc] = useState<WeeklyDoc | null>(null);
  const [retroDoc, setRetroDoc] = useState<WeeklyDoc | null>(null);
  const [loadingDocs, setLoadingDocs] = useState(true);
  const [selectedRating, setSelectedRating] = useState<number | null>(null);
  const [approvalComment, setApprovalComment] = useState('');
  const [showFeedbackInput, setShowFeedbackInput] = useState(false);
  const [feedbackText, setFeedbackText] = useState('');

  // Fetch plan/retro content when selection changes
  useEffect(() => {
    setLoadingDocs(true);
    setPlanDoc(null);
    setRetroDoc(null);
    setSelectedRating(selectedCell.cell.reviewRating?.value ?? null);
    const existingComment = selectedCell.type === 'retro'
      ? selectedCell.cell.reviewApproval?.comment
      : selectedCell.cell.planApproval?.comment;
    setApprovalComment(existingComment ?? '');
    setShowFeedbackInput(false);
    setFeedbackText('');

    const fetchDocs = async () => {
      try {
        const params = new URLSearchParams({
          person_id: selectedCell.personId,
          week_number: String(selectedCell.weekNumber),
        });

        // Fetch plan and retro in parallel
        const [planRes, retroRes] = await Promise.all([
          apiGet(`/api/weekly-plans?${params}`),
          apiGet(`/api/weekly-retros?${params}`),
        ]);

        if (planRes.ok) {
          const plans = await readJson<WeeklyDoc[]>(planRes);
          if (plans.length > 0) setPlanDoc(plans[0]);
        }
        if (retroRes.ok) {
          const retros = await readJson<WeeklyDoc[]>(retroRes);
          if (retros.length > 0) setRetroDoc(retros[0]);
        }
      } catch (err) {
        console.error('Failed to fetch plan/retro:', err);
      } finally {
        setLoadingDocs(false);
      }
    };

    fetchDocs();
  }, [selectedCell.personId, selectedCell.weekNumber]);

  const isRetroMode = selectedCell.type === 'retro';
  const planApprovalState = selectedCell.cell.planApproval?.state;
  const canApprove = selectedCell.cell.hasPlan;

  return (
    <div className="w-[400px] flex-shrink-0 border-l border-border bg-background flex flex-col overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-border px-4 py-3">
        <div>
          <div className="text-sm font-medium text-foreground">{selectedCell.personName}</div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted">{selectedCell.weekName} &middot; {isRetroMode ? 'Retro' : 'Plan'}</span>
            {batchMode && (
              <span className="rounded bg-accent/20 px-1.5 py-0.5 text-[10px] font-medium text-accent">
                {batchMode.currentIndex + 1} of {batchMode.queue.length}
              </span>
            )}
          </div>
        </div>
        <div className="flex items-center gap-1">
          {onSkip && (
            <button
              onClick={onSkip}
              className="rounded px-2 py-1 text-xs text-muted hover:text-foreground hover:bg-border/50"
            >
              Skip
            </button>
          )}
          <button
            onClick={onClose}
            className="rounded p-1 text-muted hover:text-foreground hover:bg-border/50"
            aria-label="Close panel"
          >
            <svg className="w-4 h-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Content */}
      <div className="flex-1 overflow-y-auto">
        {loadingDocs ? (
          <div className="flex items-center justify-center py-12 text-muted text-sm">Loading...</div>
        ) : isRetroMode ? (
          /* Retro mode: side-by-side plan vs retro */
          <div className="flex flex-col h-full">
            {/* Plan context (dimmed) */}
            <div className="border-b border-border">
              <div className="px-4 py-2 text-[10px] uppercase tracking-wider text-muted bg-border/20">Plan (context)</div>
              <div className="px-4 py-3 opacity-60">
                {planDoc ? (
                  <TipTapContent content={planDoc.content} />
                ) : (
                  <p className="text-sm text-muted italic">No plan submitted for this week</p>
                )}
              </div>
            </div>
            {/* Retro (primary) */}
            <div className="flex-1">
              <div className="px-4 py-2 text-[10px] uppercase tracking-wider text-muted bg-border/20">Retro</div>
              <div className="px-4 py-3">
                {retroDoc ? (
                  <TipTapContent content={retroDoc.content} />
                ) : (
                  <p className="text-sm text-muted italic">No retro submitted for this week</p>
                )}
              </div>
            </div>
          </div>
        ) : (
          /* Plan mode: show plan content */
          <div className="px-4 py-3">
            {planDoc ? (
              <TipTapContent content={planDoc.content} />
            ) : (
              <p className="text-sm text-muted italic">No plan submitted for this week</p>
            )}
          </div>
        )}
      </div>

      {/* Previous feedback (when changes were already requested) */}
      {((isRetroMode && selectedCell.cell.reviewApproval?.state === 'changes_requested') ||
        (!isRetroMode && selectedCell.cell.planApproval?.state === 'changes_requested')) && (
        <div className="border-t border-border px-4 py-2 bg-purple-500/5">
          <div className="text-[10px] uppercase tracking-wider text-purple-400 mb-1">Previous Feedback</div>
          <p className="text-xs text-muted">
            {(isRetroMode ? (selectedCell.cell.reviewApproval as { feedback?: string })?.feedback : (selectedCell.cell.planApproval as { feedback?: string })?.feedback) || 'No feedback provided'}
          </p>
        </div>
      )}

      {/* Existing approval note */}
      {((isRetroMode && selectedCell.cell.reviewApproval?.comment) ||
        (!isRetroMode && selectedCell.cell.planApproval?.comment)) && (
        <div className="border-t border-border px-4 py-2 bg-border/20">
          <div className="text-[10px] uppercase tracking-wider text-muted mb-1">Approval Note</div>
          <p className="text-xs text-foreground">
            {isRetroMode ? selectedCell.cell.reviewApproval?.comment : selectedCell.cell.planApproval?.comment}
          </p>
        </div>
      )}

      {/* Action bar */}
      <div className="border-t border-border px-4 py-3">
        {showFeedbackInput ? (
          /* Feedback input for requesting changes */
          <div>
            <div className="text-xs text-muted mb-2">What needs to change?</div>
            <textarea
              value={feedbackText}
              onChange={e => setFeedbackText(e.target.value)}
              placeholder="Explain what needs to be revised..."
              rows={3}
              className="w-full rounded border border-border bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted resize-none focus:outline-none focus:ring-1 focus:ring-purple-500"
              autoFocus
            />
            <div className="flex gap-2 mt-2">
              <button
                onClick={() => {
                  if (feedbackText.trim()) {
                    onRequestChanges(
                      selectedCell.personId,
                      selectedCell.weekNumber,
                      selectedCell.sprintId,
                      selectedCell.type,
                      feedbackText.trim()
                    );
                    setShowFeedbackInput(false);
                    setFeedbackText('');
                  }
                }}
                disabled={!feedbackText.trim()}
                className={cn(
                  'flex-1 rounded py-2 text-sm font-medium transition-colors',
                  feedbackText.trim()
                    ? 'bg-purple-600 text-white hover:bg-purple-500 cursor-pointer'
                    : 'bg-border/30 text-muted cursor-not-allowed'
                )}
              >
                Submit Request
              </button>
              <button
                onClick={() => { setShowFeedbackInput(false); setFeedbackText(''); }}
                className="rounded px-3 py-2 text-sm text-muted hover:text-foreground hover:bg-border/50"
              >
                Cancel
              </button>
            </div>
          </div>
        ) : isRetroMode ? (
          /* Rating controls for retro */
          <div>
            <div className="text-xs text-muted mb-2">Performance Rating</div>
            <div className="flex gap-1 mb-3">
              {OPM_RATINGS.map(r => (
                <button
                  key={r.value}
                  onClick={() => setSelectedRating(r.value)}
                  className={cn(
                    'flex-1 flex flex-col items-center gap-0.5 rounded py-1.5 text-xs transition-all',
                    selectedRating === r.value
                      ? 'bg-accent/20 ring-1 ring-accent'
                      : 'bg-border/30 hover:bg-border/50'
                  )}
                  title={r.label}
                >
                  <span className={cn('font-bold', r.color)}>{r.value}</span>
                  <span className="text-[9px] text-muted leading-tight">{r.label.split(' ')[0]}</span>
                </button>
              ))}
            </div>
            <label className="text-xs text-muted mb-1 block">Approval Note (optional)</label>
            <textarea
              value={approvalComment}
              onChange={e => setApprovalComment(e.target.value)}
              placeholder="Add context for this decision..."
              rows={3}
              className="w-full rounded border border-border bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted resize-none focus:outline-none focus:ring-1 focus:ring-accent mb-3"
            />
            <div className="flex gap-2">
              <button
                onClick={() => {
                  if (selectedRating) {
                    onRateRetro(
                      selectedCell.personId,
                      selectedCell.weekNumber,
                      selectedCell.sprintId,
                      selectedRating,
                      approvalComment
                    );
                  }
                }}
                disabled={!selectedRating || !retroDoc}
                className={cn(
                  'flex-1 rounded py-2 text-sm font-medium transition-colors',
                  selectedRating && retroDoc
                    ? 'bg-green-600 text-white hover:bg-green-500 cursor-pointer'
                    : 'bg-border/30 text-muted cursor-not-allowed'
                )}
              >
                {selectedCell.cell.reviewRating ? 'Update Approval' : 'Rate & Approve'}
              </button>
              {retroDoc && (
                <button
                  onClick={() => setShowFeedbackInput(true)}
                  className="rounded px-3 py-2 text-sm font-medium text-purple-400 hover:bg-purple-500/10 transition-colors"
                >
                  Request Changes
                </button>
              )}
            </div>
          </div>
        ) : (
          /* Plan actions: Approve + Request Changes */
          <div>
            <label className="text-xs text-muted mb-1 block">Approval Note (optional)</label>
            <textarea
              value={approvalComment}
              onChange={e => setApprovalComment(e.target.value)}
              placeholder="Add context for this decision..."
              rows={3}
              className="w-full rounded border border-border bg-background px-3 py-2 text-sm text-foreground placeholder:text-muted resize-none focus:outline-none focus:ring-1 focus:ring-accent mb-3"
            />
            <div className="flex gap-2">
              <button
                onClick={() => onApprovePlan(selectedCell.personId, selectedCell.weekNumber, selectedCell.sprintId, approvalComment)}
                disabled={!canApprove}
                className={cn(
                  'flex-1 rounded py-2 text-sm font-medium transition-colors',
                  planApprovalState === 'approved'
                    ? 'bg-green-600 text-white hover:bg-green-500 cursor-pointer'
                    : canApprove
                      ? planApprovalState === 'changed_since_approved'
                        ? 'bg-orange-600 text-white hover:bg-orange-500 cursor-pointer'
                        : 'bg-green-600 text-white hover:bg-green-500 cursor-pointer'
                      : 'bg-border/30 text-muted cursor-not-allowed'
                )}
              >
                {planApprovalState === 'approved'
                  ? 'Update Approval'
                  : planApprovalState === 'changed_since_approved'
                    ? 'Re-approve Plan'
                    : 'Approve Plan'}
              </button>
              {canApprove && (
                <button
                  onClick={() => setShowFeedbackInput(true)}
                  className="rounded px-3 py-2 text-sm font-medium text-purple-400 hover:bg-purple-500/10 transition-colors"
                >
                  Request Changes
                </button>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

/** Renders TipTap JSON content as simple HTML */
function TipTapContent({ content }: { content: unknown }) {
  if (!content || typeof content !== 'object') {
    return <p className="text-sm text-muted italic">Empty</p>;
  }

  const doc = content as { type?: string; content?: unknown[] };
  if (!doc.content || !Array.isArray(doc.content)) {
    return <p className="text-sm text-muted italic">Empty</p>;
  }

  return (
    <div className="text-sm text-foreground space-y-2">
      {doc.content.map((node, i) => (
        <TipTapNode key={i} node={node} />
      ))}
    </div>
  );
}

function TipTapNode({ node }: { node: unknown }) {
  if (!node || typeof node !== 'object') return null;
  const n = node as { type?: string; content?: unknown[]; text?: string; attrs?: Record<string, unknown>; marks?: Array<{ type: string }> };

  if (n.type === 'text') {
    let text = <>{n.text}</>;
    if (n.marks) {
      for (const mark of n.marks) {
        if (mark.type === 'bold') text = <strong>{text}</strong>;
        if (mark.type === 'italic') text = <em>{text}</em>;
      }
    }
    return text;
  }

  const children = n.content?.map((child, i) => <TipTapNode key={i} node={child} />) ?? null;

  switch (n.type) {
    case 'heading': {
      const level = (n.attrs?.level as number) || 2;
      if (level === 1) return <h3 className="text-base font-semibold text-foreground">{children}</h3>;
      if (level === 2) return <h4 className="text-sm font-semibold text-foreground">{children}</h4>;
      return <h5 className="text-sm font-medium text-foreground">{children}</h5>;
    }
    case 'paragraph':
      return <p className="text-sm leading-relaxed">{children || '\u00A0'}</p>;
    case 'bulletList':
      return <ul className="list-disc pl-5 space-y-1">{children}</ul>;
    case 'listItem':
      return <li className="text-sm">{children}</li>;
    case 'blockquote':
      return <blockquote className="border-l-2 border-accent/50 pl-3 text-sm italic text-muted">{children}</blockquote>;
    default:
      return <div>{children}</div>;
  }
}

export default ReviewsPage;

import { useState, useEffect, useRef, useCallback, useMemo, ReactElement } from 'react';
import { useNavigate } from 'react-router-dom';
import * as Dialog from '@radix-ui/react-dialog';
import { ProjectCombobox, Project } from '@/components/ProjectCombobox';
import { useAuth } from '@/hooks/useAuth';
import { cn } from '@/lib/cn';
import { apiPost, apiGet, apiDelete, readJson } from '@/lib/api';
import { formatDateRange } from '@/lib/date-utils';

interface User {
  personId: string; // Document ID - used for allocations (works for both pending and active)
  id: string | null; // User account ID - null for pending users
  name: string;
  email: string;
  isArchived?: boolean;
  isPending?: boolean;
  reportsTo?: string | null; // user_id of supervisor
}

interface Sprint {
  number: number;
  name: string;
  startDate: string;
  endDate: string;
  isCurrent: boolean;
}

interface Assignment {
  projectId: string | null;
  projectName: string | null;
  projectColor: string | null;
  programId: string | null;
  programName: string | null;
  emoji?: string | null;
  color: string | null;
}

interface TeamGridData {
  users: User[];
  weeks: Sprint[];
  currentSprintNumber: number;
}

interface AssignmentResponse {
  error?: string;
  issuesOrphaned?: Array<{ id: string; title: string }>;
}

const SPRINTS_PER_LOAD = 5;
const SCROLL_THRESHOLD = 200;

// Program group info for grouping users
interface ProgramGroup {
  programId: string | null;
  programName: string;
  emoji: string | null;
  color: string | null;
  users: User[];
}

export function TeamModePage(): ReactElement {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [data, setData] = useState<TeamGridData | null>(null);
  const [projects, setProjects] = useState<Project[]>([]);
  const [assignments, setAssignments] = useState<Record<string, Record<number, Assignment>>>({});
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState<'left' | 'right' | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [showArchived, setShowArchived] = useState(false);
  const [showPastWeeks, setShowPastWeeks] = useState(() => {
    try {
      return localStorage.getItem('ship:allocation-show-past-weeks') === 'true';
    } catch { return false; }
  });
  const [filterMode, setFilterMode] = useState<'my-team' | 'everyone' | null>(() => {
    try {
      const stored = localStorage.getItem('ship:allocation-filter-mode');
      if (stored === 'my-team' || stored === 'everyone') return stored;
    } catch { /* ignore */ }
    return null;
  });
  const [nameFilter, setNameFilter] = useState('');
  const [sprintRange, setSprintRange] = useState<{ min: number; max: number } | null>(null);
  const [collapsedPrograms, setCollapsedPrograms] = useState<Set<string>>(new Set());
  const [viewAsSprintNumber, setViewAsSprintNumber] = useState<number | null>(null);
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const hasScrolledToCurrentRef = useRef(false);

  // Find the current sprint number
  const currentSprintNumber = data?.currentSprintNumber ?? null;

  // Filter weeks to hide past weeks when showPastWeeks is false
  const visibleWeeks = useMemo(() => {
    if (!data) return [];
    if (showPastWeeks || currentSprintNumber === null) return data.weeks;
    return data.weeks.filter(s => s.number >= currentSprintNumber);
  }, [data, showPastWeeks, currentSprintNumber]);

  // Smart default: if user has direct reports, default to "my-team"
  const hasDirectReports = useMemo(() => {
    if (!data || !user?.id) return false;
    return data.users.some(u => u.reportsTo === user.id);
  }, [data, user?.id]);

  // Set smart default when data first loads (only if no stored value)
  useEffect(() => {
    if (data && filterMode === null) {
      setFilterMode(hasDirectReports ? 'my-team' : 'everyone');
    }
  }, [data, filterMode, hasDirectReports]);

  // Persist filter mode and past-weeks visibility to localStorage
  useEffect(() => {
    if (filterMode !== null) {
      localStorage.setItem('ship:allocation-filter-mode', filterMode);
    }
  }, [filterMode]);

  useEffect(() => {
    localStorage.setItem('ship:allocation-show-past-weeks', String(showPastWeeks));
  }, [showPastWeeks]);

  // Filter users based on filter mode and name search
  const filteredUsers = useMemo(() => {
    if (!data) return [];
    let users = data.users;
    if (filterMode === 'my-team' && user?.id) {
      users = users.filter(u => u.reportsTo === user.id);
    }
    if (nameFilter.trim()) {
      const query = nameFilter.trim().toLowerCase();
      users = users.filter(u => u.name.toLowerCase().includes(query));
    }
    return users;
  }, [data, filterMode, user?.id, nameFilter]);

  // Group users by their assignment's program for the viewed sprint
  const groupingSprintNumber = viewAsSprintNumber ?? currentSprintNumber;

  const programGroups = useMemo((): ProgramGroup[] => {
    if (!data) return [];

    const groups: Map<string, ProgramGroup> = new Map();
    const UNASSIGNED_KEY = '__unassigned__';

    for (const user of filteredUsers) {
      const currentAssignment = groupingSprintNumber
        ? assignments[user.personId]?.[groupingSprintNumber]
        : null;

      const groupKey = currentAssignment?.programId || UNASSIGNED_KEY;

      if (!groups.has(groupKey)) {
        groups.set(groupKey, {
          programId: currentAssignment?.programId || null,
          programName: currentAssignment?.programName || 'Unassigned',
          emoji: currentAssignment?.emoji || null,
          color: currentAssignment?.color || null,
          users: [],
        });
      }

      const group = groups.get(groupKey);
      if (group) {
        group.users.push(user);
      }
    }

    // Sort groups: alphabetically by name, with Unassigned last
    const sortedGroups = Array.from(groups.values()).sort((a, b) => {
      if (a.programId === null) return 1;
      if (b.programId === null) return -1;
      return a.programName.localeCompare(b.programName);
    });

    // Sort users within each group alphabetically
    for (const group of sortedGroups) {
      group.users.sort((a, b) => a.name.localeCompare(b.name));
    }

    return sortedGroups;
  }, [data, filteredUsers, assignments, groupingSprintNumber]);

  // Toggle program group collapse
  const toggleProgramCollapse = useCallback((programId: string | null) => {
    const key = programId || '__unassigned__';
    setCollapsedPrograms(prev => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  // Dialog states
  const [lastPersonDialog, setLastPersonDialog] = useState<{
    open: boolean;
    userId: string;
    sprintNumber: number;
    issuesOrphaned: Array<{ id: string; title: string }>;
    onConfirm: () => void;
  } | null>(null);

  // Initial load
  useEffect(() => {
    Promise.all([
      fetchTeamGrid(undefined, undefined, showArchived),
      fetchProjects(),
      fetchAssignments(),
    ]).finally(() => setLoading(false));
  }, []);

  // Refetch when showArchived changes
  useEffect(() => {
    // Skip initial render
    if (loading) return;
    fetchTeamGrid(sprintRange?.min, sprintRange?.max, showArchived);
  }, [showArchived]);

  // Scroll to current sprint on initial load (only when past weeks are shown)
  useEffect(() => {
    if (!showPastWeeks) return; // No need to scroll when past weeks are hidden
    if (data && scrollContainerRef.current && !hasScrolledToCurrentRef.current) {
      const currentSprintIndex = data.weeks.findIndex(s => s.isCurrent);
      if (currentSprintIndex >= 0) {
        requestAnimationFrame(() => {
          if (scrollContainerRef.current) {
            const columnWidth = 180; // matches w-[180px] on sprint columns
            const scrollPosition = currentSprintIndex * columnWidth;
            scrollContainerRef.current.scrollLeft = scrollPosition;
            hasScrolledToCurrentRef.current = true;
          }
        });
      }
    }
  }, [data, showPastWeeks]);

  async function fetchTeamGrid(fromSprint?: number, toSprint?: number, includeArchived = false) {
    try {
      const params = new URLSearchParams();
      if (fromSprint !== undefined) params.set('fromSprint', String(fromSprint));
      if (toSprint !== undefined) params.set('toSprint', String(toSprint));
      if (includeArchived) params.set('includeArchived', 'true');

      const url = `/api/team/grid${params.toString() ? `?${params}` : ''}`;
      const res = await apiGet(url);
      if (!res.ok) throw new Error('Failed to fetch team grid');
      const json = await readJson<TeamGridData>(res);

      if (json.weeks.length > 0) {
        setSprintRange({
          min: json.weeks[0].number,
          max: json.weeks[json.weeks.length - 1].number,
        });
      }

      setData(json);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    }
  }

  async function fetchProjects() {
    try {
      const res = await apiGet(`/api/team/projects`);
      if (res.ok) {
        const json = await readJson<Project[]>(res);
        setProjects(json);
      }
    } catch (err) {
      console.error('Failed to fetch projects:', err);
    }
  }

  async function fetchAssignments() {
    try {
      const res = await apiGet(`/api/team/assignments`);
      if (res.ok) {
        const json = await readJson<Record<string, Record<number, Assignment>>>(res);
        setAssignments(json);
      }
    } catch (err) {
      console.error('Failed to fetch assignments:', err);
    }
  }

  const handleAssign = async (personId: string, projectId: string, sprintNumber: number) => {
    const project = projects.find(p => p.id === projectId);
    if (!project) return;

    // Optimistic update - update UI immediately
    const previousAssignment = assignments[personId]?.[sprintNumber];
    setAssignments(prev => ({
      ...prev,
      [personId]: {
        ...prev[personId],
        [sprintNumber]: {
          projectId,
          projectName: project.title,
          projectColor: project.color ?? null,
          programId: project.programId,
          programName: project.programName,
          emoji: project.programEmoji ?? null,
          color: project.programColor ?? null,
        },
      },
    }));

    try {
      const res = await apiPost(`/api/team/assign`, { personId, projectId, sprintNumber });

      const json = await readJson<AssignmentResponse>(res);

      if (!res.ok) {
        // Rollback optimistic update
        setAssignments(prev => {
          const newAssignments = { ...prev };
          if (previousAssignment) {
            newAssignments[personId] = { ...newAssignments[personId], [sprintNumber]: previousAssignment };
          } else {
            const { [sprintNumber]: _, ...rest } = newAssignments[personId] || {};
            newAssignments[personId] = rest;
          }
          return newAssignments;
        });
        setError(json.error || 'Failed to assign');
        return;
      }
    } catch {
      // Rollback optimistic update
      setAssignments(prev => {
        const newAssignments = { ...prev };
        if (previousAssignment) {
          newAssignments[personId] = { ...newAssignments[personId], [sprintNumber]: previousAssignment };
        } else {
          const { [sprintNumber]: _, ...rest } = newAssignments[personId] || {};
          newAssignments[personId] = rest;
        }
        return newAssignments;
      });
      setError('Failed to assign user');
    }
  };

  const handleUnassign = async (personId: string, sprintNumber: number, skipConfirmation = false) => {
    // Optimistic update - remove from UI immediately
    const previousAssignment = assignments[personId]?.[sprintNumber];
    setAssignments(prev => {
      const newAssignments = { ...prev };
      if (newAssignments[personId]) {
        const { [sprintNumber]: _, ...rest } = newAssignments[personId];
        newAssignments[personId] = rest;
      }
      return newAssignments;
    });

    try {
      const res = await apiDelete(`/api/team/assign`, { personId, sprintNumber });

      const json = await readJson<AssignmentResponse>(res);

      if (!res.ok) {
        // Rollback optimistic update
        if (previousAssignment) {
          setAssignments(prev => ({
            ...prev,
            [personId]: {
              ...prev[personId],
              [sprintNumber]: previousAssignment,
            },
          }));
        }
        setError(json.error || 'Failed to unassign');
        return;
      }

      // If there were orphaned issues, show them in a dialog (unless skipped)
      if ((json.issuesOrphaned?.length ?? 0) > 0 && !skipConfirmation) {
        // Issues were already moved to backlog
      }
    } catch {
      // Rollback optimistic update
      if (previousAssignment) {
        setAssignments(prev => ({
          ...prev,
          [personId]: {
            ...prev[personId],
            [sprintNumber]: previousAssignment,
          },
        }));
      }
      setError('Failed to unassign user');
    }
  };

  const handleCellChange = useCallback((
    personId: string,
    userName: string,
    sprintNumber: number,
    sprintName: string,
    newProjectId: string | null,
    currentAssignment: Assignment | null
  ) => {
    // Same project - no change
    if (newProjectId === currentAssignment?.projectId) {
      return;
    }

    // Clear assignment
    if (newProjectId === null && currentAssignment) {
      handleUnassign(personId, sprintNumber);
      return;
    }

    // New assignment or adding to existing - both just call handleAssign
    // (multiple people can now be assigned to same project/sprint)
    if (newProjectId) {
      handleAssign(personId, newProjectId, sprintNumber);
    }
  }, [projects]);

  // Fetch more sprints
  const fetchMoreSprints = useCallback(async (direction: 'left' | 'right') => {
    if (!data || !sprintRange || loadingMore) return;

    const fromSprint = direction === 'left'
      ? Math.max(1, sprintRange.min - SPRINTS_PER_LOAD)
      : sprintRange.max + 1;
    const toSprint = direction === 'left'
      ? sprintRange.min - 1
      : sprintRange.max + SPRINTS_PER_LOAD;

    if (direction === 'left' && sprintRange.min <= 1) return;

    setLoadingMore(direction);

    try {
      const params = new URLSearchParams({
        fromSprint: String(fromSprint),
        toSprint: String(toSprint),
      });
      if (showArchived) params.set('includeArchived', 'true');

      const res = await apiGet(`/api/team/grid?${params}`);
      if (!res.ok) throw new Error('Failed to fetch more sprints');
      const newData = await readJson<TeamGridData>(res);

      const scrollContainer = scrollContainerRef.current;
      const prevScrollLeft = scrollContainer?.scrollLeft || 0;
      const prevScrollWidth = scrollContainer?.scrollWidth || 0;

      setData(prev => {
        if (!prev) return newData;
        const mergedSprints = direction === 'left'
          ? [...newData.weeks, ...prev.weeks]
          : [...prev.weeks, ...newData.weeks];
        return { ...prev, weeks: mergedSprints };
      });

      setSprintRange(prev => {
        if (!prev) return { min: fromSprint, max: toSprint };
        return {
          min: direction === 'left' ? fromSprint : prev.min,
          max: direction === 'right' ? toSprint : prev.max,
        };
      });

      if (direction === 'left' && scrollContainer) {
        requestAnimationFrame(() => {
          const newScrollWidth = scrollContainer.scrollWidth;
          const addedWidth = newScrollWidth - prevScrollWidth;
          scrollContainer.scrollLeft = prevScrollLeft + addedWidth;
        });
      }
    } catch (err) {
      console.error('Error loading more sprints:', err);
    } finally {
      setLoadingMore(null);
    }
  }, [data, sprintRange, loadingMore, showArchived]);

  const handleScroll = useCallback(() => {
    const container = scrollContainerRef.current;
    if (!container || loadingMore) return;

    const { scrollLeft, scrollWidth, clientWidth } = container;

    if (showPastWeeks && scrollLeft < SCROLL_THRESHOLD && sprintRange && sprintRange.min > 1) {
      fetchMoreSprints('left');
    }

    if (scrollWidth - scrollLeft - clientWidth < SCROLL_THRESHOLD) {
      fetchMoreSprints('right');
    }
  }, [fetchMoreSprints, loadingMore, sprintRange, showPastWeeks]);

  useEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    container.addEventListener('scroll', handleScroll);
    return () => container.removeEventListener('scroll', handleScroll);
  }, [handleScroll]);

  // Escape key clears view-as mode
  useEffect(() => {
    if (viewAsSprintNumber === null) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setViewAsSprintNumber(null);
    };
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [viewAsSprintNumber]);

  // Clear error after 3 seconds
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(null), 3000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  if (loading) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-muted">Loading team grid...</div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-red-500">{error || 'Failed to load data'}</div>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      {/* Error toast */}
      {error && (
        <div className="absolute right-4 top-4 z-50 rounded-md bg-red-500/90 px-4 py-2 text-sm text-white shadow-lg">
          {error}
        </div>
      )}

      {/* Header */}
      <header className="flex h-10 items-center justify-between border-b border-border px-4">
        <div className="flex items-center gap-3">
          <h1 className="text-sm font-medium text-foreground">Allocation</h1>
          {hasDirectReports && (
            <div className="flex rounded-md border border-border text-xs">
              <button
                onClick={() => setFilterMode('my-team')}
                className={cn(
                  'px-2 py-0.5 transition-colors',
                  filterMode === 'my-team'
                    ? 'bg-accent text-white'
                    : 'text-muted hover:text-foreground'
                )}
              >
                My Team
              </button>
              <button
                onClick={() => setFilterMode('everyone')}
                className={cn(
                  'px-2 py-0.5 transition-colors',
                  filterMode === 'everyone'
                    ? 'bg-accent text-white'
                    : 'text-muted hover:text-foreground'
                )}
              >
                Everyone
              </button>
            </div>
          )}
          <div className="relative">
            <input
              type="text"
              value={nameFilter}
              onChange={(e) => setNameFilter(e.target.value)}
              placeholder="Filter by name..."
              className="h-6 w-36 rounded border border-border bg-transparent px-2 text-xs text-foreground placeholder:text-muted focus:border-accent focus:outline-none"
            />
            {nameFilter && (
              <button
                onClick={() => setNameFilter('')}
                className="absolute right-1 top-1/2 -translate-y-1/2 rounded p-0.5 text-muted hover:text-foreground"
              >
                <svg className="h-3 w-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            )}
          </div>
          {viewAsSprintNumber !== null && (
            <div className="flex items-center gap-1.5 rounded-md border border-accent/30 bg-accent/10 px-2 py-0.5 text-xs text-accent">
              <span>Viewing as {data.weeks.find(w => w.number === viewAsSprintNumber)?.name ?? `Week ${viewAsSprintNumber}`}</span>
              <button
                onClick={() => setViewAsSprintNumber(null)}
                className="ml-0.5 rounded p-0.5 hover:bg-accent/20"
                title="Return to current week"
              >
                <svg className="h-3 w-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          )}
        </div>
        <div className="flex items-center gap-4">
          <button
            onClick={() => setShowPastWeeks(prev => !prev)}
            className={cn(
              'flex items-center gap-1 rounded-md border border-border px-2 py-0.5 text-xs transition-colors',
              showPastWeeks
                ? 'bg-accent text-white border-accent'
                : 'text-muted hover:text-foreground hover:border-foreground/30'
            )}
          >
            <svg className="h-3 w-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
            </svg>
            {showPastWeeks ? 'Hide' : 'Show'} past weeks
          </button>
          <label className="flex items-center gap-1.5 cursor-pointer">
            <input
              type="checkbox"
              checked={showArchived}
              onChange={(e) => setShowArchived(e.target.checked)}
              className="h-3.5 w-3.5 rounded border-border text-accent focus:ring-accent/50"
            />
            <span className="text-xs text-muted">Show archived</span>
          </label>
          <span className="text-xs text-muted">
            {filteredUsers.length} team members &middot; {projects.length} projects
          </span>
        </div>
      </header>

      {/* Assignments Grid - Single scroll container with sticky person column */}
      <div
        ref={scrollContainerRef}
        className="flex-1 overflow-auto pb-20"
      >
          <div className="inline-flex min-w-full">
            {/* Sticky person column */}
            <div className="flex flex-col sticky left-0 z-20 bg-background border-r border-border">
              {/* Header cell */}
              <div className="flex h-10 w-[180px] items-center justify-center border-b border-border px-3 sticky top-0 z-30 bg-background">
                <span className="text-xs font-medium text-muted">Team Member</span>
              </div>

              {/* Program groups with users */}
              {programGroups.map((group) => {
                const groupKey = group.programId || '__unassigned__';
                const isCollapsed = collapsedPrograms.has(groupKey);

                return (
                  <div key={groupKey}>
                    {/* Program group header */}
                    <button
                      onClick={() => toggleProgramCollapse(group.programId)}
                      className="flex h-8 w-[180px] items-center gap-2 border-b border-border bg-border/30 px-3 hover:bg-border/50 transition-colors cursor-pointer"
                    >
                      <ChevronIcon
                        className={cn(
                          "h-3 w-3 text-muted transition-transform",
                          isCollapsed && "-rotate-90"
                        )}
                      />
                      {group.programId ? (
                        <span
                          className="shrink-0 rounded px-1.5 py-0.5 text-[10px] font-bold text-white"
                          style={{ backgroundColor: group.color || '#6b7280' }}
                        >
                          {group.emoji || group.programName[0]}
                        </span>
                      ) : (
                        <span className="shrink-0 rounded px-1.5 py-0.5 text-[10px] font-bold text-white bg-gray-500">
                          ?
                        </span>
                      )}
                      <span className="truncate text-xs font-medium text-foreground">
                        {isCollapsed ? `${group.programName} (${group.users.length})` : group.programName}
                      </span>
                      {!isCollapsed && (
                        <span className="ml-auto text-[10px] text-muted">
                          {group.users.length}
                        </span>
                      )}
                    </button>

                    {/* Users in this group */}
                    {!isCollapsed && group.users.map((user, idx) => (
                      <div
                        key={user.id ?? `pending-${idx}`}
                        className={cn(
                          "flex h-12 w-[180px] items-center border-b border-border px-3 bg-background",
                          user.isArchived && "opacity-50",
                          user.isPending && "opacity-70"
                        )}
                      >
                        <div className="flex items-center gap-2 overflow-hidden">
                          <div className={cn(
                            "flex h-6 w-6 flex-shrink-0 items-center justify-center rounded-full text-xs font-medium text-white",
                            user.isArchived ? "bg-gray-400" : user.isPending ? "bg-gray-400" : "bg-accent/80"
                          )}>
                            {user.name.charAt(0).toUpperCase()}
                          </div>
                          <span className={cn(
                            "truncate text-sm",
                            user.isArchived ? "text-muted" : user.isPending ? "text-muted italic" : "text-foreground"
                          )}>
                            {user.name}
                            {user.isArchived && <span className="ml-1 text-xs">(archived)</span>}
                            {user.isPending && <span className="ml-1 text-xs font-normal not-italic">(pending)</span>}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>

            {/* Sprint columns */}
            <div className="flex">
              {loadingMore === 'left' && (
                <div className="flex flex-col w-[60px]">
                  <div className="h-10 flex items-center justify-center border-b border-border sticky top-0 bg-background z-10">
                    <span className="text-xs text-muted animate-pulse">...</span>
                  </div>
                </div>
              )}

              {visibleWeeks.map((sprint) => {
                const isActiveViewAs = sprint.number === viewAsSprintNumber;
                const isDefaultCurrent = sprint.isCurrent && viewAsSprintNumber === null;
                const showViewAsButton = !isActiveViewAs && !isDefaultCurrent;

                return (
                <div key={sprint.number} className="flex flex-col">
                  {/* Sprint header */}
                  <div
                    className={cn(
                      'group flex h-10 w-[180px] flex-col items-center justify-center border-b border-r border-border px-2 sticky top-0 z-10 bg-background',
                      sprint.isCurrent && 'ring-1 ring-inset ring-accent/30',
                      isActiveViewAs && 'ring-2 ring-inset ring-accent/50 bg-accent/5'
                    )}
                  >
                    <span className={cn(
                      'text-xs font-medium',
                      sprint.isCurrent ? 'text-accent' : 'text-foreground'
                    )}>
                      {sprint.name}
                    </span>
                    <span className="text-[10px] text-muted">
                      {formatDateRange(sprint.startDate, sprint.endDate)}
                    </span>
                    {showViewAsButton && (
                      <button
                        onClick={() => setViewAsSprintNumber(sprint.number)}
                        title="View as current week"
                        className="absolute right-1 top-1/2 -translate-y-1/2 rounded p-0.5 text-muted opacity-0 transition-opacity hover:bg-border/50 hover:text-foreground group-hover:opacity-100"
                      >
                        <ViewAsIcon className="h-3.5 w-3.5" />
                      </button>
                    )}
                  </div>

                  {/* Sprint cells grouped by program */}
                  {programGroups.map((group) => {
                    const groupKey = group.programId || '__unassigned__';
                    const isCollapsed = collapsedPrograms.has(groupKey);

                    return (
                      <div key={groupKey}>
                        {/* Program header spacer row for this sprint column */}
                        <div
                          className={cn(
                            "h-8 w-[180px] border-b border-r border-border bg-border/30",
                            sprint.isCurrent && "bg-accent/5"
                          )}
                        />

                        {/* Cells for users in this group */}
                        {!isCollapsed && group.users.map((user) => {
                          const isPending = user.isPending || !user.id;
                          const assignment = assignments[user.personId]?.[sprint.number];
                          const previousWeekAssignment = assignments[user.personId]?.[sprint.number - 1];
                          const cellKey = `${user.personId}-${sprint.number}`;
                          return (
                            <SprintCell
                              key={cellKey}
                              assignment={assignment}
                              previousWeekAssignment={previousWeekAssignment}
                              projects={projects}
                              isCurrent={sprint.isCurrent}
                              loading={false}
                              isPending={isPending}
                              onChange={(projectId) => {
                                handleCellChange(
                                  user.personId,
                                  user.name,
                                  sprint.number,
                                  sprint.name,
                                  projectId,
                                  assignment || null
                                );
                              }}
                              onNavigate={(projectId) => navigate(`/documents/${projectId}`)}
                            />
                          );
                        })}
                      </div>
                    );
                  })}
                </div>
                );
              })}

              {loadingMore === 'right' && (
                <div className="flex flex-col w-[60px]">
                  <div className="h-10 flex items-center justify-center border-b border-border sticky top-0 bg-background z-10">
                    <span className="text-xs text-muted animate-pulse">...</span>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>

      {/* Last Person Dialog */}
      <Dialog.Root open={lastPersonDialog?.open || false} onOpenChange={(open: boolean) => !open && setLastPersonDialog(null)}>
        <Dialog.Portal>
          <Dialog.Overlay className="fixed inset-0 z-50 bg-black/50" />
          <Dialog.Content className="fixed left-1/2 top-1/2 z-50 w-full max-w-md -translate-x-1/2 -translate-y-1/2 rounded-lg border border-border bg-background p-6 shadow-xl">
            <Dialog.Title className="text-lg font-semibold text-foreground">
              Remove Last Assignee
            </Dialog.Title>
            <Dialog.Description className="mt-2 text-sm text-muted">
              This is the last person assigned to this sprint. Removing them will delete the sprint document.
            </Dialog.Description>

            {lastPersonDialog?.issuesOrphaned && lastPersonDialog.issuesOrphaned.length > 0 && (
              <div className="mt-4">
                <p className="text-sm font-medium text-foreground">
                  {lastPersonDialog.issuesOrphaned.length} issues will be moved to backlog:
                </p>
                <ul className="mt-2 max-h-[150px] overflow-auto rounded border border-border p-2">
                  {lastPersonDialog.issuesOrphaned.map((issue) => (
                    <li key={issue.id} className="text-sm text-muted truncate">
                      {issue.title}
                    </li>
                  ))}
                </ul>
              </div>
            )}

            <div className="mt-6 flex justify-end gap-3">
              <Dialog.Close asChild>
                <button className="rounded-md px-4 py-2 text-sm text-muted hover:bg-border">
                  Cancel
                </button>
              </Dialog.Close>
              <button
                onClick={() => {
                  lastPersonDialog?.onConfirm();
                  setLastPersonDialog(null);
                }}
                className="rounded-md bg-red-600 px-4 py-2 text-sm text-white hover:bg-red-700"
              >
                Remove & Delete Week
              </button>
            </div>
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    </div>
  );
}

function SprintCell({
  assignment,
  previousWeekAssignment,
  projects,
  isCurrent,
  loading,
  isPending,
  onChange,
  onNavigate,
}: {
  assignment?: Assignment;
  previousWeekAssignment?: Assignment;
  projects: Project[];
  isCurrent: boolean;
  loading: boolean;
  isPending?: boolean;
  onChange: (projectId: string | null) => void;
  onNavigate: (projectId: string) => void;
}) {
  // Convert previous week assignment to Project format for the quick select
  const previousWeekProject: Project | null =
    previousWeekAssignment?.projectId && previousWeekAssignment?.projectName
      ? {
          id: previousWeekAssignment.projectId,
          title: previousWeekAssignment.projectName,
          color: previousWeekAssignment.projectColor,
          programId: previousWeekAssignment.programId,
          programName: previousWeekAssignment.programName,
          programEmoji: previousWeekAssignment.emoji,
          programColor: previousWeekAssignment.color,
        }
      : null;

  // isPending is only used for visual styling (dashed border), not for blocking assignment
  return (
    <div
      className={cn(
        'flex h-12 w-[180px] items-center justify-start border-b border-r border-border px-1',
        isCurrent && 'bg-accent/5',
        loading && 'animate-pulse',
        isPending && 'border-dashed'
      )}
    >
      <ProjectCombobox
        projects={projects}
        value={assignment?.projectId || null}
        onChange={onChange}
        onNavigate={onNavigate}
        disabled={loading}
        placeholder="+"
        previousWeekProject={previousWeekProject}
        triggerClassName={cn(
          'w-full h-full justify-start',
          !assignment && 'hover:bg-border/30'
        )}
      />
    </div>
  );
}

function ChevronIcon({ className }: { className?: string }) {
  return (
    <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
    </svg>
  );
}

function ViewAsIcon({ className }: { className?: string }) {
  return (
    <svg className={className} fill="none" stroke="currentColor" viewBox="0 0 24 24">
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
    </svg>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { useQueryClient } from '@tanstack/react-query';
import { useWorkspace } from '@/contexts/WorkspaceContext';
import { useAuth } from '@/hooks/useAuth';
import { api, WorkspaceMember, WorkspaceInvite, AuditLog, ApiToken, ApiTokenCreateResponse } from '@/lib/api';
import { archivedPersonsKey } from '@/contexts/ArchivedPersonsContext';
import { cn } from '@/lib/cn';

type Tab = 'members' | 'invites' | 'tokens' | 'audit';

const VALID_TABS: Tab[] = ['members', 'invites', 'tokens', 'audit'];

export function WorkspaceSettingsPage() {
  const { currentWorkspace, isWorkspaceAdmin } = useWorkspace();
  const { user } = useAuth();
  const queryClient = useQueryClient();
  const [searchParams, setSearchParams] = useSearchParams();

  // Derive active tab from URL query params
  const tabParam = searchParams.get('tab') as Tab | null;
  const activeTab: Tab = tabParam && VALID_TABS.includes(tabParam) ? tabParam : 'members';

  const handleTabChange = useCallback((tab: Tab) => {
    setSearchParams({ tab }, { replace: true });
  }, [setSearchParams]);
  const [members, setMembers] = useState<WorkspaceMember[]>([]);
  const [invites, setInvites] = useState<WorkspaceInvite[]>([]);
  const [apiTokens, setApiTokens] = useState<ApiToken[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);
  const [loading, setLoading] = useState(true);
  const [inviteEmail, setInviteEmail] = useState('');
  const [inviteSubjectDn, setInviteSubjectDn] = useState('');
  const [showPivField, setShowPivField] = useState(false);
  const [inviteRole, setInviteRole] = useState<'admin' | 'member'>('member');
  const [inviting, setInviting] = useState(false);
  const [showArchived, setShowArchived] = useState(false);

  useEffect(() => {
    if (!currentWorkspace) return;
    loadData(showArchived);
  }, [currentWorkspace, showArchived]);

  async function loadData(includeArchived = false) {
    if (!currentWorkspace) return;
    setLoading(true);

    const [membersRes, invitesRes, tokensRes, logsRes] = await Promise.all([
      api.workspaces.getMembers(currentWorkspace.id, { includeArchived }),
      api.workspaces.getInvites(currentWorkspace.id),
      api.apiTokens.list(),
      api.workspaces.getAuditLogs(currentWorkspace.id, { limit: 50 }),
    ]);

    if (membersRes.success && membersRes.data) setMembers(membersRes.data.members);
    if (invitesRes.success && invitesRes.data) setInvites(invitesRes.data.invites);
    if (tokensRes.success && tokensRes.data) setApiTokens(tokensRes.data);
    if (logsRes.success && logsRes.data) setAuditLogs(logsRes.data.logs);
    setLoading(false);
  }

  async function handleInvite(e: React.FormEvent) {
    e.preventDefault();
    if (!currentWorkspace || !inviteEmail.trim()) return;

    setInviting(true);
    const res = await api.workspaces.createInvite(currentWorkspace.id, {
      email: inviteEmail.trim(),
      x509SubjectDn: inviteSubjectDn.trim() || undefined,
      role: inviteRole,
    });
    if (res.success && res.data) {
      const { invite } = res.data;
      setInvites(prev => [...prev, invite]);
      setInviteEmail('');
      setInviteSubjectDn('');
      setShowPivField(false);
    }
    setInviting(false);
  }

  async function handleRevokeInvite(inviteId: string) {
    if (!currentWorkspace) return;
    const res = await api.workspaces.revokeInvite(currentWorkspace.id, inviteId);
    if (res.success) {
      setInvites(prev => prev.filter(i => i.id !== inviteId));
    }
  }

  async function handleUpdateRole(userId: string, newRole: 'admin' | 'member') {
    if (!currentWorkspace) return;

    // Check if this is the last admin
    const admins = members.filter(m => m.role === 'admin');
    if (admins.length === 1 && admins[0].userId === userId && newRole === 'member') {
      alert('Cannot demote the last admin. Promote another member first.');
      return;
    }

    const res = await api.workspaces.updateMember(currentWorkspace.id, userId, { role: newRole });
    if (res.success) {
      setMembers(prev => prev.map(m => m.userId === userId ? { ...m, role: newRole } : m));
    }
  }

  async function handleArchiveMember(userId: string) {
    if (!currentWorkspace) return;

    // Check if this is the last admin
    const admins = members.filter(m => m.role === 'admin');
    const member = members.find(m => m.userId === userId);
    if (member?.role === 'admin' && admins.length === 1) {
      alert('Cannot archive the last admin. Promote another member first.');
      return;
    }

    if (!confirm(`Archive ${member?.name || 'this member'}? They will lose access immediately.`)) return;

    const res = await api.workspaces.removeMember(currentWorkspace.id, userId);
    if (res.success) {
      setMembers(prev => prev.filter(m => m.userId !== userId));
      // Invalidate archived persons cache so mentions update
      queryClient.invalidateQueries({ queryKey: archivedPersonsKey });
    }
  }

  async function handleRestoreMember(userId: string) {
    if (!currentWorkspace) return;

    const res = await api.workspaces.restoreMember(currentWorkspace.id, userId);
    if (res.success) {
      // Refresh the members list to get updated data
      loadData(showArchived);
      // Invalidate archived persons cache so mentions update
      queryClient.invalidateQueries({ queryKey: archivedPersonsKey });
    }
  }

  if (!currentWorkspace) {
    return (
      <div className="flex h-full items-center justify-center">
        <div className="text-muted">No workspace selected</div>
      </div>
    );
  }

  if (!isWorkspaceAdmin) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4">
        <h1 className="text-xl font-medium text-foreground">Workspace Settings</h1>
        <p className="text-muted">You don't have permission to manage this workspace.</p>
      </div>
    );
  }

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <header className="flex h-14 items-center justify-between border-b border-border px-6">
        <h1 className="text-lg font-semibold text-foreground">
          Workspace Settings: {currentWorkspace.name}
        </h1>
      </header>

      {/* Tabs */}
      <div className="border-b border-border">
        <nav className="flex px-6">
          <TabButton active={activeTab === 'members'} onClick={() => handleTabChange('members')}>
            Members
          </TabButton>
          <TabButton active={activeTab === 'invites'} onClick={() => handleTabChange('invites')}>
            Pending Invites
          </TabButton>
          <TabButton active={activeTab === 'tokens'} onClick={() => handleTabChange('tokens')}>
            API Tokens
          </TabButton>
          <TabButton active={activeTab === 'audit'} onClick={() => handleTabChange('audit')}>
            Audit Logs
          </TabButton>
          <Link
            to="/settings/conversions"
            className={cn(
              'px-4 py-3 text-sm font-medium border-b-2 border-transparent',
              'text-muted hover:text-foreground hover:border-border/50 transition-colors'
            )}
          >
            Conversions
          </Link>
        </nav>
      </div>

      {/* Content */}
      <main className="flex-1 overflow-auto p-6 pb-20">
        {loading ? (
          <div className="flex items-center justify-center h-32">
            <div className="text-muted">Loading...</div>
          </div>
        ) : (
          <>
            {activeTab === 'members' && (
              <MembersTab
                members={members}
                currentUserId={user?.id}
                showArchived={showArchived}
                onShowArchivedChange={setShowArchived}
                onUpdateRole={handleUpdateRole}
                onArchiveMember={handleArchiveMember}
                onRestoreMember={handleRestoreMember}
              />
            )}
            {activeTab === 'invites' && (
              <InvitesTab
                invites={invites}
                inviteEmail={inviteEmail}
                setInviteEmail={setInviteEmail}
                inviteSubjectDn={inviteSubjectDn}
                setInviteSubjectDn={setInviteSubjectDn}
                showPivField={showPivField}
                setShowPivField={setShowPivField}
                inviteRole={inviteRole}
                setInviteRole={setInviteRole}
                inviting={inviting}
                onInvite={handleInvite}
                onRevoke={handleRevokeInvite}
              />
            )}
            {activeTab === 'tokens' && (
              <ApiTokensTab
                tokens={apiTokens}
                onTokenCreated={(token) => setApiTokens(prev => [token, ...prev])}
                onTokenRevoked={(tokenId) => setApiTokens(prev => prev.filter(t => t.id !== tokenId))}
              />
            )}
            {activeTab === 'audit' && (
              <AuditTab auditLogs={auditLogs} />
            )}
          </>
        )}
      </main>
    </div>
  );
}

function TabButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) {
  return (
    <button
      onClick={onClick}
      className={cn(
        'px-4 py-3 text-sm font-medium border-b-2 transition-colors',
        active
          ? 'border-accent text-foreground'
          : 'border-transparent text-muted hover:text-foreground'
      )}
    >
      {children}
    </button>
  );
}

function MembersTab({
  members,
  currentUserId,
  showArchived,
  onShowArchivedChange,
  onUpdateRole,
  onArchiveMember,
  onRestoreMember,
}: {
  members: WorkspaceMember[];
  currentUserId?: string;
  showArchived: boolean;
  onShowArchivedChange: (show: boolean) => void;
  onUpdateRole: (userId: string, role: 'admin' | 'member') => void;
  onArchiveMember: (userId: string) => void;
  onRestoreMember: (userId: string) => void;
}) {
  const activeMembers = members.filter(m => !m.isArchived);
  const adminCount = activeMembers.filter(m => m.role === 'admin').length;

  return (
    <div className="space-y-4">
      {/* Show archived toggle */}
      <div className="flex justify-end">
        <label className="flex items-center gap-1.5 cursor-pointer">
          <input
            type="checkbox"
            checked={showArchived}
            onChange={(e) => onShowArchivedChange(e.target.checked)}
            className="h-3.5 w-3.5 rounded border-border text-accent focus:ring-accent/50"
          />
          <span className="text-xs text-muted">Show archived</span>
        </label>
      </div>

      <div className="border border-border rounded-lg overflow-hidden">
        <table className="w-full">
          <thead className="bg-border/30">
            <tr>
              <th className="px-4 py-3 text-left text-sm font-medium text-muted">Name</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-muted">Email</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-muted">Role</th>
              <th className="px-4 py-3 text-left text-sm font-medium text-muted">Joined</th>
              <th className="px-4 py-3 text-right text-sm font-medium text-muted">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-border">
            {members.map((member) => {
              const isArchived = member.isArchived;
              const isLastAdmin = member.role === 'admin' && adminCount === 1;
              const isSelf = member.userId === currentUserId;

              return (
                <tr key={member.id} className={cn(isArchived && "opacity-50")}>
                  <td className={cn("px-4 py-3 text-sm font-medium", isArchived ? "text-muted" : "text-foreground")}>
                    {member.name}
                    {isArchived && <span className="ml-1 text-xs font-normal">(archived)</span>}
                    {isSelf && !isArchived && <span className="ml-2 text-muted">(you)</span>}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted">{member.email}</td>
                  <td className="px-4 py-3 text-sm">
                    {isArchived ? (
                      <span className="text-muted">-</span>
                    ) : (
                      <select
                        value={member.role || 'member'}
                        onChange={(e) => onUpdateRole(member.userId, e.target.value as 'admin' | 'member')}
                        disabled={isLastAdmin}
                        className={cn(
                          'px-2 py-1 rounded text-sm bg-background border border-border',
                          isLastAdmin && 'opacity-50 cursor-not-allowed'
                        )}
                        title={isLastAdmin ? 'Workspace must have at least one admin' : undefined}
                      >
                        <option value="admin">Admin</option>
                        <option value="member">Member</option>
                      </select>
                    )}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted">
                    {member.joinedAt ? new Date(member.joinedAt).toLocaleDateString() : '-'}
                  </td>
                  <td className="px-4 py-3 text-right">
                    {isArchived ? (
                      <button
                        onClick={() => onRestoreMember(member.userId)}
                        className="text-sm text-accent hover:text-accent/80 transition-colors"
                      >
                        Restore
                      </button>
                    ) : (
                      !isSelf && !isLastAdmin && (
                        <button
                          onClick={() => onArchiveMember(member.userId)}
                          className="text-sm text-red-500 hover:text-red-400 transition-colors"
                        >
                          Archive
                        </button>
                      )
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function InvitesTab({
  invites,
  inviteEmail,
  setInviteEmail,
  inviteSubjectDn,
  setInviteSubjectDn,
  showPivField,
  setShowPivField,
  inviteRole,
  setInviteRole,
  inviting,
  onInvite,
  onRevoke,
}: {
  invites: WorkspaceInvite[];
  inviteEmail: string;
  setInviteEmail: (v: string) => void;
  inviteSubjectDn: string;
  setInviteSubjectDn: (v: string) => void;
  showPivField: boolean;
  setShowPivField: (v: boolean) => void;
  inviteRole: 'admin' | 'member';
  setInviteRole: (v: 'admin' | 'member') => void;
  inviting: boolean;
  onInvite: (e: React.FormEvent) => void;
  onRevoke: (id: string) => void;
}) {
  const [copiedId, setCopiedId] = useState<string | null>(null);

  function handleCopyLink(invite: WorkspaceInvite) {
    const url = `${window.location.origin}/invite/${invite.token}`;
    navigator.clipboard.writeText(url);
    setCopiedId(invite.id);
    setTimeout(() => setCopiedId(null), 2000);
  }

  return (
    <div className="space-y-6">
      {/* Invite form */}
      <form onSubmit={onInvite} className="space-y-3">
        <div className="flex gap-3">
          <input
            type="email"
            value={inviteEmail}
            onChange={(e) => setInviteEmail(e.target.value)}
            placeholder="Email address"
            className="flex-1 max-w-md px-3 py-2 bg-background border border-border rounded-md text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent"
            required
          />
          <select
            value={inviteRole}
            onChange={(e) => setInviteRole(e.target.value as 'admin' | 'member')}
            className="px-3 py-2 bg-background border border-border rounded-md text-foreground"
          >
            <option value="member">Member</option>
            <option value="admin">Admin</option>
          </select>
          <button
            type="submit"
            disabled={inviting || !inviteEmail.trim()}
            className="px-4 py-2 bg-accent text-white rounded-md hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {inviting ? 'Inviting...' : 'Send Invite'}
          </button>
        </div>

        {/* PIV Subject DN field (collapsible) */}
        <div>
          <button
            type="button"
            onClick={() => setShowPivField(!showPivField)}
            className="text-xs text-muted hover:text-foreground transition-colors"
          >
            {showPivField ? '- Hide PIV options' : '+ Add PIV certificate identity'}
          </button>
          {showPivField && (
            <div className="mt-2">
              <input
                type="text"
                value={inviteSubjectDn}
                onChange={(e) => setInviteSubjectDn(e.target.value)}
                placeholder="X.509 Subject DN (e.g., CN=LASTNAME.FIRSTNAME.MIDDLE.1234567890)"
                className="w-full max-w-lg px-3 py-2 bg-background border border-border rounded-md text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent font-mono text-sm"
              />
              <p className="mt-1 text-xs text-muted">
                Optional: For PIV users whose certificate may not contain an email address.
                The certificate Subject DN will be matched during PIV login.
              </p>
            </div>
          )}
        </div>
      </form>

      {/* Pending invites */}
      {invites.length === 0 ? (
        <div className="text-muted text-sm">No pending invites</div>
      ) : (
        <div className="border border-border rounded-lg overflow-hidden">
          <table className="w-full">
            <thead className="bg-border/30">
              <tr>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Email</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">PIV Identity</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Role</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Expires</th>
                <th className="px-4 py-3 text-right text-sm font-medium text-muted">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {invites.map((invite) => (
                <tr key={invite.id}>
                  <td className="px-4 py-3 text-sm text-foreground">{invite.email}</td>
                  <td className="px-4 py-3 text-sm text-muted">
                    {invite.x509SubjectDn ? (
                      <span className="font-mono text-xs">{invite.x509SubjectDn}</span>
                    ) : (
                      <span className="text-muted/50">-</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted capitalize">{invite.role}</td>
                  <td className="px-4 py-3 text-sm text-muted">
                    {new Date(invite.expiresAt).toLocaleDateString()}
                  </td>
                  <td className="px-4 py-3 text-right space-x-3">
                    <button
                      onClick={() => handleCopyLink(invite)}
                      className={cn(
                        "text-sm transition-colors",
                        copiedId === invite.id
                          ? "text-green-500"
                          : "text-accent hover:text-accent/80"
                      )}
                    >
                      {copiedId === invite.id ? 'Copied!' : 'Copy Link'}
                    </button>
                    <button
                      onClick={() => onRevoke(invite.id)}
                      className="text-sm text-red-500 hover:text-red-400 transition-colors"
                    >
                      Revoke
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function ApiTokensTab({
  tokens,
  onTokenCreated,
  onTokenRevoked,
}: {
  tokens: ApiToken[];
  onTokenCreated: (token: ApiToken) => void;
  onTokenRevoked: (tokenId: string) => void;
}) {
  const [tokenName, setTokenName] = useState('');
  const [expiresInDays, setExpiresInDays] = useState<string>('90');
  const [creating, setCreating] = useState(false);
  const [newToken, setNewToken] = useState<ApiTokenCreateResponse | null>(null);
  const [copied, setCopied] = useState(false);

  async function handleCreate(e: React.FormEvent) {
    e.preventDefault();
    if (!tokenName.trim()) return;

    setCreating(true);
    const res = await api.apiTokens.create({
      name: tokenName.trim(),
      expires_in_days: expiresInDays ? parseInt(expiresInDays, 10) : undefined,
    });
    if (res.success && res.data) {
      setNewToken(res.data);
      onTokenCreated(res.data);
      setTokenName('');
    }
    setCreating(false);
  }

  async function handleRevoke(tokenId: string) {
    if (!confirm('Are you sure you want to revoke this token? This cannot be undone.')) return;

    const res = await api.apiTokens.revoke(tokenId);
    if (res.success) {
      onTokenRevoked(tokenId);
    }
  }

  function handleCopy() {
    if (!newToken) return;
    navigator.clipboard.writeText(newToken.token);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  function handleDismissToken() {
    setNewToken(null);
    setCopied(false);
  }

  return (
    <div className="space-y-6">
      {/* Create token form */}
      <div className="space-y-4">
        <div>
          <h3 className="text-sm font-medium text-foreground mb-1">Generate API Token</h3>
          <p className="text-xs text-muted">
            API tokens allow external tools like Claude Code to access Ship on your behalf.
          </p>
        </div>

        <form onSubmit={handleCreate} className="flex gap-3 items-end">
          <div className="flex-1 max-w-xs">
            <label className="block text-xs text-muted mb-1">Token Name</label>
            <input
              type="text"
              value={tokenName}
              onChange={(e) => setTokenName(e.target.value)}
              placeholder="e.g., Claude Code"
              className="w-full px-3 py-2 bg-background border border-border rounded-md text-foreground placeholder:text-muted focus:outline-none focus:ring-2 focus:ring-accent"
              required
            />
          </div>
          <div className="w-32">
            <label className="block text-xs text-muted mb-1">Expires</label>
            <select
              value={expiresInDays}
              onChange={(e) => setExpiresInDays(e.target.value)}
              className="w-full px-3 py-2 bg-background border border-border rounded-md text-foreground"
            >
              <option value="30">30 days</option>
              <option value="90">90 days</option>
              <option value="365">1 year</option>
              <option value="">Never</option>
            </select>
          </div>
          <button
            type="submit"
            disabled={creating || !tokenName.trim()}
            className="px-4 py-2 bg-accent text-white rounded-md hover:bg-accent/90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {creating ? 'Creating...' : 'Generate Token'}
          </button>
        </form>
      </div>

      {/* New token display (shown only once after creation) */}
      {newToken && (
        <div className="p-4 bg-yellow-500/10 border border-yellow-500/30 rounded-lg space-y-3">
          <div className="flex items-start gap-2">
            <span className="text-yellow-500 text-lg">!</span>
            <div>
              <p className="text-sm font-medium text-foreground">Copy your new API token</p>
              <p className="text-xs text-muted mt-1">
                This is the only time this token will be shown. Save it somewhere secure.
              </p>
            </div>
          </div>
          <div className="flex gap-2">
            <code className="flex-1 px-3 py-2 bg-background border border-border rounded-md text-sm font-mono text-foreground overflow-x-auto">
              {newToken.token}
            </code>
            <button
              onClick={handleCopy}
              className={cn(
                "px-3 py-2 rounded-md text-sm transition-colors",
                copied
                  ? "bg-green-500/20 text-green-500"
                  : "bg-border/50 text-foreground hover:bg-border"
              )}
            >
              {copied ? 'Copied!' : 'Copy'}
            </button>
          </div>
          <button
            onClick={handleDismissToken}
            className="text-xs text-muted hover:text-foreground transition-colors"
          >
            I've saved the token, dismiss this
          </button>
        </div>
      )}

      {/* Token list */}
      {tokens.length === 0 ? (
        <div className="text-muted text-sm">No API tokens yet</div>
      ) : (
        <div className="border border-border rounded-lg overflow-hidden">
          <table className="w-full">
            <thead className="bg-border/30">
              <tr>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Name</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Prefix</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Status</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Last Used</th>
                <th className="px-4 py-3 text-left text-sm font-medium text-muted">Expires</th>
                <th className="px-4 py-3 text-right text-sm font-medium text-muted">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-border">
              {tokens.map((token) => (
                <tr key={token.id} className={token.is_active ? '' : 'opacity-50'}>
                  <td className="px-4 py-3 text-sm text-foreground font-medium">{token.name}</td>
                  <td className="px-4 py-3 text-sm text-muted font-mono">{token.token_prefix}...</td>
                  <td className="px-4 py-3 text-sm">
                    {token.is_active ? (
                      <span className="text-green-500">Active</span>
                    ) : token.revoked_at ? (
                      <span className="text-red-500">Revoked</span>
                    ) : (
                      <span className="text-yellow-500">Expired</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted">
                    {token.last_used_at
                      ? new Date(token.last_used_at).toLocaleDateString()
                      : 'Never'}
                  </td>
                  <td className="px-4 py-3 text-sm text-muted">
                    {token.expires_at
                      ? new Date(token.expires_at).toLocaleDateString()
                      : 'Never'}
                  </td>
                  <td className="px-4 py-3 text-right">
                    {token.is_active && (
                      <button
                        onClick={() => handleRevoke(token.id)}
                        className="text-sm text-red-500 hover:text-red-400 transition-colors"
                      >
                        Revoke
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function AuditTab({ auditLogs }: { auditLogs: AuditLog[] }) {
  return (
    <div className="border border-border rounded-lg overflow-hidden">
      <table className="w-full">
        <thead className="bg-border/30">
          <tr>
            <th className="px-4 py-3 text-left text-sm font-medium text-muted">Time</th>
            <th className="px-4 py-3 text-left text-sm font-medium text-muted">Actor</th>
            <th className="px-4 py-3 text-left text-sm font-medium text-muted">Action</th>
            <th className="px-4 py-3 text-left text-sm font-medium text-muted">Resource</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-border">
          {auditLogs.map((log) => (
            <tr key={log.id}>
              <td className="px-4 py-3 text-sm text-muted whitespace-nowrap">
                {new Date(log.createdAt).toLocaleString()}
              </td>
              <td className="px-4 py-3 text-sm text-foreground">
                {log.actorName || log.actorEmail}
              </td>
              <td className="px-4 py-3 text-sm text-muted">{log.action}</td>
              <td className="px-4 py-3 text-sm text-muted">
                {log.resourceType ? `${log.resourceType}:${log.resourceId?.slice(0, 8)}...` : '-'}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
